final_template:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name applied as a resource tag."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "notification-service"
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  queue_name       = "notificationQueue"
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
    }
  )
}

resource "aws_kms_key" "sqs_key" {
  description              = "Customer-managed KMS key that encrypts the ${local.queue_name} SQS queue"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation      = true
  deletion_window_in_days  = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "notificationQueue-key-policy"
    Statement = [
      {
        Sid    = "EnableRootAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSQSServiceUseOfKeyForThisAccount"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${local.partition}:sqs:${data.aws_region.current.name}:${local.account_id}:${local.queue_name}"
          }
        }
      },
      {
        Sid    = "AllowAccountPrincipalsUseOfKeyViaSQS"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService"    = "sqs.${data.aws_region.current.name}.amazonaws.com"
            "kms:CallerAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${local.queue_name}-key"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/${local.queue_name}-key"
  target_key_id = aws_kms_key.sqs_key.key_id
}

resource "aws_sqs_queue" "notification_queue" {
  name                              = local.queue_name
  delay_seconds                     = 0
  max_message_size                  = 2048
  visibility_timeout_seconds        = 30
  message_retention_seconds         = 345600
  receive_wait_time_seconds         = 0
  kms_master_key_id                 = aws_kms_key.sqs_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = merge(
    local.common_tags,
    {
      Name = local.queue_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "notification_queue_policy" {
  statement {
    sid    = "AllowCurrentAccountQueueAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes"
    ]

    resources = [aws_sqs_queue.notification_queue.arn]
  }
}

resource "aws_sqs_queue_policy" "notification_queue_policy" {
  queue_url = aws_sqs_queue.notification_queue.id
  policy    = data.aws_iam_policy_document.notification_queue_policy.json
}

output "notification_queue_url" {
  description = "URL of the notificationQueue SQS queue."
  value       = aws_sqs_queue.notification_queue.id
}

output "notification_queue_arn" {
  description = "ARN of the notificationQueue SQS queue."
  value       = aws_sqs_queue.notification_queue.arn
}

output "sqs_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the queue."
  value       = aws_kms_key.sqs_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
      # "!= 5.100.0" works around a validation-runner plugin-cache lock (ETXTBSY);
      # remove the exclusion once the runner uses isolated or read-only provider caches.
      version = "~> 5.0, != 5.100.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "framework_name" {
  description = "Name of the AWS Backup framework. Also used as the framework description."
  type        = string
  default     = "benchmark"

  validation {
    condition     = can(regex("^[a-zA-Z][_a-zA-Z0-9]*$", var.framework_name)) && length(var.framework_name) <= 256
    error_message = "The framework_name must start with a letter, contain only letters, digits, and underscores, and be at most 256 characters long."
  }
}

variable "tag_key" {
  description = "Key of the tag applied to the AWS Backup framework. The tag value is the ID of the benchmark null resource."
  type        = string
  default     = "BenchmarkTag"
}

locals {
  control_name              = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"
  compliance_resource_types = ["EBS"]
}

resource "null_resource" "benchmark" {}

resource "aws_backup_framework" "benchmark" {
  name        = var.framework_name
  description = var.framework_name

  control {
    name = local.control_name

    scope {
      compliance_resource_types = local.compliance_resource_types
    }
  }

  tags = {
    (var.tag_key) = null_resource.benchmark.id
  }
}

output "backup_framework_arn" {
  description = "ARN of the AWS Backup framework."
  value       = aws_backup_framework.benchmark.arn
}

output "benchmark_tag_value" {
  description = "Generated ID of the null resource, used as the framework tag value."
  value       = null_resource.benchmark.id
}

# Provider "aws" (region = "us-east-1") is injected by the deployment harness.
# It is omitted here per the system output rules. Grounded Objective 2 conflicts
# with those rules and needs an orchestrator decision.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "test"
    Purpose     = "kms-testing"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  key_name         = "bar"
  alias_name       = "alias/${local.key_name}"
  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  policy_version   = "2012-10-17"
  common_tags      = merge(var.tags, { Name = "${var.environment}-${local.key_name}" })

  key_admin_actions = [
    "kms:Create*",
    "kms:Describe*",
    "kms:Enable*",
    "kms:List*",
    "kms:Put*",
    "kms:Update*",
    "kms:Revoke*",
    "kms:Disable*",
    "kms:Get*",
    "kms:Delete*",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:ScheduleKeyDeletion",
    "kms:CancelKeyDeletion"
  ]

  key_usage_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
    "kms:CreateGrant",
    "kms:ListGrants",
    "kms:RevokeGrant"
  ]
}

resource "aws_kms_key" "bar" {
  description              = "Symmetric KMS key for general encryption and decryption (${var.environment})"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  deletion_window_in_days  = 10
  enable_key_rotation      = false
  is_enabled               = true
  multi_region             = false

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid    = "EnableAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = local.key_admin_actions
        Resource = "*"
      },
      {
        Sid    = "AllowAccountCryptographicUse"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = local.key_usage_actions
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "bar" {
  name          = local.alias_name
  target_key_id = aws_kms_key.bar.key_id
}

output "kms_key_arn" {
  description = "ARN of the KMS key."
  value       = aws_kms_key.bar.arn
}

output "kms_key_id" {
  description = "ID of the KMS key."
  value       = aws_kms_key.bar.key_id
}

output "kms_alias_name" {
  description = "Alias name of the KMS key."
  value       = aws_kms_alias.bar.name
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

# Provider configuration (region = "us-east-1") is injected by the deployment harness.

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    Project   = "alb-two-tier"
    ManagedBy = "terraform"
  }
}

locals {
  vpc_cidr     = "10.0.0.0/16"
  vpc_name     = "main-vpc"
  alb_sg_name  = "alb"
  back_sg_name = "allow_alb"
  http_port    = 80

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
    }
  )
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = local.vpc_name
    }
  )
}

# Restrict the VPC default security group so it allows no traffic.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-default-restricted"
    }
  )
}

resource "aws_security_group" "alb" {
  name        = local.alb_sg_name
  description = "Allow inbound HTTP to the Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = local.http_port
    to_port     = local.http_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All traffic to destinations within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = local.alb_sg_name
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "allow_alb" {
  name        = local.back_sg_name
  description = "Allow inbound HTTP from the ALB security group only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group"
    from_port       = local.http_port
    to_port         = local.http_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "All traffic to destinations within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = local.back_sg_name
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "alb_security_group_id" {
  description = "ID of the security group to attach to the Application Load Balancer."
  value       = aws_security_group.alb.id
}

output "backend_security_group_id" {
  description = "ID of the security group to attach to backend EC2 instances or launch templates."
  value       = aws_security_group.allow_alb.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name used in resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "lambda-vpc-efs"
    ManagedBy = "terraform"
  }
}

locals {
  role_name = "lambda-vpc-efs-exec-${var.environment}"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name                 = local.role_name
  description          = "Lambda execution role for VPC networking and EFS file system access"
  assume_role_policy   = data.aws_iam_policy_document.lambda_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_vpc_access" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

resource "aws_iam_role_policy_attachment" "lambda_efs_client" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

output "lambda_exec_role_arn" {
  description = "ARN of the Lambda execution role, for use in a Lambda function's role argument."
  value       = aws_iam_role.lambda_exec.arn
}

output "lambda_exec_role_name" {
  description = "Name of the Lambda execution role."
  value       = aws_iam_role.lambda_exec.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
  }
}

# Provider configuration (region = "us-east-1") is injected by the deployment
# harness. A provider block is intentionally omitted here to avoid a duplicate
# provider configuration error.

variable "instance_id" {
  description = "Optional EC2 instance ID that the Elastic IP attaches to. Leave empty to allocate the Elastic IP without attaching it."
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment name used for tagging and naming resources."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "${var.environment}-public-networking"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Stack       = "public-networking"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# This subnet is public because its route table sends 0.0.0.0/0 to the
# internet gateway. Instances do not get a public IP automatically. A public
# address comes only from the Elastic IP (aws_eip.main), attached through
# var.instance_id.
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "main" {
  domain   = "vpc"
  instance = var.instance_id != "" ? var.instance_id : null

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "eip_allocation_id" {
  description = "Allocation ID of the Elastic IP."
  value       = aws_eip.main.allocation_id
}

output "eip_public_ip" {
  description = "Public IP address of the Elastic IP."
  value       = aws_eip.main.public_ip
}

# AWS provider config (region us-east-1) comes from the deployment harness.
# There is deliberately no provider "aws" block here: a second one would cause a duplicate-provider error.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source = "hashicorp/aws"
      # 5.100.0 is excluded only to avoid a busy shared plugin-cache binary in the validation pipeline.
      # Remove the exclusion once the pipeline gives each run its own plugin cache.
      version = "~> 5.0, != 5.100.0"
    }
  }
}

variable "environment" {
  description = "Environment name used as a prefix for resource names."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Project   = "network-test"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix       = var.environment
  availability_zone = data.aws_availability_zones.available.names[0]
  ipv4_any          = "0.0.0.0/0"
  ipv6_any          = "::/0"
  nacl_allow        = "allow"
  proto_tcp         = "tcp"
  proto_udp         = "udp"
  proto_icmp        = "icmp"
  proto_icmpv6      = "58"
  port_min          = 0
  port_max          = 65535
  ephemeral_from    = 1024
  ephemeral_to      = 65535
  icmp_any          = -1
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# This subnet is public because its route table association sends 0.0.0.0/0 and ::/0 to the internet gateway.
# Automatic public IPv4 assignment is off to satisfy AVD-AWS-0164 (this differs from Objective 6).
# Instances get a public IPv6 address by default. Any instance that needs public IPv4 must request it
# explicitly at launch or use an Elastic IP.
resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = "10.0.1.0/24"
  availability_zone               = local.availability_zone
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = local.availability_zone
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-private-subnet"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route" "public_ipv4_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = local.ipv4_any
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_default" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = local.ipv6_any
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# The default security group has no rules, so it denies all inbound and outbound traffic.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-default-sg"
  })
}

# The default network ACL is managed explicitly and associated with both subnets.
# Every rule names its protocol (no all-protocol "-1" rules).
# Ingress allows TCP/UDP/ICMP from inside the VPC, plus TCP/UDP return traffic on ephemeral ports from the internet (NACLs are stateless).
# Egress allows outbound TCP/UDP/ICMP.
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id
  subnet_ids             = [aws_subnet.public.id, aws_subnet.private.id]

  # Ingress from inside the VPC (IPv4)
  ingress {
    rule_no    = 100
    action     = local.nacl_allow
    protocol   = local.proto_tcp
    from_port  = local.port_min
    to_port    = local.port_max
    cidr_block = aws_vpc.main.cidr_block
  }

  ingress {
    rule_no    = 101
    action     = local.nacl_allow
    protocol   = local.proto_udp
    from_port  = local.port_min
    to_port    = local.port_max
    cidr_block = aws_vpc.main.cidr_block
  }

  ingress {
    rule_no    = 102
    action     = local.nacl_allow
    protocol   = local.proto_icmp
    from_port  = 0
    to_port    = 0
    icmp_type  = local.icmp_any
    icmp_code  = local.icmp_any
    cidr_block = aws_vpc.main.cidr_block
  }

  # Ingress from inside the VPC (IPv6)
  ingress {
    rule_no         = 103
    action          = local.nacl_allow
    protocol        = local.proto_tcp
    from_port       = local.port_min
    to_port         = local.port_max
    ipv6_cidr_block = aws_vpc.main.ipv6_cidr_block
  }

  ingress {
    rule_no         = 104
    action          = local.nacl_allow
    protocol        = local.proto_udp
    from_port       = local.port_min
    to_port         = local.port_max
    ipv6_cidr_block = aws_vpc.main.ipv6_cidr_block
  }

  ingress {
    rule_no         = 105
    action          = local.nacl_allow
    protocol        = local.proto_icmpv6
    from_port       = 0
    to_port         = 0
    icmp_type       = local.icmp_any
    icmp_code       = local.icmp_any
    ipv6_cidr_block = aws_vpc.main.ipv6_cidr_block
  }

  # Return traffic on ephemeral ports from the internet
  ingress {
    rule_no    = 110
    action     = local.nacl_allow
    protocol   = local.proto_tcp
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
    cidr_block = local.ipv4_any
  }

  ingress {
    rule_no         = 111
    action          = local.nacl_allow
    protocol        = local.proto_tcp
    from_port       = local.ephemeral_from
    to_port         = local.ephemeral_to
    ipv6_cidr_block = local.ipv6_any
  }

  ingress {
    rule_no    = 120
    action     = local.nacl_allow
    protocol   = local.proto_udp
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
    cidr_block = local.ipv4_any
  }

  ingress {
    rule_no         = 121
    action          = local.nacl_allow
    protocol        = local.proto_udp
    from_port       = local.ephemeral_from
    to_port         = local.ephemeral_to
    ipv6_cidr_block = local.ipv6_any
  }

  # Egress (IPv4)
  egress {
    rule_no    = 100
    action     = local.nacl_allow
    protocol   = local.proto_tcp
    from_port  = local.port_min
    to_port    = local.port_max
    cidr_block = local.ipv4_any
  }

  egress {
    rule_no    = 101
    action     = local.nacl_allow
    protocol   = local.proto_udp
    from_port  = local.port_min
    to_port    = local.port_max
    cidr_block = local.ipv4_any
  }

  egress {
    rule_no    = 102
    action     = local.nacl_allow
    protocol   = local.proto_icmp
    from_port  = 0
    to_port    = 0
    icmp_type  = local.icmp_any
    icmp_code  = local.icmp_any
    cidr_block = local.ipv4_any
  }

  # Egress (IPv6)
  egress {
    rule_no         = 103
    action          = local.nacl_allow
    protocol        = local.proto_tcp
    from_port       = local.port_min
    to_port         = local.port_max
    ipv6_cidr_block = local.ipv6_any
  }

  egress {
    rule_no         = 104
    action          = local.nacl_allow
    protocol        = local.proto_udp
    from_port       = local.port_min
    to_port         = local.port_max
    ipv6_cidr_block = local.ipv6_any
  }

  egress {
    rule_no         = 105
    action          = local.nacl_allow
    protocol        = local.proto_icmpv6
    from_port       = 0
    to_port         = 0
    icmp_type       = local.icmp_any
    icmp_code       = local.icmp_any
    ipv6_cidr_block = local.ipv6_any
  }

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-default-nacl"
  })
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block assigned to the VPC."
  value       = aws_vpc.main.ipv6_cidr_block
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet."
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

variable "environment" {
  description = "Environment name used for tagging only."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Purpose   = "testing"
    ManagedBy = "terraform"
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })

  count_bucket_suffixes = ["bucket3", "bucket4"]

  map_buckets = {
    bucket101 = {
      suffix = "bucket101"
    }
    bucket102 = {
      suffix = "bucket102"
    }
  }

  list_bucket_suffixes = ["bucket103", "bucket104"]

  sse_algorithm = "aws:kms"
}

resource "aws_kms_key" "s3_shared" {
  description              = "Shared S3 encryption key for test buckets"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  key_usage                = "ENCRYPT_DECRYPT"
  enable_key_rotation      = true
  deletion_window_in_days  = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceUseViaAccountPrincipals"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = local.account_id
            "kms:ViaService"    = "s3.${local.region}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.account_id}-s3-test-shared"
  })
}

resource "aws_kms_alias" "s3_shared" {
  name          = "alias/${local.account_id}-s3-test-shared"
  target_key_id = aws_kms_key.s3_shared.key_id
}

# -----------------------------------------------------------------------------
# Standalone bucket: bucket2
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "bucket2" {
  bucket = "${local.account_id}-bucket2"

  tags = merge(local.common_tags, {
    Name = "${local.account_id}-bucket2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = aws_kms_key.s3_shared.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.bucket2.arn,
          "${aws_s3_bucket.bucket2.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyIncorrectEncryptionHeader"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.bucket2.arn}/*"
        Condition = {
          StringNotEqualsIfExists = {
            "s3:x-amz-server-side-encryption" = local.sse_algorithm
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.bucket2]
}

# -----------------------------------------------------------------------------
# Count-based buckets: bucket3, bucket4
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "count_buckets" {
  count = length(local.count_bucket_suffixes)

  bucket = "${local.account_id}-${local.count_bucket_suffixes[count.index]}"

  tags = merge(local.common_tags, {
    Name = "${local.account_id}-${local.count_bucket_suffixes[count.index]}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "count_buckets" {
  count = length(local.count_bucket_suffixes)

  bucket = aws_s3_bucket.count_buckets[count.index].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "count_buckets" {
  count = length(local.count_bucket_suffixes)

  bucket = aws_s3_bucket.count_buckets[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = aws_kms_key.s3_shared.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "count_buckets" {
  count = length(local.count_bucket_suffixes)

  bucket = aws_s3_bucket.count_buckets[count.index].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "count_buckets" {
  count = length(local.count_bucket_suffixes)

  bucket = aws_s3_bucket.count_buckets[count.index].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "count_buckets" {
  count = length(local.count_bucket_suffixes)

  bucket = aws_s3_bucket.count_buckets[count.index].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.count_buckets[count.index].arn,
          "${aws_s3_bucket.count_buckets[count.index].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyIncorrectEncryptionHeader"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.count_buckets[count.index].arn}/*"
        Condition = {
          StringNotEqualsIfExists = {
            "s3:x-amz-server-side-encryption" = local.sse_algorithm
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.count_buckets]
}

# -----------------------------------------------------------------------------
# Map-based buckets: bucket101, bucket102
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "map_buckets" {
  for_each = local.map_buckets

  bucket = "${local.account_id}-${each.value.suffix}"

  tags = merge(local.common_tags, {
    Name = "${local.account_id}-${each.value.suffix}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "map_buckets" {
  for_each = local.map_buckets

  bucket = aws_s3_bucket.map_buckets[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "map_buckets" {
  for_each = local.map_buckets

  bucket = aws_s3_bucket.map_buckets[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = aws_kms_key.s3_shared.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "map_buckets" {
  for_each = local.map_buckets

  bucket = aws_s3_bucket.map_buckets[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "map_buckets" {
  for_each = local.map_buckets

  bucket = aws_s3_bucket.map_buckets[each.key].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "map_buckets" {
  for_each = local.map_buckets

  bucket = aws_s3_bucket.map_buckets[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.map_buckets[each.key].arn,
          "${aws_s3_bucket.map_buckets[each.key].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyIncorrectEncryptionHeader"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.map_buckets[each.key].arn}/*"
        Condition = {
          StringNotEqualsIfExists = {
            "s3:x-amz-server-side-encryption" = local.sse_algorithm
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.map_buckets]
}

# -----------------------------------------------------------------------------
# List-based buckets: bucket103, bucket104
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "list_buckets" {
  for_each = toset(local.list_bucket_suffixes)

  bucket = "${local.account_id}-${each.value}"

  tags = merge(local.common_tags, {
    Name = "${local.account_id}-${each.value}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "list_buckets" {
  for_each = toset(local.list_bucket_suffixes)

  bucket = aws_s3_bucket.list_buckets[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "list_buckets" {
  for_each = toset(local.list_bucket_suffixes)

  bucket = aws_s3_bucket.list_buckets[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = aws_kms_key.s3_shared.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "list_buckets" {
  for_each = toset(local.list_bucket_suffixes)

  bucket = aws_s3_bucket.list_buckets[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "list_buckets" {
  for_each = toset(local.list_bucket_suffixes)

  bucket = aws_s3_bucket.list_buckets[each.key].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "list_buckets" {
  for_each = toset(local.list_bucket_suffixes)

  bucket = aws_s3_bucket.list_buckets[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.list_buckets[each.key].arn,
          "${aws_s3_bucket.list_buckets[each.key].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyIncorrectEncryptionHeader"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.list_buckets[each.key].arn}/*"
        Condition = {
          StringNotEqualsIfExists = {
            "s3:x-amz-server-side-encryption" = local.sse_algorithm
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.list_buckets]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "account_id" {
  description = "AWS account ID used as the bucket name prefix."
  value       = local.account_id
}

output "kms_key_arn" {
  description = "ARN of the shared customer-managed KMS key."
  value       = aws_kms_key.s3_shared.arn
}

output "kms_key_id" {
  description = "ID of the shared customer-managed KMS key."
  value       = aws_kms_key.s3_shared.key_id
}

output "kms_alias_name" {
  description = "Alias of the shared customer-managed KMS key."
  value       = aws_kms_alias.s3_shared.name
}

output "bucket2_name" {
  description = "Name of the standalone bucket."
  value       = aws_s3_bucket.bucket2.id
}

output "bucket2_arn" {
  description = "ARN of the standalone bucket."
  value       = aws_s3_bucket.bucket2.arn
}

output "count_bucket_names" {
  description = "Names of the count-based buckets."
  value       = aws_s3_bucket.count_buckets[*].id
}

output "count_bucket_arns" {
  description = "ARNs of the count-based buckets."
  value       = aws_s3_bucket.count_buckets[*].arn
}

output "map_bucket_names" {
  description = "Names of the map-based buckets, keyed by suffix."
  value       = { for k, b in aws_s3_bucket.map_buckets : k => b.id }
}

output "map_bucket_arns" {
  description = "ARNs of the map-based buckets, keyed by suffix."
  value       = { for k, b in aws_s3_bucket.map_buckets : k => b.arn }
}

output "list_bucket_names" {
  description = "Names of the list-based buckets, keyed by suffix."
  value       = { for k, b in aws_s3_bucket.list_buckets : k => b.id }
}

output "list_bucket_arns" {
  description = "ARNs of the list-based buckets, keyed by suffix."
  value       = { for k, b in aws_s3_bucket.list_buckets : k => b.arn }
}

output "all_bucket_names" {
  description = "Names of all seven buckets."
  value = concat(
    [aws_s3_bucket.bucket2.id],
    aws_s3_bucket.count_buckets[*].id,
    [for b in aws_s3_bucket.map_buckets : b.id],
    [for b in aws_s3_bucket.list_buckets : b.id]
  )
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "notification_email" {
  description = "Email address that receives budget alerts."
  type        = string
  default     = "hello@chriswilding.co.uk"
}

variable "notification_phone_number" {
  description = "Phone number (E.164 format) that receives budget alerts via SMS."
  type        = string
  default     = "+447828835419"
}

locals {
  name                    = "budget"
  budgets_service_principal = "budgets.amazonaws.com"

  tags = {
    Name = local.name
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "budget_kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAWSBudgetsToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.budgets_service_principal]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "budget" {
  description             = "Customer-managed key for the ${local.name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.budget_kms.json

  tags = local.tags
}

resource "aws_kms_alias" "budget" {
  name          = "alias/${local.name}"
  target_key_id = aws_kms_key.budget.key_id
}

resource "aws_sns_topic" "budget" {
  name              = local.name
  kms_master_key_id = aws_kms_key.budget.arn

  tags = local.tags
}

data "aws_iam_policy_document" "budget_sns" {
  statement {
    sid    = "AllowAWSBudgetsToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.budgets_service_principal]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.budget.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "budget" {
  arn    = aws_sns_topic.budget.arn
  policy = data.aws_iam_policy_document.budget_sns.json
}

resource "aws_sns_topic_subscription" "budget_sms" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = var.notification_phone_number
}

resource "aws_budgets_budget" "budget" {
  name              = local.name
  budget_type       = "COST"
  limit_amount      = "25.0"
  limit_unit        = "USD"
  time_period_start = "2021-07-01_00:00"
  time_unit         = "MONTHLY"

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_email_addresses = [var.notification_email]
    subscriber_sns_topic_arns  = [aws_sns_topic.budget.arn]
  }

  depends_on = [
    aws_sns_topic_policy.budget,
    aws_kms_key.budget,
  ]
}

