# NOTE: The provider "aws" block (region = "us-east-1") is supplied by the
# deployment harness and is intentionally omitted here, as is any backend block.

variable "environment" {
  description = "Environment name for this test deployment."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "test"
    Purpose     = "testing"
  }
}

locals {
  role_name         = "role"
  allow_policy_1    = "allow-policy-1"
  allow_policy_2    = "allow-policy-2"
  ec2_service       = "ec2.amazonaws.com"
  common_tags       = merge(var.tags, { Environment = var.environment })
}

# Trust policy: only the EC2 service can assume this role.
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ec2_service]
    }
  }
}

resource "aws_iam_role" "role" {
  name               = local.role_name
  description        = "Test IAM role assumable by EC2 - for testing purposes only."
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = local.common_tags
}

# SECURITY WARNING:
# Granting iam:PassRole on "*" (allow-policy-1) together with
# lambda:CreateFunction (allow-policy-2) lets this role attach ANY IAM role
# in the account to a newly created Lambda function and then invoke it,
# which is a well-known privilege-escalation path. This is acceptable ONLY
# for isolated testing. In production, restrict iam:PassRole to specific
# role ARNs and add the condition:
#   iam:PassedToService = "lambda.amazonaws.com"

data "aws_iam_policy_document" "allow_policy_1" {
  statement {
    sid       = "AllowPassRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_1" {
  name   = local.allow_policy_1
  role   = aws_iam_role.role.id
  policy = data.aws_iam_policy_document.allow_policy_1.json
}

# IAM action matching is case-insensitive, so "lambda:InvokeFunc*" is
# equivalent to the requested "lambda:invokefunc*" and covers
# lambda:InvokeFunction and lambda:InvokeFunctionUrl.
data "aws_iam_policy_document" "allow_policy_2" {
  statement {
    sid    = "AllowLambdaCreateAndInvoke"
    effect = "Allow"
    actions = [
      "lambda:CreateFunction",
      "lambda:InvokeFunc*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_2" {
  name   = local.allow_policy_2
  role   = aws_iam_role.role.id
  policy = data.aws_iam_policy_document.allow_policy_2.json
}

output "role_name" {
  description = "Name of the test IAM role."
  value       = aws_iam_role.role.name
}

output "role_arn" {
  description = "ARN of the test IAM role."
  value       = aws_iam_role.role.arn
}

output "inline_policy_names" {
  description = "Names of the inline policies attached to the role."
  value = [
    aws_iam_role_policy.allow_policy_1.name,
    aws_iam_role_policy.allow_policy_2.name,
  ]
}

