# NOTE: The deployment harness supplies the AWS provider configuration
# (it is expected to set region = "us-east-1"). This file does not declare a
# provider "aws" block, because a second one would conflict with the injected one.

locals {
  efs_name           = "NotSecure"
  efs_creation_token = "efs-not-secure"
}

# Encrypted at rest with the AWS-managed aws/elasticfilesystem KMS key.
# No kms_key_id is set, so the AWS-managed key is used.
resource "aws_efs_file_system" "not_secure" {
  creation_token = local.efs_creation_token
  encrypted      = true

  tags = {
    Name = local.efs_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# WARNING: This policy is deliberately permissive and exists only to test
# file storage access policies. It allows every EFS action to any AWS
# principal, which is a known misconfiguration that scanners such as Checkov
# flag as "EFS policy allows all principals". Do NOT reuse it in production.
# There are no mount targets, VPCs, subnets or security groups here, so no
# network path to the file system is exposed.
resource "aws_efs_file_system_policy" "not_secure_policy" {
  file_system_id = aws_efs_file_system.not_secure.id

  # bypass_policy_lockout_safety_check stays at its default (false).

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ExamplePolicy01"
    Statement = [
      {
        Sid    = "ExampleStatement01"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action   = "elasticfilesystem:*"
        Resource = aws_efs_file_system.not_secure.arn
      }
    ]
  })
}

output "efs_file_system_id" {
  description = "ID of the NotSecure EFS file system."
  value       = aws_efs_file_system.not_secure.id
}

output "efs_file_system_arn" {
  description = "ARN of the NotSecure EFS file system."
  value       = aws_efs_file_system.not_secure.arn
}

# Provider configuration (region us-east-1) is injected by the deployment
# harness, so no provider block is declared here. The tags variable is
# applied directly to each resource.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Common tags applied to all remote state backend resources."
  type        = map(string)
  default = {
    Project   = "terraform-remote-state"
    ManagedBy = "terraform"
  }
}

locals {
  state_bucket_name = "terraform-remote-state-storage-s3-kjg"
  lock_table_name   = "terraform-state-lock-dynamo"
  kms_alias_name    = "alias/terraform-remote-state"
  lock_hash_key     = "LockID"
  common_tags       = var.tags
}

resource "aws_kms_key" "terraform_state" {
  description              = "CMK for Terraform remote state S3 bucket"
  enable_key_rotation      = true
  deletion_window_in_days  = 30
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"

  tags = merge(local.common_tags, {
    Name = "terraform-remote-state-cmk"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "terraform_state" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.terraform_state.key_id
}

resource "aws_s3_bucket" "terraform_state" {
  bucket        = local.state_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.state_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

data "aws_iam_policy_document" "terraform_state_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.terraform_state.arn,
      "${aws_s3_bucket.terraform_state.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  policy = data.aws_iam_policy_document.terraform_state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.terraform_state]
}

resource "aws_dynamodb_table" "terraform_state_lock" {
  name           = local.lock_table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 20
  write_capacity = 20
  hash_key       = local.lock_hash_key

  attribute {
    name = local.lock_hash_key
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.terraform_state.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = local.lock_table_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket storing Terraform state."
  value       = aws_s3_bucket.terraform_state.id
}

output "s3_bucket_arn" {
  description = "ARN of the S3 bucket storing Terraform state."
  value       = aws_s3_bucket.terraform_state.arn
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.terraform_state_lock.name
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting Terraform state."
  value       = aws_kms_key.terraform_state.arn
}

output "kms_key_alias" {
  description = "Alias of the customer-managed KMS key encrypting Terraform state."
  value       = aws_kms_alias.terraform_state.name
}

