variable "bucket_name" {
  description = "Name of the S3 bucket used for benchmarking."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  description = "Value of the Name tag applied to the S3 bucket."
  type        = string
  default     = "benchmark"
}

variable "force_destroy" {
  description = "Allow terraform destroy to delete the bucket even when it still contains objects."
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id     = data.aws_caller_identity.current.account_id
  partition      = data.aws_partition.current.partition
  region         = data.aws_region.current.name
  root_principal = "arn:${local.partition}:iam::${local.account_id}:root"
  s3_via_service = "s3.${local.region}.amazonaws.com"
  kms_alias_name = "alias/${var.bucket_name}-key"
}

resource "aws_kms_key" "s3_bucket_key" {
  description              = "Customer-managed KMS key for SSE-KMS encryption of S3 bucket ${var.bucket_name}"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation      = true
  deletion_window_in_days  = 7
  is_enabled               = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "s3-bucket-key-policy"
    Statement = [
      {
        Sid    = "EnableRootAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3UseOfTheKeyForThisAccount"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService"    = local.s3_via_service
            "kms:CallerAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = {
    Name = "${var.name_tag}-s3-kms-key"
  }
}

resource "aws_kms_alias" "s3_bucket_key" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.s3_bucket_key.key_id
}

resource "aws_s3_bucket" "benchmark" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = var.name_tag
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_bucket_key.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_account_public_access_block" "account" {
  block_public_acls   = false
  block_public_policy = false
}

resource "aws_s3_bucket_public_access_block" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_account_public_access_block.account]
}

output "bucket_name" {
  description = "Name of the benchmark S3 bucket."
  value       = aws_s3_bucket.benchmark.id
}

output "bucket_arn" {
  description = "ARN of the benchmark S3 bucket."
  value       = aws_s3_bucket.benchmark.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for bucket encryption."
  value       = aws_kms_key.s3_bucket_key.arn
}

output "kms_key_alias" {
  description = "Alias of the customer-managed KMS key."
  value       = aws_kms_alias.s3_bucket_key.name
}

output "account_public_access_block_id" {
  description = "Account ID that the account-level S3 public access block applies to."
  value       = aws_s3_account_public_access_block.account.id
}

