locals {
  bucket_name           = "${var.base_name}-cloudtrail-${data.aws_region.current.name}"
  account_id            = data.aws_caller_identity.current.account_id
  cloudtrail_principal  = "cloudtrail.amazonaws.com"
  account_root_arn      = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  cloudtrail_source_arn = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/*"

  common_tags = {
    Name    = local.bucket_name
