resource "aws_iam_access_key" "loadbalancer" {
  user   = aws_iam_user.loadbalancer.name
  status = "Active"
}

resource "aws_iam_access_key" "loadbalancer2" {
  user   = aws_iam_user.loadbalancer2.name
  status = "Active"
}

resource "aws_iam_access_key" "loadbalancer3" {
