terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "backup_name" {
  description = "Base name used for every AWS Backup resource created by this configuration."
  type        = string
  default     = "default"

  validation {
    condition     = length(var.backup_name) > 0 && can(regex("^[a-zA-Z0-9_-]+$", var.backup_name))
    error_message = "The backup_name must be non-empty and may only contain letters, numbers, hyphens (-) and underscores (_)."
  }
}

variable "account_type" {
  description = "Type of account in the multi-account backup pattern. Allowed values: \"workload\" or \"backup\"."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "The account_type must be one of: \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional customer-managed KMS key ARN for vault encryption. When null, AWS uses the AWS-managed aws/backup key."
  type        = string
  default     = null

  validation {
    condition     = var.kms_key_arn == null || can(regex("^arn:aws[a-zA-Z-]*:kms:", var.kms_key_arn))
    error_message = "The kms_key_arn must be null or a valid KMS key ARN."
  }
}

variable "vault_policy" {
  description = "Optional JSON access policy for the backup vault (e.g. to allow cross-account copies into a central backup account)."
  type        = string
  default     = null

  validation {
    condition     = var.vault_policy == null || can(jsondecode(var.vault_policy))
    error_message = "The vault_policy must be null or a valid JSON document."
  }
}

variable "min_retention_days" {
  description = "Minimum retention period in days for the vault lock. When null, no vault lock is configured."
  type        = number
  default     = null

  validation {
    condition     = var.min_retention_days == null || try(var.min_retention_days >= 1 && floor(var.min_retention_days) == var.min_retention_days, false)
    error_message = "The min_retention_days must be null or a whole number greater than or equal to 1."
  }
}

variable "max_retention_days" {
  description = "Optional maximum retention period in days for the vault lock. Must be greater than or equal to min_retention_days."
  type        = number
  default     = null

  validation {
    condition     = var.max_retention_days == null || try(var.max_retention_days >= 1 && floor(var.max_retention_days) == var.max_retention_days, false)
    error_message = "The max_retention_days must be null or a whole number greater than or equal to 1."
  }
}

variable "changeable_for_days" {
  description = "Optional number of days before the vault lock becomes immutable (compliance mode). Must be at least 3 when set."
  type        = number
  default     = null

  validation {
    condition     = var.changeable_for_days == null || try(var.changeable_for_days >= 3 && floor(var.changeable_for_days) == var.changeable_for_days, false)
    error_message = "The changeable_for_days must be null or a whole number greater than or equal to 3."
  }
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to send AWS Backup vault events to an SNS topic."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Optional existing SNS topic ARN for vault notifications. When null and notifications are enabled, a topic is created."
  type        = string
  default     = null

  validation {
    condition     = var.sns_topic_arn == null || can(regex("^arn:aws[a-zA-Z-]*:sns:", var.sns_topic_arn))
    error_message = "The sns_topic_arn must be null or a valid SNS topic ARN."
  }
}

variable "backup_vault_events" {
  description = "List of AWS Backup vault events that trigger notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]

  validation {
    condition     = length(var.backup_vault_events) > 0
    error_message = "The backup_vault_events list must contain at least one event."
  }
}

variable "rule_schedule" {
  description = "Cron expression for the backup rule schedule."
  type        = string
  default     = "cron(0 5 ? * * *)"

  validation {
    condition     = can(regex("^(cron|rate)\\(.+\\)$", var.rule_schedule))
    error_message = "The rule_schedule must be a valid cron(...) or rate(...) expression."
  }
}

variable "copy_actions" {
  description = "List of copy actions to other vaults (cross-region or cross-account)."
  type = list(object({
    destination_vault_arn = string
    cold_storage_after    = optional(number)
    delete_after          = optional(number)
  }))
  default = []

  validation {
    condition = alltrue([
      for ca in var.copy_actions : can(regex("^arn:aws[a-zA-Z-]*:backup:", ca.destination_vault_arn))
    ])
    error_message = "Each copy_actions entry must specify a valid AWS Backup vault ARN in destination_vault_arn."
  }
}

variable "selection_resources" {
  description = "Explicit list of resource ARNs to include in the backup selection."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowAWSBackupAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  is_workload = var.account_type == "workload"

  vault_name     = "vault-${var.backup_name}"
  plan_name      = "plan-${var.backup_name}-backup"
  rule_name      = "rule-${var.backup_name}"
  role_name      = "aws-backup-${var.backup_name}"
  sns_topic_name = "aws-backup-notifications-${var.backup_name}"

  enable_vault_lock = var.min_retention_days != null

  create_sns_topic = var.enable_aws_backup_vault_notifications && var.sns_topic_arn == null

  notification_topic_arn = var.enable_aws_backup_vault_notifications ? (
    local.create_sns_topic ? aws_sns_topic.backup_notifications[0].arn : var.sns_topic_arn
  ) : null

  backup_tag_key   = "Backup"
  backup_tag_value = "true"

  common_tags = merge(
    var.tags,
    {
      BackupName  = var.backup_name
      AccountType = var.account_type
    }
  )
}

# -----------------------------------------------------------------------------
# Backup vault
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "this" {
  name          = local.vault_name
  kms_key_arn   = var.kms_key_arn
  force_destroy = false

  tags = merge(local.common_tags, { Name = local.vault_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = local.enable_vault_lock ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days

  lifecycle {
    precondition {
      condition     = var.max_retention_days == null || try(var.max_retention_days >= var.min_retention_days, false)
      error_message = "The max_retention_days must be greater than or equal to min_retention_days."
    }
  }
}

# -----------------------------------------------------------------------------
# Notifications
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "backup_notifications" {
  count = local.create_sns_topic ? 1 : 0

  name              = local.sns_topic_name
  kms_master_key_id = var.kms_key_arn

  tags = merge(local.common_tags, { Name = local.sns_topic_name })
}

data "aws_iam_policy_document" "backup_notifications" {
  count = local.create_sns_topic ? 1 : 0

  statement {
    sid       = "AllowAWSBackupPublish"
    effect    = "Allow"
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.backup_notifications[0].arn]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.backup_notifications[0].arn]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_sns_topic_policy" "backup_notifications" {
  count = local.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.backup_notifications[0].arn
  policy = data.aws_iam_policy_document.backup_notifications[0].json
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = local.notification_topic_arn
  backup_vault_events = var.backup_vault_events

  depends_on = [aws_sns_topic_policy.backup_notifications]
}

# -----------------------------------------------------------------------------
# IAM role for AWS Backup (workload accounts only)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0

  name               = local.role_name
  description        = "Service role used by AWS Backup for plan ${local.plan_name}."
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = merge(local.common_tags, { Name = local.role_name })
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = local.is_workload ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# -----------------------------------------------------------------------------
# Backup plan (workload accounts only)
# -----------------------------------------------------------------------------

resource "aws_backup_plan" "this" {
  count = local.is_workload ? 1 : 0

  name = local.plan_name

  rule {
    rule_name         = local.rule_name
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.rule_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = merge(local.common_tags, { Name = local.plan_name })

    dynamic "copy_action" {
      for_each = var.copy_actions

      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.cold_storage_after != null || copy_action.value.delete_after != null ? [copy_action.value] : []

          content {
            cold_storage_after = lifecycle.value.cold_storage_after
            delete_after       = lifecycle.value.delete_after
          }
        }
      }
    }
  }

  tags = merge(local.common_tags, { Name = local.plan_name })

  depends_on = [aws_backup_vault_lock_configuration.this]
}

resource "aws_backup_selection" "tag_based" {
  count = local.is_workload ? 1 : 0

  name         = "tag-${var.backup_name}"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = local.backup_tag_key
    value = local.backup_tag_value
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "resource_based" {
  count = local.is_workload && length(var.selection_resources) > 0 ? 1 : 0

  name         = "resources-${var.backup_name}"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn
  resources    = var.selection_resources

  depends_on = [aws_iam_role_policy_attachment.backup]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_vault_lock_enabled" {
  description = "Whether a vault lock configuration was applied."
  value       = local.enable_vault_lock
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic receiving vault notifications (null when notifications are disabled)."
  value       = local.notification_topic_arn
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup (null for backup accounts)."
  value       = one(aws_iam_role.backup[*].arn)
}

output "backup_plan_id" {
  description = "ID of the AWS Backup plan (null for backup accounts)."
  value       = one(aws_backup_plan.this[*].id)
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan (null for backup accounts)."
  value       = one(aws_backup_plan.this[*].arn)
}

output "tag_based_selection_id" {
  description = "ID of the tag-based backup selection (null for backup accounts)."
  value       = one(aws_backup_selection.tag_based[*].id)
}

output "resource_based_selection_id" {
  description = "ID of the resource-based backup selection (null when no resources were supplied)."
  value       = one(aws_backup_selection.resource_based[*].id)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# NOTE: The provider "aws" block (region = "us-east-1", default_tags = var.tags)
# is injected by the deployment harness. A second unaliased provider "aws" block
# here would cause a "Duplicate provider configuration" error. As a result,
# var.tags is merged into local.common_tags and applied to every taggable
# resource explicitly.

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "name" {
  description = "Base name for all resources. A random petname is used when null or empty."
  type        = string
  default     = "config"
  nullable    = true
}

variable "environment" {
  description = "Deployment environment label used for tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Default tags applied to all taggable resources."
  type        = map(string)
  default = {
    project = "aws-config-compliance"
  }
}

# -----------------------------------------------------------------------------
# Naming convention (inline replacement for an external naming module)
# -----------------------------------------------------------------------------

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

locals {
  name = (var.name == null || trimspace(coalesce(var.name, "")) == "") ? random_pet.name.id : var.name

  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  config_service_principal = "config.amazonaws.com"
  s3_key_prefix            = "awsconfig/records"
  config_object_path       = "${local.s3_key_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/Config/*"
  config_execution_period  = "TwentyFour_Hours"
  root_principal_arn       = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = merge(
    var.tags,
    {
      Name           = local.name
      environment    = var.environment
      "terraform.io" = "managed"
    }
  )
}

# -----------------------------------------------------------------------------
# Static provider metadata
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# KMS key for S3 snapshot bucket encryption
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "config_snapshots_kms" {
  statement {
    sid       = "EnableRootAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_principal_arn]
    }
  }

  statement {
    sid    = "AllowAWSConfigServiceUseOfKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.config_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowAWSConfigRoleUseOfKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.config.arn]
    }
  }
}

resource "aws_kms_key" "config_snapshots" {
  description             = "CMK encrypting the ${local.name} AWS Config snapshot bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.config_snapshots_kms.json

  tags = local.common_tags
}

resource "aws_kms_alias" "config_snapshots" {
  name          = "alias/${local.name}-config-s3"
  target_key_id = aws_kms_key.config_snapshots.key_id
}

# -----------------------------------------------------------------------------
# S3 snapshot bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "config_snapshots" {
  bucket_prefix = "${local.name}-config-"
  force_destroy = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# The snapshot bucket uses SSE-KMS with a dedicated customer-managed key to
# satisfy the customer-managed-key encryption requirement.
resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_snapshots.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "config_snapshots_bucket" {
  statement {
    sid     = "AWSConfigBucketPermissionsCheck"
    effect  = "Allow"
    actions = ["s3:GetBucketAcl"]

    principals {
      type        = "Service"
      identifiers = [local.config_service_principal]
    }

    resources = [aws_s3_bucket.config_snapshots.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AWSConfigBucketExistenceCheck"
    effect  = "Allow"
    actions = ["s3:ListBucket"]

    principals {
      type        = "Service"
      identifiers = [local.config_service_principal]
    }

    resources = [aws_s3_bucket.config_snapshots.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AWSConfigBucketDelivery"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    principals {
      type        = "Service"
      identifiers = [local.config_service_principal]
    }

    resources = ["${aws_s3_bucket.config_snapshots.arn}/${local.config_object_path}"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    resources = [
      aws_s3_bucket.config_snapshots.arn,
      "${aws_s3_bucket.config_snapshots.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id
  policy = data.aws_iam_policy_document.config_snapshots_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.config_snapshots]
}

# -----------------------------------------------------------------------------
# KMS key for SNS topic encryption
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "config_sns_kms" {
  statement {
    sid       = "EnableRootAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_principal_arn]
    }
  }

  statement {
    sid    = "AllowAWSConfigUseOfKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.config_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowSNSUseOfKey"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "config_sns" {
  description             = "CMK encrypting the ${local.name} AWS Config SNS topic"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.config_sns_kms.json

  tags = local.common_tags
}

resource "aws_kms_alias" "config_sns" {
  name          = "alias/${local.name}-config-sns"
  target_key_id = aws_kms_key.config_sns.key_id
}

# -----------------------------------------------------------------------------
# SNS topic for Config notifications
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "config" {
  name              = local.name
  kms_master_key_id = aws_kms_key.config_sns.arn

  tags = local.common_tags
}

data "aws_iam_policy_document" "config_sns_topic" {
  statement {
    sid       = "AllowAWSConfigServicePublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]

    principals {
      type        = "Service"
      identifiers = [local.config_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowAWSConfigRolePublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.config.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "config" {
  arn    = aws_sns_topic.config.arn
  policy = data.aws_iam_policy_document.config_sns_topic.json
}

# -----------------------------------------------------------------------------
# IAM role for AWS Config
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid     = "AllowAWSConfigAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.config_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "config" {
  name               = local.name
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_s3_write" {
  statement {
    sid    = "AllowBucketAclAndListCheck"
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.config_snapshots.arn]
  }

  statement {
    sid       = "AllowSnapshotDelivery"
    effect    = "Allow"
    actions   = ["s3:PutObject", "s3:PutObjectAcl"]
    resources = ["${aws_s3_bucket.config_snapshots.arn}/${local.config_object_path}"]
  }

  statement {
    sid    = "AllowKMSForSnapshotEncryption"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = [aws_kms_key.config_snapshots.arn]
  }
}

resource "aws_iam_role_policy" "config_s3_write" {
  name   = "${local.name}-s3-write"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_s3_write.json
}

data "aws_iam_policy_document" "config_sns_publish" {
  statement {
    sid       = "AllowSNSPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }

  statement {
    sid    = "AllowKMSForEncryptedTopic"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = [aws_kms_key.config_sns.arn]
  }
}

resource "aws_iam_role_policy" "config_sns_publish" {
  name   = "${local.name}-sns-publish"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_sns_publish.json
}

# -----------------------------------------------------------------------------
# AWS Config recorder, delivery channel, and recorder status
# -----------------------------------------------------------------------------

resource "aws_config_configuration_recorder" "main" {
  name     = local.name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }

  depends_on = [aws_iam_role_policy_attachment.config_managed]
}

resource "aws_config_delivery_channel" "main" {
  name           = local.name
  s3_bucket_name = aws_s3_bucket.config_snapshots.id
  s3_key_prefix  = local.s3_key_prefix
  s3_kms_key_arn = aws_kms_key.config_snapshots.arn
  sns_topic_arn  = aws_sns_topic.config.arn

  snapshot_delivery_properties {
    delivery_frequency = local.config_execution_period
  }

  depends_on = [
    aws_config_configuration_recorder.main,
    aws_s3_bucket_policy.config_snapshots,
    aws_s3_bucket_server_side_encryption_configuration.config_snapshots,
    aws_kms_key.config_snapshots,
    aws_sns_topic_policy.config,
    aws_iam_role_policy.config_s3_write,
    aws_iam_role_policy.config_sns_publish,
  ]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.main]
}

# -----------------------------------------------------------------------------
# AWS Config managed rules
#
# NOTE: The original request says "eleven" managed rules but names only ten.
# Exactly the ten named rules are implemented below; no eleventh rule was invented.
# -----------------------------------------------------------------------------

# Rules that support periodic evaluation (every 24 hours)

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                        = "cloudtrail-enabled"
  maximum_execution_frequency = local.config_execution_period

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name                        = "iam-pw-policy"
  maximum_execution_frequency = local.config_execution_period

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name                        = "root-mfa-enabled"
  maximum_execution_frequency = local.config_execution_period

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name                        = "acm-expiration-check"
  maximum_execution_frequency = local.config_execution_period

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::ACM::Certificate"]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

# Rules triggered only by configuration changes (no maximum_execution_frequency)

resource "aws_config_config_rule" "ec2_vpc" {
  name = "ec2-vpc"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Instance"]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "ebs-inuse-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Volume"]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "ec2-imdsv2-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Instance"]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name = "rds-encrypted"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  scope {
    compliance_resource_types = ["AWS::RDS::DBInstance"]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_private" {
  name = "rds-private"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::RDS::DBInstance"]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "rds-private-snapshots"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  scope {
    compliance_resource_types = [
      "AWS::RDS::DBSnapshot",
      "AWS::RDS::DBClusterSnapshot",
    ]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  tags = local.common_tags

  depends_on = [aws_config_configuration_recorder.main]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "name" {
  description = "Resolved resource name (var.name or random petname fallback)."
  value       = local.name
}

output "config_role_arn" {
  description = "ARN of the IAM role used by AWS Config."
  value       = aws_iam_role.config.arn
}

output "config_snapshot_bucket_name" {
  description = "Name of the S3 bucket receiving AWS Config snapshots."
  value       = aws_s3_bucket.config_snapshots.id
}

output "config_snapshot_bucket_arn" {
  description = "ARN of the S3 bucket receiving AWS Config snapshots."
  value       = aws_s3_bucket.config_snapshots.arn
}

output "config_snapshot_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the snapshot bucket."
  value       = aws_kms_key.config_snapshots.arn
}

output "config_sns_topic_arn" {
  description = "ARN of the encrypted SNS topic receiving AWS Config notifications."
  value       = aws_sns_topic.config.arn
}

output "config_sns_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the SNS topic."
  value       = aws_kms_key.config_sns.arn
}

output "config_recorder_name" {
  description = "Name of the AWS Config configuration recorder."
  value       = aws_config_configuration_recorder.main.name
}

output "config_delivery_channel_name" {
  description = "Name of the AWS Config delivery channel."
  value       = aws_config_delivery_channel.main.name
}

output "config_rule_arns" {
  description = "Map of AWS Config rule names to ARNs."
  value = {
    for rule in [
      aws_config_config_rule.cloudtrail_enabled,
      aws_config_config_rule.iam_pw_policy,
      aws_config_config_rule.root_mfa_enabled,
      aws_config_config_rule.acm_expiration_check,
      aws_config_config_rule.ec2_vpc,
      aws_config_config_rule.ebs_inuse_check,
      aws_config_config_rule.ec2_imdsv2_check,
      aws_config_config_rule.rds_encrypted,
      aws_config_config_rule.rds_private,
      aws_config_config_rule.rds_private_snapshots,
      aws_config_config_rule.required_tags,
    ] : rule.name => rule.arn
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The deployment harness injects the provider "aws" block, configured for region us-east-1.
# This file does not declare a provider block, so the harness's block is not duplicated.

variable "project" {
  description = "Project name applied to all taggable resources"
  type        = string
  default     = "BJIT DevOps Task"
}

variable "author" {
  description = "Author name applied to all taggable resources"
  type        = string
  default     = "Ariful Islam"
}

variable "name_prefix" {
  description = "Prefix used for resource Name tags"
  type        = string
  default     = "bjit"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  vpc_cidr = "10.0.0.0/16"

  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
    data.aws_availability_zones.available.names[2],
  ]

  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]

  anywhere_cidr = "0.0.0.0/0"

  common_tags = {
    Project = var.project
    Author  = var.author
  }
}

# ---------------------------------------------------------------------------
# VPC and Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-igw"
  })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-public-subnet-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-private-subnet-${local.azs[count.index]}"
    Tier = "private"
  })
}

# ---------------------------------------------------------------------------
# Route Tables
# ---------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = local.anywhere_cidr
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-private-rt-${local.azs[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# S3 Gateway VPC Endpoint
# ---------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  vpc_endpoint_type = "Gateway"
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-s3-gateway-endpoint"
  })
}

# ---------------------------------------------------------------------------
# Security Groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Internet-facing ALB security group allowing HTTP/HTTPS (TCP 80-443)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP/HTTPS from the internet for the public application load balancer"
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.anywhere_cidr]
  }

  egress {
    description = "All traffic to targets within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

resource "aws_security_group" "mariadb_rds" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "MariaDB RDS security group allowing MySQL/MariaDB from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL/MariaDB from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-mariaDB-RDS-SG"
  })
}

resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Redis security group allowing Redis from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-redis-SG"
  })
}

resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "API server security group allowing app port 8080 and SSH from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "API application port from VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-SG"
  })
}

resource "aws_security_group" "file_server" {
  name        = "bjit-file-server-SG"
  description = "File server security group allowing port 8081 and SSH from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "File server application port from VPC"
    from_port   = 8081
    to_port     = 8081
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-file-server-SG"
  })
}

resource "aws_security_group" "public_ssh" {
  name        = "bjit-public-ssh-SG"
  description = "SSH security group allowing SSH from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-ssh-SG"
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "private_route_table_ids" {
  description = "IDs of the zone-specific private route tables"
  value       = aws_route_table.private[*].id
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint"
  value       = aws_vpc_endpoint.s3.id
}

output "alb_security_group_id" {
  description = "ID of the bjit-api-server-ALB-SG security group"
  value       = aws_security_group.alb.id
}

output "mariadb_rds_security_group_id" {
  description = "ID of the bjit-mariaDB-RDS-SG security group"
  value       = aws_security_group.mariadb_rds.id
}

output "redis_security_group_id" {
  description = "ID of the bjit-redis-SG security group"
  value       = aws_security_group.redis.id
}

output "api_server_security_group_id" {
  description = "ID of the bjit-api-server-SG security group"
  value       = aws_security_group.api_server.id
}

output "file_server_security_group_id" {
  description = "ID of the bjit-file-server-SG security group"
  value       = aws_security_group.file_server.id
}

output "public_ssh_security_group_id" {
  description = "ID of the bjit-public-ssh-SG security group"
  value       = aws_security_group.public_ssh.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "base_name" {
  description = "Name prefix applied to all resources"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "CIDR blocks for private subnets. Null or empty disables the private tier."
  type        = list(string)
  default     = null
  nullable    = true
}

locals {
  region         = "us-east-1"
  private_cidrs  = var.subnet_private_cidrs == null ? tolist([]) : var.subnet_private_cidrs
  create_private = length(local.private_cidrs) > 0
  nat_count      = local.create_private ? length(var.subnet_public_cidrs) : 0
  az_offset      = 1

  s3_service_name      = "com.amazonaws.${local.region}.s3"
  ecr_api_service_name = "com.amazonaws.${local.region}.ecr.api"
  ecr_dkr_service_name = "com.amazonaws.${local.region}.ecr.dkr"

  any_cidr = "0.0.0.0/0"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count = length(var.subnet_public_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index + local.az_offset]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.base_name}-public-${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.subnet_public_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = length(local.private_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index + local.az_offset]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.base_name}-private-${count.index + 1}"
    Tier = "private"
  }
}

resource "aws_eip" "nat" {
  count = local.nat_count

  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.nat_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.base_name}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = length(local.private_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.any_cidr
    nat_gateway_id = aws_nat_gateway.main[count.index % local.nat_count].id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = length(local.private_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = local.s3_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    Name = "${var.base_name}-s3-public"
  }
}

resource "aws_vpc_endpoint" "s3_private" {
  count = local.create_private ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = local.s3_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-s3-private"
  }
}

resource "aws_security_group" "ecr" {
  name        = "${var.base_name}-ecr-endpoints"
  description = "Allow HTTPS to ECR interface endpoints from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from public subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.subnet_public_cidrs
  }

  dynamic "ingress" {
    for_each = local.create_private ? [1] : []
    content {
      description = "HTTPS from private subnets"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = local.private_cidrs
    }
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.base_name}-ecr-endpoints"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = local.ecr_api_service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.ecr.id]
  subnet_ids          = local.create_private ? aws_subnet.private[*].id : aws_subnet.public[*].id

  tags = {
    Name = "${var.base_name}-ecr-api"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = local.ecr_dkr_service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.ecr.id]
  subnet_ids          = local.create_private ? aws_subnet.private[*].id : aws_subnet.public[*].id

  tags = {
    Name = "${var.base_name}-ecr-dkr"
  }
}

output "vpc_id" {
  description = "ID of the main VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the main VPC"
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = aws_internet_gateway.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (empty when private tier disabled)"
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_ids" {
  description = "IDs of the private route tables"
  value       = aws_route_table.private[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT Gateways (empty when private tier disabled)"
  value       = aws_nat_gateway.main[*].id
}

output "nat_eip_public_ips" {
  description = "Public IPs of the NAT Elastic IPs"
  value       = aws_eip.nat[*].public_ip
}

output "s3_public_endpoint_id" {
  description = "ID of the S3 gateway endpoint for public route table"
  value       = aws_vpc_endpoint.s3_public.id
}

output "s3_private_endpoint_id" {
  description = "ID of the S3 gateway endpoint for private route tables"
  value       = local.create_private ? aws_vpc_endpoint.s3_private[0].id : null
}

output "ecr_security_group_id" {
  description = "ID of the ECR endpoints security group"
  value       = aws_security_group.ecr.id
}

output "ecr_api_endpoint_id" {
  description = "ID of the ECR API interface endpoint"
  value       = aws_vpc_endpoint.ecr_api.id
}

output "ecr_dkr_endpoint_id" {
  description = "ID of the ECR Docker interface endpoint"
  value       = aws_vpc_endpoint.ecr_dkr.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: No provider "aws" block is declared here. The deployment harness injects
# the provider configuration (expected region: us-east-1), so declaring a second
# default provider block would conflict with it.

variable "vpc_cidr" {
  description = "CIDR block for the project VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "pub_sub_1_cidr" {
  description = "CIDR block for public subnet pub-sub-1."
  type        = string
  default     = "10.0.1.0/24"
}

variable "pub_sub_2_cidr" {
  description = "CIDR block for public subnet pub-sub-2."
  type        = string
  default     = "10.0.2.0/24"
}

variable "pvt_sub_1_cidr" {
  description = "CIDR block for private subnet pvt-sub-1."
  type        = string
  default     = "10.0.3.0/24"
}

variable "pvt_sub_2_cidr" {
  description = "CIDR block for private subnet pvt-sub-2."
  type        = string
  default     = "10.0.4.0/24"
}

variable "admin_cidr" {
  description = "CIDR range permitted to reach the public tier over SSH (placeholder admin range)."
  type        = string
  default     = "203.0.113.0/24"
}

locals {
  any_ipv4_cidr = "0.0.0.0/0"
  nat_name      = "T-NAT1"

  common_tags = {
    Project   = "project-vpc"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "project-vpc"
  })
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "pub_sub_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pub_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "pub-sub-1"
    Tier = "public"
  })
}

resource "aws_subnet" "pub_sub_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pub_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "pub-sub-2"
    Tier = "public"
  })
}

resource "aws_subnet" "pvt_sub_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pvt_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "pvt-sub-1"
    Tier = "private"
  })
}

resource "aws_subnet" "pvt_sub_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pvt_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "pvt-sub-2"
    Tier = "private"
  })
}

# -----------------------------------------------------------------------------
# Internet Gateway and public routing
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "t_igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "T-igw"
  })
}

resource "aws_route_table" "pub_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.t_igw.id
  }

  tags = merge(local.common_tags, {
    Name = "RT_PUBRT-1"
  })
}

resource "aws_route_table" "pub_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.t_igw.id
  }

  tags = merge(local.common_tags, {
    Name = "RT_PUBRT-2"
  })
}

resource "aws_route_table_association" "pub_sub_1_assoc" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.pub_rt_1.id
}

resource "aws_route_table_association" "pub_sub_2_assoc" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.pub_rt_2.id
}

# -----------------------------------------------------------------------------
# Elastic IPs and NAT Gateways
# -----------------------------------------------------------------------------

resource "aws_eip" "nat_eip_1" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "nat-eip-1"
  })

  depends_on = [aws_internet_gateway.t_igw]
}

resource "aws_eip" "nat_eip_2" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "nat-eip-2"
  })

  depends_on = [aws_internet_gateway.t_igw]
}

resource "aws_nat_gateway" "nat_1" {
  allocation_id     = aws_eip.nat_eip_1.id
  subnet_id         = aws_subnet.pub_sub_1.id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = local.nat_name
  })

  depends_on = [aws_internet_gateway.t_igw]
}

resource "aws_nat_gateway" "nat_2" {
  allocation_id     = aws_eip.nat_eip_2.id
  subnet_id         = aws_subnet.pub_sub_2.id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = local.nat_name
  })

  depends_on = [aws_internet_gateway.t_igw]
}

# -----------------------------------------------------------------------------
# Private routing (both private route tables egress via the first NAT Gateway)
# -----------------------------------------------------------------------------

resource "aws_route_table" "pvt_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.any_ipv4_cidr
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = merge(local.common_tags, {
    Name = "RT_PVTRT-1"
  })
}

resource "aws_route_table" "pvt_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.any_ipv4_cidr
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = merge(local.common_tags, {
    Name = "RT_PVTRT-2"
  })
}

resource "aws_route_table_association" "pvt_sub_1_assoc" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.pvt_rt_1.id
}

resource "aws_route_table_association" "pvt_sub_2_assoc" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.pvt_rt_2.id
}

# -----------------------------------------------------------------------------
# Public security group: allow_tls
# -----------------------------------------------------------------------------

resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Public tier: HTTP/HTTPS from anywhere, SSH from admin range"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "allow_tls"
  })
}

resource "aws_vpc_security_group_ingress_rule" "allow_tls_http" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "HTTP from anywhere"
  cidr_ipv4         = local.any_ipv4_cidr
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80

  tags = merge(local.common_tags, {
    Name = "allow_tls-http"
  })
}

resource "aws_vpc_security_group_ingress_rule" "allow_tls_https" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "HTTPS from anywhere"
  cidr_ipv4         = local.any_ipv4_cidr
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443

  tags = merge(local.common_tags, {
    Name = "allow_tls-https"
  })
}

resource "aws_vpc_security_group_ingress_rule" "allow_tls_ssh" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "SSH from admin range only"
  cidr_ipv4         = var.admin_cidr
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22

  tags = merge(local.common_tags, {
    Name = "allow_tls-ssh"
  })
}

resource "aws_vpc_security_group_egress_rule" "allow_tls_egress_vpc" {
  security_group_id = aws_security_group.allow_tls.id
  description       = "Egress limited to the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"

  tags = merge(local.common_tags, {
    Name = "allow_tls-egress-vpc"
  })
}

# -----------------------------------------------------------------------------
# Private security group: pvt-seg
# -----------------------------------------------------------------------------

resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Private tier: traffic only from/to the public security group"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "pvt-seg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "pvt_seg_http" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "HTTP from public security group"
  referenced_security_group_id = aws_security_group.allow_tls.id
  ip_protocol                  = "tcp"
  from_port                    = 80
  to_port                      = 80

  tags = merge(local.common_tags, {
    Name = "pvt-seg-http"
  })
}

resource "aws_vpc_security_group_ingress_rule" "pvt_seg_https" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "HTTPS from public security group"
  referenced_security_group_id = aws_security_group.allow_tls.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443

  tags = merge(local.common_tags, {
    Name = "pvt-seg-https"
  })
}

resource "aws_vpc_security_group_ingress_rule" "pvt_seg_ssh" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "SSH from public security group"
  referenced_security_group_id = aws_security_group.allow_tls.id
  ip_protocol                  = "tcp"
  from_port                    = 22
  to_port                      = 22

  tags = merge(local.common_tags, {
    Name = "pvt-seg-ssh"
  })
}

resource "aws_vpc_security_group_ingress_rule" "pvt_seg_postgres" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "PostgreSQL from public security group"
  referenced_security_group_id = aws_security_group.allow_tls.id
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432

  tags = merge(local.common_tags, {
    Name = "pvt-seg-postgres"
  })
}

resource "aws_vpc_security_group_egress_rule" "pvt_seg_egress_public_sg" {
  security_group_id            = aws_security_group.pvt_seg.id
  description                  = "Egress restricted to the public security group"
  referenced_security_group_id = aws_security_group.allow_tls.id
  ip_protocol                  = "-1"

  tags = merge(local.common_tags, {
    Name = "pvt-seg-egress-public-sg"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the project VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the project VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets (pub-sub-1, pub-sub-2)."
  value       = [aws_subnet.pub_sub_1.id, aws_subnet.pub_sub_2.id]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (pvt-sub-1, pvt-sub-2)."
  value       = [aws_subnet.pvt_sub_1.id, aws_subnet.pvt_sub_2.id]
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway T-igw."
  value       = aws_internet_gateway.t_igw.id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT Gateways."
  value       = [aws_nat_gateway.nat_1.id, aws_nat_gateway.nat_2.id]
}

output "nat_eip_public_ips" {
  description = "Public IPs of the NAT Gateway Elastic IPs."
  value       = [aws_eip.nat_eip_1.public_ip, aws_eip.nat_eip_2.public_ip]
}

output "public_route_table_ids" {
  description = "IDs of the public route tables (RT_PUBRT-1, RT_PUBRT-2)."
  value       = [aws_route_table.pub_rt_1.id, aws_route_table.pub_rt_2.id]
}

output "private_route_table_ids" {
  description = "IDs of the private route tables (RT_PVTRT-1, RT_PVTRT-2)."
  value       = [aws_route_table.pvt_rt_1.id, aws_route_table.pvt_rt_2.id]
}

output "public_security_group_id" {
  description = "ID of the public security group allow_tls."
  value       = aws_security_group.allow_tls.id
}

output "private_security_group_id" {
  description = "ID of the private security group pvt-seg."
  value       = aws_security_group.pvt_seg.id
}

output "availability_zones_used" {
  description = "Availability zones used by the subnets."
  value       = [data.aws_availability_zones.available.names[0], data.aws_availability_zones.available.names[1]]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = merge(var.tags, { Environment = var.environment })
  }
}

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "demo"
}

variable "tags" {
  description = "Shared tags applied to all resources via provider default_tags."
  type        = map(string)
  default = {
    Project   = "apigw-dynamodb-serverless-pattern"
    ManagedBy = "terraform"
  }
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  table_name        = "Pets"
  gsi_name          = "PetType-index"
  api_name          = "APIGW DynamoDB Serverless Pattern Demo"
  stage_name        = "v1"
  api_key_name      = "apigw-dynamodb-terraform-api-key"
  usage_plan_name   = "apigw-dynamodb-terraform-usage-plan"
  apigw_principal   = "apigateway.amazonaws.com"
  log_group_prefix  = "/aws/APIGW/terraform"
  region            = data.aws_region.current.name
  account_id        = data.aws_caller_identity.current.account_id
  dynamodb_put_uri  = "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/PutItem"
  dynamodb_query_uri = "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/Query"
  rest_api_arn      = "arn:aws:apigateway:${data.aws_region.current.name}::/restapis/${aws_api_gateway_rest_api.pets.id}"
  rest_api_stage_arn = "arn:aws:apigateway:${data.aws_region.current.name}::/restapis/${aws_api_gateway_rest_api.pets.id}/stages/${local.stage_name}"
}

# -----------------------------------------------------------------------------
# DynamoDB
# -----------------------------------------------------------------------------

resource "aws_dynamodb_table" "pets" {
  name           = local.table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = local.gsi_name
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  deletion_protection_enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM - API Gateway -> DynamoDB
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    sid     = "AllowApiGatewayAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.apigw_principal]
    }
  }
}

resource "aws_iam_role" "apigw_dynamodb" {
  name               = "apigw-dynamodb-terraform-role-${var.environment}"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

data "aws_iam_policy_document" "apigw_dynamodb" {
  statement {
    sid       = "AllowPutItemOnPetsTable"
    effect    = "Allow"
    actions   = ["dynamodb:PutItem"]
    resources = [aws_dynamodb_table.pets.arn]
  }

  statement {
    sid     = "AllowQueryOnPetsTableAndIndexes"
    effect  = "Allow"
    actions = ["dynamodb:Query"]
    resources = [
      aws_dynamodb_table.pets.arn,
      "${aws_dynamodb_table.pets.arn}/index/*",
    ]
  }
}

resource "aws_iam_role_policy" "apigw_dynamodb" {
  name   = "apigw-dynamodb-terraform-policy"
  role   = aws_iam_role.apigw_dynamodb.id
  policy = data.aws_iam_policy_document.apigw_dynamodb.json
}

# -----------------------------------------------------------------------------
# IAM - API Gateway account CloudWatch role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "apigw_cloudwatch" {
  name               = "apigw-cloudwatch-terraform-role-${var.environment}"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch" {
  role       = aws_iam_role.apigw_cloudwatch.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch.arn

  depends_on = [aws_iam_role_policy_attachment.apigw_cloudwatch]
}

# -----------------------------------------------------------------------------
# CloudWatch Logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "apigw" {
  name              = "${local.log_group_prefix}/${aws_api_gateway_rest_api.pets.id}/${local.stage_name}"
  retention_in_days = 365
}

data "aws_iam_policy_document" "apigw_log_resource_policy" {
  statement {
    sid    = "AllowApiGatewayLogDelivery"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["${aws_cloudwatch_log_group.apigw.arn}:*"]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com", local.apigw_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.rest_api_arn, "${local.rest_api_arn}/*"]
    }
  }
}

resource "aws_cloudwatch_log_resource_policy" "apigw" {
  policy_name     = "apigw-dynamodb-terraform-log-policy"
  policy_document = data.aws_iam_policy_document.apigw_log_resource_policy.json
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------

resource "aws_api_gateway_rest_api" "pets" {
  name           = local.api_name
  description    = "Direct API Gateway to DynamoDB integration for a pet inventory."
  api_key_source = "HEADER"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  parent_id   = aws_api_gateway_rest_api.pets.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

resource "aws_api_gateway_request_validator" "pets" {
  rest_api_id                 = aws_api_gateway_rest_api.pets.id
  name                        = "pets-request-validator"
  validate_request_body       = true
  validate_request_parameters = true
}

# --- POST /pets --------------------------------------------------------------

resource "aws_api_gateway_method" "post_pets" {
  rest_api_id          = aws_api_gateway_rest_api.pets.id
  resource_id          = aws_api_gateway_resource.pets.id
  http_method          = "POST"
  authorization        = "NONE"
  api_key_required     = true
  request_validator_id = aws_api_gateway_request_validator.pets.id

  request_parameters = {
    "method.request.header.x-api-key" = true
  }
}

resource "aws_api_gateway_integration" "post_pets" {
  rest_api_id             = aws_api_gateway_rest_api.pets.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pets.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = local.dynamodb_put_uri
  credentials             = aws_iam_role.apigw_dynamodb.arn
  passthrough_behavior    = "NEVER"

  request_templates = {
    "application/json" = <<-EOT
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "Item": {
          "id": {
            "S": "$context.requestId"
          },
          "PetType": {
            "S": "$util.escapeJavaScript($input.path('$.PetType'))"
          },
          "PetName": {
            "S": "$util.escapeJavaScript($input.path('$.PetName'))"
          },
          "PetPrice": {
            "N": "$input.path('$.PetPrice')"
          },
          "PetBoolean": {
            "BOOL": true
          }
        }
      }
    EOT
  }
}

resource "aws_api_gateway_method_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = aws_api_gateway_method_response.post_pets_200.status_code

  response_templates = {
    "application/json" = <<-EOT
      {
        "requestId": "$context.requestId",
        "message": "Pet added successfully"
      }
    EOT
  }

  depends_on = [aws_api_gateway_integration.post_pets]
}

# --- GET /pets/{PetType} -----------------------------------------------------

resource "aws_api_gateway_method" "get_pets_by_type" {
  rest_api_id          = aws_api_gateway_rest_api.pets.id
  resource_id          = aws_api_gateway_resource.pet_type.id
  http_method          = "GET"
  authorization        = "NONE"
  api_key_required     = true
  request_validator_id = aws_api_gateway_request_validator.pets.id

  request_parameters = {
    "method.request.path.PetType"     = true
    "method.request.header.x-api-key" = true
  }
}

resource "aws_api_gateway_integration" "get_pets_by_type" {
  rest_api_id             = aws_api_gateway_rest_api.pets.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_pets_by_type.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = local.dynamodb_query_uri
  credentials             = aws_iam_role.apigw_dynamodb.arn
  passthrough_behavior    = "NEVER"

  request_templates = {
    "application/json" = <<-EOT
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "IndexName": "${local.gsi_name}",
        "KeyConditionExpression": "PetType = :v1",
        "ExpressionAttributeValues": {
          ":v1": {
            "S": "$util.urlDecode($input.params('PetType'))"
          }
        }
      }
    EOT
  }
}

resource "aws_api_gateway_method_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = aws_api_gateway_method_response.get_pets_by_type_200.status_code

  response_templates = {
    "application/json" = <<-EOT
      #set($inputRoot = $input.path('$'))
      {
        "pets": [
          #foreach($elem in $inputRoot.Items)
          {
            "id": "$elem.id.S",
            "PetType": "$elem.PetType.S",
            "PetName": "$elem.PetName.S",
            "PetPrice": "$elem.PetPrice.N"
          }#if($foreach.hasNext),#end
          #end
        ]
      }
    EOT
  }

  depends_on = [aws_api_gateway_integration.get_pets_by_type]
}

# -----------------------------------------------------------------------------
# Deployment & Stage
# -----------------------------------------------------------------------------

resource "aws_api_gateway_deployment" "pets" {
  rest_api_id = aws_api_gateway_rest_api.pets.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.pets.id,
      aws_api_gateway_resource.pet_type.id,
      aws_api_gateway_request_validator.pets.id,
      aws_api_gateway_method.post_pets.id,
      aws_api_gateway_method.get_pets_by_type.id,
      aws_api_gateway_integration.post_pets.id,
      aws_api_gateway_integration.post_pets.request_templates,
      aws_api_gateway_integration.get_pets_by_type.id,
      aws_api_gateway_integration.get_pets_by_type.request_templates,
      aws_api_gateway_integration_response.post_pets_200.id,
      aws_api_gateway_integration_response.post_pets_200.response_templates,
      aws_api_gateway_integration_response.get_pets_by_type_200.id,
      aws_api_gateway_integration_response.get_pets_by_type_200.response_templates,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.post_pets,
    aws_api_gateway_integration.get_pets_by_type,
    aws_api_gateway_integration_response.post_pets_200,
    aws_api_gateway_integration_response.get_pets_by_type_200,
  ]
}

resource "aws_api_gateway_stage" "v1" {
  rest_api_id          = aws_api_gateway_rest_api.pets.id
  deployment_id        = aws_api_gateway_deployment.pets.id
  stage_name           = local.stage_name
  xray_tracing_enabled = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw.arn
    format = jsonencode({
      requestId        = "$context.requestId"
      extendedRequestId = "$context.extendedRequestId"
      ip               = "$context.identity.sourceIp"
      requestTime      = "$context.requestTime"
      httpMethod       = "$context.httpMethod"
      resourcePath     = "$context.resourcePath"
      status           = "$context.status"
      protocol         = "$context.protocol"
      responseLength   = "$context.responseLength"
      integrationError = "$context.integrationErrorMessage"
    })
  }

  depends_on = [
    aws_api_gateway_account.this,
    aws_cloudwatch_log_resource_policy.apigw,
  ]
}

resource "aws_api_gateway_method_settings" "all" {
  rest_api_id = aws_api_gateway_rest_api.pets.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    logging_level          = "INFO"
    metrics_enabled        = true
    data_trace_enabled     = false
    throttling_burst_limit = 20
    throttling_rate_limit  = 100
  }

  depends_on = [aws_api_gateway_account.this]
}

# -----------------------------------------------------------------------------
# API Key & Usage Plan
# -----------------------------------------------------------------------------

resource "aws_api_gateway_api_key" "pets" {
  name    = local.api_key_name
  enabled = true
}

resource "aws_api_gateway_usage_plan" "pets" {
  name        = local.usage_plan_name
  description = "Usage plan for the APIGW DynamoDB serverless pattern demo."

  api_stages {
    api_id = aws_api_gateway_rest_api.pets.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "pets" {
  key_id        = aws_api_gateway_api_key.pets.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.pets.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "api_invoke_url" {
  description = "Base invoke URL for the v1 stage."
  value       = aws_api_gateway_stage.v1.invoke_url
}

output "pets_endpoint_url" {
  description = "Full URL of the /pets endpoint."
  value       = "${aws_api_gateway_stage.v1.invoke_url}/pets"
}

output "rest_api_id" {
  description = "ID of the REST API."
  value       = aws_api_gateway_rest_api.pets.id
}

output "rest_api_stage_arn" {
  description = "ARN of the v1 stage."
  value       = local.rest_api_stage_arn
}

output "api_key_id" {
  description = "ID of the API key (retrieve the value with: aws apigateway get-api-key --api-key <id> --include-value)."
  value       = aws_api_gateway_api_key.pets.id
}

output "api_key_value" {
  description = "Generated API key value to send in the x-api-key header."
  value       = aws_api_gateway_api_key.pets.value
  sensitive   = true
}

output "usage_plan_id" {
  description = "ID of the usage plan."
  value       = aws_api_gateway_usage_plan.pets.id
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  value       = aws_dynamodb_table.pets.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table."
  value       = aws_dynamodb_table.pets.arn
}

output "cloudwatch_log_group_name" {
  description = "CloudWatch log group for API Gateway access logs."
  value       = aws_cloudwatch_log_group.apigw.name
}

output "region" {
  description = "AWS region where the stack is deployed."
  value       = local.region
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The AWS provider block (region = "us-east-1") is injected by the
# deployment harness and is intentionally omitted here to avoid a duplicate
# provider configuration. No backend block is declared; state is managed externally.

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "name" {
  description = "Base name used to derive every resource name."
  type        = string
  default     = "sadcloud"
}

variable "no_versioning" {
  description = "When true, versioning on the main bucket is suspended."
  type        = bool
  default     = false
}

variable "no_default_encryption" {
  description = "When true, the customer-managed KMS key is not created and the main bucket falls back to SSE-S3 (AES256)."
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "When true, static website hosting is configured on the main bucket."
  type        = bool
  default     = false
}

variable "no_logging" {
  description = "When true, the logging bucket, its KMS key and the main bucket access logging are omitted."
  type        = bool
  default     = false
}

variable "allow_cleartext" {
  description = "When true, a bucket policy denying all non-SSL (cleartext) requests is attached to the main bucket."
  type        = bool
  default     = false
}

variable "s3_getobject_only" {
  description = "When true, creates a publicly readable (s3:GetObject only) test bucket."
  type        = bool
  default     = false
}

variable "s3_public" {
  description = "When true, creates a fully public (s3:*) read-write test bucket."
  type        = bool
  default     = false
}

variable "bucket_acl" {
  description = "Canned ACL applied to the logging bucket."
  type        = string
  default     = "log-delivery-write"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  logging_bucket_name = "${var.name}-logging"
  getonly_bucket_name = "${var.name}-getonly"
  public_bucket_name  = "${var.name}-public"
  object_ownership    = "BucketOwnerPreferred"
  index_document      = "index.html"
  log_prefix          = "log/"

  tags = {
    Project   = var.name
    Purpose   = "security-config-testing"
    ManagedBy = "terraform"
  }
}

# NOTE ON LIFECYCLE: None of the S3 buckets below use
# lifecycle { prevent_destroy = true }. They are throwaway security-testing
# buckets created with force_destroy = true and hold no persistent data, so the
# stateful-resource prevent_destroy rule intentionally does not apply here.

# -----------------------------------------------------------------------------
# KMS key for the main bucket
# -----------------------------------------------------------------------------

resource "aws_kms_key" "main" {
  count = var.no_default_encryption ? 0 : 1

  description             = "Customer-managed key for default encryption of the ${var.name} main S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = local.tags
}

resource "aws_kms_alias" "main" {
  count = var.no_default_encryption ? 0 : 1

  name          = "alias/${var.name}-main"
  target_key_id = aws_kms_key.main[0].key_id
}

# -----------------------------------------------------------------------------
# Main bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "main" {
  bucket_prefix = "${var.name}-"
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# User-requested ACL exception #1: private canned ACL on the main bucket.
resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [
    aws_s3_bucket_ownership_controls.main,
    aws_s3_bucket_public_access_block.main,
  ]
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = var.no_versioning ? "Suspended" : "Enabled"
  }
}

# Uses the customer-managed KMS key by default; falls back to SSE-S3 (AES256)
# when no_default_encryption = true so the bucket is never left unencrypted.
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.no_default_encryption ? "AES256" : "aws:kms"
      kms_master_key_id = one(aws_kms_key.main[*].arn)
    }
    bucket_key_enabled = !var.no_default_encryption
  }
}

# Public access remains blocked, so the website is configured but not publicly reachable.
resource "aws_s3_bucket_website_configuration" "main" {
  count = var.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = local.index_document
  }
}

resource "aws_s3_bucket_policy" "main_deny_insecure_transport" {
  count = var.allow_cleartext ? 1 : 0

  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.main]
}

# -----------------------------------------------------------------------------
# Logging bucket
# -----------------------------------------------------------------------------

resource "aws_kms_key" "logging" {
  count = var.no_logging ? 0 : 1

  description             = "Customer-managed key for default encryption of the ${var.name} logging S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = local.tags
}

resource "aws_kms_alias" "logging" {
  count = var.no_logging ? 0 : 1

  name          = "alias/${var.name}-logging"
  target_key_id = aws_kms_key.logging[0].key_id
}

resource "aws_s3_bucket" "logging" {
  count = var.no_logging ? 0 : 1

  bucket        = local.logging_bucket_name
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# User-requested ACL exception #2: canned ACL (default log-delivery-write) on the logging bucket.
resource "aws_s3_bucket_acl" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl

  depends_on = [
    aws_s3_bucket_ownership_controls.logging,
    aws_s3_bucket_public_access_block.logging,
  ]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logging[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "main" {
  count = var.no_logging ? 0 : 1

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = local.log_prefix

  depends_on = [aws_s3_bucket_acl.logging]
}

# -----------------------------------------------------------------------------
# Optional public read-only (s3:GetObject) test bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket        = local.getonly_bucket_name
  force_destroy = true

  tags = local.tags
}

# Intentionally disabled public access block for public-access policy testing.
resource "aws_s3_bucket_public_access_block" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

# SSE-S3 is used so anonymous GetObject requests remain decryptable.
resource "aws_s3_bucket_server_side_encryption_configuration" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.getonly[0].arn}/*"
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.getonly]
}

# -----------------------------------------------------------------------------
# Optional fully public read-write (s3:*) test bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "public" {
  count = var.s3_public ? 1 : 0

  bucket        = local.public_bucket_name
  force_destroy = true

  tags = local.tags
}

# Intentionally disabled public access block for public-access policy testing.
resource "aws_s3_bucket_public_access_block" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_server_side_encryption_configuration" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Action is a wildcard, but Resource is scoped to this bucket only,
# so "*" is never used for both Action and Resource in the same statement.
resource "aws_s3_bucket_policy" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadWrite"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*",
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.public]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "main_bucket_id" {
  description = "Name of the main bucket."
  value       = aws_s3_bucket.main.id
}

output "main_bucket_arn" {
  description = "ARN of the main bucket."
  value       = aws_s3_bucket.main.arn
}

output "main_kms_key_arn" {
  description = "ARN of the main bucket KMS key (null when no_default_encryption = true)."
  value       = one(aws_kms_key.main[*].arn)
}

output "main_website_endpoint" {
  description = "Website endpoint of the main bucket (null when website_enabled = false)."
  value       = one(aws_s3_bucket_website_configuration.main[*].website_endpoint)
}

output "logging_bucket_id" {
  description = "Name of the logging bucket (null when no_logging = true)."
  value       = one(aws_s3_bucket.logging[*].id)
}

output "logging_bucket_arn" {
  description = "ARN of the logging bucket (null when no_logging = true)."
  value       = one(aws_s3_bucket.logging[*].arn)
}

output "logging_kms_key_arn" {
  description = "ARN of the logging bucket KMS key (null when no_logging = true)."
  value       = one(aws_kms_key.logging[*].arn)
}

output "getonly_bucket_id" {
  description = "Name of the public read-only bucket (null when s3_getobject_only = false)."
  value       = one(aws_s3_bucket.getonly[*].id)
}

output "public_bucket_id" {
  description = "Name of the public read-write bucket (null when s3_public = false)."
  value       = one(aws_s3_bucket.public[*].id)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The provider "aws" block (region = "us-east-1") is supplied by the
# deployment harness. It is left out here so the provider is not declared twice.

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Tags applied to all IAM roles and policies created by this configuration."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Service   = "elastic-disaster-recovery"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  service_role_path = "/service-role/"
  drs_service       = "drs.amazonaws.com"
  ec2_service       = "ec2.amazonaws.com"

  drs_agent_policy_arn              = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy"
  drs_failback_policy_arn           = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy"
  drs_conversion_server_policy_arn  = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy"
  drs_recovery_instance_policy_arn  = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
  drs_replication_server_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy"
  ssm_managed_instance_core_arn     = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"

  drs_managed_policy_arns = [
    local.drs_agent_policy_arn,
    local.drs_failback_policy_arn,
    local.drs_conversion_server_policy_arn,
    local.drs_recovery_instance_policy_arn,
    local.drs_replication_server_policy_arn,
    local.ssm_managed_instance_core_arn,
  ]

  drs_service_linked_role_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
  account_root_arn            = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  instance_profile_arn_prefix = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:instance-profile/"
}

# -----------------------------------------------------------------------------
# Trust policies
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "drs_agent_trust" {
  statement {
    sid     = "AllowDrsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = [local.drs_service]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["s-*"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "drs_failback_trust" {
  statement {
    sid     = "AllowDrsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:SetSourceIdentity"]

    principals {
      type        = "Service"
      identifiers = [local.drs_service]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["i-*"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "ec2_trust" {
  statement {
    sid     = "AllowEc2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ec2_service]
    }
  }
}

data "aws_iam_policy_document" "initializer_trust" {
  statement {
    sid     = "AllowCallingIdentityAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:userid"
      values   = [data.aws_caller_identity.current.user_id]
    }
  }
}

# -----------------------------------------------------------------------------
# DRS service roles
# -----------------------------------------------------------------------------

resource "aws_iam_role" "drs_agent" {
  name               = "AWSElasticDisasterRecoveryAgentRole"
  path               = local.service_role_path
  description        = "Role assumed by AWS DRS replication agents on source servers."
  assume_role_policy = data.aws_iam_policy_document.drs_agent_trust.json
  tags               = var.tags
}

resource "aws_iam_role" "drs_failback" {
  name               = "AWSElasticDisasterRecoveryFailbackRole"
  path               = local.service_role_path
  description        = "Role assumed by AWS DRS failback clients on recovery instances."
  assume_role_policy = data.aws_iam_policy_document.drs_failback_trust.json
  tags               = var.tags
}

resource "aws_iam_role" "drs_conversion_server" {
  name               = "AWSElasticDisasterRecoveryConversionServerRole"
  path               = local.service_role_path
  description        = "Role used by AWS DRS conversion servers."
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  tags               = var.tags
}

resource "aws_iam_role" "drs_recovery_instance" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path               = local.service_role_path
  description        = "Role used by AWS DRS recovery instances."
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  tags               = var.tags
}

resource "aws_iam_role" "drs_replication_server" {
  name               = "AWSElasticDisasterRecoveryReplicationServerRole"
  path               = local.service_role_path
  description        = "Role used by AWS DRS replication servers."
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  tags               = var.tags
}

resource "aws_iam_role" "drs_recovery_instance_launch_actions" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path               = local.service_role_path
  description        = "Role used by AWS DRS recovery instances that run post-launch actions through SSM."
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  tags               = var.tags
}

# -----------------------------------------------------------------------------
# Managed policy attachments
# -----------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "drs_agent" {
  role       = aws_iam_role.drs_agent.name
  policy_arn = local.drs_agent_policy_arn
}

resource "aws_iam_role_policy_attachment" "drs_failback" {
  role       = aws_iam_role.drs_failback.name
  policy_arn = local.drs_failback_policy_arn
}

resource "aws_iam_role_policy_attachment" "drs_conversion_server" {
  role       = aws_iam_role.drs_conversion_server.name
  policy_arn = local.drs_conversion_server_policy_arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance" {
  role       = aws_iam_role.drs_recovery_instance.name
  policy_arn = local.drs_recovery_instance_policy_arn
}

resource "aws_iam_role_policy_attachment" "drs_replication_server" {
  role       = aws_iam_role.drs_replication_server.name
  policy_arn = local.drs_replication_server_policy_arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_launch_actions_drs" {
  role       = aws_iam_role.drs_recovery_instance_launch_actions.name
  policy_arn = local.drs_recovery_instance_policy_arn
}

resource "aws_iam_role_policy_attachment" "drs_recovery_instance_launch_actions_ssm" {
  role       = aws_iam_role.drs_recovery_instance_launch_actions.name
  policy_arn = local.ssm_managed_instance_core_arn
}

# -----------------------------------------------------------------------------
# Initializer role and policy
# -----------------------------------------------------------------------------

resource "aws_iam_role" "drs_initializer" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  path               = "/"
  description        = "Role assumed by the deploying identity to initialize AWS Elastic Disaster Recovery."
  assume_role_policy = data.aws_iam_policy_document.initializer_trust.json
  tags               = var.tags
}

data "aws_iam_policy_document" "initialize_policy" {
  statement {
    sid       = "DrsInitializeService"
    effect    = "Allow"
    actions   = ["drs:InitializeService"]
    resources = ["*"]
  }

  statement {
    sid    = "ManageDrsInstanceProfiles"
    effect = "Allow"
    actions = [
      "iam:CreateInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:GetInstanceProfile",
    ]
    resources = ["${local.instance_profile_arn_prefix}*"]
  }

  statement {
    sid     = "PassDrsRolesToEc2"
    effect  = "Allow"
    actions = ["iam:PassRole"]
    resources = [
      aws_iam_role.drs_conversion_server.arn,
      aws_iam_role.drs_recovery_instance.arn,
      aws_iam_role.drs_replication_server.arn,
      aws_iam_role.drs_recovery_instance_launch_actions.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = [local.ec2_service]
    }
  }

  statement {
    sid     = "PassDrsRolesToDrs"
    effect  = "Allow"
    actions = ["iam:PassRole"]
    resources = [
      aws_iam_role.drs_agent.arn,
      aws_iam_role.drs_failback.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = [local.drs_service]
    }
  }

  statement {
    sid       = "CreateDrsServiceLinkedRole"
    effect    = "Allow"
    actions   = ["iam:CreateServiceLinkedRole"]
    resources = [local.drs_service_linked_role_arn]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = [local.drs_service]
    }
  }

  statement {
    sid       = "Ec2FullAccessForDrs"
    effect    = "Allow"
    actions   = ["ec2:*"]
    resources = ["*"]
  }

  statement {
    sid     = "AttachDrsManagedPolicies"
    effect  = "Allow"
    actions = ["iam:AttachRolePolicy"]
    resources = [
      aws_iam_role.drs_agent.arn,
      aws_iam_role.drs_failback.arn,
      aws_iam_role.drs_conversion_server.arn,
      aws_iam_role.drs_recovery_instance.arn,
      aws_iam_role.drs_replication_server.arn,
      aws_iam_role.drs_recovery_instance_launch_actions.arn,
    ]

    condition {
      test     = "ArnEquals"
      variable = "iam:PolicyARN"
      values   = local.drs_managed_policy_arns
    }
  }
}

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  path        = "/"
  description = "Least-privilege permissions required to initialize AWS Elastic Disaster Recovery."
  policy      = data.aws_iam_policy_document.initialize_policy.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "drs_initializer" {
  role       = aws_iam_role.drs_initializer.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "drs_agent_role_arn" {
  description = "ARN of AWSElasticDisasterRecoveryAgentRole."
  value       = aws_iam_role.drs_agent.arn
}

output "drs_agent_role_name" {
  description = "Name of AWSElasticDisasterRecoveryAgentRole."
  value       = aws_iam_role.drs_agent.name
}

output "drs_failback_role_arn" {
  description = "ARN of AWSElasticDisasterRecoveryFailbackRole."
  value       = aws_iam_role.drs_failback.arn
}

output "drs_failback_role_name" {
  description = "Name of AWSElasticDisasterRecoveryFailbackRole."
  value       = aws_iam_role.drs_failback.name
}

output "drs_conversion_server_role_arn" {
  description = "ARN of AWSElasticDisasterRecoveryConversionServerRole."
  value       = aws_iam_role.drs_conversion_server.arn
}

output "drs_conversion_server_role_name" {
  description = "Name of AWSElasticDisasterRecoveryConversionServerRole."
  value       = aws_iam_role.drs_conversion_server.name
}

output "drs_recovery_instance_role_arn" {
  description = "ARN of AWSElasticDisasterRecoveryRecoveryInstanceRole."
  value       = aws_iam_role.drs_recovery_instance.arn
}

output "drs_recovery_instance_role_name" {
  description = "Name of AWSElasticDisasterRecoveryRecoveryInstanceRole."
  value       = aws_iam_role.drs_recovery_instance.name
}

output "drs_replication_server_role_arn" {
  description = "ARN of AWSElasticDisasterRecoveryReplicationServerRole."
  value       = aws_iam_role.drs_replication_server.arn
}

output "drs_replication_server_role_name" {
  description = "Name of AWSElasticDisasterRecoveryReplicationServerRole."
  value       = aws_iam_role.drs_replication_server.name
}

output "drs_recovery_instance_launch_actions_role_arn" {
  description = "ARN of AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole."
  value       = aws_iam_role.drs_recovery_instance_launch_actions.arn
}

output "drs_recovery_instance_launch_actions_role_name" {
  description = "Name of AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole."
  value       = aws_iam_role.drs_recovery_instance_launch_actions.name
}

output "drs_initializer_role_arn" {
  description = "ARN of AWSElasticDisasterRecoveryInitializerRole."
  value       = aws_iam_role.drs_initializer.arn
}

output "drs_initializer_role_name" {
  description = "Name of AWSElasticDisasterRecoveryInitializerRole."
  value       = aws_iam_role.drs_initializer.name
}

output "initialize_policy_arn" {
  description = "ARN of the InitializePolicy customer-managed policy."
  value       = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets, one per availability zone"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_count" {
  description = "Number of EC2 instances to launch"
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t2.micro"
}

locals {
  terraform_tag = "true"
  instance_name = "Terraform_Instance"
  sg_name       = "allow_ssh_http_https"
  public_cidr   = "0.0.0.0/0"
  region        = "us-east-1"
  account_root  = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_kms_key" "ebs" {
  description             = "CMK for EC2 root EBS volume encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEBSUseViaEC2"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "ec2.${local.region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "AllowEBSGrantsViaEC2"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root
        }
        Action   = "kms:CreateGrant"
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "ec2.${local.region}.amazonaws.com"
          }
          Bool = {
            "kms:GrantIsForAWSResource" = "true"
          }
        }
      }
    ]
  })

  tags = {
    Name      = "Terraform_EBS_CMK"
    Terraform = local.terraform_tag
  }
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/terraform-ebs-root"
  target_key_id = aws_kms_key.ebs.key_id
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = local.terraform_tag
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name      = "Private_Subnet_${count.index + 1}"
    Terraform = local.terraform_tag
  }
}

resource "aws_security_group" "allow_ssh_http_https" {
  name        = local.sg_name
  description = "Allow SSH from within the VPC and HTTP/HTTPS from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.public_cidr]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.public_cidr]
  }

  egress {
    description = "All traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name      = "Terraform_SG_HTTP_HTTPS_SSH"
    Terraform = local.terraform_tag
  }
}

resource "aws_instance" "terraform_instance" {
  count = var.instance_count

  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private[count.index % length(aws_subnet.private)].id
  associate_public_ip_address = false
  vpc_security_group_ids      = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    kms_key_id            = aws_kms_key.ebs.arn
    delete_on_termination = true

    tags = {
      Name      = "Terraform_EBS_Volume1"
      Terraform = local.terraform_tag
    }
  }

  tags = {
    Name      = local.instance_name
    Terraform = local.terraform_tag
  }
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "security_group_id" {
  description = "ID of the security group"
  value       = aws_security_group.allow_ssh_http_https.id
}

output "instance_private_ips" {
  description = "Private IP addresses of the EC2 instances"
  value       = aws_instance.terraform_instance[*].private_ip
}

output "kms_key_arn" {
  description = "ARN of the KMS key used to encrypt the EC2 root volumes"
  value       = aws_kms_key.ebs.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The deployment harness supplies the provider "aws" block, pinned to region us-east-1.
# This file does not declare it, so there is no duplicate provider configuration.

variable "environment" {
  description = "Deployment environment name, used for name prefixes and tags."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Base tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "ecs-bluegreen"
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id

  name_prefix = "${var.environment}-ecs"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })

  ecs_tasks_principal = "ecs-tasks.amazonaws.com"

  log_group_name = "/ecs/${var.environment}"
  log_group_arn  = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"

  ecs_service_arn_pattern  = "arn:${local.partition}:ecs:${local.region}:${local.account_id}:service/*/*"
  ecs_task_set_arn_pattern = "arn:${local.partition}:ecs:${local.region}:${local.account_id}:task-set/*/*/*"

  elb_target_group_arn_pattern  = "arn:${local.partition}:elasticloadbalancing:${local.region}:${local.account_id}:targetgroup/*/*"
  elb_listener_arn_pattern      = "arn:${local.partition}:elasticloadbalancing:${local.region}:${local.account_id}:listener/*/*/*/*"
  elb_listener_rule_arn_pattern = "arn:${local.partition}:elasticloadbalancing:${local.region}:${local.account_id}:listener-rule/*/*/*/*/*"

  cloudwatch_alarm_arn_pattern = "arn:${local.partition}:cloudwatch:${local.region}:${local.account_id}:alarm:*"

  lambda_function_arn_patterns = [
    "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:${var.environment}-*",
    "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:CodeDeployHook_*",
  ]

  ssm_parameter_arn_pattern = "arn:${local.partition}:ssm:${local.region}:${local.account_id}:parameter/${var.environment}/*"
  secret_arn_pattern        = "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:${var.environment}/*"
  ecr_repository_arn        = "arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/*"
  security_group_arn        = "arn:${local.partition}:ec2:${local.region}:${local.account_id}:security-group/*"

  codedeploy_application_arn       = "arn:${local.partition}:codedeploy:${local.region}:${local.account_id}:application:*"
  codedeploy_deployment_group_arn  = "arn:${local.partition}:codedeploy:${local.region}:${local.account_id}:deploymentgroup:*/*"
  codedeploy_deployment_config_arn = "arn:${local.partition}:codedeploy:${local.region}:${local.account_id}:deploymentconfig:*"

  artifacts_bucket_name = "${local.name_prefix}-artifacts-${local.account_id}-${local.region}"
}

# -----------------------------------------------------------------------------
# KMS
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowEcsTaskAndExecutionRolesUseOfKey"
    effect = "Allow"

    principals {
      type = "AWS"
      identifiers = [
        aws_iam_role.ecs_task_role.arn,
        aws_iam_role.ecs_exec_task_role.arn,
      ]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = [local.log_group_arn]
    }
  }
}

resource "aws_kms_key" "ecs" {
  description             = "KMS key for ${local.name_prefix} logs, artifacts, secrets and notifications"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms"
  })
}

resource "aws_kms_alias" "ecs" {
  name          = "alias/${var.environment}-ecs"
  target_key_id = aws_kms_key.ecs.key_id
}

# -----------------------------------------------------------------------------
# S3 artifacts bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "ecs_artifacts" {
  bucket        = local.artifacts_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.artifacts_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "ecs_artifacts" {
  bucket = aws_s3_bucket.ecs_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "ecs_artifacts" {
  bucket = aws_s3_bucket.ecs_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.ecs.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "ecs_artifacts" {
  bucket = aws_s3_bucket.ecs_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "ecs_artifacts_bucket_policy" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
      "s3:GetBucketPolicy",
      "s3:PutBucketPolicy",
      "s3:DeleteBucketPolicy",
      "s3:PutObjectTagging",
      "s3:GetObjectTagging",
      "s3:RestoreObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = [
      aws_s3_bucket.ecs_artifacts.arn,
      "${aws_s3_bucket.ecs_artifacts.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "ecs_artifacts" {
  bucket = aws_s3_bucket.ecs_artifacts.id
  policy = data.aws_iam_policy_document.ecs_artifacts_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.ecs_artifacts]
}

# -----------------------------------------------------------------------------
# CloudWatch Logs and SNS
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "ecs" {
  name              = local.log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.ecs.arn

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

resource "aws_sns_topic" "ecs_deployments" {
  name              = "${local.name_prefix}-deployments"
  kms_master_key_id = aws_kms_key.ecs.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-deployments"
  })
}

# -----------------------------------------------------------------------------
# ecsServiceRole
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_service_role_trust" {
  statement {
    sid     = "AllowEcsAndS3AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com", "s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "ecs_service_role" {
  name               = "ecsServiceRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_service_role_trust.json

  tags = merge(local.common_tags, {
    Name = "ecsServiceRole"
  })
}

data "aws_iam_policy_document" "ecs_task_role_policy" {
  statement {
    sid    = "ElbDescribe"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeTargetHealth",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeRules",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ElbTargetRegistration"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:DeregisterTargets",
    ]
    resources = [local.elb_target_group_arn_pattern]
  }

  statement {
    sid    = "Ec2Describe"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeVpcs",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "Ec2SecurityGroupIngress"
    effect    = "Allow"
    actions   = ["ec2:AuthorizeSecurityGroupIngress"]
    resources = [local.security_group_arn]
  }

  statement {
    sid    = "SsmParameterRead"
    effect = "Allow"
    actions = [
      "ssm:GetParameter",
      "ssm:GetParameters",
    ]
    resources = [local.ssm_parameter_arn_pattern]
  }

  statement {
    sid    = "SecretsManagerRead"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = [local.secret_arn_pattern]
  }

  statement {
    sid    = "KmsUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.ecs.arn]
  }

  statement {
    sid    = "CodeDeployDeployments"
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:GetApplication",
      "codedeploy:GetApplicationRevision",
      "codedeploy:RegisterApplicationRevision",
    ]
    resources = [
      local.codedeploy_application_arn,
      local.codedeploy_deployment_group_arn,
      local.codedeploy_deployment_config_arn,
    ]
  }

  statement {
    sid       = "SnsPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.ecs_deployments.arn]
  }

  statement {
    sid       = "CloudWatchDescribeAlarms"
    effect    = "Allow"
    actions   = ["cloudwatch:DescribeAlarms"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchManageAlarms"
    effect = "Allow"
    actions = [
      "cloudwatch:PutMetricAlarm",
      "cloudwatch:DeleteAlarms",
    ]
    resources = [local.cloudwatch_alarm_arn_pattern]
  }

  statement {
    sid       = "LambdaInvoke"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.lambda_function_arn_patterns
  }
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name   = "ecsTaskRolePolicy"
  role   = aws_iam_role.ecs_service_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_policy.json
}

# -----------------------------------------------------------------------------
# ecsExecTaskRole
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_exec_task_role_trust" {
  statement {
    sid     = "AllowEcsTasksAndS3AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ecs_tasks_principal, "s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "ecs_exec_task_role" {
  name               = "ecsExecTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_exec_task_role_trust.json

  tags = merge(local.common_tags, {
    Name = "ecsExecTaskRole"
  })
}

data "aws_iam_policy_document" "ecs_exec_role_policy" {
  statement {
    sid       = "EcrAuthorizationToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid    = "EcrImagePull"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
    ]
    resources = [local.ecr_repository_arn]
  }

  statement {
    sid       = "EcsDescribeServices"
    effect    = "Allow"
    actions   = ["ecs:DescribeServices"]
    resources = [local.ecs_service_arn_pattern]
  }

  statement {
    sid    = "CloudWatchLogsWrite"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]
    resources = [
      aws_cloudwatch_log_group.ecs.arn,
      "${aws_cloudwatch_log_group.ecs.arn}:log-stream:*",
    ]
  }

  statement {
    sid    = "SecretsManagerRead"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
    ]
    resources = [local.secret_arn_pattern]
  }

  statement {
    sid    = "KmsUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.ecs.arn]
  }

  statement {
    sid    = "SsmParameterRead"
    effect = "Allow"
    actions = [
      "ssm:GetParameter",
      "ssm:GetParameters",
    ]
    resources = [local.ssm_parameter_arn_pattern]
  }
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name   = "ecsExecRolePolicy"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_exec_role_policy.json
}

data "aws_iam_policy_document" "ecs_execution_additional" {
  statement {
    sid       = "EcsListServices"
    effect    = "Allow"
    actions   = ["ecs:ListServices"]
    resources = ["*"]
  }

  statement {
    sid       = "EcsDescribeServices"
    effect    = "Allow"
    actions   = ["ecs:DescribeServices"]
    resources = [local.ecs_service_arn_pattern]
  }

  statement {
    sid       = "S3ListArtifactsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.ecs_artifacts.arn]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = ["${aws_s3_bucket.ecs_artifacts.arn}/*"]
  }
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name   = "ecsExecution_additional"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_execution_additional.json
}

# -----------------------------------------------------------------------------
# ecsTaskRole
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_task_role_trust" {
  statement {
    sid     = "AllowEcsTasksAndS3AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ecs_tasks_principal, "s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "ecs_task_role" {
  name               = "ecsTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_role_trust.json

  tags = merge(local.common_tags, {
    Name = "ecsTaskRole"
  })
}

data "aws_iam_policy_document" "ecs_task_role_additional" {
  statement {
    sid       = "EcsListServices"
    effect    = "Allow"
    actions   = ["ecs:ListServices"]
    resources = ["*"]
  }

  statement {
    sid       = "EcsDescribeServices"
    effect    = "Allow"
    actions   = ["ecs:DescribeServices"]
    resources = [local.ecs_service_arn_pattern]
  }

  statement {
    sid       = "S3ListArtifactsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.ecs_artifacts.arn]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = ["${aws_s3_bucket.ecs_artifacts.arn}/*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name   = "ecsTaskRole_additional"
  role   = aws_iam_role.ecs_task_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_additional.json
}

# -----------------------------------------------------------------------------
# ecs_autoscale_role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_autoscale_role_trust" {
  statement {
    sid     = "AllowApplicationAutoscalingAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "ecs_autoscale_role" {
  name               = "ecs_autoscale_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_autoscale_role_trust.json

  tags = merge(local.common_tags, {
    Name = "ecs_autoscale_role"
  })
}

data "aws_iam_policy_document" "ecs_autoscale_role_policy" {
  statement {
    sid    = "EcsDescribeAndUpdateServices"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices",
      "ecs:UpdateService",
    ]
    resources = [local.ecs_service_arn_pattern]
  }

  statement {
    sid       = "CloudWatchDescribeAlarms"
    effect    = "Allow"
    actions   = ["cloudwatch:DescribeAlarms"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchManageAlarms"
    effect = "Allow"
    actions = [
      "cloudwatch:PutMetricAlarm",
      "cloudwatch:DeleteAlarms",
    ]
    resources = [local.cloudwatch_alarm_arn_pattern]
  }
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name   = "ecs_autoscale_role_policy"
  role   = aws_iam_role.ecs_autoscale_role.id
  policy = data.aws_iam_policy_document.ecs_autoscale_role_policy.json
}

# -----------------------------------------------------------------------------
# ecs_codedeploy_role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_codedeploy_role_trust" {
  statement {
    sid     = "AllowCodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "ecs_codedeploy_role" {
  name               = "ecs_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_codedeploy_role_trust.json

  tags = merge(local.common_tags, {
    Name = "ecs_codedeploy_role"
  })
}

resource "aws_iam_role_policy_attachment" "ecs_codedeploy_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

data "aws_iam_policy_document" "ecs_codedeploy_role_policy" {
  statement {
    sid    = "EcsTaskSetManagement"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices",
      "ecs:CreateTaskSet",
      "ecs:UpdateServicePrimaryTaskSet",
      "ecs:DeleteTaskSet",
    ]
    resources = [
      local.ecs_service_arn_pattern,
      local.ecs_task_set_arn_pattern,
    ]
  }

  statement {
    sid    = "ElbDescribe"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:DescribeTargetHealth",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ElbTrafficShift"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:ModifyRule",
    ]
    resources = [
      local.elb_listener_arn_pattern,
      local.elb_listener_rule_arn_pattern,
    ]
  }

  statement {
    sid       = "LambdaInvokeHooks"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.lambda_function_arn_patterns
  }

  statement {
    sid       = "CloudWatchDescribeAlarms"
    effect    = "Allow"
    actions   = ["cloudwatch:DescribeAlarms"]
    resources = ["*"]
  }

  statement {
    sid       = "SnsPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.ecs_deployments.arn]
  }

  statement {
    sid    = "S3ArtifactRead"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
    ]
    resources = ["${aws_s3_bucket.ecs_artifacts.arn}/*"]
  }

  statement {
    sid    = "KmsUseForArtifactsAndNotifications"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.ecs.arn]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name   = "ecs_codedeploy_role_policy"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy.json
}

data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task" {
  statement {
    sid       = "PassEcsTaskRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_task_role.arn]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = [local.ecs_tasks_principal]
    }
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name   = "ecs_codedeploy_role_policy_task"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task.json
}

data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task_exec" {
  statement {
    sid       = "PassEcsExecTaskRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_exec_task_role.arn]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = [local.ecs_tasks_principal]
    }
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name   = "ecs_codedeploy_role_policy_task_exec"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task_exec.json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "ecs_service_role_arn" {
  description = "ARN of the ecsServiceRole IAM role."
  value       = aws_iam_role.ecs_service_role.arn
}

output "ecs_service_role_name" {
  description = "Name of the ecsServiceRole IAM role."
  value       = aws_iam_role.ecs_service_role.name
}

output "ecs_exec_task_role_arn" {
  description = "ARN of the ecsExecTaskRole IAM role (task execution role)."
  value       = aws_iam_role.ecs_exec_task_role.arn
}

output "ecs_exec_task_role_name" {
  description = "Name of the ecsExecTaskRole IAM role."
  value       = aws_iam_role.ecs_exec_task_role.name
}

output "ecs_task_role_arn" {
  description = "ARN of the ecsTaskRole IAM role."
  value       = aws_iam_role.ecs_task_role.arn
}

output "ecs_task_role_name" {
  description = "Name of the ecsTaskRole IAM role."
  value       = aws_iam_role.ecs_task_role.name
}

output "ecs_autoscale_role_arn" {
  description = "ARN of the ecs_autoscale_role IAM role."
  value       = aws_iam_role.ecs_autoscale_role.arn
}

output "ecs_autoscale_role_name" {
  description = "Name of the ecs_autoscale_role IAM role."
  value       = aws_iam_role.ecs_autoscale_role.name
}

output "ecs_codedeploy_role_arn" {
  description = "ARN of the ecs_codedeploy_role IAM role."
  value       = aws_iam_role.ecs_codedeploy_role.arn
}

output "ecs_codedeploy_role_name" {
  description = "Name of the ecs_codedeploy_role IAM role."
  value       = aws_iam_role.ecs_codedeploy_role.name
}

output "ecs_artifacts_bucket_id" {
  description = "ID (name) of the ECS artifacts S3 bucket."
  value       = aws_s3_bucket.ecs_artifacts.id
}

output "ecs_kms_key_arn" {
  description = "ARN of the ECS KMS key."
  value       = aws_kms_key.ecs.arn
}

output "ecs_deployments_sns_topic_arn" {
  description = "ARN of the ECS deployments SNS topic."
  value       = aws_sns_topic.ecs_deployments.arn
}

output "ecs_log_group_name" {
  description = "Name of the ECS CloudWatch log group."
  value       = aws_cloudwatch_log_group.ecs.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Deployment environment used for tagging"
  type        = string
  default     = "prod"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  any_ipv4_cidr = "0.0.0.0/0"

  external_vpc_cidr = "10.41.0.0/16"
  internal_vpc_cidr = "10.40.0.0/16"

  external_subnets = [
    { cidr = "10.41.0.0/24", name = "Subnet0-1a" },
    { cidr = "10.41.1.0/24", name = "Subnet1-1b" },
    { cidr = "10.41.2.0/24", name = "Subnet2-1c" },
    { cidr = "10.41.3.0/24", name = "Subnet3-1d" },
  ]

  internal_subnets = [
    { cidr = "10.40.0.0/24", name = "Subnet0-1a" },
    { cidr = "10.40.1.0/24", name = "Subnet1-1b" },
    { cidr = "10.40.2.0/24", name = "Subnet2-1c" },
    { cidr = "10.40.3.0/24", name = "Subnet3-1d" },
  ]

  common_tags = {
    environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# External VPC (public-facing)
# -----------------------------------------------------------------------------

resource "aws_vpc" "external" {
  cidr_block           = local.external_vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name    = "Production External"
    purpose = "Production External VPC"
  })
}

resource "aws_default_security_group" "external_default" {
  vpc_id = aws_vpc.external.id

  tags = merge(local.common_tags, {
    Name = "Production External Default SG"
  })
}

resource "aws_subnet" "external" {
  count = length(local.external_subnets)

  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnets[count.index].cidr
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = local.external_subnets[count.index].name
  })
}

resource "aws_internet_gateway" "external_gw" {
  vpc_id = aws_vpc.external.id

  tags = merge(local.common_tags, {
    Name = "External GW"
  })
}

resource "aws_route_table" "external_public" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.external_gw.id
  }

  tags = merge(local.common_tags, {
    Name = "Production External Public RT"
  })
}

resource "aws_main_route_table_association" "external_main" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external_public.id
}

resource "aws_route_table_association" "external" {
  count = length(local.external_subnets)

  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external_public.id
}

resource "aws_default_network_acl" "external_default" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id
  subnet_ids             = aws_subnet.external[*].id

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = local.any_ipv4_cidr
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = local.any_ipv4_cidr
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = local.any_ipv4_cidr
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "Production External Default NACL"
  })
}

# -----------------------------------------------------------------------------
# Internal VPC (isolated: no IGW, no NAT, no peering, no internet routes)
# -----------------------------------------------------------------------------

resource "aws_vpc" "internal" {
  cidr_block           = local.internal_vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = false

  tags = merge(local.common_tags, {
    Name    = "Production Internal"
    purpose = "Production Internal VPC"
  })
}

resource "aws_default_security_group" "internal_default" {
  vpc_id = aws_vpc.internal.id

  tags = merge(local.common_tags, {
    Name = "Production Internal Default SG"
  })
}

resource "aws_subnet" "internal" {
  count = length(local.internal_subnets)

  vpc_id                  = aws_vpc.internal.id
  cidr_block              = local.internal_subnets[count.index].cidr
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = local.internal_subnets[count.index].name
  })
}

resource "aws_default_network_acl" "internal_default" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id
  subnet_ids             = aws_subnet.internal[*].id

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = local.any_ipv4_cidr
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = local.any_ipv4_cidr
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = local.any_ipv4_cidr
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  tags = merge(local.common_tags, {
    Name = "Production Internal Default NACL"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "external_vpc_id" {
  description = "ID of the production external VPC"
  value       = aws_vpc.external.id
}

output "internal_vpc_id" {
  description = "ID of the production internal VPC"
  value       = aws_vpc.internal.id
}

output "external_subnet_ids" {
  description = "IDs of the external VPC subnets"
  value       = aws_subnet.external[*].id
}

output "internal_subnet_ids" {
  description = "IDs of the internal VPC subnets"
  value       = aws_subnet.internal[*].id
}

output "external_internet_gateway_id" {
  description = "ID of the external VPC internet gateway"
  value       = aws_internet_gateway.external_gw.id
}

output "external_public_route_table_id" {
  description = "ID of the external VPC public (main) route table"
  value       = aws_route_table.external_public.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "prefix" {
  description = "Prefix used for naming and tagging all resources."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN for the HTTPS listener. When null, a self-signed certificate is generated and imported into ACM."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional public URL override for n8n webhooks. When null, the HTTPS load balancer endpoint is used."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of n8n ECS tasks."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "n8n container image."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider to use (FARGATE or FARGATE_SPOT)."
  type        = string
  default     = "FARGATE_SPOT"

  validation {
    condition     = contains(["FARGATE", "FARGATE_SPOT"], var.fargate_type)
    error_message = "fargate_type must be either \"FARGATE\" or \"FARGATE_SPOT\"."
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  vpc_cidr             = "10.0.0.0/16"
  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
    data.aws_availability_zones.available.names[2],
  ]

  container_name = "n8n"
  container_port = 5678
  volume_name    = "n8n-data"
  ecs_principal  = "ecs-tasks.amazonaws.com"
  any_ipv4       = "0.0.0.0/0"

  certificate_arn = coalesce(var.certificate_arn, one(aws_acm_certificate.self_signed[*].arn))
  webhook_url     = coalesce(var.url, "https://${aws_lb.main.dns_name}/")
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.prefix}-private-${count.index + 1}"
  }
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.prefix}-public-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = length(local.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = length(local.private_subnet_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups
#
# NOTE: Limiting all egress to the VPC CIDR, with no NAT gateway and no VPC
# endpoints, blocks the ECS tasks from pulling the n8nio/n8n image from Docker
# Hub and from reaching the CloudWatch Logs and EFS IAM (STS/elasticfilesystem)
# endpoints. This rule is kept because the request explicitly requires that all
# security groups limit outbound traffic to the VPC CIDR.
# -----------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${var.prefix}-alb-sg"
  description = "n8n load balancer security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.any_ipv4]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.any_ipv4]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-alb-sg"
  }
}

resource "aws_security_group" "service" {
  name        = "${var.prefix}-service-sg"
  description = "n8n ECS service security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n port from the load balancer only"
    from_port       = local.container_port
    to_port         = local.container_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-service-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.prefix}-efs-sg"
  description = "n8n EFS mount target security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-efs-sg"
  }
}

# -----------------------------------------------------------------------------
# Application Load Balancer
# -----------------------------------------------------------------------------

resource "aws_lb" "main" {
  name                       = "${var.prefix}-alb"
  load_balancer_type         = "application"
  internal                   = true
  drop_invalid_header_fields = true
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id

  tags = {
    Name = "${var.prefix}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name                 = "${var.prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = {
    Name = "${var.prefix}-tg"
  }
}

resource "tls_private_key" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key_pem       = tls_private_key.self_signed[0].private_key_pem
  validity_period_hours = 8760

  subject {
    common_name  = aws_lb.main.dns_name
    organization = var.prefix
  }

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = "${var.prefix}-self-signed-cert"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name = "${var.prefix}-https-listener"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      protocol    = "HTTPS"
      port        = "443"
      status_code = "HTTP_301"
    }
  }

  tags = {
    Name = "${var.prefix}-http-listener"
  }
}

# -----------------------------------------------------------------------------
# EFS
# -----------------------------------------------------------------------------

resource "aws_efs_file_system" "main" {
  creation_token = "${var.prefix}-efs"
  encrypted      = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.prefix}-efs"
  }
}

resource "aws_efs_mount_target" "main" {
  count = length(local.private_subnet_cidrs)

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${var.prefix}-efs-ap"
  }
}

# -----------------------------------------------------------------------------
# Logging
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.prefix}-logs"
  retention_in_days = 1

  tags = {
    Name = "${var.prefix}-logs"
  }
}

# -----------------------------------------------------------------------------
# IAM
# -----------------------------------------------------------------------------

resource "aws_iam_role" "task_execution" {
  name = "${var.prefix}-task-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = local.ecs_principal }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.prefix}-task-execution-role"
  }
}

resource "aws_iam_role" "task" {
  name = "${var.prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = local.ecs_principal }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.prefix}-task-role"
  }
}

resource "aws_iam_role_policy" "task_execution_logs" {
  name = "${var.prefix}-task-execution-logs"
  role = aws_iam_role.task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*",
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${var.prefix}-task-logs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*",
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_efs" {
  name = "${var.prefix}-task-efs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
        ]
        Resource = aws_efs_file_system.main.arn
        Condition = {
          StringEquals = {
            "elasticfilesystem:AccessPointArn" = aws_efs_access_point.n8n.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# ECS
# -----------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = "${var.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${var.prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_ecs_task_definition" "n8n" {
  family                   = "${var.prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.task_execution.arn
  task_role_arn            = aws_iam_role.task.arn

  runtime_platform {
    operating_system_family = "LINUX"
    cpu_architecture        = "X86_64"
  }

  volume {
    name = local.volume_name

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = local.container_name
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = local.container_port
          hostPort      = local.container_port
          protocol      = "tcp"
        }
      ]

      mountPoints = [
        {
          sourceVolume  = local.volume_name
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = var.prefix
        }
      }
    }
  ])

  tags = {
    Name = "${var.prefix}-task"
  }
}

resource "aws_ecs_service" "n8n" {
  name                              = "${var.prefix}-service"
  cluster                           = aws_ecs_cluster.main.id
  task_definition                   = aws_ecs_task_definition.n8n.arn
  desired_count                     = var.desired_count
  platform_version                  = "1.4.0"
  health_check_grace_period_seconds = 60

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.service.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = local.container_name
    container_port   = local.container_port
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
    aws_efs_mount_target.main,
    aws_ecs_cluster_capacity_providers.main,
  ]

  tags = {
    Name = "${var.prefix}-service"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "alb_dns_name" {
  description = "DNS name of the internal Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "webhook_url" {
  description = "Effective n8n webhook URL."
  value       = local.webhook_url
}

output "efs_file_system_id" {
  description = "ID of the EFS file system backing n8n data."
  value       = aws_efs_file_system.main.id
}

output "ecs_cluster_name" {
  description = "Name of the ECS cluster."
  value       = aws_ecs_cluster.main.name
}

output "ecs_service_name" {
  description = "Name of the ECS service."
  value       = aws_ecs_service.n8n.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The deployment harness supplies the AWS provider configuration (region us-east-1).

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "lambda-rds-dev"
  vpc_cidr    = "10.32.0.0/20"

  common_tags = {
    Environment = var.environment
    Project     = "lambda-rds"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  instance_tenancy     = "default"

  tags = merge(local.common_tags, {
    Name = local.name_prefix
  })
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default-sg"
  })
}

resource "aws_subnet" "db_subnet_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "lambda-rds-db-subnet-1"
  })
}

resource "aws_subnet" "db_subnet_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "lambda-rds-db-subnet-2"
  })
}

resource "aws_subnet" "lambda_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-lambda-subnet"
  })
}

resource "aws_subnet" "bastion_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "lambda-rds-bastion-host-subnet"
  })
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  subnet_ids = [
    aws_subnet.db_subnet_1.id,
    aws_subnet.db_subnet_2.id,
    aws_subnet.lambda_subnet.id,
    aws_subnet.bastion_subnet.id,
  ]

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default-nacl"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "lambda-rds-public-subnet"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "bastion_public" {
  subnet_id      = aws_subnet.bastion_subnet.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "postgres_db" {
  name        = "${local.name_prefix}-postgres-db"
  description = "PostgreSQL database access from bastion host and Lambda functions"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-postgres-db"
  })
}

resource "aws_security_group" "lambda_functions" {
  name        = "${local.name_prefix}-lambda-functions"
  description = "Lambda functions with egress restricted to the VPC"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-lambda-functions"
  })
}

resource "aws_security_group" "bastion_host" {
  name        = "${local.name_prefix}-bastion-host"
  description = "Bastion host with SSH from the VPC and egress only to PostgreSQL"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-bastion-host"
  })
}

resource "aws_vpc_security_group_ingress_rule" "postgres_from_bastion" {
  security_group_id            = aws_security_group.postgres_db.id
  description                  = "PostgreSQL from bastion host"
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  referenced_security_group_id = aws_security_group.bastion_host.id

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "postgres_from_lambda" {
  security_group_id            = aws_security_group.postgres_db.id
  description                  = "PostgreSQL from Lambda functions"
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  referenced_security_group_id = aws_security_group.lambda_functions.id

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "postgres_egress_vpc" {
  security_group_id = aws_security_group.postgres_db.id
  description       = "Egress restricted to the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "lambda_egress_vpc" {
  security_group_id = aws_security_group.lambda_functions.id
  description       = "Egress restricted to the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = local.common_tags
}

resource "aws_vpc_security_group_ingress_rule" "bastion_ssh_from_vpc" {
  security_group_id = aws_security_group.bastion_host.id
  description       = "SSH from within the VPC only"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "bastion_to_postgres" {
  security_group_id            = aws_security_group.bastion_host.id
  description                  = "PostgreSQL to the database security group only"
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
  referenced_security_group_id = aws_security_group.postgres_db.id

  tags = local.common_tags
}

output "vpc_id" {
  description = "ID of the lambda-rds-dev VPC"
  value       = aws_vpc.main.id
}

output "db_subnet_ids" {
  description = "IDs of the database subnets, ready for an aws_db_subnet_group"
  value       = [aws_subnet.db_subnet_1.id, aws_subnet.db_subnet_2.id]
}

output "lambda_subnet_id" {
  description = "ID of the Lambda subnet"
  value       = aws_subnet.lambda_subnet.id
}

output "bastion_subnet_id" {
  description = "ID of the bastion host subnet"
  value       = aws_subnet.bastion_subnet.id
}

output "postgres_db_security_group_id" {
  description = "ID of the PostgreSQL database security group"
  value       = aws_security_group.postgres_db.id
}

output "lambda_functions_security_group_id" {
  description = "ID of the Lambda functions security group"
  value       = aws_security_group.lambda_functions.id
}

output "bastion_host_security_group_id" {
  description = "ID of the bastion host security group"
  value       = aws_security_group.bastion_host.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }

  vpc_cidr         = "10.255.0.0/16"
  admin_cidr       = "203.0.113.0/24"
  anywhere_ipv4    = "0.0.0.0/0"
  rds_1a_cidr      = "10.255.100.0/24"
  rds_1e_cidr      = "10.255.101.0/24"
  ssh_port         = 22
  http_port        = 80
  https_port       = 443
  jenkins_port     = 8080
  postgres_port    = 5432
  tcp_protocol     = "tcp"
  all_protocols    = "-1"
  egress_rule_desc = "Allow all outbound traffic restricted to the Quasar VPC CIDR"
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "quasar" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

################################################################################
# Subnets for Multi-AZ RDS
################################################################################

resource "aws_subnet" "rds_1a" {
  vpc_id                  = aws_vpc.quasar.id
  cidr_block              = local.rds_1a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id                  = aws_vpc.quasar.id
  cidr_block              = local.rds_1e_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_db_subnet_group" "quasar_rds" {
  name        = "quasar-rds"
  description = "Quasar multi-AZ RDS subnet group"
  subnet_ids  = [aws_subnet.rds_1a.id, aws_subnet.rds_1e.id]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS"
  })
}

################################################################################
# Security Groups
################################################################################

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Quasar bastion host - SSH access from the admin network"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "Quasar HA-Proxy load balancer - public HTTP/HTTPS and bastion SSH"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Quasar Jenkins CI/CD - bastion SSH and HA-Proxy web traffic"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "Quasar ETL compute nodes - SSH from bastion and Jenkins"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "Quasar PostgreSQL databases - PostgreSQL client access"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

################################################################################
# Egress Rules (restricted to VPC CIDR)
################################################################################

resource "aws_vpc_security_group_egress_rule" "bastion_egress_vpc" {
  security_group_id = aws_security_group.bastion.id
  description       = local.egress_rule_desc
  ip_protocol       = local.all_protocols
  cidr_ipv4         = aws_vpc.quasar.cidr_block

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion egress to VPC"
  })
}

resource "aws_vpc_security_group_egress_rule" "ha_proxy_egress_vpc" {
  security_group_id = aws_security_group.ha_proxy.id
  description       = local.egress_rule_desc
  ip_protocol       = local.all_protocols
  cidr_ipv4         = aws_vpc.quasar.cidr_block

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy egress to VPC"
  })
}

resource "aws_vpc_security_group_egress_rule" "jenkins_egress_vpc" {
  security_group_id = aws_security_group.jenkins.id
  description       = local.egress_rule_desc
  ip_protocol       = local.all_protocols
  cidr_ipv4         = aws_vpc.quasar.cidr_block

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins egress to VPC"
  })
}

resource "aws_vpc_security_group_egress_rule" "etl_egress_vpc" {
  security_group_id = aws_security_group.etl.id
  description       = local.egress_rule_desc
  ip_protocol       = local.all_protocols
  cidr_ipv4         = aws_vpc.quasar.cidr_block

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL egress to VPC"
  })
}

resource "aws_vpc_security_group_egress_rule" "postgresql_egress_vpc" {
  security_group_id = aws_security_group.postgresql.id
  description       = local.egress_rule_desc
  ip_protocol       = local.all_protocols
  cidr_ipv4         = aws_vpc.quasar.cidr_block

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL egress to VPC"
  })
}

################################################################################
# Bastion Ingress
################################################################################

resource "aws_vpc_security_group_ingress_rule" "bastion_ssh_from_admin" {
  security_group_id = aws_security_group.bastion.id
  description       = "SSH from placeholder admin range (RFC 5737 TEST-NET-3) - replace before production use"
  ip_protocol       = local.tcp_protocol
  from_port         = local.ssh_port
  to_port           = local.ssh_port
  cidr_ipv4         = local.admin_cidr

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion SSH from admin"
  })
}

################################################################################
# HA-Proxy Ingress
################################################################################

resource "aws_vpc_security_group_ingress_rule" "ha_proxy_http_from_anywhere" {
  security_group_id = aws_security_group.ha_proxy.id
  description       = "HTTP from anywhere"
  ip_protocol       = local.tcp_protocol
  from_port         = local.http_port
  to_port           = local.http_port
  cidr_ipv4         = local.anywhere_ipv4

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy HTTP from anywhere"
  })
}

resource "aws_vpc_security_group_ingress_rule" "ha_proxy_https_from_anywhere" {
  security_group_id = aws_security_group.ha_proxy.id
  description       = "HTTPS from anywhere"
  ip_protocol       = local.tcp_protocol
  from_port         = local.https_port
  to_port           = local.https_port
  cidr_ipv4         = local.anywhere_ipv4

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy HTTPS from anywhere"
  })
}

resource "aws_vpc_security_group_ingress_rule" "ha_proxy_ssh_from_bastion" {
  security_group_id            = aws_security_group.ha_proxy.id
  description                  = "SSH from the Quasar bastion security group"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.ssh_port
  to_port                      = local.ssh_port
  referenced_security_group_id = aws_security_group.bastion.id

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy SSH from bastion"
  })
}

################################################################################
# Jenkins Ingress
################################################################################

resource "aws_vpc_security_group_ingress_rule" "jenkins_ssh_from_bastion" {
  security_group_id            = aws_security_group.jenkins.id
  description                  = "SSH from the Quasar bastion security group"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.ssh_port
  to_port                      = local.ssh_port
  referenced_security_group_id = aws_security_group.bastion.id

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins SSH from bastion"
  })
}

resource "aws_vpc_security_group_ingress_rule" "jenkins_8080_from_ha_proxy" {
  security_group_id            = aws_security_group.jenkins.id
  description                  = "Jenkins web UI (8080) from the Quasar HA-Proxy security group"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.jenkins_port
  to_port                      = local.jenkins_port
  referenced_security_group_id = aws_security_group.ha_proxy.id

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins 8080 from HA-Proxy"
  })
}

################################################################################
# ETL Ingress
################################################################################

resource "aws_vpc_security_group_ingress_rule" "etl_ssh_from_bastion" {
  security_group_id            = aws_security_group.etl.id
  description                  = "SSH from the Quasar bastion security group"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.ssh_port
  to_port                      = local.ssh_port
  referenced_security_group_id = aws_security_group.bastion.id

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL SSH from bastion"
  })
}

resource "aws_vpc_security_group_ingress_rule" "etl_ssh_from_jenkins" {
  security_group_id            = aws_security_group.etl.id
  description                  = "SSH from the Quasar Jenkins security group"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.ssh_port
  to_port                      = local.ssh_port
  referenced_security_group_id = aws_security_group.jenkins.id

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL SSH from Jenkins"
  })
}

################################################################################
# PostgreSQL Ingress
################################################################################

resource "aws_vpc_security_group_ingress_rule" "postgresql_from_anywhere" {
  security_group_id = aws_security_group.postgresql.id
  description       = "PostgreSQL from anywhere (as requested)"
  ip_protocol       = local.tcp_protocol
  from_port         = local.postgres_port
  to_port           = local.postgres_port
  cidr_ipv4         = local.anywhere_ipv4

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL 5432 from anywhere"
  })
}

resource "aws_vpc_security_group_ingress_rule" "postgresql_from_etl" {
  security_group_id            = aws_security_group.postgresql.id
  description                  = "PostgreSQL from the Quasar ETL security group"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.postgres_port
  to_port                      = local.postgres_port
  referenced_security_group_id = aws_security_group.etl.id

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL 5432 from ETL"
  })
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the Quasar VPC"
  value       = aws_vpc.quasar.id
}

output "rds_subnet_ids" {
  description = "IDs of the Quasar RDS subnets"
  value       = [aws_subnet.rds_1a.id, aws_subnet.rds_1e.id]
}

output "db_subnet_group_name" {
  description = "Name of the Quasar RDS DB subnet group"
  value       = aws_db_subnet_group.quasar_rds.name
}

output "security_group_ids" {
  description = "IDs of the Quasar security groups"
  value = {
    bastion    = aws_security_group.bastion.id
    ha_proxy   = aws_security_group.ha_proxy.id
    jenkins    = aws_security_group.jenkins.id
    etl        = aws_security_group.etl.id
    postgresql = aws_security_group.postgresql.id
  }
}

# Amazon SQS queue module with optional DLQ, redrive and queue policies.
# NOTE: The AWS provider configuration (region = "us-east-1") is injected by the
# deployment harness, so no provider block is declared here.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# General
################################################################################

variable "create" {
  description = "Whether to create any SQS resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Human-readable name of the queue. Any trailing .fifo suffix is stripped and re-added automatically when fifo_queue is true"
  type        = string
  default     = "app-queue"
}

variable "use_name_prefix" {
  description = "Whether to use name as a prefix (name_prefix) instead of an exact queue name"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to all queues"
  type        = map(string)
  default     = {}
}

################################################################################
# FIFO settings
################################################################################

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = null
}

variable "deduplication_scope" {
  description = "Whether message deduplication occurs at the message group or queue level (messageGroup or queue). FIFO only"
  type        = string
  default     = null

  validation {
    condition     = var.deduplication_scope == null ? true : contains(["messageGroup", "queue"], var.deduplication_scope)
    error_message = "deduplication_scope must be one of: messageGroup, queue."
  }
}

variable "fifo_throughput_limit" {
  description = "Whether the FIFO throughput quota applies per queue or per message group (perQueue or perMessageGroupId). FIFO only"
  type        = string
  default     = null

  validation {
    condition     = var.fifo_throughput_limit == null ? true : contains(["perQueue", "perMessageGroupId"], var.fifo_throughput_limit)
    error_message = "fifo_throughput_limit must be one of: perQueue, perMessageGroupId."
  }
}

################################################################################
# Standard queue settings
################################################################################

variable "delay_seconds" {
  description = "Time in seconds that delivery of all messages is delayed (0-900)"
  type        = number
  default     = 0

  validation {
    condition     = var.delay_seconds >= 0 && var.delay_seconds <= 900
    error_message = "delay_seconds must be between 0 and 900."
  }
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024-262144)"
  type        = number
  default     = 262144

  validation {
    condition     = var.max_message_size >= 1024 && var.max_message_size <= 262144
    error_message = "max_message_size must be between 1024 and 262144."
  }
}

variable "message_retention_seconds" {
  description = "Seconds SQS retains a message (60-1209600)"
  type        = number
  default     = 345600

  validation {
    condition     = var.message_retention_seconds >= 60 && var.message_retention_seconds <= 1209600
    error_message = "message_retention_seconds must be between 60 and 1209600."
  }
}

variable "receive_wait_time_seconds" {
  description = "Long polling wait time in seconds (0-20)"
  type        = number
  default     = 0

  validation {
    condition     = var.receive_wait_time_seconds >= 0 && var.receive_wait_time_seconds <= 20
    error_message = "receive_wait_time_seconds must be between 0 and 20."
  }
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds (0-43200)"
  type        = number
  default     = 30

  validation {
    condition     = var.visibility_timeout_seconds >= 0 && var.visibility_timeout_seconds <= 43200
    error_message = "visibility_timeout_seconds must be between 0 and 43200."
  }
}

################################################################################
# Encryption
################################################################################

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed server-side encryption (SSE-SQS). Ignored when kms_master_key_id is set"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "ID or alias of a KMS key for SSE-KMS. When set, SSE-SQS is disabled"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Seconds SQS can reuse a data key before calling KMS again (60-86400). Only used with kms_master_key_id"
  type        = number
  default     = null

  validation {
    condition     = var.kms_data_key_reuse_period_seconds == null ? true : (var.kms_data_key_reuse_period_seconds >= 60 && var.kms_data_key_reuse_period_seconds <= 86400)
    error_message = "kms_data_key_reuse_period_seconds must be between 60 and 86400."
  }
}

################################################################################
# Main queue policy
################################################################################

variable "create_queue_policy" {
  description = "Whether to create an SQS queue policy for the main queue"
  type        = bool
  default     = false
}

variable "source_queue_policy_documents" {
  description = "IAM policy documents (JSON) merged into the main queue policy. Statements need unique SIDs"
  type        = list(string)
  default     = []
}

variable "override_queue_policy_documents" {
  description = "IAM policy documents (JSON) whose statements override same-SID statements in the main queue policy"
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "Map of custom IAM statements for the main queue policy. Each needs specific SQS actions; resources default to the main queue ARN"
  type        = any
  default     = {}

  validation {
    condition = alltrue([
      for s in values(var.queue_policy_statements) :
      !contains(try(s.actions, []), "*") && !contains(try(s.actions, []), "sqs:*")
    ])
    error_message = "queue_policy_statements must name specific SQS actions; wildcard actions are not allowed."
  }
}

################################################################################
# Dead-letter queue
################################################################################

variable "create_dlq" {
  description = "Whether to create a dead-letter queue aligned with the main queue"
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "DLQ name. Defaults to \"<name>-dlq\" (plus .fifo for FIFO queues)"
  type        = string
  default     = null
}

variable "dlq_content_based_deduplication" {
  description = "Override content-based deduplication for the DLQ (inherits main queue when null)"
  type        = bool
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "Override deduplication scope for the DLQ (inherits main queue when null)"
  type        = string
  default     = null
}

variable "dlq_fifo_throughput_limit" {
  description = "Override the FIFO throughput limit for the DLQ (inherits main queue when null)"
  type        = string
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Override delay_seconds for the DLQ (inherits main queue when null)"
  type        = number
  default     = null
}

variable "dlq_max_message_size" {
  description = "Override max_message_size for the DLQ (inherits main queue when null)"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Override message_retention_seconds for the DLQ (inherits main queue when null)"
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Override receive_wait_time_seconds for the DLQ (inherits main queue when null)"
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Override visibility_timeout_seconds for the DLQ (inherits main queue when null)"
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Override SSE-SQS for the DLQ (inherits main queue when null)"
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "Override the KMS key for the DLQ (inherits main queue when null)"
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "Override the KMS data key reuse period for the DLQ (inherits main queue when null)"
  type        = number
  default     = null
}

variable "dlq_tags" {
  description = "Extra tags for the DLQ, merged over var.tags"
  type        = map(string)
  default     = {}
}

################################################################################
# Redrive / redrive allow policies
################################################################################

variable "redrive_policy" {
  description = "Extra redrive policy attributes merged over the defaults (deadLetterTargetArn = DLQ ARN, maxReceiveCount = 5)"
  type        = any
  default     = {}
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the DLQ that allows only the source queue (byQueue)"
  type        = bool
  default     = true
}

variable "dlq_redrive_allow_policy" {
  description = "Extra redrive allow policy attributes merged over the defaults (redrivePermission = byQueue, sourceQueueArns = [main queue ARN])"
  type        = any
  default     = {}
}

################################################################################
# DLQ queue policy
################################################################################

variable "create_dlq_queue_policy" {
  description = "Whether to create an SQS queue policy for the DLQ"
  type        = bool
  default     = false
}

variable "source_dlq_queue_policy_documents" {
  description = "IAM policy documents (JSON) merged into the DLQ policy. Statements need unique SIDs"
  type        = list(string)
  default     = []
}

variable "override_dlq_queue_policy_documents" {
  description = "IAM policy documents (JSON) whose statements override same-SID statements in the DLQ policy"
  type        = list(string)
  default     = []
}

variable "dlq_queue_policy_statements" {
  description = "Map of custom IAM statements for the DLQ policy. Each needs specific SQS actions; resources default to the DLQ ARN"
  type        = any
  default     = {}

  validation {
    condition = alltrue([
      for s in values(var.dlq_queue_policy_statements) :
      !contains(try(s.actions, []), "*") && !contains(try(s.actions, []), "sqs:*")
    ])
    error_message = "dlq_queue_policy_statements must name specific SQS actions; wildcard actions are not allowed."
  }
}

################################################################################
# Locals
################################################################################

locals {
  fifo_suffix = ".fifo"

  base_name = trimsuffix(var.name, local.fifo_suffix)

  # Exact name gets .fifo for FIFO queues. For name_prefix, the AWS provider
  # appends .fifo after the generated unique ID, so the prefix must not include it.
  name        = var.fifo_queue ? "${local.base_name}${local.fifo_suffix}" : local.base_name
  name_prefix = "${local.base_name}-"

  queue_name        = var.use_name_prefix ? null : local.name
  queue_name_prefix = var.use_name_prefix ? local.name_prefix : null

  # Main queue encryption: a custom KMS key disables SSE-SQS
  sqs_managed_sse_enabled           = var.kms_master_key_id != null ? null : var.sqs_managed_sse_enabled
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null

  # DLQ naming
  dlq_base_name   = trimsuffix(coalesce(var.dlq_name, "${local.base_name}-dlq"), local.fifo_suffix)
  dlq_name        = var.fifo_queue ? "${local.dlq_base_name}${local.fifo_suffix}" : local.dlq_base_name
  dlq_name_prefix = "${local.dlq_base_name}-"

  dlq_queue_name        = var.use_name_prefix ? null : local.dlq_name
  dlq_queue_name_prefix = var.use_name_prefix ? local.dlq_name_prefix : null

  # DLQ FIFO settings inherit from the main queue unless overridden
  dlq_content_based_deduplication = var.fifo_queue ? try(coalesce(var.dlq_content_based_deduplication, var.content_based_deduplication), null) : null
  dlq_deduplication_scope         = var.fifo_queue ? try(coalesce(var.dlq_deduplication_scope, var.deduplication_scope), null) : null
  dlq_fifo_throughput_limit       = var.fifo_queue ? try(coalesce(var.dlq_fifo_throughput_limit, var.fifo_throughput_limit), null) : null

  # DLQ standard settings inherit from the main queue unless overridden
  dlq_delay_seconds              = try(coalesce(var.dlq_delay_seconds, var.delay_seconds), var.delay_seconds)
  dlq_max_message_size           = try(coalesce(var.dlq_max_message_size, var.max_message_size), var.max_message_size)
  dlq_message_retention_seconds  = try(coalesce(var.dlq_message_retention_seconds, var.message_retention_seconds), var.message_retention_seconds)
  dlq_receive_wait_time_seconds  = try(coalesce(var.dlq_receive_wait_time_seconds, var.receive_wait_time_seconds), var.receive_wait_time_seconds)
  dlq_visibility_timeout_seconds = try(coalesce(var.dlq_visibility_timeout_seconds, var.visibility_timeout_seconds), var.visibility_timeout_seconds)

  # DLQ encryption inherits the main queue's base encryption unless overridden
  dlq_kms_master_key_id                 = try(coalesce(var.dlq_kms_master_key_id, var.kms_master_key_id), null)
  dlq_sqs_managed_sse_enabled           = local.dlq_kms_master_key_id != null ? null : try(coalesce(var.dlq_sqs_managed_sse_enabled, var.sqs_managed_sse_enabled), true)
  dlq_kms_data_key_reuse_period_seconds = local.dlq_kms_master_key_id != null ? try(coalesce(var.dlq_kms_data_key_reuse_period_seconds, var.kms_data_key_reuse_period_seconds), null) : null

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  default_queue_actions = [
    "sqs:SendMessage",
    "sqs:ReceiveMessage",
    "sqs:DeleteMessage",
    "sqs:GetQueueAttributes",
    "sqs:GetQueueUrl",
  ]

  default_max_receive_count = 5
}

################################################################################
# Static metadata
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

################################################################################
# Main queue
################################################################################

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = local.kms_data_key_reuse_period_seconds

  tags = var.tags

  lifecycle {
    prevent_destroy = true

    # The redrive policy is managed by aws_sqs_queue_redrive_policy.this
    ignore_changes = [redrive_policy]
  }
}

################################################################################
# Main queue policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  # Baseline statement: only this account may use the queue
  statement {
    sid       = "AccountAccess"
    effect    = "Allow"
    actions   = local.default_queue_actions
    resources = [aws_sqs_queue.this[0].arn]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = try(statement.value.sid, statement.key)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, "Allow")
      resources     = try(statement.value.resources, [aws_sqs_queue.this[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, statement.value.condition, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Dead-letter queue
################################################################################

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_queue_name
  name_prefix = local.dlq_queue_name_prefix

  # A FIFO source queue always requires a FIFO DLQ
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = local.dlq_content_based_deduplication
  deduplication_scope         = local.dlq_deduplication_scope
  fifo_throughput_limit       = local.dlq_fifo_throughput_limit

  delay_seconds              = local.dlq_delay_seconds
  max_message_size           = local.dlq_max_message_size
  message_retention_seconds  = local.dlq_message_retention_seconds
  receive_wait_time_seconds  = local.dlq_receive_wait_time_seconds
  visibility_timeout_seconds = local.dlq_visibility_timeout_seconds

  sqs_managed_sse_enabled           = local.dlq_sqs_managed_sse_enabled
  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_data_key_reuse_period_seconds

  tags = merge(var.tags, var.dlq_tags)

  lifecycle {
    prevent_destroy = true

    # The redrive allow policy is managed by aws_sqs_queue_redrive_allow_policy.dlq
    ignore_changes = [redrive_allow_policy]
  }
}

################################################################################
# Redrive policy (main queue -> DLQ)
################################################################################

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode(merge(
    {
      deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
      maxReceiveCount     = local.default_max_receive_count
    },
    var.redrive_policy
  ))
}

################################################################################
# Redrive allow policy (DLQ accepts only the source queue)
################################################################################

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  redrive_allow_policy = jsonencode(merge(
    {
      redrivePermission = "byQueue"
      sourceQueueArns   = [aws_sqs_queue.this[0].arn]
    },
    var.dlq_redrive_allow_policy
  ))
}

################################################################################
# DLQ queue policy
################################################################################

data "aws_iam_policy_document" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents   = var.source_dlq_queue_policy_documents
  override_policy_documents = var.override_dlq_queue_policy_documents

  # Baseline statement: only this account may use the DLQ
  statement {
    sid       = "AccountAccess"
    effect    = "Allow"
    actions   = local.default_queue_actions
    resources = [aws_sqs_queue.dlq[0].arn]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements

    content {
      sid           = try(statement.value.sid, statement.key)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, "Allow")
      resources     = try(statement.value.resources, [aws_sqs_queue.dlq[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, statement.value.condition, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = data.aws_iam_policy_document.dlq[0].json
}

################################################################################
# Outputs
################################################################################

output "queue_id" {
  description = "URL of the main SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "ARN of the main SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "URL of the main SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "Name of the main SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "queue_policy" {
  description = "Policy JSON attached to the main queue"
  value       = try(aws_sqs_queue_policy.this[0].policy, null)
}

output "dead_letter_queue_id" {
  description = "URL of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dead_letter_queue_arn" {
  description = "ARN of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "URL of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dead_letter_queue_name" {
  description = "Name of the dead-letter queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

output "dead_letter_queue_policy" {
  description = "Policy JSON attached to the dead-letter queue"
  value       = try(aws_sqs_queue_policy.dlq[0].policy, null)
}

output "redrive_policy" {
  description = "Redrive policy attached to the main queue"
  value       = try(aws_sqs_queue_redrive_policy.this[0].redrive_policy, null)
}

output "dead_letter_queue_redrive_allow_policy" {
  description = "Redrive allow policy attached to the dead-letter queue"
  value       = try(aws_sqs_queue_redrive_allow_policy.dlq[0].redrive_allow_policy, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}

################################################################################
# Control variables
################################################################################

variable "create" {
  description = "Global switch controlling whether any resources are created"
  type        = bool
  default     = true
}

variable "create_app" {
  description = "Whether to create a CodeDeploy application"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use an existing CodeDeploy application (named by app_name) instead of creating one"
  type        = bool
  default     = false
}

variable "create_deployment_group" {
  description = "Whether to create a CodeDeploy deployment group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use an existing CodeDeploy deployment group (named by deployment_group_name) instead of creating one"
  type        = bool
  default     = false
}

variable "create_codedeploy_role" {
  description = "Whether to create an IAM role for CodeDeploy"
  type        = bool
  default     = true
}

variable "attach_hooks_policy" {
  description = "Whether to attach an inline policy allowing CodeDeploy to invoke the lifecycle hook functions"
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach an inline policy allowing CodeDeploy to publish to trigger SNS topics"
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Whether to build the AppSpec revision and deployment script"
  type        = bool
  default     = false
}

variable "save_deploy_script" {
  description = "Whether to save the generated deployment script locally"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Whether to execute the deployment script via a null_resource provisioner"
  type        = bool
  default     = false
}

variable "wait_deployment_completion" {
  description = "Whether the deployment script should poll until the deployment finishes"
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Whether to force a new deployment on every apply using a uuid() trigger"
  type        = bool
  default     = false
}

################################################################################
# Deployment input variables
################################################################################

variable "function_name" {
  description = "Name of the Lambda function to deploy"
  type        = string
  default     = ""
}

variable "alias_name" {
  description = "Name of the Lambda alias whose traffic is shifted"
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Lambda function version currently served by the alias"
  type        = string
  default     = ""
}

variable "target_version" {
  description = "Lambda function version to shift alias traffic to"
  type        = string
  default     = ""
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function to run as the BeforeAllowTraffic hook"
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of the Lambda function to run as the AfterAllowTraffic hook"
  type        = string
  default     = null
}

variable "description" {
  description = "Description attached to the created deployment"
  type        = string
  default     = "Lambda blue/green deployment created by Terraform"
}

################################################################################
# Naming and configuration variables
################################################################################

variable "app_name" {
  description = "Name of the CodeDeploy application"
  type        = string
  default     = "lambda-bluegreen-app"
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group"
  type        = string
  default     = "lambda-bluegreen-dg"
}

variable "deployment_config_name" {
  description = "Name of the CodeDeploy deployment configuration"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "codedeploy_principals" {
  description = "Service principals allowed to assume the CodeDeploy role"
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "codedeploy_role_arn" {
  description = "ARN of the IAM role used by CodeDeploy when create_codedeploy_role is false"
  type        = string
  default     = null
}

variable "aws_cli_command" {
  description = "Command used to invoke the AWS CLI in the deployment script"
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between deployment status polls"
  type        = number
  default     = 5

  validation {
    condition     = var.get_deployment_sleep_timer > 0
    error_message = "get_deployment_sleep_timer must be greater than 0."
  }
}

variable "interpreter" {
  description = "Interpreter used by the local-exec provisioner to run the deployment script"
  type        = list(string)
  default     = ["/bin/bash", "-c"]
}

variable "tags" {
  description = "Tags applied to all taggable resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Monitoring and rollback variables
################################################################################

variable "auto_rollback_enabled" {
  description = "Whether automatic rollbacks are enabled on the deployment group"
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "Events that trigger an automatic rollback"
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarm_enabled" {
  description = "Whether CloudWatch alarm monitoring is enabled on the deployment group"
  type        = bool
  default     = false
}

variable "alarms" {
  description = "CloudWatch alarm names monitored by the deployment group"
  type        = list(string)
  default     = []
}

variable "alarm_ignore_poll_alarm_failure" {
  description = "Whether deployments continue if alarm state cannot be retrieved from CloudWatch"
  type        = bool
  default     = false
}

variable "triggers" {
  description = "Map of notification triggers for the deployment group"
  type = map(object({
    trigger_events     = list(string)
    trigger_name       = string
    trigger_target_arn = string
  }))
  default = {}
}

################################################################################
# Locals
################################################################################

locals {
  create_app_resource = var.create && var.create_app && !var.use_existing_app
  create_dg_resource  = var.create && var.create_deployment_group && !var.use_existing_deployment_group

  hooks = {
    for k, v in {
      BeforeAllowTraffic = var.before_allow_traffic_hook_arn
      AfterAllowTraffic  = var.after_allow_traffic_hook_arn
    } : k => v if v != null && v != ""
  }

  hook_arns           = distinct(values(local.hooks))
  trigger_target_arns = distinct([for t in values(var.triggers) : t.trigger_target_arn])

  codedeploy_lambda_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"

  app_name              = try(aws_codedeploy_app.this[0].name, var.app_name)
  deployment_group_name = try(aws_codedeploy_deployment_group.this[0].deployment_group_name, var.deployment_group_name)
  service_role_arn      = var.create_codedeploy_role ? try(aws_iam_role.codedeploy[0].arn, null) : var.codedeploy_role_arn

  appspec_base = {
    version = "0.0"
    Resources = [
      {
        (var.function_name) = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
  }

  appspec_hooks = {
    for k in(length(local.hooks) > 0 ? ["Hooks"] : []) : k => [
      for hook_name, hook_arn in local.hooks : { (hook_name) = hook_arn }
    ]
  }

  appspec        = jsonencode(merge(local.appspec_base, local.appspec_hooks))
  appspec_sha256 = sha256(local.appspec)

  revision = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.appspec
      sha256  = local.appspec_sha256
    }
  })

  script = <<-EOT
    #!/bin/bash
    set -euo pipefail

    ID=$(${var.aws_cli_command} deploy create-deployment \
      --application-name '${local.app_name}' \
      --deployment-group-name '${local.deployment_group_name}' \
      --deployment-config-name '${var.deployment_config_name}' \
      --description '${var.description}' \
      --revision '${local.revision}' \
      --output text \
      --query '[deploymentId]')

    echo "Created CodeDeploy deployment: $ID"
    %{~if var.wait_deployment_completion}

    STATUS=$(${var.aws_cli_command} deploy get-deployment \
      --deployment-id "$ID" \
      --output text \
      --query '[deploymentInfo.status]')

    while [[ "$STATUS" == "Created" || "$STATUS" == "InProgress" || "$STATUS" == "Pending" || "$STATUS" == "Queued" || "$STATUS" == "Ready" ]]; do
      echo "Deployment $ID status: $STATUS"
      sleep ${var.get_deployment_sleep_timer}
      STATUS=$(${var.aws_cli_command} deploy get-deployment \
        --deployment-id "$ID" \
        --output text \
        --query '[deploymentInfo.status]')
    done

    echo "Deployment $ID finished with status: $STATUS"

    if [[ "$STATUS" == "Succeeded" ]]; then
      exit 0
    fi

    echo "Deployment $ID did not succeed" >&2
    exit 1
    %{~endif}
  EOT
}

################################################################################
# CodeDeploy application
################################################################################

resource "aws_codedeploy_app" "this" {
  count = local.create_app_resource ? 1 : 0

  compute_platform = "Lambda"
  name             = var.app_name
  tags             = var.tags
}

################################################################################
# IAM role for CodeDeploy
################################################################################

data "aws_iam_policy_document" "assume_role" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    sid     = "CodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name               = "${var.app_name}-codedeploy"
  assume_role_policy = data.aws_iam_policy_document.assume_role[0].json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = local.codedeploy_lambda_policy_arn
}

data "aws_iam_policy_document" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.hook_arns) > 0 ? 1 : 0

  statement {
    sid       = "InvokeLifecycleHooks"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hook_arns
  }
}

resource "aws_iam_role_policy" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.hook_arns) > 0 ? 1 : 0

  name   = "${var.app_name}-codedeploy-hooks"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.hooks[0].json
}

data "aws_iam_policy_document" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(local.trigger_target_arns) > 0 ? 1 : 0

  statement {
    sid       = "PublishTriggerNotifications"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = local.trigger_target_arns
  }
}

resource "aws_iam_role_policy" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(local.trigger_target_arns) > 0 ? 1 : 0

  name   = "${var.app_name}-codedeploy-triggers"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.triggers[0].json
}

################################################################################
# CodeDeploy deployment group
################################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = local.create_dg_resource ? 1 : 0

  app_name               = local.app_name
  deployment_group_name  = var.deployment_group_name
  service_role_arn       = local.service_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = var.alarm_enabled ? [1] : []

    content {
      enabled                   = true
      alarms                    = var.alarms
      ignore_poll_alarm_failure = var.alarm_ignore_poll_alarm_failure
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.triggers

    content {
      trigger_events     = trigger_configuration.value.trigger_events
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
    }
  }

  tags = var.tags

  lifecycle {
    precondition {
      condition     = local.service_role_arn != null
      error_message = "A service role is required: set create_codedeploy_role = true or provide codedeploy_role_arn."
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.codedeploy_lambda,
  ]
}

################################################################################
# Deployment script and runner
################################################################################

resource "local_file" "deploy_script" {
  count = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0

  content         = local.script
  filename        = "${path.module}/deploy_script_${local.appspec_sha256}.sh"
  file_permission = "0755"
}

resource "null_resource" "deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    appspec_sha256 = local.appspec_sha256
    force_deploy   = var.force_deploy ? uuid() : ""
  }

  provisioner "local-exec" {
    command     = local.script
    interpreter = var.interpreter
  }

  depends_on = [
    aws_codedeploy_app.this,
    aws_codedeploy_deployment_group.this,
    aws_iam_role_policy_attachment.codedeploy_lambda,
    aws_iam_role_policy.hooks,
    aws_iam_role_policy.triggers,
  ]
}

################################################################################
# Outputs
################################################################################

output "codedeploy_app_id" {
  description = "ID of the CodeDeploy application"
  value       = try(aws_codedeploy_app.this[0].id, null)
}

output "codedeploy_app_name" {
  description = "Name of the CodeDeploy application"
  value       = try(local.app_name, null)
}

output "codedeploy_deployment_group_id" {
  description = "ID of the CodeDeploy deployment group"
  value       = try(aws_codedeploy_deployment_group.this[0].id, null)
}

output "codedeploy_deployment_group_name" {
  description = "Name of the CodeDeploy deployment group"
  value       = try(local.deployment_group_name, null)
}

output "codedeploy_iam_role_name" {
  description = "Name of the IAM role used by CodeDeploy"
  value       = try(aws_iam_role.codedeploy[0].name, null)
}

output "codedeploy_iam_role_arn" {
  description = "ARN of the IAM role used by CodeDeploy"
  value       = try(local.service_role_arn, null)
}

output "appspec" {
  description = "AppSpec JSON content of the deployment revision"
  value       = try(var.create && var.create_deployment ? local.appspec : null, null)
}

output "appspec_sha256" {
  description = "SHA256 of the AppSpec JSON content"
  value       = try(var.create && var.create_deployment ? local.appspec_sha256 : null, null)
}

output "script" {
  description = "Generated deployment script"
  value       = try(var.create && var.create_deployment ? local.script : null, null)
}

output "deploy_script" {
  description = "Path to the saved deployment script"
  value       = try(local_file.deploy_script[0].filename, null)
}

output "deployment_runner_id" {
  description = "ID of the null_resource that ran the deployment"
  value       = try(null_resource.deployment[0].id, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# NOTE: The AWS provider (region = "us-east-1") is injected by the deployment
# harness. A provider block is intentionally omitted to avoid duplicate
# provider configuration errors.

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.16.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "name_prefix" {
  description = "Prefix used for the VPC and child resource Name tags."
  type        = string
  default     = "tf-project"
}

variable "max_subnet_count" {
  description = "Maximum number of shuffled AZs to select; also caps the number of subnets per tier."
  type        = number
  default     = 3

  validation {
    condition     = var.max_subnet_count >= 1
    error_message = "max_subnet_count must be at least 1."
  }
}

variable "web_subnet_cidrs" {
  description = "CIDR blocks for the public web tier subnets."
  type        = list(string)
  default     = ["10.16.0.0/20", "10.16.16.0/20", "10.16.32.0/20"]
}

variable "app_subnet_cidrs" {
  description = "CIDR blocks for the private application tier subnets."
  type        = list(string)
  default     = ["10.16.48.0/20", "10.16.64.0/20", "10.16.80.0/20"]
}

variable "db_subnet_cidrs" {
  description = "CIDR blocks for the private database tier subnets."
  type        = list(string)
  default     = ["10.16.96.0/20", "10.16.112.0/20", "10.16.128.0/20"]
}

variable "reserved_subnet_cidrs" {
  description = "CIDR blocks for the private reserved tier subnets."
  type        = list(string)
  default     = ["10.16.144.0/20", "10.16.160.0/20", "10.16.176.0/20"]
}

variable "web_subnet_count" {
  description = "Number of web subnets to create (0 disables the tier)."
  type        = number
  default     = 3

  validation {
    condition     = var.web_subnet_count >= 0
    error_message = "web_subnet_count must be zero or greater."
  }
}

variable "app_subnet_count" {
  description = "Number of app subnets to create (0 disables the tier)."
  type        = number
  default     = 3

  validation {
    condition     = var.app_subnet_count >= 0
    error_message = "app_subnet_count must be zero or greater."
  }
}

variable "db_subnet_count" {
  description = "Number of database subnets to create (0 disables the tier)."
  type        = number
  default     = 3

  validation {
    condition     = var.db_subnet_count >= 0
    error_message = "db_subnet_count must be zero or greater."
  }
}

variable "reserved_subnet_count" {
  description = "Number of reserved subnets to create (0 disables the tier)."
  type        = number
  default     = 3

  validation {
    condition     = var.reserved_subnet_count >= 0
    error_message = "reserved_subnet_count must be zero or greater."
  }
}

variable "web_map_public_ip_on_launch" {
  description = "Assign public IPv4 addresses automatically to instances launched in web subnets. Disabled by default for security. Enable only if instances need a public IP without an explicit EIP or ENI assignment."
  type        = bool
  default     = false
}

variable "create_internet_gateway" {
  description = "Whether to create an internet gateway and public route table for the web tier."
  type        = bool
  default     = true
}

variable "interface_endpoints" {
  description = "Map of interface VPC endpoints to create, keyed by a logical name."
  type = map(object({
    service_name        = string
    private_dns_enabled = optional(bool, true)
  }))
  default = {}
}

variable "gateway_endpoint_service_name" {
  description = "Service name for an optional gateway VPC endpoint (e.g. com.amazonaws.us-east-1.s3). Empty disables it."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project     = "tf-project"
    ManagedBy   = "terraform"
    Environment = "dev"
  }
}

resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

resource "random_shuffle" "azs" {
  input        = data.aws_availability_zones.available.names
  result_count = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))
}

locals {
  vpc_name = "${var.name_prefix}-${random_integer.vpc_suffix.result}"

  az_count     = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))
  shuffled_azs = random_shuffle.azs.result

  web_subnet_count      = min(var.web_subnet_count, length(var.web_subnet_cidrs), local.az_count)
  app_subnet_count      = min(var.app_subnet_count, length(var.app_subnet_cidrs), local.az_count)
  db_subnet_count       = min(var.db_subnet_count, length(var.db_subnet_cidrs), local.az_count)
  reserved_subnet_count = min(var.reserved_subnet_count, length(var.reserved_subnet_cidrs), local.az_count)

  private_subnet_total = local.app_subnet_count + local.db_subnet_count + local.reserved_subnet_count

  create_public_route_table    = var.create_internet_gateway && local.web_subnet_count > 0
  create_private_route_table   = local.private_subnet_total > 0
  create_gateway_endpoint      = var.gateway_endpoint_service_name != ""
  create_interface_endpoint_sg = length(var.interface_endpoints) > 0

  https_port = 443
  tcp        = "tcp"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = local.vpc_name
  })
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-default-sg-restricted"
  })
}

resource "aws_subnet" "web" {
  count = local.web_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.web_subnet_cidrs[count.index]
  availability_zone       = element(local.shuffled_azs, count.index)
  map_public_ip_on_launch = var.web_map_public_ip_on_launch

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-web-${count.index + 1}"
    Tier = "web"
  })
}

resource "aws_subnet" "app" {
  count = local.app_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.app_subnet_cidrs[count.index]
  availability_zone       = element(local.shuffled_azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-app-${count.index + 1}"
    Tier = "app"
  })
}

resource "aws_subnet" "db" {
  count = local.db_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.db_subnet_cidrs[count.index]
  availability_zone       = element(local.shuffled_azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-db-${count.index + 1}"
    Tier = "db"
  })
}

resource "aws_subnet" "reserved" {
  count = local.reserved_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.reserved_subnet_cidrs[count.index]
  availability_zone       = element(local.shuffled_azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-reserved-${count.index + 1}"
    Tier = "reserved"
  })
}

resource "aws_internet_gateway" "main" {
  count = var.create_internet_gateway ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-igw"
  })
}

resource "aws_route_table" "public" {
  count = local.create_public_route_table ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  count = local.create_public_route_table ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "web" {
  count = local.create_public_route_table ? local.web_subnet_count : 0

  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = local.create_private_route_table ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-private-rt"
  })
}

resource "aws_route_table_association" "app" {
  count = local.create_private_route_table ? local.app_subnet_count : 0

  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "db" {
  count = local.create_private_route_table ? local.db_subnet_count : 0

  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count = local.create_private_route_table ? local.reserved_subnet_count : 0

  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_security_group" "vpc_endpoints" {
  count = local.create_interface_endpoint_sg ? 1 : 0

  name        = "${local.vpc_name}-vpce-sg"
  description = "Allow HTTPS from within the VPC to interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = local.https_port
    to_port     = local.https_port
    protocol    = local.tcp
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS responses within VPC"
    from_port   = local.https_port
    to_port     = local.https_port
    protocol    = local.tcp
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-vpce-sg"
  })
}

resource "aws_vpc_endpoint" "interface" {
  for_each = var.interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = each.value.private_dns_enabled
  security_group_ids  = [aws_security_group.vpc_endpoints[0].id]
  subnet_ids = length(aws_subnet.app) > 0 ? aws_subnet.app[*].id : (
    length(aws_subnet.db) > 0 ? aws_subnet.db[*].id : (
      length(aws_subnet.reserved) > 0 ? aws_subnet.reserved[*].id : aws_subnet.web[*].id
    )
  )

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-vpce-${each.key}"
  })

  lifecycle {
    precondition {
      condition     = local.private_subnet_total + local.web_subnet_count > 0
      error_message = "At least one subnet must exist to create interface VPC endpoints."
    }
  }
}

resource "aws_vpc_endpoint" "gateway" {
  count = local.create_gateway_endpoint ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = var.gateway_endpoint_service_name
  vpc_endpoint_type = "Gateway"

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-vpce-gateway"
  })
}

resource "aws_vpc_endpoint_route_table_association" "gateway_private" {
  count = local.create_gateway_endpoint && local.create_private_route_table ? 1 : 0

  vpc_endpoint_id = aws_vpc_endpoint.gateway[0].id
  route_table_id  = aws_route_table.private[0].id
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_name" {
  description = "Name tag of the VPC including the random suffix."
  value       = local.vpc_name
}

output "selected_availability_zones" {
  description = "Randomly shuffled availability zones used for subnet placement."
  value       = local.shuffled_azs
}

output "web_subnet_ids" {
  description = "IDs of the web (public) subnets."
  value       = aws_subnet.web[*].id
}

output "web_subnets_map_public_ip" {
  description = "Whether instances launched in web subnets automatically receive a public IPv4 address."
  value       = var.web_map_public_ip_on_launch
}

output "app_subnet_ids" {
  description = "IDs of the application subnets."
  value       = aws_subnet.app[*].id
}

output "db_subnet_ids" {
  description = "IDs of the database subnets."
  value       = aws_subnet.db[*].id
}

output "reserved_subnet_ids" {
  description = "IDs of the reserved subnets."
  value       = aws_subnet.reserved[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway, or null if not created."
  value       = try(aws_internet_gateway.main[0].id, null)
}

output "public_route_table_id" {
  description = "ID of the public route table, or null if not created."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_id" {
  description = "ID of the shared private route table, or null if not created."
  value       = try(aws_route_table.private[0].id, null)
}

output "vpc_endpoint_security_group_id" {
  description = "ID of the interface endpoint security group, or null if not created."
  value       = try(aws_security_group.vpc_endpoints[0].id, null)
}

output "interface_endpoint_ids" {
  description = "Map of interface VPC endpoint IDs keyed by logical name."
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

output "gateway_endpoint_id" {
  description = "ID of the gateway VPC endpoint, or null if not created."
  value       = try(aws_vpc_endpoint.gateway[0].id, null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The provider "aws" block (region = "us-east-1") is injected by the
# deployment harness and is intentionally omitted here to avoid a duplicate
# provider configuration.

variable "internal_domain_name" {
  description = "Private DNS domain name used by the DHCP options set and the private Route 53 hosted zone."
  type        = string
  default     = "internal"
}

variable "dns_servers" {
  description = "DNS resolvers handed out via DHCP: the VPC built-in resolver plus a standard public DNS server."
  type        = list(string)
  default     = ["AmazonProvidedDNS", "8.8.8.8"]
}

variable "admin_cidrs" {
  description = "Admin networks allowed to SSH into instances in the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "tags" {
  description = "Common tags merged into every taggable resource."
  type        = map(string)
  default = {
    Project = "multi-tier-network"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr       = "10.0.0.0/16"
  any_cidr       = "0.0.0.0/0"
  az_primary     = data.aws_availability_zones.available.names[0]
  az_secondary   = data.aws_availability_zones.available.names[1]
  ssh_port       = 22
  ephemeral_from = 32768
  ephemeral_to   = 65535
  game_port_a    = 27015
  game_port_b    = 27020

  subnet_cidrs = {
    reserved   = "10.0.0.0/24"
    sandbox    = "10.0.1.0/24"
    web        = "10.0.2.0/24"
    database   = "10.0.3.0/24"
    gameserver = "10.0.4.0/22"
  }
}

# ---------------------------------------------------------------------------
# VPC, Internet Gateway, DHCP options, private DNS
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "ig"
  })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain_name
  domain_name_servers = var.dns_servers

  tags = merge(var.tags, {
    Name = "main"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name    = var.internal_domain_name
  comment = "Private hosted zone for the main VPC"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = merge(var.tags, {
    Name = var.internal_domain_name
  })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.reserved
  availability_zone       = local.az_primary
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "reserved"
  })
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.sandbox
  availability_zone       = local.az_secondary
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "sandbox"
  })
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.web
  availability_zone       = local.az_primary
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "web"
  })
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.database
  availability_zone       = local.az_secondary
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "database"
  })
}

resource "aws_subnet" "gameserver" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.gameserver
  availability_zone       = local.az_primary
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "gameserver"
  })
}

# ---------------------------------------------------------------------------
# Route tables (one per subnet) and associations
# ---------------------------------------------------------------------------

resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_cidr
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(var.tags, {
    Name = "reserved"
  })
}

resource "aws_route_table" "sandbox" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_cidr
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(var.tags, {
    Name = "sandbox"
  })
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_cidr
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(var.tags, {
    Name = "web"
  })
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_cidr
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(var.tags, {
    Name = "database"
  })
}

resource "aws_route_table" "gameserver" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_cidr
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(var.tags, {
    Name = "gameserver"
  })
}

resource "aws_route_table_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  route_table_id = aws_route_table.reserved.id
}

resource "aws_route_table_association" "sandbox" {
  subnet_id      = aws_subnet.sandbox.id
  route_table_id = aws_route_table.sandbox.id
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

resource "aws_route_table_association" "database" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table_association" "gameserver" {
  subnet_id      = aws_subnet.gameserver.id
  route_table_id = aws_route_table.gameserver.id
}

# ---------------------------------------------------------------------------
# Network ACLs (reserved subnet stays on the VPC default ACL)
# ---------------------------------------------------------------------------

resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.sandbox.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(var.tags, {
    Name = "sandbox"
  })
}

resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.web.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.ssh_port
    to_port    = local.ssh_port
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(var.tags, {
    Name = "web"
  })
}

resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.database.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(var.tags, {
    Name = "database"
  })
}

resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.gameserver.id]

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.ssh_port
    to_port    = local.ssh_port
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.game_port_a
    to_port    = local.game_port_a
  }

  ingress {
    rule_no    = 120
    protocol   = "udp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.game_port_a
    to_port    = local.game_port_a
  }

  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.game_port_b
    to_port    = local.game_port_b
  }

  ingress {
    rule_no    = 140
    protocol   = "udp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.game_port_b
    to_port    = local.game_port_b
  }

  ingress {
    rule_no    = 150
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
  }

  ingress {
    rule_no    = 160
    protocol   = "udp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = 0
    to_port    = 65535
  }

  egress {
    rule_no    = 110
    protocol   = "udp"
    action     = "allow"
    cidr_block = local.any_cidr
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(var.tags, {
    Name = "gameserver"
  })
}

# ---------------------------------------------------------------------------
# Security groups (standalone rule resources only)
# ---------------------------------------------------------------------------

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from admin networks and from members of this group"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "Home SSH"
  })
}

resource "aws_vpc_security_group_ingress_rule" "home_ssh_admin" {
  for_each = toset(var.admin_cidrs)

  security_group_id = aws_security_group.home_ssh.id
  description       = "SSH from admin network ${each.value}"
  ip_protocol       = "tcp"
  from_port         = local.ssh_port
  to_port           = local.ssh_port
  cidr_ipv4         = each.value

  tags = var.tags
}

resource "aws_vpc_security_group_ingress_rule" "home_ssh_self" {
  security_group_id            = aws_security_group.home_ssh.id
  description                  = "SSH from members of Home SSH"
  ip_protocol                  = "tcp"
  from_port                    = local.ssh_port
  to_port                      = local.ssh_port
  referenced_security_group_id = aws_security_group.home_ssh.id

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "home_ssh_vpc" {
  security_group_id = aws_security_group.home_ssh.id
  description       = "All outbound traffic restricted to the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = var.tags
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from within the VPC and from members of this group for Packer builds"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "Packer SSH"
  })
}

resource "aws_vpc_security_group_ingress_rule" "packer_ssh_vpc" {
  security_group_id = aws_security_group.packer_ssh.id
  description       = "SSH from the VPC CIDR"
  ip_protocol       = "tcp"
  from_port         = local.ssh_port
  to_port           = local.ssh_port
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = var.tags
}

resource "aws_vpc_security_group_ingress_rule" "packer_ssh_self" {
  security_group_id            = aws_security_group.packer_ssh.id
  description                  = "SSH from members of Packer SSH"
  ip_protocol                  = "tcp"
  from_port                    = local.ssh_port
  to_port                      = local.ssh_port
  referenced_security_group_id = aws_security_group.packer_ssh.id

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "packer_ssh_vpc" {
  security_group_id = aws_security_group.packer_ssh.id
  description       = "All outbound traffic restricted to the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the main VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the main VPC"
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.ig.id
}

output "dhcp_options_id" {
  description = "ID of the VPC DHCP options set"
  value       = aws_vpc_dhcp_options.main.id
}

output "private_zone_id" {
  description = "ID of the private Route 53 hosted zone"
  value       = aws_route53_zone.internal.zone_id
}

output "private_zone_name" {
  description = "Name of the private Route 53 hosted zone"
  value       = aws_route53_zone.internal.name
}

output "subnet_ids" {
  description = "Map of subnet name to subnet ID"
  value = {
    reserved   = aws_subnet.reserved.id
    sandbox    = aws_subnet.sandbox.id
    web        = aws_subnet.web.id
    database   = aws_subnet.database.id
    gameserver = aws_subnet.gameserver.id
  }
}

output "route_table_ids" {
  description = "Map of subnet name to route table ID"
  value = {
    reserved   = aws_route_table.reserved.id
    sandbox    = aws_route_table.sandbox.id
    web        = aws_route_table.web.id
    database   = aws_route_table.database.id
    gameserver = aws_route_table.gameserver.id
  }
}

output "network_acl_ids" {
  description = "Map of subnet name to dedicated network ACL ID"
  value = {
    sandbox    = aws_network_acl.sandbox.id
    web        = aws_network_acl.web.id
    database   = aws_network_acl.database.id
    gameserver = aws_network_acl.gameserver.id
  }
}

output "home_ssh_security_group_id" {
  description = "ID of the Home SSH security group"
  value       = aws_security_group.home_ssh.id
}

output "packer_ssh_security_group_id" {
  description = "ID of the Packer SSH security group"
  value       = aws_security_group.packer_ssh.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "env" {
  description = "Environment name used as a prefix for resource Name tags"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_app_subnet_cidrs" {
  description = "CIDR blocks for the private application subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_db_subnet_cidrs" {
  description = "CIDR blocks for the private database subnets"
  type        = list(string)
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix  = var.env
  az_count     = 3
  default_cidr = "0.0.0.0/0"
  azs          = slice(data.aws_availability_zones.available.names, 0, local.az_count)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-subnet-az${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_subnet" "private_app" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_app_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-app-subnet-az${count.index + 1}"
    Tier = "private-app"
  }
}

resource "aws_subnet" "private_db" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_db_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-db-subnet-az${count.index + 1}"
    Tier = "private-db"
  }
}

resource "aws_eip" "nat" {
  count  = local.az_count
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip-az${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = local.az_count
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}-nat-gw-az${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.default_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private_app" {
  count  = local.az_count
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.default_cidr
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${local.name_prefix}-private-app-rt-az${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_app" {
  count          = local.az_count
  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

resource "aws_route_table" "private_db" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-private-db-rt"
  }
}

resource "aws_route_table_association" "private_db" {
  count          = local.az_count
  subnet_id      = aws_subnet.private_db[count.index].id
  route_table_id = aws_route_table.private_db.id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the subnets"
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_app_subnet_ids" {
  description = "IDs of the private application subnets"
  value       = aws_subnet.private_app[*].id
}

output "private_db_subnet_ids" {
  description = "IDs of the private database subnets"
  value       = aws_subnet.private_db[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways"
  value       = aws_nat_gateway.main[*].id
}

output "nat_gateway_public_ips" {
  description = "Public IPs of the NAT gateway Elastic IPs"
  value       = aws_eip.nat[*].public_ip
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_app_route_table_ids" {
  description = "IDs of the private application route tables"
  value       = aws_route_table.private_app[*].id
}

output "private_db_route_table_id" {
  description = "ID of the private database route table"
  value       = aws_route_table.private_db.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Default tags applied to all resources via the provider."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

variable "bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the IAM account alias. Requires an IAM account alias to exist."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Append a random hex suffix to the bucket name to guarantee global uniqueness."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional custom JSON bucket policy that is extended with the enforced compliance statements."
  type        = string
  default     = ""
}

variable "enable_s3_public_access_block" {
  description = "Enable the S3 public access block for the bucket."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  }
}

variable "kms_master_key_id" {
  description = "Optional KMS key ID/ARN. When set, aws:kms encryption is used instead of AES256."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether to use an S3 Bucket Key for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Versioning status of the bucket."
  type        = string
  default     = "Enabled"

  validation {
    condition     = contains(["Enabled", "Suspended", "Disabled"], var.versioning_status)
    error_message = "versioning_status must be Enabled, Suspended or Disabled."
  }
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even when it contains objects."
  type        = bool
  default     = false
}

variable "transition_default_minimum_object_size" {
  description = "Default minimum object size behavior applied to lifecycle transitions."
  type        = string
  default     = "all_storage_classes_128K"

  validation {
    condition     = contains(["all_storage_classes_128K", "varies_by_storage_class"], var.transition_default_minimum_object_size)
    error_message = "transition_default_minimum_object_size must be all_storage_classes_128K or varies_by_storage_class."
  }
}

variable "enable_analytics" {
  description = "Enable storage class analytics for the entire bucket."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable weekly ORC bucket inventory reports."
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Name of an external target bucket for server access logging. Logging is disabled when null."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status. Not configured when null."
  type        = string
  default     = null

  validation {
    condition     = var.transfer_acceleration == null ? true : contains(["Enabled", "Suspended"], var.transfer_acceleration)
    error_message = "transfer_acceleration must be null, Enabled or Suspended."
  }
}

variable "s3_bucket_acl" {
  description = "Canned ACL for the bucket. UNUSED: aws_s3_bucket_acl is deprecated and the default BucketOwnerEnforced ownership disables ACLs; access is controlled by the bucket policy and public access block."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules to apply to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

# -----------------------------------------------------------------------------
# Data sources (static metadata only)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

resource "random_id" "suffix" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  alias_prefix  = var.use_account_alias_prefix ? "${data.aws_iam_account_alias.current[0].account_alias}-" : ""
  random_suffix = var.use_random_suffix ? "-${random_id.suffix[0].hex}" : ""

  bucket_name = lower("${local.alias_prefix}${var.bucket_name}${local.random_suffix}")

  analytics_prefix = "_AWSBucketAnalytics/"
  inventory_prefix = "_AWSBucketInventory/"

  sse_algorithm = var.kms_master_key_id != null ? "aws:kms" : "AES256"

  s3_service_principal = "s3.amazonaws.com"
}

# -----------------------------------------------------------------------------
# Bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_master_key_id
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket                                 = aws_s3_bucket.this.id
  transition_default_minimum_object_size = var.transition_default_minimum_object_size

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-management"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []
    content {
      id     = "expire-analytics-exports"
      status = "Enabled"

      filter {
        prefix = local.analytics_prefix
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []
    content {
      id     = "expire-inventory-reports"
      status = "Enabled"

      filter {
        prefix = local.inventory_prefix
      }

      expiration {
        days = 14
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# -----------------------------------------------------------------------------
# Bucket policy
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "bucket_policy" {
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid     = "AllowS3InventoryAndAnalyticsDelivery"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.this.arn}/${local.analytics_prefix}*",
      "${aws_s3_bucket.this.arn}/${local.inventory_prefix}*",
    ]

    principals {
      type        = "Service"
      identifiers = [local.s3_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:s3:::${aws_s3_bucket.this.id}"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this,
  ]
}

# -----------------------------------------------------------------------------
# Analytics and inventory
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucket"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn        = aws_s3_bucket.this.arn
          bucket_account_id = local.account_id
          format            = "CSV"
          prefix            = local.analytics_prefix
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket                   = aws_s3_bucket.this.id
  name                     = "EntireBucketWeekly"
  included_object_versions = "All"
  enabled                  = true

  schedule {
    frequency = "Weekly"
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus",
    "ObjectOwner",
  ]

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      account_id = local.account_id
      format     = "ORC"
      prefix     = local.inventory_prefix

      encryption {
        sse_s3 {}
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# -----------------------------------------------------------------------------
# Optional features
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "bucket_id" {
  description = "Name of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "Regional domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_policy_json" {
  description = "Effective bucket policy JSON."
  value       = data.aws_iam_policy_document.bucket_policy.json
}

output "encryption_algorithm" {
  description = "Server-side encryption algorithm in use (AES256 or aws:kms)."
  value       = local.sse_algorithm
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "bucket_name" {
  description = "Name of the S3 bucket."
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment name used in default tags."
  type        = string
  default     = "Development"
}

variable "tags" {
  description = "Additional tags merged into the default tags."
  type        = map(string)
  default     = {}
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: AES256, aws:kms, or none."
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "aws:kms", "none"], var.sse_algorithm)
    error_message = "sse_algorithm must be one of \"AES256\", \"aws:kms\" or \"none\"."
  }
}

variable "kms_master_key_id" {
  description = "KMS key ID or ARN for aws:kms encryption. When null and sse_algorithm is aws:kms, a key is created."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether to enable an S3 Bucket Key for SSE-KMS."
  type        = bool
  default     = false
}

variable "enable_public_access_block" {
  description = "Whether to create the public access block resource."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies."
  type        = bool
  default     = true
}

variable "control_object_ownership" {
  description = "Whether to manage S3 bucket ownership controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting."
  type        = string
  default     = "ObjectWriter"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of \"BucketOwnerEnforced\", \"BucketOwnerPreferred\" or \"ObjectWriter\"."
  }
}

variable "acl" {
  description = "Canned ACL to apply to the bucket."
  type        = string
  default     = null
}

variable "grants" {
  description = "JSON-encoded list of grant objects with id, type, permission and optional uri."
  type        = string
  default     = null
}

variable "owner_id" {
  description = "Canonical user ID of the bucket owner for the access control policy."
  type        = string
  default     = null
}

variable "versioning" {
  description = "Versioning status: Enabled, Suspended or Disabled."
  type        = string
  default     = "Disabled"

  validation {
    condition     = contains(["Enabled", "Suspended", "Disabled"], var.versioning)
    error_message = "versioning must be one of \"Enabled\", \"Suspended\" or \"Disabled\"."
  }
}

variable "mfa_delete" {
  description = "MFA delete status: Enabled or Disabled."
  type        = string
  default     = "Disabled"

  validation {
    condition     = contains(["Enabled", "Disabled"], var.mfa_delete)
    error_message = "mfa_delete must be either \"Enabled\" or \"Disabled\"."
  }
}

variable "bucket_logging" {
  description = "Whether to enable server access logging."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Name of the bucket that receives access logs."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for access log objects."
  type        = string
  default     = "logs/"
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default Object Lock retention mode."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be either \"GOVERNANCE\" or \"COMPLIANCE\"."
  }
}

variable "object_lock_days" {
  description = "Default Object Lock retention period in days."
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Default Object Lock retention period in years."
  type        = number
  default     = null
}

variable "enable_website" {
  description = "Whether to enable static website hosting."
  type        = bool
  default     = false
}

variable "website" {
  description = "Website configuration map with keys index_document, error_document and redirect_all_requests_to."
  type        = map(string)
  default     = {}
}

variable "intelligent_tiering" {
  description = "JSON-encoded map of intelligent tiering configuration names to objects with status, filter and tiering."
  type        = string
  default     = null
}

variable "metric_configuration" {
  description = "JSON-encoded list of metric configuration objects with name and optional filter."
  type        = string
  default     = null
}

variable "cors_rule" {
  description = "JSON-encoded list of CORS rule objects."
  type        = string
  default     = null
}

variable "lifecycle_rule" {
  description = "JSON-encoded list of lifecycle rule objects."
  type        = string
  default     = null
}

locals {
  default_tags = merge(
    {
      Environment     = var.environment
      ServiceProvider = "Rackspace"
    },
    var.tags
  )

  create_kms_key = var.sse_algorithm == "aws:kms" && var.kms_master_key_id == null

  kms_key_id = var.sse_algorithm == "aws:kms" ? (
    var.kms_master_key_id != null ? var.kms_master_key_id : aws_kms_key.s3[0].arn
  ) : null

  grants = var.grants != null ? jsondecode(var.grants) : []

  acl_owner_id = var.owner_id != null ? var.owner_id : data.aws_caller_identity.current.id

  intelligent_tiering = var.intelligent_tiering != null ? jsondecode(var.intelligent_tiering) : {}

  metric_configuration = var.metric_configuration != null ? {
    for metric in jsondecode(var.metric_configuration) : metric.name => metric
  } : {}

  cors_rules = var.cors_rule != null ? jsondecode(var.cors_rule) : []

  lifecycle_rules = var.lifecycle_rule != null ? jsondecode(var.lifecycle_rule) : []

  website_redirect = lookup(var.website, "redirect_all_requests_to", null)
}

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  object_lock_enabled = var.object_lock_enabled

  tags = local.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "s3" {
  count = local.create_kms_key ? 1 : 0

  description             = "KMS key for S3 bucket ${var.bucket_name} server-side encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = local.default_tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.sse_algorithm == "none" ? 0 : 1

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = local.kms_key_id
    }

    bucket_key_enabled = var.sse_algorithm == "aws:kms" ? var.bucket_key_enabled : null
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_public_access_block ? 1 : 0

  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = (var.acl != null || var.grants != null) ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.grants == null ? var.acl : null

  dynamic "access_control_policy" {
    for_each = var.grants != null ? [1] : []

    content {
      dynamic "grant" {
        for_each = local.grants

        content {
          permission = grant.value.permission

          grantee {
            type = grant.value.type
            id   = try(grant.value.id, null)
            uri  = try(grant.value.uri, null)
          }
        }
      }

      owner {
        id = local.acl_owner_id
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = var.versioning
    mfa_delete = var.mfa_delete
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.bucket_logging ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = var.logging_target_bucket != null
      error_message = "logging_target_bucket must be set when bucket_logging is true."
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = (var.object_lock_days != null || var.object_lock_years != null) ? [1] : []

    content {
      default_retention {
        mode  = var.object_lock_mode
        days  = var.object_lock_days
        years = var.object_lock_years
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.enable_website ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = local.website_redirect == null ? [lookup(var.website, "index_document", "index.html")] : []

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = local.website_redirect == null && lookup(var.website, "error_document", null) != null ? [var.website["error_document"]] : []

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = local.website_redirect != null ? [local.website_redirect] : []

    content {
      host_name = redirect_all_requests_to.value
    }
  }
}

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = local.intelligent_tiering

  bucket = aws_s3_bucket.this.id
  name   = each.key
  status = try(each.value.status, "Enabled")

  dynamic "filter" {
    for_each = try(each.value.filter, null) != null ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)
      tags   = try(filter.value.tags, null)
    }
  }

  dynamic "tiering" {
    for_each = each.value.tiering

    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

resource "aws_s3_bucket_metric" "this" {
  for_each = local.metric_configuration

  bucket = aws_s3_bucket.this.id
  name   = each.key

  dynamic "filter" {
    for_each = try(each.value.filter, null) != null ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)
      tags   = try(filter.value.tags, null)
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.cors_rule != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = local.cors_rules

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.lifecycle_rule != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = local.lifecycle_rules

    content {
      id     = rule.value.id
      status = try(rule.value.enabled, true) ? "Enabled" : "Disabled"

      filter {
        prefix = try(rule.value.filter.prefix, rule.value.prefix, "")
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])

        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "website_endpoint" {
  description = "The website endpoint, if static website hosting is enabled."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

terraform {
  required_version = ">= 1.9.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_region" "replica" {
  provider = aws.replica
}

variable "bucket_name" {
  description = "Optional explicit bucket name. When null, bucket_name_prefix is used."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name == null || length(var.bucket_name) <= 63
    error_message = "bucket_name must be 63 characters or fewer."
  }
}

variable "bucket_name_prefix" {
  description = "Bucket name prefix used when bucket_name is null."
  type        = string
  default     = "enterprise-data-"

  validation {
    condition     = var.bucket_name_prefix == null || length(var.bucket_name_prefix) <= 37
    error_message = "bucket_name_prefix must be 37 characters or fewer."
  }
}

variable "force_destroy" {
  description = "Allow deletion of non-empty buckets."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "prod"
    ManagedBy   = "terraform"
  }
}

variable "object_ownership" {
  description = "S3 object ownership setting. NOTE: ACL grants (aws_s3_bucket_acl) are out of scope for this configuration even when ObjectWriter is selected; access control relies on ownership controls, the public access block and the bucket policy."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs on the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket access."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for SSE-KMS. When null, AES256 (SSE-S3) is used."
  type        = string
  default     = null
}

variable "versioning_enabled" {
  description = "Enable bucket versioning. Required for replication and object lock."
  type        = bool
  default     = true
}

variable "custom_policy_json" {
  description = "Optional custom bucket policy JSON merged with the enforced policies."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "Source bucket ARNs allowed to deliver server access logs into the main bucket."
  type        = list(string)
  default     = []
}

variable "enable_eventbridge" {
  description = "Enable EventBridge notifications for the main bucket."
  type        = bool
  default     = true
}

variable "enable_access_logging" {
  description = "Enable server access logging for the main bucket."
  type        = bool
  default     = true
}

variable "object_lock_enabled" {
  description = "Enable S3 object lock on the main bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default object lock retention mode."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Default object lock retention in days."
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Default object lock retention in years."
  type        = number
  default     = null

  validation {
    condition     = !(var.object_lock_days != null && var.object_lock_years != null)
    error_message = "object_lock_days and object_lock_years must not both be set."
  }
}

variable "replication_rules" {
  description = "Cross-region replication rules."
  type = list(object({
    id                        = string
    priority                  = number
    prefix                    = string
    status                    = string
    storage_class             = string
    replica_kms_enabled       = bool
    delete_marker_replication = bool
  }))
  default = [
    {
      id                        = "replicate-all"
      priority                  = 1
      prefix                    = ""
      status                    = "Enabled"
      storage_class             = "STANDARD"
      replica_kms_enabled       = true
      delete_marker_replication = true
    }
  ]

  validation {
    condition     = alltrue([for r in var.replication_rules : contains(["Enabled", "Disabled"], r.status)])
    error_message = "Each replication rule status must be Enabled or Disabled."
  }
}

variable "inventory_configs" {
  description = "S3 inventory configurations keyed by inventory name."
  type = map(object({
    format                   = string
    frequency                = string
    included_object_versions = string
    optional_fields          = list(string)
    prefix                   = string
    encryption               = string
  }))
  default = {
    weekly-parquet = {
      format                   = "Parquet"
      frequency                = "Weekly"
      included_object_versions = "Current"
      optional_fields          = ["Size", "LastModifiedDate", "StorageClass", "ETag", "EncryptionStatus", "ReplicationStatus"]
      prefix                   = ""
      encryption               = "SSE-KMS"
    }
  }

  validation {
    condition     = alltrue([for c in values(var.inventory_configs) : contains(["Parquet", "CSV", "ORC"], c.format)])
    error_message = "Inventory format must be Parquet, CSV or ORC."
  }

  validation {
    condition     = alltrue([for c in values(var.inventory_configs) : contains(["Daily", "Weekly"], c.frequency)])
    error_message = "Inventory frequency must be Daily or Weekly."
  }

  validation {
    condition     = alltrue([for c in values(var.inventory_configs) : contains(["All", "Current"], c.included_object_versions)])
    error_message = "Inventory included_object_versions must be All or Current."
  }

  validation {
    condition     = alltrue([for c in values(var.inventory_configs) : contains(["SSE-KMS", "SSE-S3"], c.encryption)])
    error_message = "Inventory encryption must be SSE-KMS or SSE-S3."
  }
}

variable "cors_rules" {
  description = "CORS rules for the main bucket."
  type = list(object({
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = list(string)
    expose_headers  = list(string)
    max_age_seconds = number
  }))
  default = [
    {
      allowed_methods = ["GET", "HEAD"]
      allowed_origins = ["https://example.com"]
      allowed_headers = ["Authorization", "Content-Type"]
      expose_headers  = ["ETag"]
      max_age_seconds = 3000
    }
  ]
}

variable "lifecycle_rules" {
  description = "Lifecycle rules for the main bucket."
  type = list(object({
    id              = string
    enabled         = bool
    prefix          = string
    expiration_days = number
    transitions = list(object({
      days          = number
      storage_class = string
    }))
    noncurrent_version_expiration_days = number
    noncurrent_version_transitions = list(object({
      days          = number
      storage_class = string
    }))
    abort_incomplete_multipart_upload_days = number
  }))
  default = [
    {
      id              = "default-tiering"
      enabled         = true
      prefix          = ""
      expiration_days = null
      transitions = [
        {
          days          = 30
          storage_class = "STANDARD_IA"
        },
        {
          days          = 90
          storage_class = "GLACIER"
        }
      ]
      noncurrent_version_expiration_days     = 365
      noncurrent_version_transitions         = []
      abort_incomplete_multipart_upload_days = 7
    }
  ]
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  bucket_name   = var.bucket_name
  bucket_prefix = var.bucket_name == null ? var.bucket_name_prefix : null

  sse_algorithm      = var.kms_key_arn != null ? "aws:kms" : "AES256"
  bucket_key_enabled = var.kms_key_arn != null

  versioning_status = var.versioning_enabled ? "Enabled" : "Suspended"

  logging_enabled = var.enable_access_logging

  s3_service_principal      = "s3.amazonaws.com"
  logging_service_principal = "logging.s3.amazonaws.com"

  access_log_prefix = "s3-access-logs/"

  source_kms_key_arns = compact([var.kms_key_arn, aws_kms_key.s3_data.arn])

  common_tags = merge(var.tags, {
    Module = "enterprise-s3"
  })
}

# ---------------------------------------------------------------------------
# KMS keys
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "s3_data_key" {
  statement {
    sid       = "EnableAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.s3_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "s3_data" {
  description             = "KMS key for enterprise S3 data and inventory reports"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.s3_data_key.json

  tags = local.common_tags
}

resource "aws_kms_alias" "s3_data" {
  name          = "alias/enterprise-s3-data"
  target_key_id = aws_kms_key.s3_data.key_id
}

data "aws_iam_policy_document" "replica_key" {
  statement {
    sid       = "EnableAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.s3_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "KMS key for enterprise S3 replica bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_key.json

  tags = local.common_tags
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = "alias/enterprise-s3-replica"
  target_key_id = aws_kms_key.replica.key_id
}

# ---------------------------------------------------------------------------
# Main bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "main" {
  bucket              = local.bucket_name
  bucket_prefix       = local.bucket_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = !(var.enable_access_logging && var.object_lock_enabled)
      error_message = "Server access logging and object locking must not be enabled together."
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_key_arn
    }
    bucket_key_enabled = local.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = local.versioning_status
  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.main.arn,
      "${aws_s3_bucket.main.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "log_delivery" {
  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid       = "AllowS3ServerAccessLogDelivery"
      effect    = "Allow"
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.main.arn}/*"]

      principals {
        type        = "Service"
        identifiers = [local.logging_service_principal]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }
    }
  }
}

data "aws_iam_policy_document" "combined" {
  source_policy_documents = compact([
    data.aws_iam_policy_document.deny_insecure_transport.json,
    length(var.logging_source_bucket_arns) > 0 ? data.aws_iam_policy_document.log_delivery.json : "",
    var.custom_policy_json != null ? var.custom_policy_json : ""
  ])
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = data.aws_iam_policy_document.combined.json

  depends_on = [aws_s3_bucket_public_access_block.main]
}

resource "aws_s3_bucket_notification" "main" {
  count = var.enable_eventbridge ? 1 : 0

  bucket      = aws_s3_bucket.main.id
  eventbridge = true
}

# ---------------------------------------------------------------------------
# Access logs bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  bucket_prefix = "access-logs-"
  force_destroy = var.force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  statement {
    sid       = "AllowS3ServerAccessLogDelivery"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.access_logs[0].arn}/${local.access_log_prefix}*"]

    principals {
      type        = "Service"
      identifiers = [local.logging_service_principal]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.main.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.access_logs[0].arn,
      "${aws_s3_bucket.access_logs[0].arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id
  policy = data.aws_iam_policy_document.access_logs[0].json

  depends_on = [aws_s3_bucket_public_access_block.access_logs]
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    id     = "expire-access-logs"
    status = "Enabled"

    filter {
      prefix = ""
    }

    expiration {
      days = 365
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.access_logs]
}

resource "aws_s3_bucket_logging" "main" {
  count = local.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.access_logs[0].id
  target_prefix = local.access_log_prefix

  depends_on = [aws_s3_bucket_policy.access_logs]

  lifecycle {
    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Server access logging cannot be enabled while object lock is enabled."
    }
  }
}

# ---------------------------------------------------------------------------
# Object lock
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }

  depends_on = [aws_s3_bucket_versioning.main]

  lifecycle {
    precondition {
      condition     = length(var.logging_source_bucket_arns) == 0
      error_message = "Object lock cannot be enabled while the bucket is a server access log target (logging_source_bucket_arns is non-empty)."
    }

    precondition {
      condition     = !var.enable_access_logging
      error_message = "Object lock cannot be combined with server access logging."
    }

    precondition {
      condition     = var.versioning_enabled
      error_message = "Object lock requires versioning_enabled = true."
    }

    precondition {
      condition     = var.object_lock_days != null || var.object_lock_years != null
      error_message = "Either object_lock_days or object_lock_years must be set when object lock is enabled."
    }
  }
}

# ---------------------------------------------------------------------------
# Replica bucket (us-west-2)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  provider = aws.replica

  bucket_prefix = "replica-"
  force_destroy = var.force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "replica" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id
  policy = data.aws_iam_policy_document.replica.json

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

resource "aws_s3_bucket_lifecycle_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    id     = "replica-hygiene"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.replica]
}

# ---------------------------------------------------------------------------
# Replication IAM
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.s3_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "replication" {
  name_prefix        = "s3-replication-"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketConfiguration"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.main.arn]
  }

  statement {
    sid    = "SourceObjectRead"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.main.arn}/*"]
  }

  statement {
    sid    = "DestinationObjectWrite"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner"
    ]
    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  statement {
    sid       = "SourceKeyDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = local.source_kms_key_arns

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "ReplicaKeyEncrypt"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.replica.arn]

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.replica.name}.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "replication" {
  name_prefix = "s3-replication-"
  description = "Least-privilege policy for S3 cross-region replication"
  policy      = data.aws_iam_policy_document.replication.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

resource "aws_s3_bucket_replication_configuration" "main" {
  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      filter {
        prefix = rule.value.prefix
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication ? "Enabled" : "Disabled"
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.replica_kms_enabled ? [1] : []

        content {
          sse_kms_encrypted_objects {
            status = "Enabled"
          }
        }
      }

      destination {
        bucket        = aws_s3_bucket.replica.arn
        storage_class = rule.value.storage_class

        dynamic "encryption_configuration" {
          for_each = rule.value.replica_kms_enabled ? [1] : []

          content {
            replica_kms_key_id = aws_kms_key.replica.arn
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.main,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication
  ]

  lifecycle {
    precondition {
      condition     = var.versioning_enabled
      error_message = "Replication requires versioning_enabled = true."
    }

    precondition {
      condition     = length(distinct([for r in var.replication_rules : r.priority])) == length(var.replication_rules)
      error_message = "Replication rule priorities must be unique."
    }
  }
}

# ---------------------------------------------------------------------------
# Inventory destination bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "inventory" {
  bucket_prefix = "inventory-reports-"
  force_destroy = var.force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "inventory" {
  bucket = aws_s3_bucket.inventory.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "inventory" {
  bucket = aws_s3_bucket.inventory.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "inventory" {
  bucket = aws_s3_bucket.inventory.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_data.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "inventory" {
  bucket = aws_s3_bucket.inventory.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "inventory" {
  statement {
    sid       = "AllowS3InventoryDelivery"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.inventory.arn}/*"]

    principals {
      type        = "Service"
      identifiers = [local.s3_service_principal]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.main.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.inventory.arn,
      "${aws_s3_bucket.inventory.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "inventory" {
  bucket = aws_s3_bucket.inventory.id
  policy = data.aws_iam_policy_document.inventory.json

  depends_on = [aws_s3_bucket_public_access_block.inventory]
}

resource "aws_s3_bucket_lifecycle_configuration" "inventory" {
  bucket = aws_s3_bucket.inventory.id

  rule {
    id     = "expire-inventory-reports"
    status = "Enabled"

    filter {
      prefix = ""
    }

    expiration {
      days = 180
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.inventory]
}

resource "aws_s3_bucket_inventory" "main" {
  for_each = var.inventory_configs

  bucket                   = aws_s3_bucket.main.id
  name                     = each.key
  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields

  schedule {
    frequency = each.value.frequency
  }

  filter {
    prefix = each.value.prefix
  }

  destination {
    bucket {
      format     = each.value.format
      bucket_arn = aws_s3_bucket.inventory.arn
      account_id = data.aws_caller_identity.current.account_id
      prefix     = "inventory/${each.key}"

      encryption {
        dynamic "sse_kms" {
          for_each = each.value.encryption == "SSE-KMS" ? [1] : []

          content {
            key_id = aws_kms_key.s3_data.arn
          }
        }

        dynamic "sse_s3" {
          for_each = each.value.encryption == "SSE-S3" ? [1] : []

          content {}
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.inventory]
}

# ---------------------------------------------------------------------------
# CORS
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = cors_rule.value.allowed_headers
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ---------------------------------------------------------------------------
# Lifecycle management
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      filter {
        prefix = rule.value.prefix
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [rule.value.expiration_days] : []

        content {
          days = expiration.value
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [rule.value.noncurrent_version_expiration_days] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []

        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.main]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "bucket_id" {
  description = "ID of the main bucket."
  value       = aws_s3_bucket.main.id
}

output "bucket_arn" {
  description = "ARN of the main bucket."
  value       = aws_s3_bucket.main.arn
}

output "bucket_regional_domain_name" {
  description = "Regional domain name of the main bucket."
  value       = aws_s3_bucket.main.bucket_regional_domain_name
}

output "replica_bucket_arn" {
  description = "ARN of the cross-region replica bucket."
  value       = aws_s3_bucket.replica.arn
}

output "replication_role_arn" {
  description = "ARN of the IAM role used for replication."
  value       = aws_iam_role.replication.arn
}

output "kms_key_arn" {
  description = "ARN of the s3_data KMS key."
  value       = aws_kms_key.s3_data.arn
}

output "access_logs_bucket_id" {
  description = "ID of the access logs bucket, or null when access logging is disabled."
  value       = try(aws_s3_bucket.access_logs[0].id, null)
}

output "inventory_bucket_arn" {
  description = "ARN of the inventory reports bucket."
  value       = aws_s3_bucket.inventory.arn
}

output "acl_management_note" {
  description = "Scope note regarding canned ACLs."
  value       = "ACL grants (aws_s3_bucket_acl) are out of scope for this configuration even when object_ownership = ObjectWriter; access control relies on ownership controls, the public access block and the bucket policy."
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "group_name_prefix" {
  description = "Prefix used for IAM group and custom policy names."
  type        = string
  default     = "app"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "account-security-baseline"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id        = data.aws_caller_identity.current.account_id
  partition         = data.aws_partition.current.partition
  region            = data.aws_region.current.name
  root_principal    = "arn:${local.partition}:iam::${local.account_id}:root"
  self_user_arn     = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
  self_mfa_arn      = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
  mfa_condition_var = "aws:MultiFactorAuthPresent"
  developer_group   = "${var.group_name_prefix}_developer"
  admin_group       = "${var.group_name_prefix}_admin"
  remote_state_name = "${local.account_id}-${local.region}-tf-remote-state"
  managed_policy_arns = {
    iam_read_only       = "arn:${local.partition}:iam::aws:policy/IAMReadOnlyAccess"
    iam_change_password = "arn:${local.partition}:iam::aws:policy/IAMUserChangePassword"
    iam_user_ssh_keys   = "arn:${local.partition}:iam::aws:policy/IAMUserSSHKeys"
  }
}

# -----------------------------------------------------------------------------
# Account-wide security baselines
# -----------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
}

resource "aws_s3_account_public_access_block" "account" {
  account_id              = data.aws_caller_identity.current.account_id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# KMS customer managed key for the remote-state bucket
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "remote_state_kms" {
  statement {
    sid       = "EnableRootAccountKeyAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_principal]
    }
  }
}

resource "aws_kms_key" "remote_state" {
  description             = "CMK for Terraform remote-state bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.remote_state_kms.json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "remote_state" {
  name          = "alias/${var.group_name_prefix}-tf-remote-state"
  target_key_id = aws_kms_key.remote_state.key_id
}

# -----------------------------------------------------------------------------
# Remote-state bucket (protected from developer access)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "remote_state" {
  bucket = local.remote_state_name
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket                  = aws_s3_bucket.remote_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.remote_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "developer" {
  name = local.developer_group
}

resource "aws_iam_group" "admin" {
  name = local.admin_group
}

# -----------------------------------------------------------------------------
# Developer group: AWS-managed policies
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = local.managed_policy_arns.iam_read_only
}

resource "aws_iam_group_policy_attachment" "developer_iam_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = local.managed_policy_arns.iam_change_password
}

resource "aws_iam_group_policy_attachment" "developer_iam_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = local.managed_policy_arns.iam_user_ssh_keys
}

# -----------------------------------------------------------------------------
# Developer group: manage own access keys
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "manage_own_access_keys" {
  statement {
    sid    = "ManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]
    resources = [local.self_user_arn]
  }
}

resource "aws_iam_policy" "manage_own_access_keys" {
  name        = "${var.group_name_prefix}-developer-manage-own-access-keys"
  description = "Allows users to manage only their own IAM access keys."
  policy      = data.aws_iam_policy_document.manage_own_access_keys.json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "developer_manage_own_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_own_access_keys.arn
}

# -----------------------------------------------------------------------------
# Developer group: manage own virtual MFA device
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "manage_own_mfa" {
  statement {
    sid    = "ListVirtualMFADevices"
    effect = "Allow"
    actions = [
      "iam:ListVirtualMFADevices",
    ]
    resources = ["arn:${local.partition}:iam::${local.account_id}:mfa/*"]
  }

  statement {
    sid    = "ManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [local.self_mfa_arn]
  }

  statement {
    sid    = "ManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "DeactivateOwnMFAOnlyWhenMFAPresent"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = [local.self_user_arn]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_var
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "manage_own_mfa" {
  name        = "${var.group_name_prefix}-developer-manage-own-mfa"
  description = "Allows users to manage their own virtual MFA device; deactivation requires MFA."
  policy      = data.aws_iam_policy_document.manage_own_mfa.json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "developer_manage_own_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_own_mfa.arn
}

# -----------------------------------------------------------------------------
# Developer group: MFA-gated S3 access
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "s3_mfa_access" {
  statement {
    sid       = "AllowS3WithMFA"
    effect    = "Allow"
    actions   = ["s3:*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_var
      values   = ["true"]
    }
  }

  statement {
    sid       = "DenyCreateBucketOutsideDesignatedRegion"
    effect    = "Deny"
    actions   = ["s3:CreateBucket"]
    resources = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [local.region]
    }
  }

  statement {
    sid     = "DenyAccessToRemoteStateBucket"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.remote_state.arn,
      "${aws_s3_bucket.remote_state.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "s3_mfa_access" {
  name        = "${var.group_name_prefix}-developer-s3-mfa"
  description = "MFA-gated S3 access restricted to the designated region, excluding the Terraform remote-state bucket."
  policy      = data.aws_iam_policy_document.s3_mfa_access.json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "developer_s3_mfa_access" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.s3_mfa_access.arn
}

# -----------------------------------------------------------------------------
# Developer group: MFA-gated compute access
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "compute_mfa_access" {
  statement {
    sid    = "AllowComputeServicesWithMFA"
    effect = "Allow"
    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*",
    ]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_var
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowEC2AndAutoScalingServiceLinkedRolesWithMFA"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole",
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling*",
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/ec2scheduled.amazonaws.com/AWSServiceRoleForEC2Scheduled*",
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/elasticloadbalancing.amazonaws.com/AWSServiceRoleForElasticLoadBalancing*",
    ]

    condition {
      test     = "StringLike"
      variable = "iam:AWSServiceName"
      values = [
        "autoscaling.amazonaws.com",
        "ec2scheduled.amazonaws.com",
        "elasticloadbalancing.amazonaws.com",
      ]
    }

    condition {
      test     = "Bool"
      variable = local.mfa_condition_var
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "compute_mfa_access" {
  name        = "${var.group_name_prefix}-developer-compute-mfa"
  description = "MFA-gated access to EC2, ELB, CloudWatch, AutoScaling and their service-linked roles."
  policy      = data.aws_iam_policy_document.compute_mfa_access.json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "developer_compute_mfa_access" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.compute_mfa_access.arn
}

# -----------------------------------------------------------------------------
# Admin role (break-glass, MFA-gated)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootAssumeWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.root_principal]
    }

    condition {
      test     = "Bool"
      variable = local.mfa_condition_var
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name               = "admin"
  description        = "Administrative role assumable by account principals with MFA."
  assume_role_policy = data.aws_iam_policy_document.admin_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "admin_mfa_full_access" {
  statement {
    sid       = "FullAdministrativeAccessWithMFA"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_var
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_mfa_full_access" {
  name        = "${var.group_name_prefix}-admin-mfa-full-access"
  description = "Break-glass full administrative access, granted only when MFA is present."
  policy      = data.aws_iam_policy_document.admin_mfa_full_access.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "admin_mfa_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_mfa_full_access.arn
}

# -----------------------------------------------------------------------------
# Admin group: assume admin role with MFA
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid       = "AssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_var
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = "${var.group_name_prefix}-admin-assume-admin-role"
  description = "Allows admin group members to assume the admin role when MFA is present."
  policy      = data.aws_iam_policy_document.assume_admin_role.json
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "admin_assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "developer_group_name" {
  description = "Name of the developer IAM group."
  value       = aws_iam_group.developer.name
}

output "developer_group_arn" {
  description = "ARN of the developer IAM group."
  value       = aws_iam_group.developer.arn
}

output "admin_group_name" {
  description = "Name of the admin IAM group."
  value       = aws_iam_group.admin.name
}

output "admin_group_arn" {
  description = "ARN of the admin IAM group."
  value       = aws_iam_group.admin.arn
}

output "admin_role_arn" {
  description = "ARN of the MFA-gated admin role."
  value       = aws_iam_role.admin.arn
}

output "remote_state_bucket_name" {
  description = "Name of the Terraform remote-state S3 bucket."
  value       = aws_s3_bucket.remote_state.id
}

output "remote_state_bucket_arn" {
  description = "ARN of the Terraform remote-state S3 bucket."
  value       = aws_s3_bucket.remote_state.arn
}

output "remote_state_kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting the remote-state bucket."
  value       = aws_kms_key.remote_state.arn
}

output "developer_custom_policy_arns" {
  description = "ARNs of the custom policies attached to the developer group."
  value = {
    manage_own_access_keys = aws_iam_policy.manage_own_access_keys.arn
    manage_own_mfa         = aws_iam_policy.manage_own_mfa.arn
    s3_mfa_access          = aws_iam_policy.s3_mfa_access.arn
    compute_mfa_access     = aws_iam_policy.compute_mfa_access.arn
  }
}

# Terraform configuration for the AWS VPC (us-east-1)
# Region us-east-1 is set by the deployment harness's injected provider "aws" block.
# This file has no provider block because a second unaliased one would fail as a duplicate.

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnets" {
  description = "List of 16 subnet definitions. Each one has a CIDR block, an index into the available AZ list, and a Name tag."
  type = list(object({
    cidr_block = string
    az_index   = number
    name       = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24", az_index = 0, name = "subnet-0" },
    { cidr_block = "10.0.1.0/24", az_index = 1, name = "subnet-1" },
    { cidr_block = "10.0.2.0/24", az_index = 2, name = "subnet-2" },
    { cidr_block = "10.0.3.0/24", az_index = 0, name = "subnet-3" },
    { cidr_block = "10.0.4.0/24", az_index = 1, name = "subnet-4" },
    { cidr_block = "10.0.5.0/24", az_index = 2, name = "subnet-5" },
    { cidr_block = "10.0.6.0/24", az_index = 0, name = "subnet-6" },
    { cidr_block = "10.0.7.0/24", az_index = 1, name = "subnet-7" },
    { cidr_block = "10.0.8.0/24", az_index = 2, name = "subnet-8" },
    { cidr_block = "10.0.9.0/24", az_index = 0, name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", az_index = 1, name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", az_index = 2, name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", az_index = 0, name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", az_index = 1, name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", az_index = 2, name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", az_index = 0, name = "subnet-15" },
  ]

  validation {
    condition     = length(var.subnets) == 16
    error_message = "Exactly 16 subnet definitions are required."
  }

  validation {
    condition     = alltrue([for s in var.subnets : s.az_index >= 0 && s.az_index <= 2])
    error_message = "Each az_index must be 0, 1, or 2 (three availability zones)."
  }
}

locals {
  # Subnet indices split into four tiers of four
  private_tier_a = [0, 1, 2, 3]
  private_tier_b = [4, 5, 6, 7]
  public         = [8, 9, 10, 11]
  spare          = [12, 13, 14, 15]

  private = concat(local.private_tier_a, local.private_tier_b)

  any_ipv4 = "0.0.0.0/0"
  any_ipv6 = "::/0"
  tcp      = "tcp"
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr_block
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_subnet" "main" {
  count = length(var.subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnets[count.index].cidr_block
  availability_zone       = data.aws_availability_zones.available.names[var.subnets[count.index].az_index]
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnets[count.index].name
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "deployme-natgw-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.main[local.private[0]].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "deployme-natgw"
  }
}

# Private route table: the VPC's main route table, sending outbound traffic through the NAT gateway
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.any_ipv4
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  count = length(local.private)

  subnet_id      = aws_subnet.main[local.private[count.index]].id
  route_table_id = aws_route_table.private.id
}

# Public route table: IPv4 and IPv6 traffic goes to the internet gateway
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = local.any_ipv6
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  count = length(local.public)

  subnet_id      = aws_subnet.main[local.public[count.index]].id
  route_table_id = aws_route_table.public.id
}

# Spare route table: IPv4 and IPv6 traffic goes to the internet gateway
resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = local.any_ipv6
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  count = length(local.spare)

  subnet_id      = aws_subnet.main[local.spare[count.index]].id
  route_table_id = aws_route_table.spare.id
}

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow HTTP and HTTPS from anywhere, SSH from inside the VPC, and egress only to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "allow_web_traffic"
  }
}

resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.allow_web_traffic.id
  description       = "HTTPS from anywhere"
  ip_protocol       = local.tcp
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = local.any_ipv4
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.allow_web_traffic.id
  description       = "HTTP from anywhere"
  ip_protocol       = local.tcp
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = local.any_ipv4
}

resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.allow_web_traffic.id
  description       = "SSH from within the VPC only"
  ip_protocol       = local.tcp
  from_port         = 22
  to_port           = 22
  cidr_ipv4         = var.vpc_cidr_block
}

resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.allow_web_traffic.id
  description       = "All outbound traffic, but only to the VPC CIDR"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

output "server_public_ip" {
  description = "Public IP address of the NAT gateway's Elastic IP."
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The aws provider configuration (region = "us-east-1") is injected by the
# deployment harness. It is intentionally not declared here to avoid a duplicate
# provider configuration error.

# ------------------------------------------------------------------------------
# Labels
# ------------------------------------------------------------------------------

variable "name" {
  type        = string
  default     = "network-security"
  description = "Name (e.g. `app` or `cluster`)."
}

variable "environment" {
  type        = string
  default     = "dev"
  description = "Environment (e.g. `prod`, `dev`, `staging`)."
}

variable "managedby" {
  type        = string
  default     = "opsstation"
  description = "ManagedBy, opsstation."
}

variable "label_order" {
  type        = list(string)
  default     = ["name", "environment"]
  description = "Label order, e.g. `name`,`environment`."
}

variable "repository" {
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
  description = "Terraform current module repo."
}

module "labels" {
  source = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

# ------------------------------------------------------------------------------
# Core toggles
# ------------------------------------------------------------------------------

variable "enable" {
  type        = bool
  default     = true
  description = "Flag to control module creation. When false, no resources are provisioned."
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "Optional ID of an existing VPC. When empty, a new VPC is created."
}

variable "vpc_cidr_block" {
  type        = string
  default     = "10.0.0.0/16"
  description = "CIDR block for the VPC created when vpc_id is not supplied."
}

variable "new_sg" {
  type        = bool
  default     = true
  description = "Whether to create a new security group."
}

variable "existing_sg_id" {
  type        = string
  default     = null
  description = "ID of an existing security group to which rules are applied instead of the new one."
}

variable "sg_description" {
  type        = string
  default     = "Managed by Terraform"
  description = "Description of the security group."
}

# ------------------------------------------------------------------------------
# Prefix list variables
# ------------------------------------------------------------------------------

variable "prefix_list_enabled" {
  type        = bool
  default     = false
  description = "Whether to create a managed prefix list."
}

variable "prefix_list_ids" {
  type        = list(string)
  default     = []
  description = "IDs of existing managed prefix lists. When supplied, no prefix list is created."
}

variable "prefix_list_address_family" {
  type        = string
  default     = "IPv4"
  description = "Address family (IPv4 or IPv6) of the managed prefix list."

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either \"IPv4\" or \"IPv6\"."
  }
}

variable "max_entries" {
  type        = number
  default     = 5
  description = "Maximum number of entries the managed prefix list can hold."
}

variable "entry" {
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default     = []
  description = "Entries (CIDR + description) for the managed prefix list."
}

# ------------------------------------------------------------------------------
# Rule variables - new security group
# ------------------------------------------------------------------------------

variable "new_sg_ingress_rules_with_cidr_blocks" {
  type = list(object({
    rule_count       = number
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = optional(list(string))
    ipv6_cidr_blocks = optional(list(string))
    description      = string
  }))
  default     = []
  description = "Ingress rules with CIDR blocks for the new security group."
}

