# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  create_vpc         = var.enable && var.vpc_id == ""
  create_sg          = var.enable && var.new_sg
  create_prefix_list = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) < 1

  apply_new_sg_rules      = var.enable && var.new_sg && var.existing_sg_id == null
  apply_existing_sg_rules = var.enable && var.existing_sg_id != null

  sg_name          = format("%s-sg", module.labels.id)
  prefix_list_name = format("%s-prefix-list", module.labels.id)
  vpc_name         = format("%s-vpc", module.labels.id)

  vpc_id = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.main[0].id, null)
  sg_id  = var.existing_sg_id != null ? var.existing_sg_id : join("", aws_security_group.default[*].id)

  default_prefix_list_ids = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : aws_ec2_managed_prefix_list.prefix_list[*].id
}

# ------------------------------------------------------------------------------
# Network (greenfield)
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(module.labels.tags, { Name = local.vpc_name })
}

# Lock down the VPC's default security group (no ingress/egress rules).
resource "aws_default_security_group" "main" {
  count = local.create_vpc ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(module.labels.tags, { Name = format("%s-default-sg", module.labels.id) })
}

# ------------------------------------------------------------------------------
# Security group
# ------------------------------------------------------------------------------

resource "aws_security_group" "default" {
  count = local.create_sg ? 1 : 0

  name        = local.sg_name
  description = var.sg_description
  vpc_id      = local.vpc_id

  tags = merge(module.labels.tags, { Name = local.sg_name })

  lifecycle {
    create_before_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Managed prefix list
# ------------------------------------------------------------------------------

resource "aws_ec2_managed_prefix_list" "prefix_list" {
  count = local.create_prefix_list ? 1 : 0

  name           = local.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.max_entries

  dynamic "entry" {
    for_each = var.entry
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(module.labels.tags, { Name = local.prefix_list_name })
}

# ------------------------------------------------------------------------------
# Rules - CIDR blocks
# ------------------------------------------------------------------------------

resource "aws_security_group_rule" "new_sg_ingress_with_cidr_blocks" {
  for_each = local.apply_new_sg_rules ? { for rule in var.new_sg_ingress_rules_with_cidr_blocks : tostring(rule.rule_count) => rule } : {}

  type              = "ingress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = try(length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null, null)
  ipv6_cidr_blocks  = try(length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null, null)
  description       = each.value.description
}

resource "aws_security_group_rule" "new_sg_egress_with_cidr_blocks" {
  for_each = local.apply_new_sg_rules ? { for rule in var.new_sg_egress_rules_with_cidr_blocks : tostring(rule.rule_count) => rule } : {}

  type              = "egress"
  security_group_id = local.sg_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = try(length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null, null)
  ipv6_cidr_blocks  = try(length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null, null)
  description       = each.value.description
}

