  cidr_blocks       = try(length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null, null)
  ipv6_cidr_blocks  = try(length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null, null)
