# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "vpc_id" {
  value       = local.vpc_id
  description = "ID of the VPC hosting the security group."
}

output "security_group_id" {
  value       = join("", aws_security_group.default[*].id)
  description = "ID of the newly created security group."
}

output "security_group_arn" {
  value       = join("", aws_security_group.default[*].arn)
  description = "ARN of the newly created security group."
}

output "security_group_name" {
  value       = join("", aws_security_group.default[*].name)
  description = "Name of the newly created security group."
}

output "target_security_group_id" {
  value       = local.sg_id
  description = "ID of the security group that rules are applied to (new or existing)."
}

output "prefix_list_id" {
  value       = try(aws_ec2_managed_prefix_list.prefix_list[0].id, "")
  description = "ID of the created managed prefix list."
}

output "prefix_list_arn" {
  value       = try(aws_ec2_managed_prefix_list.prefix_list[0].arn, "")
  description = "ARN of the created managed prefix list."
}

output "tags" {
  value       = module.labels.tags
  description = "Tags applied to the resources."
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Environment name used to construct ECS role names."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to all taggable IAM resources."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Stack     = "security-identity-baseline"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  managed_policy_prefix = "arn:${local.partition}:iam::aws:policy"

  ecs_task_role_name      = "ecs-task-role-for-${var.environment_name}"
  ecs_execution_role_name = "ecs-execution-role-for-${var.environment_name}"
  ecs_events_role_name    = "ecs_events_role-for-${var.environment_name}"

  secrets_arn_pattern       = "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
  kms_key_arn_pattern       = "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"
  lambda_function_arn       = "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
  logs_arn_prefix           = "arn:${local.partition}:logs:${local.region}:${local.account_id}"
  lambda_log_group_arn      = "${local.logs_arn_prefix}:log-group:/aws/lambda/*:*"
  state_machine_arn_pattern = "arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:*"
  iam_user_self_arn         = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
  iam_mfa_self_arn          = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"

  ecs_execution_managed_policies = {
    ecs_task_execution = "${local.managed_policy_prefix}/service-role/AmazonECSTaskExecutionRolePolicy"
    ec2_container_svc  = "${local.managed_policy_prefix}/service-role/AmazonEC2ContainerServiceRole"
  }
}

# -----------------------------------------------------------------------------
# Account password policy
# -----------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

# -----------------------------------------------------------------------------
# Trust policies
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "AllowEcsTasksAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    sid     = "AllowEventBridgeAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "states_assume_role" {
  statement {
    sid     = "AllowStepFunctionsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

# -----------------------------------------------------------------------------
# ECS task role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ecs_task_role" {
  name               = local.ecs_task_role_name
  description        = "ECS task role for the ${var.environment_name} environment."
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_task_secrets_manager_rw" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "${local.managed_policy_prefix}/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy_attachment" "ecs_task_s3_full_access" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "${local.managed_policy_prefix}/AmazonS3FullAccess"
}

data "aws_iam_policy_document" "ecs_task_ssm_messages" {
  statement {
    sid    = "AllowSsmMessagesChannels"
    effect = "Allow"
    actions = [
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel",
    ]
    resources = ["*"]
  }
}

