}

resource "aws_iam_role_policy_attachment" "ecs_execution_container_service_policy" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = local.ecs_execution_managed_policies.ec2_container_svc
}

data "aws_iam_policy_document" "ecs_execution_secrets_kms" {
  statement {
    sid    = "AllowSecretsManagerRead"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = [local.secrets_arn_pattern]
  }

  statement {
    sid       = "AllowKmsDecryptViaSecretsManager"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [local.kms_key_arn_pattern]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["secretsmanager.${local.region}.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "ecs_execution_secrets_kms" {
  name   = "ecs-execution-secrets-kms-${var.environment_name}"
  role   = aws_iam_role.ecs_execution_role.id
  policy = data.aws_iam_policy_document.ecs_execution_secrets_kms.json
}

