# Terraform configuration for the AWS FIS chaos engineering environment (us-east-1)
#
# NOTE: The deployment harness injects the provider "aws" configuration, so a
# second un-aliased provider block would cause a "Duplicate provider
# configuration" error. That is why there is no provider block here. To get the
# same effect as the requested default_tags
# (Project / Environment / ManagedBy), every taggable resource merges
# local.common_tags. If you run this outside the harness, add:
#   provider "aws" {
#     region = "us-east-1"
#     default_tags { tags = local.common_tags }
#   }
#
# Private connectivity: the instances have no unrestricted egress. ECS, SSM and
# the AL2023 package repositories are reached through VPC endpoints (an S3
# gateway endpoint plus interface endpoints). Instance egress is limited to TCP
# 443 to the VPC CIDR and to the S3 gateway prefix list.
#
# AZ selection: the subnet AZ is the first sorted AZ that both offers the
# instance type (static EC2 catalog lookup) and is not a known-constrained
# zone, instead of blindly using names[0].
#
# Naming: every account-unique name (bucket, secret, IAM role, instance
# profile, security groups, launch template, ASG, key pair and KMS alias) is
# generated from a prefix, so the template can be applied again safely.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used in resource naming and tagging."
  type        = string
  default     = "chaos"
}

variable "admin_cidr" {
  description = "CIDR block allowed to reach the instances over SSH."
  type        = string
  default     = "203.0.113.0/24"

  validation {
    condition     = can(cidrhost(var.admin_cidr, 0))
    error_message = "admin_cidr must be a valid IPv4 CIDR block, e.g. 203.0.113.0/24."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = "fis-chaos-${var.environment}"

  common_tags = {
    Project     = "fis-chaos"
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  chaos_tag_key   = "ChaosTarget"
  chaos_tag_value = "true"

  chaos_target_tags = {
    (local.chaos_tag_key) = local.chaos_tag_value
  }

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  fis_log_prefix   = "fis-experiments"
  ecs_cluster_name = "${local.name_prefix}-cluster"
  fis_doc_cpu      = "arn:${local.partition}:ssm:${local.region}::document/AWSFIS-Run-CPU-Stress"

  instance_type = "t3.small"
  https_port    = 443

  subnet_az = sort(tolist(setintersection(
    toset(data.aws_ec2_instance_type_offerings.instance_type.locations),
    toset(data.aws_availability_zones.available.names),
  )))[0]

  interface_endpoint_services = toset([
    "ecs",
    "ecs-agent",
    "ecs-telemetry",
    "ssm",
    "ssmmessages",
    "ec2messages",
  ])
}

# -----------------------------------------------------------------------------
# Data sources (static / well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state            = "available"
  exclude_zone_ids = ["use1-az3"]

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_ec2_instance_type_offerings" "instance_type" {
  location_type = "availability-zone"

  filter {
    name   = "instance-type"
    values = [local.instance_type]
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-ecs-hvm-*-x86_64"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = local.subnet_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, local.chaos_target_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# VPC endpoints (private access to S3, ECS and SSM)
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  })
}

resource "aws_security_group" "instances" {
  name_prefix = "${local.name_prefix}-instances-"
  description = "ECS chaos target instances - SSH from admin CIDR, HTTPS egress to VPC endpoints only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "HTTPS to interface VPC endpoints (ECS, SSM) inside the VPC"
    from_port   = local.https_port
    to_port     = local.https_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description     = "HTTPS to S3 via the gateway endpoint (AL2023 package repositories)"
    from_port       = local.https_port
    to_port         = local.https_port
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.s3.prefix_list_id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instances-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "${local.name_prefix}-vpce-"
  description = "Interface VPC endpoints - HTTPS from chaos instances only"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "vpc_endpoints_https" {
  security_group_id            = aws_security_group.vpc_endpoints.id
  description                  = "HTTPS from chaos instances"
  ip_protocol                  = "tcp"
  from_port                    = local.https_port
  to_port                      = local.https_port
  referenced_security_group_id = aws_security_group.instances.id

  tags = local.common_tags
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${each.value}-endpoint"
  })
}

# -----------------------------------------------------------------------------
# SSH key material
# -----------------------------------------------------------------------------

resource "tls_private_key" "ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "admin" {
  key_name_prefix = local.name_prefix
  public_key      = tls_private_key.ssh.public_key_openssh

  tags = local.common_tags
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name_prefix             = "${local.name_prefix}-ssh-private-key-"
  description             = "Private SSH key for the FIS chaos ECS instances"
  recovery_window_in_days = 30

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.ssh.private_key_pem
}

# -----------------------------------------------------------------------------
# ECS cluster
# -----------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = local.ecs_cluster_name

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# EC2 instance IAM role / profile
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_instance" {
  name_prefix        = "${local.name_prefix}-ec2-"
  description        = "Instance role for ECS container instances targeted by FIS"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, local.chaos_target_tags)
}

resource "aws_iam_role_policy_attachment" "ec2_ecs" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2_instance.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_instance" {
  name_prefix = "${local.name_prefix}-ec2-"
  role        = aws_iam_role.ec2_instance.name

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Launch template + Auto Scaling Group
# -----------------------------------------------------------------------------

resource "aws_launch_template" "ecs" {
  name_prefix   = "${local.name_prefix}-ecs-"
  description   = "ECS-optimized AL2023 instances for FIS chaos experiments"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = local.instance_type
  key_name      = aws_key_pair.admin.key_name

  update_default_version = true

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_instance.name
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "enabled"
  }

  network_interfaces {
    device_index                = 0
    associate_public_ip_address = true
    delete_on_termination       = true
    security_groups             = [aws_security_group.instances.id]
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  monitoring {
    enabled = true
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -euo pipefail
    echo "ECS_CLUSTER=${aws_ecs_cluster.main.name}" >> /etc/ecs/ecs.config
  EOT
  )

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, local.chaos_target_tags, {
      Name = "${local.name_prefix}-ecs-instance"
    })
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.common_tags, local.chaos_target_tags, {
      Name = "${local.name_prefix}-ecs-volume"
    })
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_instance_profile.ec2_instance,
    aws_iam_role_policy_attachment.ec2_ecs,
    aws_iam_role_policy_attachment.ec2_ssm,
  ]
}

resource "aws_autoscaling_group" "ecs" {
  name_prefix               = "${local.name_prefix}-ecs-"
  min_size                  = 1
  max_size                  = 3
  desired_capacity          = 2
  vpc_zone_identifier       = [aws_subnet.public.id]
  health_check_type         = "EC2"
  health_check_grace_period = 120

  # FIS resolves experiment targets at experiment start, not at apply time,
  # so apply does not block on instance health.
  wait_for_capacity_timeout = "0"

  launch_template {
    id      = aws_launch_template.ecs.id
    version = aws_launch_template.ecs.latest_version
  }

  instance_refresh {
    strategy = "Rolling"
    preferences {
      min_healthy_percentage = 50
    }
  }

  dynamic "tag" {
    for_each = merge(local.common_tags, local.chaos_target_tags, {
      Name = "${local.name_prefix}-ecs-instance"
    })
    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }

  depends_on = [
    aws_route_table_association.public,
    aws_vpc_endpoint.s3,
    aws_vpc_endpoint.interface,
    aws_vpc_security_group_ingress_rule.vpc_endpoints_https,
  ]
}

# -----------------------------------------------------------------------------
# KMS key for FIS log bucket
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "fis_logs_kms" {
  statement {
    sid       = "EnableAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowLogDeliveryUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:*"]
    }
  }

  statement {
    sid    = "AllowS3UseOfKeyForAccount"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "fis_logs" {
  description             = "CMK for ${local.name_prefix} FIS experiment logs"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.fis_logs_kms.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# KMS alias names are unique per account and region. Because the key uses
# prevent_destroy (and KMS deletion is deferred), an alias from an earlier or
# failed apply can outlive it, so a fixed name would collide on redeploy. A
# generated name is used instead. It still begins with
# "alias/fis-chaos-<env>-fis-logs".
resource "aws_kms_alias" "fis_logs" {
  name_prefix   = "alias/${local.name_prefix}-fis-logs-"
  target_key_id = aws_kms_key.fis_logs.key_id
}

# -----------------------------------------------------------------------------
# S3 bucket for FIS logs
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "fis_logs" {
  bucket_prefix = "${local.name_prefix}-fis-logs-"
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket                  = aws_s3_bucket.fis_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis_logs.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "fis_logs_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.fis_logs.arn,
      "${aws_s3_bucket.fis_logs.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "AWSLogDeliveryWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.fis_logs.arn}/${local.fis_log_prefix}/*"]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:*"]
    }
  }

  statement {
    sid       = "AWSLogDeliveryAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl", "s3:ListBucket"]
    resources = [aws_s3_bucket.fis_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:*"]
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = data.aws_iam_policy_document.fis_logs_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.fis_logs,
    aws_s3_bucket_ownership_controls.fis_logs,
  ]
}

# -----------------------------------------------------------------------------
# FIS IAM role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "fis_assume_role" {
  statement {
    sid     = "AllowFISAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["fis.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:fis:${local.region}:${local.account_id}:experiment/*"]
    }
  }
}

resource "aws_iam_role" "fis" {
  name_prefix        = "${local.name_prefix}-fis-"
  description        = "Role assumed by AWS FIS to run chaos experiments"
  assume_role_policy = data.aws_iam_policy_document.fis_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "fis_ec2" {
  role       = aws_iam_role.fis.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSFaultInjectionSimulatorEC2Access"
}

resource "aws_iam_role_policy_attachment" "fis_network" {
  role       = aws_iam_role.fis.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSFaultInjectionSimulatorNetworkAccess"
}

data "aws_iam_policy_document" "fis_inline" {
  statement {
    sid    = "DescribeTargets"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeVolumes",
      "ec2:DescribeSubnets",
      "tag:GetResources",
      "iam:ListRoles",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "PauseTaggedVolumeIO"
    effect    = "Allow"
    actions   = ["ec2:PauseVolumeIO"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:volume/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/${local.chaos_tag_key}"
      values   = [local.chaos_tag_value]
    }
  }

  statement {
    sid       = "TerminateTaggedInstances"
    effect    = "Allow"
    actions   = ["ec2:TerminateInstances"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:instance/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/${local.chaos_tag_key}"
      values   = [local.chaos_tag_value]
    }
  }

  statement {
    sid       = "SendCpuStressDocument"
    effect    = "Allow"
    actions   = ["ssm:SendCommand"]
    resources = [local.fis_doc_cpu]
  }

  statement {
    sid       = "SendCommandToTaggedInstances"
    effect    = "Allow"
    actions   = ["ssm:SendCommand"]
    resources = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:instance/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/${local.chaos_tag_key}"
      values   = [local.chaos_tag_value]
    }
  }

  statement {
    sid    = "ManageSsmCommands"
    effect = "Allow"
    actions = [
      "ssm:ListCommands",
      "ssm:CancelCommand",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "InjectApiFaults"
    effect = "Allow"
    actions = [
      "fis:InjectApiInternalError",
    ]
    resources = [aws_iam_role.ec2_instance.arn]
  }

  statement {
    sid    = "FisLogDelivery"
    effect = "Allow"
    actions = [
      "logs:CreateLogDelivery",
      "logs:DeleteLogDelivery",
      "logs:GetLogDelivery",
      "logs:ListLogDeliveries",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "FisLogBucketPolicy"
    effect = "Allow"
    actions = [
      "s3:GetBucketPolicy",
      "s3:PutBucketPolicy",
    ]
    resources = [aws_s3_bucket.fis_logs.arn]
  }
}

resource "aws_iam_role_policy" "fis_inline" {
  name   = "${local.name_prefix}-fis-inline"
  role   = aws_iam_role.fis.id
  policy = data.aws_iam_policy_document.fis_inline.json
}

# -----------------------------------------------------------------------------
# FIS experiment templates (no stop conditions - stop_condition source = none)
# -----------------------------------------------------------------------------

resource "aws_fis_experiment_template" "api_internal_error" {
  description = "${local.name_prefix}: inject internal errors into EC2 DescribeImages"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "inject-describe-images-error"
    action_id = "aws:fis:inject-api-internal-error"

    parameter {
      key   = "service"
      value = "ec2"
    }

    parameter {
      key   = "operations"
      value = "DescribeImages"
    }

    parameter {
      key   = "percentage"
      value = "100"
    }

    parameter {
      key   = "duration"
      value = "PT5M"
    }

    target {
      key   = "Roles"
      value = "chaos-roles"
    }
  }

  # FIS does not support tag selection for aws:iam:role targets
  # ("TargetResourceType aws:iam:role does not support tags"), so this is the
  # one documented exception to target-by-tag: the ChaosTarget-tagged EC2
  # instance role is selected by ARN.
  target {
    name           = "chaos-roles"
    resource_type  = "aws:iam:role"
    selection_mode = "ALL"
    resource_arns  = [aws_iam_role.ec2_instance.arn]
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = local.fis_log_prefix
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-api-internal-error"
  })

  depends_on = [
    aws_iam_role_policy.fis_inline,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "${local.name_prefix}: pause I/O on a tagged in-use EBS volume"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "pause-volume-io"
    action_id = "aws:ebs:pause-volume-io"

    parameter {
      key   = "duration"
      value = "PT2M"
    }

    target {
      key   = "Volumes"
      value = "chaos-volumes"
    }
  }

  target {
    name           = "chaos-volumes"
    resource_type  = "aws:ec2:ebs-volume"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }

    filter {
      path   = "State.Name"
      values = ["in-use"]
    }

    filter {
      path   = "AvailabilityZone"
      values = [aws_subnet.public.availability_zone]
    }
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = local.fis_log_prefix
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ebs-pause-io"
  })

  depends_on = [
    aws_iam_role_policy.fis_inline,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "cpu_stress" {
  description = "${local.name_prefix}: CPU stress on a tagged running instance via SSM"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "cpu-stress"
    action_id = "aws:ssm:send-command"

    parameter {
      key   = "documentArn"
      value = local.fis_doc_cpu
    }

    parameter {
      key = "documentParameters"
      value = jsonencode({
        DurationSeconds     = "120"
        InstallDependencies = "True"
        LoadPercent         = "100"
      })
    }

    parameter {
      key   = "duration"
      value = "PT2M"
    }

    target {
      key   = "Instances"
      value = "chaos-instances"
    }
  }

  target {
    name           = "chaos-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }

    filter {
      path   = "State.Name"
      values = ["running"]
    }
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = local.fis_log_prefix
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cpu-stress"
  })

  depends_on = [
    aws_iam_role_policy.fis_inline,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "terminate_instance" {
  description = "${local.name_prefix}: terminate one tagged running instance"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "terminate-instance"
    action_id = "aws:ec2:terminate-instances"

    target {
      key   = "Instances"
      value = "chaos-instances"
    }
  }

  target {
    name           = "chaos-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }

    filter {
      path   = "State.Name"
      values = ["running"]
    }
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = local.fis_log_prefix
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-terminate-instance"
  })

  depends_on = [
    aws_iam_role_policy.fis_inline,
    aws_s3_bucket_policy.fis_logs,
  ]
}

resource "aws_fis_experiment_template" "network_disruption" {
  description = "${local.name_prefix}: disrupt all connectivity on the tagged subnet"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "disrupt-connectivity"
    action_id = "aws:network:disrupt-connectivity"

    parameter {
      key   = "scope"
      value = "all"
    }

    parameter {
      key   = "duration"
      value = "PT2M"
    }

    target {
      key   = "Subnets"
      value = "chaos-subnets"
    }
  }

  target {
    name           = "chaos-subnets"
    resource_type  = "aws:ec2:subnet"
    selection_mode = "ALL"

    resource_tag {
      key   = local.chaos_tag_key
      value = local.chaos_tag_value
    }
  }

  log_configuration {
    log_schema_version = 2

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = local.fis_log_prefix
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-network-disruption"
  })

  depends_on = [
    aws_iam_role_policy.fis_inline,
    aws_iam_role_policy_attachment.fis_network,
    aws_s3_bucket_policy.fis_logs,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the chaos VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet targeted by the network disruption experiment."
  value       = aws_subnet.public.id
}

output "public_subnet_availability_zone" {
  description = "Availability Zone selected for the public subnet."
  value       = aws_subnet.public.availability_zone
}

output "security_group_id" {
  description = "Security group attached to the ECS instances."
  value       = aws_security_group.instances.id
}

output "vpc_endpoints_security_group_id" {
  description = "Security group attached to the interface VPC endpoints."
  value       = aws_security_group.vpc_endpoints.id
}

output "s3_gateway_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint."
  value       = aws_vpc_endpoint.s3.id
}

output "interface_endpoint_ids" {
  description = "IDs of the interface VPC endpoints keyed by service short name."
  value       = { for svc, ep in aws_vpc_endpoint.interface : svc => ep.id }
}

output "ecs_cluster_name" {
  description = "Name of the ECS cluster the instances register into."
  value       = aws_ecs_cluster.main.name
}

output "autoscaling_group_name" {
  description = "Name of the ECS Auto Scaling Group."
  value       = aws_autoscaling_group.ecs.name
}

output "launch_template_id" {
  description = "ID of the ECS launch template."
  value       = aws_launch_template.ecs.id
}

output "ecs_ami_id" {
  description = "Resolved ECS-optimized AMI ID."
  value       = data.aws_ami.ecs_optimized.id
}

output "key_pair_name" {
  description = "Name of the EC2 key pair for SSH access."
  value       = aws_key_pair.admin.key_name
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the SSH private key."
  value       = aws_secretsmanager_secret.ssh_private_key.arn
}

output "ec2_instance_role_arn" {
  description = "ARN of the EC2 instance role (API fault target)."
  value       = aws_iam_role.ec2_instance.arn
}

output "fis_role_arn" {
  description = "ARN of the IAM role assumed by FIS."
  value       = aws_iam_role.fis.arn
}

output "fis_logs_bucket_name" {
  description = "Name of the S3 bucket receiving FIS experiment logs."
  value       = aws_s3_bucket.fis_logs.id
}

output "fis_logs_kms_key_arn" {
  description = "ARN of the CMK encrypting FIS experiment logs."
  value       = aws_kms_key.fis_logs.arn
}

output "fis_logs_kms_alias_name" {
  description = "Generated alias name of the CMK encrypting FIS experiment logs."
  value       = aws_kms_alias.fis_logs.name
}

output "fis_experiment_template_ids" {
  description = "IDs of the FIS experiment templates."
  value = {
    api_internal_error = aws_fis_experiment_template.api_internal_error.id
    ebs_pause_io       = aws_fis_experiment_template.ebs_pause_io.id
    cpu_stress         = aws_fis_experiment_template.cpu_stress.id
    terminate_instance = aws_fis_experiment_template.terminate_instance.id
    network_disruption = aws_fis_experiment_template.network_disruption.id
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Data Sources (static / well-known metadata only)
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

################################################################################
# Variables
################################################################################

variable "name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "main"

  validation {
    condition     = can(regex("^[a-z0-9-]{1,32}$", var.name))
    error_message = "name must be 1-32 characters of lowercase letters, digits, or hyphens."
  }
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

variable "create_vpc" {
  description = "Controls whether the VPC and all dependent resources are created."
  type        = bool
  default     = true
}

variable "cidr" {
  description = "IPv4 CIDR block for the VPC. Ignored when use_ipam_pool is true."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.cidr, 0))
    error_message = "cidr must be a valid IPv4 CIDR block."
  }
}

variable "use_ipam_pool" {
  description = "When true, a greenfield IPAM, pool, and pool CIDR are created and the VPC CIDR is allocated from that pool."
  type        = bool
  default     = false
}

variable "ipam_pool_cidr" {
  description = "CIDR provisioned into the greenfield IPAM pool."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = can(cidrhost(var.ipam_pool_cidr, 0))
    error_message = "ipam_pool_cidr must be a valid IPv4 CIDR block."
  }
}

variable "ipv4_netmask_length" {
  description = "Netmask length of the VPC CIDR allocated from the IPAM pool."
  type        = number
  default     = 16

  validation {
    condition     = var.ipv4_netmask_length >= 16 && var.ipv4_netmask_length <= 28
    error_message = "ipv4_netmask_length must be between 16 and 28."
  }
}

variable "secondary_cidr_blocks" {
  description = "Secondary IPv4 CIDR blocks to associate with the VPC."
  type        = list(string)
  default     = []
}

variable "instance_tenancy" {
  description = "Tenancy option for instances launched into the VPC."
  type        = string
  default     = "default"

  validation {
    condition     = contains(["default", "dedicated"], var.instance_tenancy)
    error_message = "instance_tenancy must be either \"default\" or \"dedicated\"."
  }
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "enable_ipv6" {
  description = "Request an Amazon-provided IPv6 /56 CIDR block for the VPC."
  type        = bool
  default     = false
}

variable "map_public_ip_on_launch" {
  description = "Default for map_public_ip_on_launch on public subnets when not set per subnet."
  type        = bool
  default     = false
}

variable "public_subnets" {
  description = "Map of public subnets keyed by logical name."
  type = map(object({
    cidr_block              = string
    az_index                = number
    ipv6_prefix             = optional(number)
    assign_ipv6_on_creation = optional(bool, false)
    map_public_ip_on_launch = optional(bool)
  }))
  default = {
    public_a = {
      cidr_block  = "10.0.0.0/24"
      az_index    = 0
      ipv6_prefix = 0
    }
    public_b = {
      cidr_block  = "10.0.1.0/24"
      az_index    = 1
      ipv6_prefix = 1
    }
  }
}

variable "private_subnets" {
  description = "Map of private subnets keyed by logical name."
  type = map(object({
    cidr_block              = string
    az_index                = number
    ipv6_prefix             = optional(number)
    assign_ipv6_on_creation = optional(bool, false)
    map_public_ip_on_launch = optional(bool)
  }))
  default = {
    private_a = {
      cidr_block  = "10.0.10.0/24"
      az_index    = 0
      ipv6_prefix = 10
    }
    private_b = {
      cidr_block  = "10.0.11.0/24"
      az_index    = 1
      ipv6_prefix = 11
    }
  }
}

variable "create_igw" {
  description = "Create an Internet Gateway for public subnets."
  type        = bool
  default     = true
}

variable "create_egress_only_igw" {
  description = "Create an egress-only Internet Gateway for IPv6 egress from private subnets (requires enable_ipv6)."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Create one NAT Gateway (with Elastic IP) per public subnet for private subnet egress."
  type        = bool
  default     = true
}

variable "public_dedicated_network_acl" {
  description = "Create a dedicated network ACL for public subnets."
  type        = bool
  default     = true
}

variable "private_dedicated_network_acl" {
  description = "Create a dedicated network ACL for private subnets."
  type        = bool
  default     = true
}

variable "public_inbound_acl_rules" {
  description = "Inbound rules for the public network ACL. Set use_vpc_cidr = true to target the VPC primary CIDR. IPv6 rules apply only when enable_ipv6 is true."
  type = list(object({
    rule_number     = number
    rule_action     = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    use_vpc_cidr    = optional(bool, false)
  }))
  default = [
    { rule_number = 100, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "tcp", use_vpc_cidr = true },
    { rule_number = 110, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "udp", use_vpc_cidr = true },
    { rule_number = 120, rule_action = "allow", from_port = 443, to_port = 443, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 130, rule_action = "allow", from_port = 80, to_port = 80, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 140, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 150, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_number = 160, rule_action = "allow", from_port = 443, to_port = 443, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 170, rule_action = "allow", from_port = 80, to_port = 80, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 180, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 190, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "udp", ipv6_cidr_block = "::/0" },
  ]

  validation {
    condition = alltrue([
      for r in var.public_inbound_acl_rules : !(lower(r.rule_action) == "allow" && contains(["-1", "all"], lower(r.protocol)))
    ])
    error_message = "public_inbound_acl_rules must not allow all protocols (protocol \"-1\"/\"all\"); specify tcp/udp with explicit ports (Trivy AWS-0102)."
  }
}

variable "public_outbound_acl_rules" {
  description = "Outbound rules for the public network ACL. Set use_vpc_cidr = true to target the VPC primary CIDR. IPv6 rules apply only when enable_ipv6 is true."
  type = list(object({
    rule_number     = number
    rule_action     = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    use_vpc_cidr    = optional(bool, false)
  }))
  default = [
    { rule_number = 100, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "tcp", use_vpc_cidr = true },
    { rule_number = 110, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "udp", use_vpc_cidr = true },
    { rule_number = 120, rule_action = "allow", from_port = 443, to_port = 443, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 130, rule_action = "allow", from_port = 80, to_port = 80, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 140, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 150, rule_action = "allow", from_port = 53, to_port = 53, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_number = 160, rule_action = "allow", from_port = 123, to_port = 123, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_number = 170, rule_action = "allow", from_port = 443, to_port = 443, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 180, rule_action = "allow", from_port = 80, to_port = 80, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 190, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 200, rule_action = "allow", from_port = 53, to_port = 53, protocol = "udp", ipv6_cidr_block = "::/0" },
    { rule_number = 210, rule_action = "allow", from_port = 123, to_port = 123, protocol = "udp", ipv6_cidr_block = "::/0" },
  ]

  validation {
    condition = alltrue([
      for r in var.public_outbound_acl_rules : !(lower(r.rule_action) == "allow" && contains(["-1", "all"], lower(r.protocol)))
    ])
    error_message = "public_outbound_acl_rules must not allow all protocols (protocol \"-1\"/\"all\"); specify tcp/udp with explicit ports (Trivy AWS-0102)."
  }
}

variable "private_inbound_acl_rules" {
  description = "Inbound rules for the private network ACL (allow all TCP/UDP within the VPC plus return traffic). Set use_vpc_cidr = true to target the VPC primary CIDR. IPv6 rules apply only when enable_ipv6 is true."
  type = list(object({
    rule_number     = number
    rule_action     = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    use_vpc_cidr    = optional(bool, false)
  }))
  default = [
    { rule_number = 100, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "tcp", use_vpc_cidr = true },
    { rule_number = 110, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "udp", use_vpc_cidr = true },
    { rule_number = 120, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 130, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_number = 140, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 150, rule_action = "allow", from_port = 1024, to_port = 65535, protocol = "udp", ipv6_cidr_block = "::/0" },
  ]

  validation {
    condition = alltrue([
      for r in var.private_inbound_acl_rules : !(lower(r.rule_action) == "allow" && contains(["-1", "all"], lower(r.protocol)))
    ])
    error_message = "private_inbound_acl_rules must not allow all protocols (protocol \"-1\"/\"all\"); specify tcp/udp with explicit ports (Trivy AWS-0102)."
  }
}

variable "private_outbound_acl_rules" {
  description = "Outbound rules for the private network ACL (allow all TCP/UDP within the VPC plus web/DNS/NTP egress). Set use_vpc_cidr = true to target the VPC primary CIDR. IPv6 rules apply only when enable_ipv6 is true."
  type = list(object({
    rule_number     = number
    rule_action     = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    use_vpc_cidr    = optional(bool, false)
  }))
  default = [
    { rule_number = 100, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "tcp", use_vpc_cidr = true },
    { rule_number = 110, rule_action = "allow", from_port = 0, to_port = 65535, protocol = "udp", use_vpc_cidr = true },
    { rule_number = 120, rule_action = "allow", from_port = 443, to_port = 443, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 130, rule_action = "allow", from_port = 80, to_port = 80, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_number = 140, rule_action = "allow", from_port = 53, to_port = 53, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_number = 150, rule_action = "allow", from_port = 123, to_port = 123, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_number = 160, rule_action = "allow", from_port = 443, to_port = 443, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 170, rule_action = "allow", from_port = 80, to_port = 80, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_number = 180, rule_action = "allow", from_port = 53, to_port = 53, protocol = "udp", ipv6_cidr_block = "::/0" },
    { rule_number = 190, rule_action = "allow", from_port = 123, to_port = 123, protocol = "udp", ipv6_cidr_block = "::/0" },
  ]

  validation {
    condition = alltrue([
      for r in var.private_outbound_acl_rules : !(lower(r.rule_action) == "allow" && contains(["-1", "all"], lower(r.protocol)))
    ])
    error_message = "private_outbound_acl_rules must not allow all protocols (protocol \"-1\"/\"all\"); specify tcp/udp with explicit ports (Trivy AWS-0102)."
  }
}

variable "enable_dhcp_options" {
  description = "Create a custom DHCP options set and associate it with the VPC."
  type        = bool
  default     = false
}

variable "dhcp_options_domain_name" {
  description = "Domain name for the DHCP options set."
  type        = string
  default     = "ec2.internal"
}

variable "dhcp_options_domain_name_servers" {
  description = "Domain name servers for the DHCP options set."
  type        = list(string)
  default     = ["AmazonProvidedDNS"]
}

variable "enable_flow_log" {
  description = "Enable VPC flow logs."
  type        = bool
  default     = true
}

variable "flow_log_destination_type" {
  description = "Flow log destination type: cloud-watch-logs or s3."
  type        = string
  default     = "cloud-watch-logs"

  validation {
    condition     = contains(["cloud-watch-logs", "s3"], var.flow_log_destination_type)
    error_message = "flow_log_destination_type must be \"cloud-watch-logs\" or \"s3\"."
  }
}

variable "flow_log_traffic_type" {
  description = "Type of traffic to capture: ACCEPT, REJECT, or ALL."
  type        = string
  default     = "ALL"

  validation {
    condition     = contains(["ACCEPT", "REJECT", "ALL"], var.flow_log_traffic_type)
    error_message = "flow_log_traffic_type must be ACCEPT, REJECT, or ALL."
  }
}

variable "flow_log_max_aggregation_interval" {
  description = "Maximum interval in seconds for aggregating a flow log record (60 or 600)."
  type        = number
  default     = 60

  validation {
    condition     = contains([60, 600], var.flow_log_max_aggregation_interval)
    error_message = "flow_log_max_aggregation_interval must be 60 or 600."
  }
}

variable "flow_log_log_format" {
  description = "Custom flow log record format."
  type        = string
  default     = "$${version} $${account-id} $${interface-id} $${srcaddr} $${dstaddr} $${srcport} $${dstport} $${protocol} $${packets} $${bytes} $${start} $${end} $${action} $${log-status} $${vpc-id} $${subnet-id} $${az-id} $${tcp-flags} $${flow-direction} $${traffic-path}"
}

variable "flow_log_retention_in_days" {
  description = "Retention in days for the CloudWatch flow log group."
  type        = number
  default     = 365
}

variable "flow_log_file_format" {
  description = "File format for S3 flow log delivery: plain-text or parquet."
  type        = string
  default     = "parquet"

  validation {
    condition     = contains(["plain-text", "parquet"], var.flow_log_file_format)
    error_message = "flow_log_file_format must be plain-text or parquet."
  }
}

variable "manage_default_security_group" {
  description = "Adopt the default security group and strip all of its rules."
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Adopt and manage the default network ACL."
  type        = bool
  default     = false
}

variable "default_network_acl_ingress" {
  description = "Ingress rules for the default network ACL. Set use_vpc_cidr = true to target the VPC primary CIDR. IPv6 rules apply only when enable_ipv6 is true."
  type = list(object({
    rule_no         = number
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    use_vpc_cidr    = optional(bool, false)
  }))
  default = [
    { rule_no = 100, action = "allow", from_port = 0, to_port = 65535, protocol = "tcp", use_vpc_cidr = true },
    { rule_no = 110, action = "allow", from_port = 0, to_port = 65535, protocol = "udp", use_vpc_cidr = true },
    { rule_no = 120, action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_no = 130, action = "allow", from_port = 1024, to_port = 65535, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_no = 140, action = "allow", from_port = 1024, to_port = 65535, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_no = 150, action = "allow", from_port = 1024, to_port = 65535, protocol = "udp", ipv6_cidr_block = "::/0" },
  ]

  validation {
    condition = alltrue([
      for r in var.default_network_acl_ingress : !(lower(r.action) == "allow" && contains(["-1", "all"], lower(r.protocol)))
    ])
    error_message = "default_network_acl_ingress must not allow all protocols (protocol \"-1\"/\"all\"); specify tcp/udp with explicit ports (Trivy AWS-0102)."
  }
}

variable "default_network_acl_egress" {
  description = "Egress rules for the default network ACL. Set use_vpc_cidr = true to target the VPC primary CIDR. IPv6 rules apply only when enable_ipv6 is true."
  type = list(object({
    rule_no         = number
    action          = string
    from_port       = number
    to_port         = number
    protocol        = string
    cidr_block      = optional(string)
    ipv6_cidr_block = optional(string)
    use_vpc_cidr    = optional(bool, false)
  }))
  default = [
    { rule_no = 100, action = "allow", from_port = 0, to_port = 65535, protocol = "tcp", use_vpc_cidr = true },
    { rule_no = 110, action = "allow", from_port = 0, to_port = 65535, protocol = "udp", use_vpc_cidr = true },
    { rule_no = 120, action = "allow", from_port = 443, to_port = 443, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_no = 130, action = "allow", from_port = 80, to_port = 80, protocol = "tcp", cidr_block = "0.0.0.0/0" },
    { rule_no = 140, action = "allow", from_port = 53, to_port = 53, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_no = 150, action = "allow", from_port = 123, to_port = 123, protocol = "udp", cidr_block = "0.0.0.0/0" },
    { rule_no = 160, action = "allow", from_port = 443, to_port = 443, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_no = 170, action = "allow", from_port = 80, to_port = 80, protocol = "tcp", ipv6_cidr_block = "::/0" },
    { rule_no = 180, action = "allow", from_port = 53, to_port = 53, protocol = "udp", ipv6_cidr_block = "::/0" },
    { rule_no = 190, action = "allow", from_port = 123, to_port = 123, protocol = "udp", ipv6_cidr_block = "::/0" },
  ]

  validation {
    condition = alltrue([
      for r in var.default_network_acl_egress : !(lower(r.action) == "allow" && contains(["-1", "all"], lower(r.protocol)))
    ])
    error_message = "default_network_acl_egress must not allow all protocols (protocol \"-1\"/\"all\"); specify tcp/udp with explicit ports (Trivy AWS-0102)."
  }
}

variable "manage_default_route_table" {
  description = "Adopt and manage the default route table."
  type        = bool
  default     = false
}

variable "default_route_table_propagating_vgws" {
  description = "Virtual gateway IDs for route propagation on the default route table."
  type        = list(string)
  default     = []
}

################################################################################
# Locals
################################################################################

locals {
  create_vpc_count = var.create_vpc ? 1 : 0
  use_ipam         = var.create_vpc && var.use_ipam_pool

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  # Primary VPC CIDR (known after apply when allocated from IPAM); used by ACL rules with use_vpc_cidr = true.
  vpc_cidr_block = try(aws_vpc.this[0].cidr_block, null)

  common_tags = merge(var.tags, { Module = "vpc", Environment = var.name })

  public_subnets  = var.create_vpc ? var.public_subnets : {}
  private_subnets = var.create_vpc ? var.private_subnets : {}

  create_public_route_table = var.create_vpc && length(var.public_subnets) > 0
  create_igw                = var.create_vpc && var.create_igw && length(var.public_subnets) > 0
  create_egress_only_igw    = var.create_vpc && var.create_egress_only_igw && var.enable_ipv6

  nat_subnets     = var.create_vpc && var.enable_nat_gateway && var.create_igw ? var.public_subnets : {}
  nat_subnet_keys = sort(keys(local.nat_subnets))

  # Map each private subnet to a NAT Gateway in the same AZ, falling back to the first NAT Gateway.
  private_nat_map = length(local.nat_subnet_keys) == 0 ? {} : {
    for k, v in local.private_subnets : k => try(
      [for pk in local.nat_subnet_keys : pk if local.nat_subnets[pk].az_index == v.az_index][0],
      local.nat_subnet_keys[0]
    )
  }

  create_public_acl  = var.create_vpc && var.public_dedicated_network_acl && length(var.public_subnets) > 0
  create_private_acl = var.create_vpc && var.private_dedicated_network_acl && length(var.private_subnets) > 0

  # Keys are rule numbers (known at plan time); only values may be computed (VPC CIDR).
  # Rules with use_vpc_cidr are IPv4; IPv6 rules are applied only when enable_ipv6 is true.
  public_inbound_rules = local.create_public_acl ? {
    for r in var.public_inbound_acl_rules : tostring(r.rule_number) => {
      rule_number     = r.rule_number
      rule_action     = r.rule_action
      from_port       = r.from_port
      to_port         = r.to_port
      protocol        = r.protocol
      cidr_block      = r.use_vpc_cidr ? local.vpc_cidr_block : r.cidr_block
      ipv6_cidr_block = r.use_vpc_cidr ? null : r.ipv6_cidr_block
    } if r.use_vpc_cidr || r.ipv6_cidr_block == null || var.enable_ipv6
  } : {}
  public_outbound_rules = local.create_public_acl ? {
    for r in var.public_outbound_acl_rules : tostring(r.rule_number) => {
      rule_number     = r.rule_number
      rule_action     = r.rule_action
      from_port       = r.from_port
      to_port         = r.to_port
      protocol        = r.protocol
      cidr_block      = r.use_vpc_cidr ? local.vpc_cidr_block : r.cidr_block
      ipv6_cidr_block = r.use_vpc_cidr ? null : r.ipv6_cidr_block
    } if r.use_vpc_cidr || r.ipv6_cidr_block == null || var.enable_ipv6
  } : {}
  private_inbound_rules = local.create_private_acl ? {
    for r in var.private_inbound_acl_rules : tostring(r.rule_number) => {
      rule_number     = r.rule_number
      rule_action     = r.rule_action
      from_port       = r.from_port
      to_port         = r.to_port
      protocol        = r.protocol
      cidr_block      = r.use_vpc_cidr ? local.vpc_cidr_block : r.cidr_block
      ipv6_cidr_block = r.use_vpc_cidr ? null : r.ipv6_cidr_block
    } if r.use_vpc_cidr || r.ipv6_cidr_block == null || var.enable_ipv6
  } : {}
  private_outbound_rules = local.create_private_acl ? {
    for r in var.private_outbound_acl_rules : tostring(r.rule_number) => {
      rule_number     = r.rule_number
      rule_action     = r.rule_action
      from_port       = r.from_port
      to_port         = r.to_port
      protocol        = r.protocol
      cidr_block      = r.use_vpc_cidr ? local.vpc_cidr_block : r.cidr_block
      ipv6_cidr_block = r.use_vpc_cidr ? null : r.ipv6_cidr_block
    } if r.use_vpc_cidr || r.ipv6_cidr_block == null || var.enable_ipv6
  } : {}

  default_nacl_ingress = [
    for r in var.default_network_acl_ingress : {
      rule_no         = r.rule_no
      action          = r.action
      from_port       = r.from_port
      to_port         = r.to_port
      protocol        = r.protocol
      cidr_block      = r.use_vpc_cidr ? local.vpc_cidr_block : r.cidr_block
      ipv6_cidr_block = r.use_vpc_cidr ? null : r.ipv6_cidr_block
    } if r.use_vpc_cidr || r.ipv6_cidr_block == null || var.enable_ipv6
  ]
  default_nacl_egress = [
    for r in var.default_network_acl_egress : {
      rule_no         = r.rule_no
      action          = r.action
      from_port       = r.from_port
      to_port         = r.to_port
      protocol        = r.protocol
      cidr_block      = r.use_vpc_cidr ? local.vpc_cidr_block : r.cidr_block
      ipv6_cidr_block = r.use_vpc_cidr ? null : r.ipv6_cidr_block
    } if r.use_vpc_cidr || r.ipv6_cidr_block == null || var.enable_ipv6
  ]

  enable_flow_log        = var.create_vpc && var.enable_flow_log
  flow_log_to_cloudwatch = local.enable_flow_log && var.flow_log_destination_type == "cloud-watch-logs"
  flow_log_to_s3         = local.enable_flow_log && var.flow_log_destination_type == "s3"

  flow_log_group_name  = "/aws/vpc-flow-log/${var.name}"
  flow_log_bucket_name = "${var.name}-vpc-flow-logs-${local.account_id}"
  flow_log_name        = "${var.name}-vpc-flow-log"
}

################################################################################
# IPAM (greenfield - created only when use_ipam_pool is true)
################################################################################

resource "aws_vpc_ipam" "this" {
  count = local.use_ipam ? 1 : 0

  description = "${var.name} IPAM"

  operating_regions {
    region_name = local.region
  }

  tags = merge(local.common_tags, { Name = "${var.name}-ipam" })
}

resource "aws_vpc_ipam_pool" "this" {
  count = local.use_ipam ? 1 : 0

  address_family = "ipv4"
  ipam_scope_id  = aws_vpc_ipam.this[0].private_default_scope_id
  locale         = local.region
  description    = "${var.name} IPv4 pool"

  allocation_default_netmask_length = var.ipv4_netmask_length

  tags = merge(local.common_tags, { Name = "${var.name}-ipam-pool" })
}

resource "aws_vpc_ipam_pool_cidr" "this" {
  count = local.use_ipam ? 1 : 0

  ipam_pool_id = aws_vpc_ipam_pool.this[0].id
  cidr         = var.ipam_pool_cidr
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  count = local.create_vpc_count

  cidr_block          = local.use_ipam ? null : var.cidr
  ipv4_ipam_pool_id   = local.use_ipam ? aws_vpc_ipam_pool.this[0].id : null
  ipv4_netmask_length = local.use_ipam ? var.ipv4_netmask_length : null

  assign_generated_ipv6_cidr_block = var.enable_ipv6
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support

  tags = merge(local.common_tags, { Name = var.name })

  depends_on = [aws_vpc_ipam_pool_cidr.this]
}

resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each = toset(var.create_vpc ? var.secondary_cidr_blocks : [])

  vpc_id     = aws_vpc.this[0].id
  cidr_block = each.value
}

################################################################################
# Subnets
################################################################################

resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr_block
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  ipv6_cidr_block                 = var.enable_ipv6 && each.value.ipv6_prefix != null ? cidrsubnet(aws_vpc.this[0].ipv6_cidr_block, 8, each.value.ipv6_prefix) : null
  assign_ipv6_address_on_creation = var.enable_ipv6 && each.value.ipv6_prefix != null ? each.value.assign_ipv6_on_creation : false
  map_public_ip_on_launch         = coalesce(each.value.map_public_ip_on_launch, var.map_public_ip_on_launch)

  tags = merge(local.common_tags, {
    Name = "${var.name}-${each.key}"
    Tier = "public"
  })

  depends_on = [aws_vpc_ipv4_cidr_block_association.secondary]
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = each.value.cidr_block
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  ipv6_cidr_block                 = var.enable_ipv6 && each.value.ipv6_prefix != null ? cidrsubnet(aws_vpc.this[0].ipv6_cidr_block, 8, each.value.ipv6_prefix) : null
  assign_ipv6_address_on_creation = var.enable_ipv6 && each.value.ipv6_prefix != null ? each.value.assign_ipv6_on_creation : false
  map_public_ip_on_launch         = false

  tags = merge(local.common_tags, {
    Name = "${var.name}-${each.key}"
    Tier = "private"
  })

  depends_on = [aws_vpc_ipv4_cidr_block_association.secondary]
}

################################################################################
# Internet Gateways
################################################################################

resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, { Name = "${var.name}-igw" })
}

resource "aws_egress_only_internet_gateway" "this" {
  count = var.create_vpc && var.create_egress_only_igw && var.enable_ipv6 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, { Name = "${var.name}-eigw" })
}

################################################################################
# Public Routing
################################################################################

resource "aws_route_table" "public" {
  count = local.create_public_route_table ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, {
    Name = "${var.name}-public"
    Tier = "public"
  })
}

resource "aws_route" "public_internet_gateway" {
  count = local.create_public_route_table && local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route" "public_internet_gateway_ipv6" {
  count = local.create_public_route_table && local.create_igw && var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.public[0].id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# NAT Gateways
################################################################################

resource "aws_eip" "nat" {
  for_each = local.nat_subnets

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${var.name}-nat-${each.key}" })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  for_each = local.nat_subnets

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = merge(local.common_tags, { Name = "${var.name}-nat-${each.key}" })

  depends_on = [aws_internet_gateway.this]
}

################################################################################
# Private Routing
################################################################################

resource "aws_route_table" "private" {
  for_each = local.private_subnets

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, {
    Name = "${var.name}-${each.key}"
    Tier = "private"
  })
}

resource "aws_route" "private_nat_gateway" {
  for_each = local.private_nat_map

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.value].id
}

resource "aws_route" "private_ipv6_egress" {
  for_each = local.create_egress_only_igw ? local.private_subnets : {}

  route_table_id              = aws_route_table.private[each.key].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

################################################################################
# Network ACLs
################################################################################

resource "aws_network_acl" "public" {
  count = local.create_public_acl ? 1 : 0

  vpc_id     = aws_vpc.this[0].id
  subnet_ids = [for s in aws_subnet.public : s.id]

  tags = merge(local.common_tags, {
    Name = "${var.name}-public"
    Tier = "public"
  })
}

resource "aws_network_acl_rule" "public_inbound" {
  for_each = local.public_inbound_rules

  network_acl_id  = aws_network_acl.public[0].id
  egress          = false
  rule_number     = each.value.rule_number
  rule_action     = each.value.rule_action
  from_port       = each.value.from_port
  to_port         = each.value.to_port
  protocol        = each.value.protocol
  cidr_block      = each.value.cidr_block
  ipv6_cidr_block = each.value.ipv6_cidr_block
}

resource "aws_network_acl_rule" "public_outbound" {
  for_each = local.public_outbound_rules

  network_acl_id  = aws_network_acl.public[0].id
  egress          = true
  rule_number     = each.value.rule_number
  rule_action     = each.value.rule_action
  from_port       = each.value.from_port
  to_port         = each.value.to_port
  protocol        = each.value.protocol
  cidr_block      = each.value.cidr_block
  ipv6_cidr_block = each.value.ipv6_cidr_block
}

resource "aws_network_acl" "private" {
  count = local.create_private_acl ? 1 : 0

  vpc_id     = aws_vpc.this[0].id
  subnet_ids = [for s in aws_subnet.private : s.id]

  tags = merge(local.common_tags, {
    Name = "${var.name}-private"
    Tier = "private"
  })
}

resource "aws_network_acl_rule" "private_inbound" {
  for_each = local.private_inbound_rules

  network_acl_id  = aws_network_acl.private[0].id
  egress          = false
  rule_number     = each.value.rule_number
  rule_action     = each.value.rule_action
  from_port       = each.value.from_port
  to_port         = each.value.to_port
  protocol        = each.value.protocol
  cidr_block      = each.value.cidr_block
  ipv6_cidr_block = each.value.ipv6_cidr_block
}

resource "aws_network_acl_rule" "private_outbound" {
  for_each = local.private_outbound_rules

  network_acl_id  = aws_network_acl.private[0].id
  egress          = true
  rule_number     = each.value.rule_number
  rule_action     = each.value.rule_action
  from_port       = each.value.from_port
  to_port         = each.value.to_port
  protocol        = each.value.protocol
  cidr_block      = each.value.cidr_block
  ipv6_cidr_block = each.value.ipv6_cidr_block
}

################################################################################
# DHCP Options
################################################################################

resource "aws_vpc_dhcp_options" "this" {
  count = var.create_vpc && var.enable_dhcp_options ? 1 : 0

  domain_name         = var.dhcp_options_domain_name
  domain_name_servers = var.dhcp_options_domain_name_servers

  tags = merge(local.common_tags, { Name = "${var.name}-dhcp" })
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = var.create_vpc && var.enable_dhcp_options ? 1 : 0

  vpc_id          = aws_vpc.this[0].id
  dhcp_options_id = aws_vpc_dhcp_options.this[0].id
}

################################################################################
# Flow Logs - KMS
################################################################################

resource "aws_kms_key" "flow_log" {
  count = local.enable_flow_log ? 1 : 0

  description             = "KMS key encrypting VPC flow logs for ${var.name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsUse"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.flow_log_group_name}"
          }
        }
      },
      {
        Sid       = "AllowLogDeliveryToS3"
        Effect    = "Allow"
        Principal = { Service = "delivery.logs.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${local.flow_log_name}-kms" })
}

resource "aws_kms_alias" "flow_log" {
  count = local.enable_flow_log ? 1 : 0

  name          = "alias/${local.flow_log_name}"
  target_key_id = aws_kms_key.flow_log[0].key_id
}

################################################################################
# Flow Logs - CloudWatch Logs destination
################################################################################

resource "aws_cloudwatch_log_group" "flow_log" {
  count = local.flow_log_to_cloudwatch ? 1 : 0

  name              = local.flow_log_group_name
  retention_in_days = var.flow_log_retention_in_days
  kms_key_id        = aws_kms_key.flow_log[0].arn

  tags = merge(local.common_tags, { Name = local.flow_log_name })
}

resource "aws_iam_role" "flow_log" {
  count = local.flow_log_to_cloudwatch ? 1 : 0

  name = "${local.flow_log_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowVpcFlowLogsAssume"
        Effect    = "Allow"
        Principal = { Service = "vpc-flow-logs.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${local.partition}:ec2:${local.region}:${local.account_id}:vpc-flow-log/*"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${local.flow_log_name}-role" })
}

resource "aws_iam_role_policy" "flow_log" {
  count = local.flow_log_to_cloudwatch ? 1 : 0

  name = "${local.flow_log_name}-policy"
  role = aws_iam_role.flow_log[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowWriteToFlowLogGroup"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_log[0].arn,
          "${aws_cloudwatch_log_group.flow_log[0].arn}:*"
        ]
      }
    ]
  })
}

################################################################################
# Flow Logs - S3 destination
################################################################################

resource "aws_s3_bucket" "flow_log" {
  count = local.flow_log_to_s3 ? 1 : 0

  bucket = local.flow_log_bucket_name

  tags = merge(local.common_tags, { Name = local.flow_log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "flow_log" {
  count = local.flow_log_to_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_log" {
  count = local.flow_log_to_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.flow_log[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "flow_log" {
  count = local.flow_log_to_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "flow_log" {
  count = local.flow_log_to_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "flow_log" {
  count = local.flow_log_to_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSLogDeliveryWrite"
        Effect    = "Allow"
        Principal = { Service = "delivery.logs.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.flow_log[0].arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:*"
          }
        }
      },
      {
        Sid       = "AWSLogDeliveryAclCheck"
        Effect    = "Allow"
        Principal = { Service = "delivery.logs.amazonaws.com" }
        Action = [
          "s3:GetBucketAcl",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.flow_log[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:*"
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.flow_log[0].arn,
          "${aws_s3_bucket.flow_log[0].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.flow_log]
}

################################################################################
# Flow Log
################################################################################

resource "aws_flow_log" "this" {
  count = var.create_vpc && var.enable_flow_log ? 1 : 0

  vpc_id                   = aws_vpc.this[0].id
  traffic_type             = var.flow_log_traffic_type
  log_destination_type     = var.flow_log_destination_type
  log_destination          = local.flow_log_to_cloudwatch ? aws_cloudwatch_log_group.flow_log[0].arn : aws_s3_bucket.flow_log[0].arn
  iam_role_arn             = local.flow_log_to_cloudwatch ? aws_iam_role.flow_log[0].arn : null
  log_format               = var.flow_log_log_format
  max_aggregation_interval = var.flow_log_max_aggregation_interval

  dynamic "destination_options" {
    for_each = local.flow_log_to_s3 ? [1] : []

    content {
      file_format                = var.flow_log_file_format
      hive_compatible_partitions = false
      per_hour_partition         = true
    }
  }

  tags = merge(local.common_tags, { Name = local.flow_log_name })

  depends_on = [
    aws_iam_role_policy.flow_log,
    aws_s3_bucket_policy.flow_log,
    aws_s3_bucket_server_side_encryption_configuration.flow_log
  ]
}

################################################################################
# Default VPC Resource Governance
################################################################################

# No ingress/egress blocks: all rules are stripped (CIS 5.4 - default SG denies all traffic).
resource "aws_default_security_group" "this" {
  count = var.create_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, { Name = "${var.name}-default" })
}

resource "aws_default_network_acl" "this" {
  count = var.create_vpc && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  dynamic "ingress" {
    for_each = local.default_nacl_ingress

    content {
      rule_no         = ingress.value.rule_no
      action          = ingress.value.action
      from_port       = ingress.value.from_port
      to_port         = ingress.value.to_port
      protocol        = ingress.value.protocol
      cidr_block      = ingress.value.cidr_block
      ipv6_cidr_block = ingress.value.ipv6_cidr_block
    }
  }

  dynamic "egress" {
    for_each = local.default_nacl_egress

    content {
      rule_no         = egress.value.rule_no
      action          = egress.value.action
      from_port       = egress.value.from_port
      to_port         = egress.value.to_port
      protocol        = egress.value.protocol
      cidr_block      = egress.value.cidr_block
      ipv6_cidr_block = egress.value.ipv6_cidr_block
    }
  }

  tags = merge(local.common_tags, { Name = "${var.name}-default" })

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

resource "aws_default_route_table" "this" {
  count = var.create_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id
  propagating_vgws       = var.default_route_table_propagating_vgws

  tags = merge(local.common_tags, { Name = "${var.name}-default" })
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the VPC."
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_arn" {
  description = "ARN of the VPC."
  value       = try(aws_vpc.this[0].arn, null)
}

output "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block of the VPC."
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block of the VPC."
  value       = try(aws_vpc.this[0].ipv6_cidr_block, null)
}

output "vpc_secondary_cidr_blocks" {
  description = "Secondary IPv4 CIDR blocks associated with the VPC."
  value       = try({ for k, v in aws_vpc_ipv4_cidr_block_association.secondary : k => v.id }, {})
}

output "ipam_pool_id" {
  description = "ID of the greenfield IPAM pool."
  value       = try(aws_vpc_ipam_pool.this[0].id, null)
}

output "public_subnet_ids" {
  description = "Map of public subnet keys to IDs."
  value       = try({ for k, v in aws_subnet.public : k => v.id }, {})
}

output "private_subnet_ids" {
  description = "Map of private subnet keys to IDs."
  value       = try({ for k, v in aws_subnet.private : k => v.id }, {})
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "egress_only_internet_gateway_id" {
  description = "ID of the egress-only Internet Gateway."
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
}

output "nat_gateway_ids" {
  description = "Map of public subnet keys to NAT Gateway IDs."
  value       = try({ for k, v in aws_nat_gateway.this : k => v.id }, {})
}

output "nat_public_ips" {
  description = "Map of public subnet keys to NAT Elastic IP addresses."
  value       = try({ for k, v in aws_eip.nat : k => v.public_ip }, {})
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "Map of private subnet keys to route table IDs."
  value       = try({ for k, v in aws_route_table.private : k => v.id }, {})
}

output "public_network_acl_id" {
  description = "ID of the public network ACL."
  value       = try(aws_network_acl.public[0].id, null)
}

output "private_network_acl_id" {
  description = "ID of the private network ACL."
  value       = try(aws_network_acl.private[0].id, null)
}

output "dhcp_options_id" {
  description = "ID of the DHCP options set."
  value       = try(aws_vpc_dhcp_options.this[0].id, null)
}

output "flow_log_id" {
  description = "ID of the VPC flow log."
  value       = try(aws_flow_log.this[0].id, null)
}

output "flow_log_destination_arn" {
  description = "ARN of the flow log destination."
  value       = try(aws_flow_log.this[0].log_destination, null)
}

output "flow_log_kms_key_arn" {
  description = "ARN of the KMS key encrypting flow logs."
  value       = try(aws_kms_key.flow_log[0].arn, null)
}

output "flow_log_cloudwatch_iam_role_arn" {
  description = "ARN of the IAM role used by flow logs to write to CloudWatch Logs."
  value       = try(aws_iam_role.flow_log[0].arn, null)
}

output "default_security_group_id" {
  description = "ID of the managed default security group."
  value       = try(aws_default_security_group.this[0].id, null)
}

output "default_network_acl_id" {
  description = "ID of the managed default network ACL."
  value       = try(aws_default_network_acl.this[0].id, null)
}

output "default_route_table_id" {
  description = "ID of the managed default route table."
  value       = try(aws_default_route_table.this[0].id, null)
}

output "availability_zones" {
  description = "Availability zones available in the region."
  value       = try(data.aws_availability_zones.available.names, null)
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "name" {
  description = "Explicit name for the Transfer server. If null, a two-word random pet name is used."
  type        = string
  default     = null
}

variable "tags" {
  description = "Additional tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "endpoint_type" {
  description = "Transfer server endpoint type: PUBLIC, VPC or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of PUBLIC, VPC or VPC_ENDPOINT."
  }
}

variable "endpoint_details" {
  description = "Optional pre-existing network details for VPC / VPC_ENDPOINT endpoints. Missing pieces are created automatically."
  type = object({
    vpc_id                 = optional(string)
    subnet_ids             = optional(list(string), [])
    security_group_ids     = optional(list(string), [])
    address_allocation_ids = optional(list(string), [])
    vpc_endpoint_id        = optional(string)
  })
  default = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC created when endpoint_type is VPC and no VPC is supplied."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_subnet_count" {
  description = "Number of public subnets (and therefore Elastic IPs) to create in the greenfield VPC."
  type        = number
  default     = 2

  validation {
    condition     = var.vpc_subnet_count >= 1 && var.vpc_subnet_count <= 3
    error_message = "vpc_subnet_count must be between 1 and 3."
  }
}

variable "domain" {
  description = "Storage domain for the Transfer server."
  type        = string
  default     = "S3"

  validation {
    condition     = contains(["S3", "EFS"], var.domain)
    error_message = "domain must be S3 or EFS."
  }
}

variable "protocols" {
  description = "File transfer protocols enabled on the server."
  type        = list(string)
  default     = ["SFTP"]

  validation {
    condition     = length(var.protocols) > 0 && alltrue([for p in var.protocols : contains(["SFTP", "FTPS", "FTP", "AS2"], p)])
    error_message = "protocols must be a non-empty list containing only SFTP, FTPS, FTP or AS2."
  }
}

variable "identity_provider_type" {
  description = "Identity provider type: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE or AWS_LAMBDA."
  type        = string
  default     = "SERVICE_MANAGED"

  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE", "AWS_LAMBDA"], var.identity_provider_type)
    error_message = "identity_provider_type must be SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE or AWS_LAMBDA."
  }
}

variable "api_gateway_url" {
  description = "Invoke URL of the API Gateway used for authentication when identity_provider_type is API_GATEWAY."
  type        = string
  default     = null
}

variable "certificate_arn" {
  description = "ACM certificate ARN, required when FTPS is enabled."
  type        = string
  default     = null
}

variable "pre_authentication_login_banner" {
  description = "Banner displayed before users authenticate."
  type        = string
  default     = null
}

variable "post_authentication_login_banner" {
  description = "Banner displayed after users authenticate."
  type        = string
  default     = null
}

variable "security_policy_name" {
  description = "Security policy applied to the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "host_key" {
  description = "Optional RSA/ECDSA/ED25519 private host key. Supply via a secure mechanism (e.g. TF_VAR_host_key); never commit it."
  type        = string
  default     = null
  sensitive   = true
}

variable "logging_role_arn" {
  description = "Existing IAM role ARN for Transfer logging. If null, a role with AWSTransferLoggingAccess is created."
  type        = string
  default     = null
}

variable "structured_log_destinations" {
  description = "Additional CloudWatch log group ARNs (suffixed with :*) for structured logging."
  type        = list(string)
  default     = []
}

variable "log_retention_days" {
  description = "Retention in days for the Transfer server CloudWatch log group."
  type        = number
  default     = 90
}

variable "protocol_details" {
  description = "Optional protocol details (AS2 transports, passive IP, set-stat option, TLS session resumption)."
  type = object({
    as2_transports              = optional(list(string))
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = null
}

variable "create_route53_zone" {
  description = "Whether to create a Route 53 hosted zone for the SFTP sub-domain."
  type        = bool
  default     = false
}

variable "route53_zone_name" {
  description = "Domain name of the hosted zone created when create_route53_zone is true."
  type        = string
  default     = "sftp-example.internal"
}

variable "route53_zone_id" {
  description = "Hosted zone ID to place the CNAME record in (used when create_route53_zone is false)."
  type        = string
  default     = null
}

variable "subdomain" {
  description = "Sub-domain mapped to the Transfer server endpoint."
  type        = string
  default     = "sftp"
}

variable "sftp_users" {
  description = "Map of SFTP users. home_directory_bucket defaults to the managed bucket; home_directory_prefix defaults to the map key."
  type = map(object({
    user_name             = optional(string)
    home_directory_bucket = optional(string)
    home_directory_prefix = optional(string)
  }))
  default = {
    demo = {
      home_directory_prefix = "demo"
    }
  }
}

variable "sftp_users_ssh_keys" {
  description = "Map of user key (matching sftp_users) to SSH public key body."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Naming
# ---------------------------------------------------------------------------

resource "random_pet" "server_name" {
  length    = 2
  separator = "-"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  server_name = coalesce(var.name, random_pet.server_name.id)

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  transfer_service_principal = "transfer.amazonaws.com"
  account_root_arn           = "arn:${local.partition}:iam::${local.account_id}:root"
  s3_via_service             = "s3.${local.region}.amazonaws.com"

  common_tags = merge(var.tags, {
    Name      = local.server_name
    ManagedBy = "terraform"
  })

  is_vpc          = var.endpoint_type == "VPC"
  is_vpc_endpoint = var.endpoint_type == "VPC_ENDPOINT"

  supplied_vpc_id          = var.endpoint_details == null ? null : var.endpoint_details.vpc_id
  supplied_subnet_ids      = var.endpoint_details == null ? [] : var.endpoint_details.subnet_ids
  supplied_sg_ids          = var.endpoint_details == null ? [] : var.endpoint_details.security_group_ids
  supplied_allocation_ids  = var.endpoint_details == null ? [] : var.endpoint_details.address_allocation_ids
  supplied_vpc_endpoint_id = var.endpoint_details == null ? null : var.endpoint_details.vpc_endpoint_id

  create_vpc_network = local.is_vpc && local.supplied_vpc_id == null
  create_sg          = local.is_vpc && length(local.supplied_sg_ids) == 0
  create_eips        = local.is_vpc && length(local.supplied_allocation_ids) == 0

  create_logging_role = var.logging_role_arn == null
  create_api_gw_role  = var.identity_provider_type == "API_GATEWAY"
  create_dns          = var.create_route53_zone || var.route53_zone_id != null

  vpc_id     = local.create_vpc_network ? aws_vpc.this[0].id : local.supplied_vpc_id
  subnet_ids = local.create_vpc_network ? aws_subnet.public[*].id : local.supplied_subnet_ids

  security_group_ids     = local.create_sg ? [aws_security_group.transfer[0].id] : local.supplied_sg_ids
  address_allocation_ids = local.create_eips ? aws_eip.transfer[*].allocation_id : local.supplied_allocation_ids

  logging_role_arn = local.create_logging_role ? aws_iam_role.logging[0].arn : var.logging_role_arn
  route53_zone_id  = var.create_route53_zone ? aws_route53_zone.sftp[0].zone_id : var.route53_zone_id

  structured_log_destinations = concat(
    ["${aws_cloudwatch_log_group.transfer.arn}:*"],
    var.structured_log_destinations
  )

  # Transfer-managed users are only valid with the SERVICE_MANAGED identity provider.
  sftp_users = var.identity_provider_type == "SERVICE_MANAGED" ? var.sftp_users : {}

  sftp_user_homes = {
    for key, user in local.sftp_users : key => {
      user_name = coalesce(user.user_name, key)
      bucket    = coalesce(user.home_directory_bucket, aws_s3_bucket.sftp_home.id)
      prefix    = trim(coalesce(user.home_directory_prefix, key), "/")
    }
  }

  sftp_ssh_keys = {
    for key, body in var.sftp_users_ssh_keys : key => body
    if contains(keys(local.sftp_users), key)
  }
}

# ---------------------------------------------------------------------------
# Greenfield network (VPC endpoint type without a supplied VPC)
# ---------------------------------------------------------------------------

resource "aws_vpc" "this" {
  count = local.create_vpc_network ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.server_name}-vpc" })
}

resource "aws_default_security_group" "this" {
  count = local.create_vpc_network ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, { Name = "${local.server_name}-default-sg" })
}

resource "aws_internet_gateway" "this" {
  count = local.create_vpc_network ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, { Name = "${local.server_name}-igw" })
}

resource "aws_subnet" "public" {
  count = local.create_vpc_network ? var.vpc_subnet_count : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.server_name}-public-${count.index}" })
}

resource "aws_route_table" "public" {
  count = local.create_vpc_network ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[0].id
  }

  tags = merge(local.common_tags, { Name = "${local.server_name}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = local.create_vpc_network ? var.vpc_subnet_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ---------------------------------------------------------------------------
# Security group and Elastic IPs for VPC-hosted endpoints
# ---------------------------------------------------------------------------

resource "aws_security_group" "transfer" {
  count = local.create_sg ? 1 : 0

  name        = "${local.server_name}-transfer-sg"
  description = "Allow SFTP access to the ${local.server_name} Transfer Family server"
  vpc_id      = local.vpc_id

  ingress {
    description = "SFTP"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.server_name}-transfer-sg" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_eip" "transfer" {
  count = local.create_eips ? length(local.subnet_ids) : 0

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.server_name}-eip-${count.index}" })

  depends_on = [aws_internet_gateway.this]
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = var.log_retention_days

  tags = local.common_tags
}

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    sid     = "AllowTransferAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.transfer_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "logging" {
  count = local.create_logging_role ? 1 : 0

  name               = "${local.server_name}-transfer-logging"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "logging" {
  count = local.create_logging_role ? 1 : 0

  role       = aws_iam_role.logging[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# ---------------------------------------------------------------------------
# API Gateway authorization role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "api_gw" {
  count = local.create_api_gw_role ? 1 : 0

  name               = "${local.server_name}-transfer-api-gw"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "api_gw" {
  count = local.create_api_gw_role ? 1 : 0

  statement {
    sid       = "InvokeIdentityApi"
    effect    = "Allow"
    actions   = ["execute-api:Invoke"]
    resources = ["arn:${local.partition}:execute-api:${local.region}:${local.account_id}:*/*/GET/*"]
  }

  statement {
    sid       = "ReadIdentityApi"
    effect    = "Allow"
    actions   = ["apigateway:GET"]
    resources = ["arn:${local.partition}:apigateway:${local.region}::/restapis/*"]
  }

  statement {
    sid    = "CloudWatchLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/transfer/*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/transfer/*:log-stream:*",
    ]
  }
}

resource "aws_iam_role_policy" "api_gw" {
  count = local.create_api_gw_role ? 1 : 0

  name   = "${local.server_name}-transfer-api-gw"
  role   = aws_iam_role.api_gw[0].id
  policy = data.aws_iam_policy_document.api_gw[0].json
}

# ---------------------------------------------------------------------------
# Transfer server
# ---------------------------------------------------------------------------

resource "aws_transfer_server" "this" {
  endpoint_type          = var.endpoint_type
  domain                 = var.domain
  protocols              = var.protocols
  identity_provider_type = var.identity_provider_type
  url                    = local.create_api_gw_role ? var.api_gateway_url : null
  invocation_role        = local.create_api_gw_role ? aws_iam_role.api_gw[0].arn : null

  certificate                      = var.certificate_arn
  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner
  security_policy_name             = var.security_policy_name
  host_key                         = var.host_key

  logging_role                = local.logging_role_arn
  structured_log_destinations = local.structured_log_destinations

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "PUBLIC" ? [] : [var.endpoint_type]

    content {
      vpc_id                 = local.is_vpc ? local.vpc_id : null
      subnet_ids             = local.is_vpc ? local.subnet_ids : null
      security_group_ids     = local.is_vpc ? local.security_group_ids : null
      address_allocation_ids = local.is_vpc ? local.address_allocation_ids : null
      vpc_endpoint_id        = local.is_vpc_endpoint ? local.supplied_vpc_endpoint_id : null
    }
  }

  dynamic "protocol_details" {
    for_each = var.protocol_details == null ? [] : [var.protocol_details]

    content {
      as2_transports              = protocol_details.value.as2_transports
      passive_ip                  = protocol_details.value.passive_ip
      set_stat_option             = protocol_details.value.set_stat_option
      tls_session_resumption_mode = protocol_details.value.tls_session_resumption_mode
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.logging,
    aws_iam_role_policy.api_gw,
    aws_route_table_association.public,
  ]

  lifecycle {
    precondition {
      condition     = !local.create_api_gw_role || var.api_gateway_url != null
      error_message = "api_gateway_url must be set when identity_provider_type is API_GATEWAY."
    }

    precondition {
      condition     = !contains(var.protocols, "FTPS") || var.certificate_arn != null
      error_message = "certificate_arn must be set when FTPS is enabled."
    }

    precondition {
      condition     = !(contains(var.protocols, "FTP") || contains(var.protocols, "FTPS")) || var.endpoint_type != "PUBLIC"
      error_message = "FTP and FTPS protocols require a VPC-hosted endpoint."
    }

    precondition {
      condition     = !local.is_vpc_endpoint || local.supplied_vpc_endpoint_id != null
      error_message = "endpoint_details.vpc_endpoint_id must be set when endpoint_type is VPC_ENDPOINT."
    }

    precondition {
      condition     = local.create_vpc_network || !local.is_vpc || length(local.supplied_subnet_ids) > 0
      error_message = "endpoint_details.subnet_ids must be supplied when an existing vpc_id is provided."
    }
  }
}

# ---------------------------------------------------------------------------
# DNS
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "sftp" {
  count = var.create_route53_zone ? 1 : 0

  name = var.route53_zone_name

  tags = local.common_tags
}

resource "aws_route53_record" "sftp" {
  count = local.create_dns ? 1 : 0

  zone_id = local.route53_zone_id
  name    = var.subdomain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.this.endpoint]
}

# ---------------------------------------------------------------------------
# KMS customer managed key for the home directory bucket
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "sftp_home_kms" {
  statement {
    sid       = "EnableAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }

  statement {
    sid    = "AllowS3UsageWithinAccount"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = [local.s3_via_service]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "sftp_home" {
  description             = "CMK encrypting SFTP home directories for ${local.server_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.sftp_home_kms.json

  tags = merge(local.common_tags, { Name = "${local.server_name}-sftp-home" })
}

resource "aws_kms_alias" "sftp_home" {
  name          = "alias/${local.server_name}-sftp-home"
  target_key_id = aws_kms_key.sftp_home.key_id
}

# ---------------------------------------------------------------------------
# S3 home directory bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "sftp_home" {
  bucket = "${local.server_name}-sftp-home-${local.account_id}"

  tags = merge(local.common_tags, { Name = "${local.server_name}-sftp-home" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "sftp_home" {
  bucket = aws_s3_bucket.sftp_home.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "sftp_home" {
  bucket = aws_s3_bucket.sftp_home.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sftp_home" {
  bucket = aws_s3_bucket.sftp_home.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sftp_home.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "sftp_home" {
  bucket = aws_s3_bucket.sftp_home.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "sftp_home_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.sftp_home.arn,
      "${aws_s3_bucket.sftp_home.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "sftp_home" {
  bucket = aws_s3_bucket.sftp_home.id
  policy = data.aws_iam_policy_document.sftp_home_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.sftp_home]
}

# ---------------------------------------------------------------------------
# SFTP users
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "sftp_user_assume_role" {
  statement {
    sid     = "AllowTransferAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.transfer_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:transfer:${local.region}:${local.account_id}:user/*"]
    }
  }
}

resource "aws_iam_role" "sftp_user" {
  for_each = local.sftp_users

  name               = substr("${local.server_name}-sftp-${each.key}", 0, 64)
  assume_role_policy = data.aws_iam_policy_document.sftp_user_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.server_name}-sftp-${each.key}" })
}

data "aws_iam_policy_document" "sftp_user" {
  for_each = local.sftp_user_homes

  statement {
    sid       = "ListHomeDirectory"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = ["arn:${local.partition}:s3:::${each.value.bucket}"]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values = [
        each.value.prefix,
        "${each.value.prefix}/*",
      ]
    }
  }

  statement {
    sid       = "GetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = ["arn:${local.partition}:s3:::${each.value.bucket}"]
  }

  statement {
    sid    = "HomeDirectoryObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
    ]
    resources = ["arn:${local.partition}:s3:::${each.value.bucket}/${each.value.prefix}/*"]
  }

  statement {
    sid    = "HomeDirectoryKmsAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.sftp_home.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = [local.s3_via_service]
    }
  }
}

resource "aws_iam_role_policy" "sftp_user" {
  for_each = local.sftp_users

  name   = "${local.server_name}-sftp-${each.key}"
  role   = aws_iam_role.sftp_user[each.key].id
  policy = data.aws_iam_policy_document.sftp_user[each.key].json
}

resource "aws_transfer_user" "this" {
  for_each = local.sftp_users

  server_id           = aws_transfer_server.this.id
  user_name           = local.sftp_user_homes[each.key].user_name
  role                = aws_iam_role.sftp_user[each.key].arn
  home_directory_type = "LOGICAL"

  home_directory_mappings {
    entry  = "/"
    target = "/${local.sftp_user_homes[each.key].bucket}/${local.sftp_user_homes[each.key].prefix}"
  }

  tags = merge(local.common_tags, { Name = "${local.server_name}-${each.key}" })

  depends_on = [aws_iam_role_policy.sftp_user]
}

resource "aws_transfer_ssh_key" "this" {
  for_each = local.sftp_ssh_keys

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.key].user_name
  body      = each.value
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "server_name" {
  description = "Resolved name of the Transfer server."
  value       = local.server_name
}

output "server_id" {
  description = "ID of the Transfer server."
  value       = aws_transfer_server.this.id
}

output "server_arn" {
  description = "ARN of the Transfer server."
  value       = aws_transfer_server.this.arn
}

output "server_endpoint" {
  description = "Endpoint hostname of the Transfer server."
  value       = aws_transfer_server.this.endpoint
}

output "host_key_fingerprint" {
  description = "Host key fingerprint of the Transfer server."
  value       = aws_transfer_server.this.host_key_fingerprint
}

output "dns_record_fqdn" {
  description = "FQDN of the Route 53 CNAME record, if created."
  value       = local.create_dns ? aws_route53_record.sftp[0].fqdn : null
}

output "route53_zone_id" {
  description = "Hosted zone ID used for the SFTP record, if any."
  value       = local.route53_zone_id
}

output "vpc_id" {
  description = "VPC hosting the Transfer endpoint, if VPC-hosted."
  value       = local.is_vpc ? local.vpc_id : null
}

output "subnet_ids" {
  description = "Subnets hosting the Transfer endpoint, if VPC-hosted."
  value       = local.is_vpc ? local.subnet_ids : []
}

output "security_group_id" {
  description = "ID of the security group created for the Transfer endpoint, if any."
  value       = local.create_sg ? aws_security_group.transfer[0].id : null
}

output "elastic_ips" {
  description = "Public IPs of the Elastic IPs created for the Transfer endpoint."
  value       = aws_eip.transfer[*].public_ip
}

output "logging_role_arn" {
  description = "IAM role ARN used for Transfer logging."
  value       = local.logging_role_arn
}

output "api_gateway_role_arn" {
  description = "IAM role ARN used for API Gateway authorization, if created."
  value       = local.create_api_gw_role ? aws_iam_role.api_gw[0].arn : null
}

output "log_group_name" {
  description = "CloudWatch log group receiving structured Transfer logs."
  value       = aws_cloudwatch_log_group.transfer.name
}

output "sftp_home_bucket" {
  description = "Name of the S3 bucket backing user home directories."
  value       = aws_s3_bucket.sftp_home.id
}

output "sftp_home_kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting SFTP home directories."
  value       = aws_kms_key.sftp_home.arn
}

output "sftp_user_arns" {
  description = "Map of user key to Transfer user ARN."
  value       = { for k, u in aws_transfer_user.this : k => u.arn }
}

output "sftp_user_role_arns" {
  description = "Map of user key to IAM role ARN."
  value       = { for k, r in aws_iam_role.sftp_user : k => r.arn }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The AWS provider (region = "us-east-1", default_tags Project = "md-k8s")
# is injected by the deployment harness and intentionally not declared here.

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "production"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  cluster_name = "md-k8s"
  vpc_cidr     = "192.168.0.0/16"

  public_subnet_cidrs = [
    "192.168.0.0/19",
    "192.168.32.0/19",
    "192.168.64.0/19",
  ]

  private_subnet_cidrs = [
    "192.168.96.0/19",
    "192.168.128.0/19",
    "192.168.160.0/19",
  ]

  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
    data.aws_availability_zones.available.names[2],
  ]

  cluster_tag_key    = "kubernetes.io/cluster/${local.cluster_name}"
  cluster_log_group  = "/aws/eks/${local.cluster_name}/cluster"
  partition          = data.aws_partition.current.partition
  account_root_arn   = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  log_group_arn_base = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Project     = local.cluster_name
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name                    = "${local.cluster_name}-vpc"
    (local.cluster_tag_key) = "shared"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "${local.cluster_name}-public-${local.azs[count.index]}"
    "kubernetes.io/role/elb" = "1"
    (local.cluster_tag_key)  = "shared"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                              = "${local.cluster_name}-private-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb" = "1"
    (local.cluster_tag_key)           = "shared"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "private" {
  name        = "${local.cluster_name}-private-subnet-group"
  description = "Private subnets for ${local.cluster_name}"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# KMS key for Kubernetes secrets envelope encryption and control plane logs
# -----------------------------------------------------------------------------

resource "aws_kms_key" "eks_secrets" {
  description             = "Envelope encryption key for ${local.cluster_name} EKS secrets"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsEncryption"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "${local.log_group_arn_base}:log-group:${local.cluster_log_group}"
          }
        }
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-eks-secrets"
  })
}

resource "aws_kms_alias" "eks_secrets" {
  name          = "alias/${local.cluster_name}-eks-secrets"
  target_key_id = aws_kms_key.eks_secrets.key_id
}

# -----------------------------------------------------------------------------
# IAM - EKS cluster service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_ec2_describe" {
  name = "${local.cluster_name}-ec2-describe"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DescribeEc2Networking"
        Effect = "Allow"
        Action = [
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeAddresses",
          "ec2:DescribeInternetGateways",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy" "eks_cloudwatch_metrics" {
  name = "${local.cluster_name}-cloudwatch-metrics"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishCloudWatchMetrics"
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      },
    ]
  })
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "eks_control_plane" {
  name        = "${local.cluster_name}-control-plane-sg"
  description = "Additional security group for the ${local.cluster_name} EKS control plane"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-control-plane-sg"
  })
}

resource "aws_security_group" "eks_nodes" {
  name        = "${local.cluster_name}-node-shared-sg"
  description = "Shared security group for ${local.cluster_name} worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name                    = "${local.cluster_name}-node-shared-sg"
    (local.cluster_tag_key) = "owned"
  })
}

resource "aws_vpc_security_group_ingress_rule" "control_plane_https_from_nodes" {
  security_group_id            = aws_security_group.eks_control_plane.id
  description                  = "Allow nodes to reach the Kubernetes API over HTTPS"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.eks_nodes.id
}

resource "aws_vpc_security_group_egress_rule" "control_plane_to_vpc" {
  security_group_id = aws_security_group.eks_control_plane.id
  description       = "Allow control plane egress within the VPC only"
  ip_protocol       = "-1"
  cidr_ipv4         = local.vpc_cidr
}

resource "aws_vpc_security_group_ingress_rule" "nodes_self" {
  security_group_id            = aws_security_group.eks_nodes.id
  description                  = "Allow node-to-node traffic"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.eks_nodes.id
}

resource "aws_vpc_security_group_ingress_rule" "nodes_from_cluster_sg" {
  security_group_id            = aws_security_group.eks_nodes.id
  description                  = "Allow traffic from the EKS-managed cluster security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_eks_cluster.md_k8s.vpc_config[0].cluster_security_group_id
}

resource "aws_vpc_security_group_egress_rule" "nodes_to_vpc" {
  security_group_id = aws_security_group.eks_nodes.id
  description       = "Allow node egress within the VPC only"
  ip_protocol       = "-1"
  cidr_ipv4         = local.vpc_cidr
}

# -----------------------------------------------------------------------------
# EKS control plane
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "eks_cluster" {
  name              = local.cluster_log_group
  retention_in_days = 365
  kms_key_id        = aws_kms_key.eks_secrets.arn

  tags = local.common_tags
}

resource "aws_eks_cluster" "md_k8s" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  enabled_cluster_log_types = [
    "api",
    "audit",
    "authenticator",
    "controllerManager",
    "scheduler",
  ]

  access_config {
    authentication_mode                         = "API_AND_CONFIG_MAP"
    bootstrap_cluster_creator_admin_permissions = true
  }

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids      = [aws_security_group.eks_control_plane.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks_secrets.arn
    }
  }

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_ec2_describe,
    aws_iam_role_policy.eks_cloudwatch_metrics,
    aws_cloudwatch_log_group.eks_cluster,
    aws_route_table_association.private,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cluster_name" {
  description = "Name of the EKS cluster."
  value       = aws_eks_cluster.md_k8s.name
}

output "cluster_arn" {
  description = "ARN of the EKS cluster."
  value       = aws_eks_cluster.md_k8s.arn
}

output "cluster_endpoint" {
  description = "Private API server endpoint of the EKS cluster."
  value       = aws_eks_cluster.md_k8s.endpoint
}

output "cluster_certificate_authority_data" {
  description = "Base64-encoded certificate authority data for the cluster."
  value       = aws_eks_cluster.md_k8s.certificate_authority[0].data
}

output "cluster_security_group_id" {
  description = "EKS-managed cluster security group ID."
  value       = aws_eks_cluster.md_k8s.vpc_config[0].cluster_security_group_id
}

output "control_plane_security_group_id" {
  description = "Additional control plane security group ID."
  value       = aws_security_group.eks_control_plane.id
}

output "node_security_group_id" {
  description = "Shared node security group ID."
  value       = aws_security_group.eks_nodes.id
}

output "cluster_role_arn" {
  description = "ARN of the EKS cluster service role."
  value       = aws_iam_role.eks_cluster.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for secrets envelope encryption."
  value       = aws_kms_key.eks_secrets.arn
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_public_ip" {
  description = "Public IP of the NAT gateway."
  value       = aws_eip.nat.public_ip
}

output "db_subnet_group_name" {
  description = "Name of the private DB subnet group."
  value       = aws_db_subnet_group.private.name
}

# Provider configuration is injected by the deployment harness, so this file has no
# provider block and no backend block. The label tags in local.tags are set
# explicitly on every taggable resource, which gives the same result as
# provider-level default_tags.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata (used only for KMS key policy / bucket policy principals)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Label inputs (self-contained replacement for an external label module)
# -----------------------------------------------------------------------------

variable "namespace" {
  description = "Namespace, usually an abbreviation of the organization name."
  type        = string
  default     = "eg"
}

variable "environment" {
  description = "Environment or region identifier, e.g. 'use1'."
  type        = string
  default     = "use1"
}

variable "stage" {
  description = "Stage, e.g. 'prod', 'staging', 'dev'."
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Component or solution name."
  type        = string
  default     = "general-purpose"
}

variable "attributes" {
  description = "Additional attributes appended to the generated ID."
  type        = list(string)
  default     = []
}

variable "delimiter" {
  description = "Delimiter placed between label parts."
  type        = string
  default     = "-"
}

variable "tags" {
  description = "Additional tags merged into the generated label tags."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Feature switches
# -----------------------------------------------------------------------------

variable "enabled" {
  description = "Master switch for the optional bucket features. The bucket, public access block, ownership controls, versioning, encryption and baseline TLS policy are always created."
  type        = bool
  default     = true
}

variable "versioning_enabled" {
  description = "Enable versioning on the bucket. Forced on when object lock is enabled."
  type        = bool
  default     = true
}

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: 'aws:kms' or 'AES256'."
  type        = string
  default     = "aws:kms"

  validation {
    condition     = contains(["aws:kms", "AES256"], var.sse_algorithm)
    error_message = "sse_algorithm must be either \"aws:kms\" or \"AES256\"."
  }
}

variable "kms_master_key_id" {
  description = "Optional existing KMS key ARN or ID. When empty and sse_algorithm is aws:kms, a dedicated customer-managed key is created."
  type        = string
  default     = ""
}

variable "lifecycle_rules" {
  description = "Lifecycle rules. Day values of null disable that transition or expiration."
  type = list(object({
    id                                     = string
    enabled                                = optional(bool, true)
    prefix                                 = optional(string, "")
    standard_ia_transition_days            = optional(number)
    glacier_transition_days                = optional(number)
    deep_archive_transition_days           = optional(number)
    expiration_days                        = optional(number)
    noncurrent_version_glacier_days        = optional(number)
    noncurrent_version_expiration_days     = optional(number)
    abort_incomplete_multipart_upload_days = optional(number, 7)
  }))
  default = []
}

variable "logging_enabled" {
  description = "Enable server access logging to a dedicated log bucket created by this configuration."
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "Enable static website hosting configuration."
  type        = bool
  default     = false
}

variable "index_document" {
  description = "Website index document."
  type        = string
  default     = "index.html"
}

variable "error_document" {
  description = "Website error document."
  type        = string
  default     = "error.html"
}

variable "routing_rules" {
  description = "Website routing rules."
  type = list(object({
    condition = optional(object({
      key_prefix_equals               = optional(string)
      http_error_code_returned_equals = optional(string)
    }))
    redirect = object({
      host_name               = optional(string)
      http_redirect_code      = optional(string)
      protocol                = optional(string)
      replace_key_prefix_with = optional(string)
      replace_key_with        = optional(string)
    })
  }))
  default = []
}

variable "cors_rules" {
  description = "CORS rules for the bucket."
  type = list(object({
    allowed_headers = optional(list(string), [])
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock. Can only be set at bucket creation."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default object lock retention mode: GOVERNANCE or COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Default object lock retention period in days."
  type        = number
  default     = 30

  validation {
    condition     = var.object_lock_days > 0
    error_message = "object_lock_days must be greater than 0."
  }
}

variable "policy_enabled" {
  description = "Append the statements from policy_statements to the bucket policy."
  type        = bool
  default     = false
}

variable "policy_statements" {
  description = "Additional bucket policy statements. When resources is empty, the statement applies to the bucket and all of its objects."
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = optional(list(string), [])
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = []

  validation {
    condition = alltrue([
      for s in var.policy_statements : !(contains(s.actions, "*") && contains(s.resources, "*"))
    ])
    error_message = "A policy statement may not use \"*\" for both actions and resources."
  }
}

variable "acceleration_status" {
  description = "Transfer acceleration status: Enabled or Suspended."
  type        = string
  default     = "Suspended"

  validation {
    condition     = contains(["Enabled", "Suspended"], var.acceleration_status)
    error_message = "acceleration_status must be Enabled or Suspended."
  }
}

variable "request_payer" {
  description = "Who pays for requests and data transfer: BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"

  validation {
    condition     = contains(["BucketOwner", "Requester"], var.request_payer)
    error_message = "request_payer must be BucketOwner or Requester."
  }
}

variable "canned_acl" {
  description = "Kept for interface compatibility only. ACLs are disabled (BucketOwnerEnforced), so only \"private\" is accepted."
  type        = string
  default     = "private"

  validation {
    condition     = var.canned_acl == "private"
    error_message = "ACLs are disabled through BucketOwnerEnforced ownership and an always-on public access block. canned_acl must be \"private\". Use policy_statements instead."
  }
}

variable "grants" {
  description = "Kept for interface compatibility only. ACL grants are not supported because ACLs are disabled, so this list must be empty."
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  default = []

  validation {
    condition     = length(var.grants) == 0
    error_message = "ACL grants are not supported because ACLs are disabled (BucketOwnerEnforced). Use policy_statements to grant access."
  }
}

# -----------------------------------------------------------------------------
# Label / locals
# -----------------------------------------------------------------------------

locals {
  label_parts = compact(concat(
    [var.namespace, var.environment, var.stage, var.name],
    var.attributes
  ))

  id = lower(join(var.delimiter, local.label_parts))

  tags = merge(
    var.tags,
    {
      Name        = local.id
      Namespace   = var.namespace
      Environment = var.environment
      Stage       = var.stage
      ManagedBy   = "terraform"
    }
  )

  logs_bucket_name = "${local.id}-logs"

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  root_arn   = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  kms_enabled    = var.sse_algorithm == "aws:kms"
  create_kms_key = local.kms_enabled && var.kms_master_key_id == ""

  kms_key_arn = local.kms_enabled ? (
    var.kms_master_key_id != "" ? var.kms_master_key_id : aws_kms_key.bucket[0].arn
  ) : null

  versioning_status = (var.versioning_enabled || var.object_lock_enabled) ? "Enabled" : "Suspended"

  lifecycle_enabled    = var.enabled && length(var.lifecycle_rules) > 0
  logging_enabled      = var.enabled && var.logging_enabled
  website_enabled      = var.enabled && var.website_enabled
  cors_enabled         = var.enabled && length(var.cors_rules) > 0
  object_lock_enabled  = var.enabled && var.object_lock_enabled
  acceleration_enabled = var.enabled && var.acceleration_status == "Enabled"
  requester_pays       = var.enabled && var.request_payer == "Requester"
  custom_policy        = var.enabled && var.policy_enabled

  custom_policy_statements = local.custom_policy ? var.policy_statements : []
}

# -----------------------------------------------------------------------------
# KMS key (created only when using aws:kms without a supplied key)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid     = "EnableRootAccountAdministration"
    effect  = "Allow"
    actions = ["kms:*"]

    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  statement {
    sid    = "AllowS3UseOfTheKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_partition.current.dns_suffix != "" ? "" : ""}${replace(local.partition, "aws", "") == "" ? "" : ""}us-east-1.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "bucket" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer-managed key for S3 bucket ${local.id}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = local.tags
}

resource "aws_kms_alias" "bucket" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${local.id}"
  target_key_id = aws_kms_key.bucket[0].key_id
}

# -----------------------------------------------------------------------------
# Primary bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket              = local.id
  force_destroy       = false
  object_lock_enabled = var.object_lock_enabled

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = local.versioning_status
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = local.kms_enabled
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.lifecycle_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      filter {
        prefix = rule.value.prefix
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "transition" {
        for_each = rule.value.standard_ia_transition_days != null ? [rule.value.standard_ia_transition_days] : []
        content {
          days          = transition.value
          storage_class = "STANDARD_IA"
        }
      }

      dynamic "transition" {
        for_each = rule.value.glacier_transition_days != null ? [rule.value.glacier_transition_days] : []
        content {
          days          = transition.value
          storage_class = "GLACIER"
        }
      }

      dynamic "transition" {
        for_each = rule.value.deep_archive_transition_days != null ? [rule.value.deep_archive_transition_days] : []
        content {
          days          = transition.value
          storage_class = "DEEP_ARCHIVE"
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [rule.value.expiration_days] : []
        content {
          days = expiration.value
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_glacier_days != null ? [rule.value.noncurrent_version_glacier_days] : []
        content {
          noncurrent_days = noncurrent_version_transition.value
          storage_class   = "GLACIER"
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [rule.value.noncurrent_version_expiration_days] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# -----------------------------------------------------------------------------
# Access logging target bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "logs" {
  count = local.logging_enabled ? 1 : 0

  bucket        = local.logs_bucket_name
  force_destroy = false

  tags = merge(local.tags, { Name = local.logs_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server access log delivery supports only SSE-S3 on the target bucket.
resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "logs" {
  count = local.logging_enabled ? 1 : 0

  statement {
    sid       = "S3ServerAccessLogsPolicy"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs[0].arn}/log/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.this.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.logs[0].arn,
      "${aws_s3_bucket.logs[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id
  policy = data.aws_iam_policy_document.logs[0].json

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

resource "aws_s3_bucket_logging" "this" {
  count = local.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = aws_s3_bucket.logs[0].id
  target_prefix = "log/"

  depends_on = [aws_s3_bucket_policy.logs]
}

# -----------------------------------------------------------------------------
# Static website hosting
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = var.index_document
  }

  error_document {
    key = var.error_document
  }

  dynamic "routing_rule" {
    for_each = var.routing_rules

    content {
      dynamic "condition" {
        for_each = routing_rule.value.condition != null ? [routing_rule.value.condition] : []
        content {
          key_prefix_equals               = condition.value.key_prefix_equals
          http_error_code_returned_equals = condition.value.http_error_code_returned_equals
        }
      }

      redirect {
        host_name               = routing_rule.value.redirect.host_name
        http_redirect_code      = routing_rule.value.redirect.http_redirect_code
        protocol                = routing_rule.value.redirect.protocol
        replace_key_prefix_with = routing_rule.value.redirect.replace_key_prefix_with
        replace_key_with        = routing_rule.value.redirect.replace_key_with
      }
    }
  }
}

# -----------------------------------------------------------------------------
# CORS
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.cors_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Object lock
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# -----------------------------------------------------------------------------
# Transfer acceleration / requester pays
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.acceleration_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.requester_pays ? 1 : 0

  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

# -----------------------------------------------------------------------------
# Bucket policy (TLS-deny baseline + optional custom statements)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = local.custom_policy_statements

    content {
      sid     = statement.value.sid
      effect  = statement.value.effect
      actions = statement.value.actions
      resources = length(statement.value.resources) > 0 ? statement.value.resources : [
        aws_s3_bucket.this.arn,
        "${aws_s3_bucket.this.arn}/*",
      ]

      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "bucket_id" {
  description = "ID (name) of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Domain name of the bucket."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Regional domain name of the bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "tags" {
  description = "Tags applied to the bucket, generated by the label."
  value       = aws_s3_bucket.this.tags_all
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for bucket encryption, or null when AES256 is used."
  value       = local.kms_key_arn
}

output "logs_bucket_id" {
  description = "ID of the access log target bucket, or null when logging is disabled."
  value       = local.logging_enabled ? aws_s3_bucket.logs[0].id : null
}

output "website_endpoint" {
  description = "Website endpoint, or null when website hosting is disabled."
  value       = local.website_enabled ? aws_s3_bucket_website_configuration.this[0].website_endpoint : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy the VPC into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC, used as the Name tag prefix for all resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "az_count" {
  description = "Number of availability zones to use. null means use all available AZs in the region."
  type        = number
  default     = null

  validation {
    condition     = var.az_count == null ? true : var.az_count >= 1
    error_message = "The az_count value must be null (all available AZs) or a number greater than or equal to 1."
  }
}

variable "create_public_subnets" {
  description = "Whether to create public subnets (and the internet gateway, public route table and public network ACL)."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets (and the private route table and private network ACL)."
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT gateway for private subnet egress. Requires both public and private subnets."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    Environment = "benchmark"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  vpc_cidr       = "10.0.0.0/18"
  all_cidr       = "0.0.0.0/0"
  available_azs  = data.aws_availability_zones.available.names
  az_count       = var.az_count == null ? length(local.available_azs) : min(var.az_count, length(local.available_azs))
  azs            = slice(local.available_azs, 0, local.az_count)
  nat_enabled    = var.create_nat_gateway && var.create_public_subnets && var.create_private_subnets
  subnet_newbits = 4
  private_offset = 8

  public_subnet_cidrs  = [for i in range(local.az_count) : cidrsubnet(local.vpc_cidr, local.subnet_newbits, i)]
  private_subnet_cidrs = [for i in range(local.az_count) : cidrsubnet(local.vpc_cidr, local.subnet_newbits, i + local.private_offset)]

  flow_log_group_name = "/aws/vpc/${var.vpc_name}/flow-logs"
  account_id          = data.aws_caller_identity.current.account_id
  partition           = data.aws_partition.current.partition
  region_name         = data.aws_region.current.name
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = var.vpc_name
  })
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-default-sg"
  })
}

# -----------------------------------------------------------------------------
# Internet gateway
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-igw"
  })
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-${count.index}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-${count.index}"
    Tier = "private"
  })
}

# -----------------------------------------------------------------------------
# NAT gateway
# -----------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = local.nat_enabled ? 1 : 0

  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.nat_enabled ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Route tables
# -----------------------------------------------------------------------------

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.all_cidr
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-rt"
  })
}

resource "aws_route" "private_nat" {
  count = local.nat_enabled ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = local.all_cidr
  nat_gateway_id         = aws_nat_gateway.main[0].id
}

resource "aws_route_table_association" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# -----------------------------------------------------------------------------
# Network ACLs
# -----------------------------------------------------------------------------

resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.public[*].id

  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = local.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 1024
    to_port    = 65535
  }

  ingress {
    rule_no    = 140
    protocol   = "udp"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 0
    to_port    = 0
  }

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-nacl"
  })
}

resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = local.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 1024
    to_port    = 65535
  }

  ingress {
    rule_no    = 120
    protocol   = "udp"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = local.all_cidr
    from_port  = 0
    to_port    = 0
  }

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-nacl"
  })
}

# -----------------------------------------------------------------------------
# VPC flow logs
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "flow_logs_kms" {
  statement {
    sid       = "EnableRootAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsUse"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region_name}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region_name}:${local.account_id}:log-group:${local.flow_log_group_name}"]
    }
  }
}

resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for ${var.vpc_name} VPC flow log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.flow_logs_kms.json

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-flow-logs-kms"
  })
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/${var.vpc_name}-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = local.flow_log_group_name
  retention_in_days = 365
  kms_key_id        = aws_kms_key.flow_logs.arn

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-flow-logs"
  })
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "${var.vpc_name}-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-flow-logs-role"
  })
}

data "aws_iam_policy_document" "flow_logs_publish" {
  statement {
    sid    = "PublishFlowLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]
    resources = [
      aws_cloudwatch_log_group.flow_logs.arn,
      "${aws_cloudwatch_log_group.flow_logs.arn}:*",
    ]
  }

  statement {
    sid       = "DescribeLogGroups"
    effect    = "Allow"
    actions   = ["logs:DescribeLogGroups"]
    resources = ["arn:${local.partition}:logs:${local.region_name}:${local.account_id}:log-group:*"]
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name   = "${var.vpc_name}-flow-logs-policy"
  role   = aws_iam_role.flow_logs.id
  policy = data.aws_iam_policy_document.flow_logs_publish.json
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn             = aws_iam_role.flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-flow-log"
  })

  depends_on = [aws_iam_role_policy.flow_logs]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the subnets."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway, or null if not created."
  value       = try(aws_internet_gateway.main[0].id, null)
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway, or null if not created."
  value       = try(aws_nat_gateway.main[0].id, null)
}

output "nat_gateway_public_ip" {
  description = "Public IP of the NAT gateway, or null if not created."
  value       = try(aws_eip.nat[0].public_ip, null)
}

output "public_route_table_id" {
  description = "ID of the public route table, or null if not created."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_id" {
  description = "ID of the private route table, or null if not created."
  value       = try(aws_route_table.private[0].id, null)
}

output "public_network_acl_id" {
  description = "ID of the public network ACL, or null if not created."
  value       = try(aws_network_acl.public[0].id, null)
}

output "private_network_acl_id" {
  description = "ID of the private network ACL, or null if not created."
  value       = try(aws_network_acl.private[0].id, null)
}

output "default_security_group_id" {
  description = "ID of the VPC default security group (locked down, deny-all)."
  value       = aws_default_security_group.default.id
}

output "flow_log_id" {
  description = "ID of the VPC flow log."
  value       = aws_flow_log.main.id
}

output "flow_log_group_name" {
  description = "Name of the CloudWatch log group receiving VPC flow logs."
  value       = aws_cloudwatch_log_group.flow_logs.name
}

# Omits the provider block because the deployment harness injects it.
# Target region: us-east-1.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr_block" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  description = "Request an Amazon-provided IPv6 CIDR block for the VPC and its subnets."
  type        = bool
  default     = true
}

variable "instance_tenancy" {
  description = "Tenancy option for instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "sn_details" {
  description = "Subnet definitions: name, index into available AZs, and whether the subnet is public."
  type = list(object({
    name      = string
    az_index  = number
    is_public = bool
  }))
  default = [
    { name = "sn-web-a", az_index = 0, is_public = true },
    { name = "sn-app-a", az_index = 0, is_public = false },
    { name = "sn-db-a", az_index = 0, is_public = false },
    { name = "sn-reserved-a", az_index = 0, is_public = false },
    { name = "sn-web-b", az_index = 1, is_public = true },
    { name = "sn-app-b", az_index = 1, is_public = false },
    { name = "sn-db-b", az_index = 1, is_public = false },
    { name = "sn-reserved-b", az_index = 1, is_public = false },
    { name = "sn-web-c", az_index = 2, is_public = true },
    { name = "sn-app-c", az_index = 2, is_public = false },
    { name = "sn-db-c", az_index = 2, is_public = false },
    { name = "sn-reserved-c", az_index = 2, is_public = false },
  ]
}

locals {
  vpc_name         = "main-vpc"
  tcp_protocol     = "tcp"
  https_port       = 443
  ssh_port         = 22
  any_ipv4_cidr    = "0.0.0.0/0"
  any_ipv6_cidr    = "::/0"
  ipv4_subnet_bits = 4
  ipv6_subnet_bits = 8

  subnets = { for sn in var.sn_details : sn.name => sn }

  public_subnets = { for name, sn in local.subnets : name => sn if sn.is_public }
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr_block
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support

  tags = {
    Name = local.vpc_name
  }
}

module "subnet_addrs_ipv4" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block
  networks = [
    for sn in var.sn_details : {
      name     = sn.name
      new_bits = local.ipv4_subnet_bits
    }
  ]
}

module "subnet_addrs_ipv6" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"
  count   = var.is_ipv6_enabled ? 1 : 0

  base_cidr_block = aws_vpc.main.ipv6_cidr_block
  networks = [
    for sn in var.sn_details : {
      name     = sn.name
      new_bits = local.ipv6_subnet_bits
    }
  ]
}

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                          = aws_vpc.main.id
  availability_zone               = data.aws_availability_zones.available.names[each.value.az_index]
  cidr_block                      = module.subnet_addrs_ipv4.network_cidr_blocks[each.key]
  ipv6_cidr_block                 = var.is_ipv6_enabled ? module.subnet_addrs_ipv6[0].network_cidr_blocks[each.key] : null
  assign_ipv6_address_on_creation = var.is_ipv6_enabled
  map_public_ip_on_launch         = false

  tags = {
    Name = each.key
    Tier = each.value.is_public ? "public" : "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public_rt_web" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4_default" {
  route_table_id         = aws_route_table.public_rt_web.id
  destination_cidr_block = local.any_ipv4_cidr
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_default" {
  count = var.is_ipv6_enabled ? 1 : 0

  route_table_id              = aws_route_table.public_rt_web.id
  destination_ipv6_cidr_block = local.any_ipv6_cidr
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public_rt_web.id
}

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Web tier: public HTTPS ingress, SSH from VPC, HTTPS egress to app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "App tier: HTTPS ingress from web tier, HTTPS egress to db tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Database tier: HTTPS ingress from app tier only"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "web_https_in" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Public TLS entry point"
  ip_protocol       = local.tcp_protocol
  from_port         = local.https_port
  to_port           = local.https_port
  cidr_ipv4         = local.any_ipv4_cidr
}

resource "aws_vpc_security_group_ingress_rule" "web_ssh_in" {
  security_group_id = aws_security_group.web_sg.id
  description       = "SSH from within the VPC only"
  ip_protocol       = local.tcp_protocol
  from_port         = local.ssh_port
  to_port           = local.ssh_port
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_vpc_security_group_egress_rule" "web_to_app_https" {
  security_group_id            = aws_security_group.web_sg.id
  description                  = "HTTPS to app tier"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.https_port
  to_port                      = local.https_port
  referenced_security_group_id = aws_security_group.app_sg.id
}

resource "aws_vpc_security_group_ingress_rule" "app_https_from_web" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "HTTPS from web tier"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.https_port
  to_port                      = local.https_port
  referenced_security_group_id = aws_security_group.web_sg.id
}

resource "aws_vpc_security_group_egress_rule" "app_to_db_https" {
  security_group_id            = aws_security_group.app_sg.id
  description                  = "HTTPS to db tier"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.https_port
  to_port                      = local.https_port
  referenced_security_group_id = aws_security_group.db_sg.id
}

resource "aws_vpc_security_group_ingress_rule" "db_https_from_app" {
  security_group_id            = aws_security_group.db_sg.id
  description                  = "HTTPS from app tier"
  ip_protocol                  = local.tcp_protocol
  from_port                    = local.https_port
  to_port                      = local.https_port
  referenced_security_group_id = aws_security_group.app_sg.id
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "IPv4 CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block of the VPC (null when IPv6 is disabled)."
  value       = var.is_ipv6_enabled ? aws_vpc.main.ipv6_cidr_block : null
}

output "subnet_ids" {
  description = "Map of subnet name to subnet ID."
  value       = { for name, sn in aws_subnet.this : name => sn.id }
}

output "subnet_ipv4_cidr_blocks" {
  description = "Map of subnet name to IPv4 CIDR block."
  value       = module.subnet_addrs_ipv4.network_cidr_blocks
}

output "subnet_ipv6_cidr_blocks" {
  description = "Map of subnet name to IPv6 CIDR block (null when IPv6 is disabled)."
  value       = var.is_ipv6_enabled ? module.subnet_addrs_ipv6[0].network_cidr_blocks : null
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = [for name in keys(local.public_subnets) : aws_subnet.this[name].id]
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public_rt_web.id
}

output "web_sg_id" {
  description = "ID of the web tier security group."
  value       = aws_security_group.web_sg.id
}

output "app_sg_id" {
  description = "ID of the app tier security group."
  value       = aws_security_group.app_sg.id
}

output "db_sg_id" {
  description = "ID of the database tier security group."
  value       = aws_security_group.db_sg.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket that stores canary artifacts."
  type        = string
  default     = "benchmark-canary-bucket-tf5x"
}

variable "s3_versioning_enabled" {
  description = "Whether versioning is enabled on the canary artifact bucket."
  type        = bool
  default     = false
}

variable "enable_kms" {
  description = "Whether to create and use a customer managed KMS key."
  type        = bool
  default     = true
}

variable "kms_alias" {
  description = "Alias for the customer managed KMS key."
  type        = string
  default     = "alias/benchmark-canary-key"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic for canary failure notifications."
  type        = string
  default     = "benchmark-canary-topic"
}

variable "alarm_email" {
  description = "Email address subscribed to canary failure notifications."
  type        = string
  default     = "nobody@example.com"
}

variable "enable_success_percent_alarm" {
  description = "Whether to create a SuccessPercent alarm for each canary."
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for the canary VPC."
  type        = string
  default     = "10.20.0.0/16"
}

variable "health_check_target_cidrs" {
  description = "Explicit IPv4 CIDRs of the health-check targets the canaries are allowed to reach on TCP 80/443 (defaults to example.com addresses)."
  type        = list(string)
  default = [
    "23.192.228.80/32",
    "23.192.228.84/32",
    "23.215.0.136/32",
    "23.215.0.138/32",
    "96.7.128.175/32",
    "96.7.128.198/32",
  ]

  validation {
    condition = alltrue([
      for c in var.health_check_target_cidrs :
      can(cidrhost(c, 0)) && !contains(["0.0.0.0/0", "::/0"], c)
    ])
    error_message = "health_check_target_cidrs must contain valid, specific CIDRs; 0.0.0.0/0 and ::/0 are not allowed."
  }
}

variable "cors_rules" {
  description = "CORS rules applied to the canary artifact bucket."
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = list(string)
    max_age_seconds = number
  }))
  default = [
    {
      allowed_headers = ["*"]
      allowed_methods = ["GET", "PUT"]
      allowed_origins = ["*"]
      expose_headers  = ["ETag"]
      max_age_seconds = 3000
    }
  ]
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "benchmark-canary"
    ManagedBy = "terraform"
  }
}

variable "vpc_canaries" {
  description = "Map of VPC canary configurations keyed by canary name (lowercase, max 21 characters)."
  type = map(object({
    schedule_expression = string
    handler             = string
    runtime_version     = string
    source_type         = string
    script_content      = optional(string)
    s3_key              = optional(string)
  }))
  default = {
    "health-check" = {
      schedule_expression = "rate(5 minutes)"
      handler             = "canary.handler"
      runtime_version     = "syn-nodejs-puppeteer-9.1"
      source_type         = "zip"
      script_content      = <<-EOT
        const synthetics = require('Synthetics');
        const log = require('SyntheticsLogger');

        const apiCanaryBlueprint = async function () {
          const requestOptions = {
            hostname: 'example.com',
            method: 'GET',
            path: '/',
            port: 443,
            protocol: 'https:'
          };

          const validateSuccessful = async function (res) {
            return new Promise((resolve, reject) => {
              if (res.statusCode < 200 || res.statusCode > 299) {
                reject(new Error(res.statusCode + ' ' + res.statusMessage));
              }
              res.on('data', () => {});
              res.on('end', () => resolve());
            });
          };

          log.info('Starting health check');
          await synthetics.executeHttpStep('healthCheck', requestOptions, validateSuccessful);
        };

        exports.handler = async () => {
          return await apiCanaryBlueprint();
        };
      EOT
    }
  }

  validation {
    condition     = alltrue([for k, v in var.vpc_canaries : contains(["zip", "s3"], v.source_type)])
    error_message = "Each canary source_type must be either \"zip\" or \"s3\"."
  }
}

locals {
  name_prefix = "benchmark-canary"

  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  canary_subnet_ids         = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  canary_security_group_ids = [aws_security_group.canary.id]

  s3_canaries = { for k, v in var.vpc_canaries : k => v if v.source_type == "s3" }

  kms_key_arn = var.enable_kms ? aws_kms_key.canary[0].arn : null

  interface_endpoint_services = toset(concat(["monitoring", "logs"], var.enable_kms ? ["kms"] : []))

  health_check_cidrs = toset(var.health_check_target_cidrs)

  cloudwatch_namespace = "CloudWatchSynthetics"
  cloudwatch_principal = "cloudwatch.amazonaws.com"
  any_ipv4_cidr        = "0.0.0.0/0"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "${local.name_prefix}-public-a" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 10)
  availability_zone = local.azs[0]

  tags = merge(var.tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 11)
  availability_zone = local.azs[1]

  tags = merge(var.tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.tags, { Name = "${local.name_prefix}-nat-eip" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_a.id

  tags = merge(var.tags, { Name = "${local.name_prefix}-nat" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.any_ipv4_cidr
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(var.tags, { Name = "${local.name_prefix}-s3-endpoint" })
}

resource "aws_security_group" "canary" {
  name        = "${local.name_prefix}-sg"
  description = "Egress-only security group for CloudWatch Synthetics canaries"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, { Name = "${local.name_prefix}-sg" })
}

resource "aws_vpc_security_group_egress_rule" "canary_s3_https" {
  security_group_id = aws_security_group.canary.id
  description       = "HTTPS egress to S3 through the gateway endpoint prefix list"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  prefix_list_id    = aws_vpc_endpoint.s3.prefix_list_id

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "canary_vpc_https" {
  security_group_id = aws_security_group.canary.id
  description       = "HTTPS egress to interface VPC endpoints inside the VPC"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = var.vpc_cidr

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "canary_health_https" {
  for_each = local.health_check_cidrs

  security_group_id = aws_security_group.canary.id
  description       = "HTTPS egress to health-check target ${each.value}"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = each.value

  tags = var.tags
}

resource "aws_vpc_security_group_egress_rule" "canary_health_http" {
  for_each = local.health_check_cidrs

  security_group_id = aws_security_group.canary.id
  description       = "HTTP egress to health-check target ${each.value}"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = each.value

  tags = var.tags
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpce-sg"
  description = "Security group for interface VPC endpoints used by the canaries"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, { Name = "${local.name_prefix}-vpce-sg" })
}

resource "aws_vpc_security_group_ingress_rule" "vpc_endpoints_from_canary" {
  security_group_id            = aws_security_group.vpc_endpoints.id
  description                  = "HTTPS from canary security group"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.canary.id

  tags = var.tags
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = merge(var.tags, { Name = "${local.name_prefix}-${each.value}-endpoint" })
}

# ---------------------------------------------------------------------------
# IAM
# ---------------------------------------------------------------------------

resource "random_pet" "role_prefix" {
  length    = 2
  separator = "-"
}

data "aws_iam_policy_document" "canary_assume_role" {
  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "canary_exec" {
  name               = "${random_pet.role_prefix.id}-canary-exec-role"
  assume_role_policy = data.aws_iam_policy_document.canary_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "canary_exec" {
  statement {
    sid       = "S3ObjectReadWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject", "s3:GetObject"]
    resources = ["${aws_s3_bucket.canary_artifacts.arn}/*"]
  }

  statement {
    sid       = "S3BucketList"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = [aws_s3_bucket.canary_artifacts.arn]
  }

  statement {
    sid       = "S3ListAllBuckets"
    effect    = "Allow"
    actions   = ["s3:ListAllMyBuckets"]
    resources = ["*"]
  }

  statement {
    sid       = "CloudWatchPutMetrics"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "cloudwatch:namespace"
      values   = [local.cloudwatch_namespace]
    }
  }

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/cwsyn-*",
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/cwsyn-*:*",
    ]
  }

  statement {
    sid    = "Ec2NetworkInterfaces"
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
    ]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = var.enable_kms ? [1] : []
    content {
      sid       = "KmsArtifactEncryption"
      effect    = "Allow"
      actions   = ["kms:Decrypt", "kms:GenerateDataKey"]
      resources = [aws_kms_key.canary[0].arn]
    }
  }
}

resource "aws_iam_policy" "canary_exec" {
  name        = "${random_pet.role_prefix.id}-canary-exec-policy"
  description = "Least-privilege execution policy for CloudWatch Synthetics VPC canaries"
  policy      = data.aws_iam_policy_document.canary_exec.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "canary_exec" {
  role       = aws_iam_role.canary_exec.name
  policy_arn = aws_iam_policy.canary_exec.arn
}

# ---------------------------------------------------------------------------
# KMS
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_canary" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchUseOfKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.cloudwatch_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "canary" {
  count = var.enable_kms ? 1 : 0

  description             = "KMS key for CloudWatch Synthetics canary artifacts and alerts"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_canary.json

  tags = var.tags
}

resource "aws_kms_alias" "canary" {
  count = var.enable_kms ? 1 : 0

  name          = var.kms_alias
  target_key_id = aws_kms_key.canary[0].key_id
}

# ---------------------------------------------------------------------------
# S3 artifact bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "canary_artifacts" {
  bucket        = var.s3_bucket_name
  force_destroy = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "canary_artifacts" {
  bucket = aws_s3_bucket.canary_artifacts.id

  versioning_configuration {
    status = var.s3_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "canary_artifacts" {
  bucket = aws_s3_bucket.canary_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_cors_configuration" "canary_artifacts" {
  bucket = aws_s3_bucket.canary_artifacts.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary_artifacts" {
  bucket = aws_s3_bucket.canary_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Canary sources
# ---------------------------------------------------------------------------

data "archive_file" "canary_zip" {
  for_each = var.vpc_canaries

  type        = "zip"
  output_path = "${path.module}/build/${each.key}.zip"

  source {
    content  = coalesce(each.value.script_content, "exports.handler = async () => {};")
    filename = "nodejs/node_modules/canary.js"
  }
}

resource "aws_s3_object" "canary_script" {
  for_each = local.s3_canaries

  bucket      = aws_s3_bucket.canary_artifacts.id
  key         = coalesce(each.value.s3_key, "canary-sources/${each.key}.zip")
  source      = data.archive_file.canary_zip[each.key].output_path
  source_hash = data.archive_file.canary_zip[each.key].output_base64sha256

  tags = var.tags

  depends_on = [aws_s3_bucket_server_side_encryption_configuration.canary_artifacts]
}

# ---------------------------------------------------------------------------
# SNS
# ---------------------------------------------------------------------------

resource "aws_sns_topic" "canary_alerts" {
  name              = var.sns_topic_name
  kms_master_key_id = var.enable_kms ? aws_kms_key.canary[0].id : "alias/aws/sns"

  tags = var.tags
}

data "aws_iam_policy_document" "sns_canary_alerts" {
  statement {
    sid       = "AllowCloudWatchAlarmsPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.canary_alerts.arn]

    principals {
      type        = "Service"
      identifiers = [local.cloudwatch_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAccountTopicManagement"
    effect = "Allow"
    actions = [
      "sns:GetTopicAttributes",
      "sns:SetTopicAttributes",
      "sns:Subscribe",
      "sns:ListSubscriptionsByTopic",
      "sns:Publish",
    ]
    resources = [aws_sns_topic.canary_alerts.arn]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_sns_topic_policy" "canary_alerts" {
  arn    = aws_sns_topic.canary_alerts.arn
  policy = data.aws_iam_policy_document.sns_canary_alerts.json
}

resource "aws_sns_topic_subscription" "canary_email" {
  topic_arn = aws_sns_topic.canary_alerts.arn
  protocol  = "email"
  endpoint  = var.alarm_email
}

# ---------------------------------------------------------------------------
# Synthetics canaries
# ---------------------------------------------------------------------------

resource "aws_synthetics_canary" "vpc" {
  for_each = var.vpc_canaries

  name                 = each.key
  artifact_s3_location = "s3://${aws_s3_bucket.canary_artifacts.id}/canary-artifacts/${each.key}/"
  execution_role_arn   = aws_iam_role.canary_exec.arn
  handler              = each.value.handler
  runtime_version      = each.value.runtime_version
  start_canary         = true
  delete_lambda        = true

  zip_file  = each.value.source_type == "zip" ? data.archive_file.canary_zip[each.key].output_path : null
  s3_bucket = each.value.source_type == "s3" ? aws_s3_bucket.canary_artifacts.id : null
  s3_key    = each.value.source_type == "s3" ? aws_s3_object.canary_script[each.key].key : null

  schedule {
    expression = each.value.schedule_expression
  }

  run_config {
    timeout_in_seconds = 120
  }

  vpc_config {
    subnet_ids         = local.canary_subnet_ids
    security_group_ids = local.canary_security_group_ids
  }

  dynamic "artifact_config" {
    for_each = var.enable_kms ? [1] : []
    content {
      s3_encryption {
        encryption_mode = "SSE_KMS"
        kms_key_arn     = aws_kms_key.canary[0].arn
      }
    }
  }

  tags = var.tags

  depends_on = [
    aws_iam_role_policy_attachment.canary_exec,
    aws_s3_bucket_public_access_block.canary_artifacts,
    aws_s3_bucket_server_side_encryption_configuration.canary_artifacts,
    aws_route_table_association.private_a,
    aws_route_table_association.private_b,
    aws_vpc_endpoint.s3,
    aws_vpc_endpoint.interface,
    aws_vpc_security_group_ingress_rule.vpc_endpoints_from_canary,
    aws_vpc_security_group_egress_rule.canary_s3_https,
    aws_vpc_security_group_egress_rule.canary_vpc_https,
    aws_vpc_security_group_egress_rule.canary_health_https,
    aws_vpc_security_group_egress_rule.canary_health_http,
  ]
}

# ---------------------------------------------------------------------------
# CloudWatch alarms
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "canary_failed" {
  for_each = var.vpc_canaries

  alarm_name          = "${each.key}-canary-failed"
  alarm_description   = "Canary ${each.key} reported one or more failed runs."
  namespace           = local.cloudwatch_namespace
  metric_name         = "Failed"
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    CanaryName = aws_synthetics_canary.vpc[each.key].name
  }

  alarm_actions = [aws_sns_topic.canary_alerts.arn]

  tags = var.tags
}

resource "aws_cloudwatch_metric_alarm" "canary_success_percent" {
  for_each = var.enable_success_percent_alarm ? var.vpc_canaries : {}

  alarm_name          = "${each.key}-canary-success-percent"
  alarm_description   = "Canary ${each.key} success percentage fell below 90%."
  namespace           = local.cloudwatch_namespace
  metric_name         = "SuccessPercent"
  statistic           = "Average"
  period              = 300
  evaluation_periods  = 1
  threshold           = 90
  comparison_operator = "LessThanThreshold"
  treat_missing_data  = "notBreaching"

  dimensions = {
    CanaryName = aws_synthetics_canary.vpc[each.key].name
  }

  alarm_actions = [aws_sns_topic.canary_alerts.arn]
  ok_actions    = [aws_sns_topic.canary_alerts.arn]

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the canary VPC."
  value       = aws_vpc.main.id
}

output "canary_subnet_ids" {
  description = "Private subnet IDs the canaries run in."
  value       = local.canary_subnet_ids
}

output "canary_security_group_ids" {
  description = "Security group IDs attached to the canaries."
  value       = local.canary_security_group_ids
}

output "vpc_endpoint_ids" {
  description = "IDs of the S3 gateway endpoint and interface VPC endpoints."
  value = merge(
    { s3 = aws_vpc_endpoint.s3.id },
    { for k, e in aws_vpc_endpoint.interface : k => e.id }
  )
}

output "canary_execution_role_arn" {
  description = "ARN of the canary execution IAM role."
  value       = aws_iam_role.canary_exec.arn
}

output "canary_artifacts_bucket_name" {
  description = "Name of the S3 bucket storing canary artifacts."
  value       = aws_s3_bucket.canary_artifacts.id
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key (null when disabled)."
  value       = local.kms_key_arn
}

output "sns_topic_arn" {
  description = "ARN of the canary alert SNS topic."
  value       = aws_sns_topic.canary_alerts.arn
}

output "canary_names" {
  description = "Names of the deployed Synthetics canaries."
  value       = { for k, c in aws_synthetics_canary.vpc : k => c.name }
}

output "canary_arns" {
  description = "ARNs of the deployed Synthetics canaries."
  value       = { for k, c in aws_synthetics_canary.vpc : k => c.arn }
}

output "canary_failed_alarm_arns" {
  description = "ARNs of the canary failure alarms."
  value       = { for k, a in aws_cloudwatch_metric_alarm.canary_failed : k => a.arn }
}

output "canary_success_percent_alarm_arns" {
  description = "ARNs of the optional canary success percent alarms."
  value       = { for k, a in aws_cloudwatch_metric_alarm.canary_success_percent : k => a.arn }
}

# Configuration targets region us-east-1. The aws provider block is supplied by
# the deployment harness and is intentionally omitted here.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Data Sources
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Variables
################################################################################

variable "create_vpc" {
  description = "Controls whether the VPC and all associated resources are created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name used as an identifier and prefix for all resources."
  type        = string
  default     = "main"
}

variable "cidr" {
  description = "The IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "azs" {
  description = "List of availability zone names (e.g. us-east-1a) or IDs (e.g. use1-az1). Falls back to all available AZs in the region when empty."
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "List of public subnet CIDR blocks inside the VPC."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnets" {
  description = "List of private subnet CIDR blocks inside the VPC."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.12.0/24"]
}

variable "intra_subnets" {
  description = "List of isolated intra subnet CIDR blocks inside the VPC (no internet routing)."
  type        = list(string)
  default     = ["10.0.21.0/24", "10.0.22.0/24"]
}

variable "public_subnet_suffix" {
  description = "Suffix appended to public subnet names."
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix appended to private subnet names."
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix appended to intra subnet names."
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Explicit names for public subnets. Overrides generated names when supplied."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit names for private subnets. Overrides generated names when supplied."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit names for intra subnets. Overrides generated names when supplied."
  type        = list(string)
  default     = []
}

variable "map_public_ip_on_launch" {
  description = "Auto-assign public IP addresses to instances launched in public subnets."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls whether an Internet Gateway is created for public subnets."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Provision NAT Gateways for private subnet outbound internet access."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Map of tags applied to all resources."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  azs = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names

  all_ipv4_cidr = "0.0.0.0/0"
  az_name_regex = "^[a-z]{2}-"

  len_public_subnets  = length(var.public_subnets)
  len_private_subnets = length(var.private_subnets)
  len_intra_subnets   = length(var.intra_subnets)

  create_public  = var.create_vpc && local.len_public_subnets > 0
  create_private = var.create_vpc && local.len_private_subnets > 0
  create_intra   = var.create_vpc && local.len_intra_subnets > 0

  create_igw_effective = local.create_public && var.create_igw

  nat_gateway_count = (
    var.enable_nat_gateway && local.create_public && local.create_private && local.create_igw_effective
    ? min(local.len_public_subnets, local.len_private_subnets)
    : 0
  )

  vpc_id = try(aws_vpc.this[0].id, "")
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge({ Name = var.name }, var.tags)
}

# Lock down the default security group: no ingress or egress rules.
resource "aws_default_security_group" "this" {
  count = var.create_vpc ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge({ Name = "${var.name}-default" }, var.tags)
}

################################################################################
# Public Subnets
################################################################################

resource "aws_subnet" "public" {
  count = local.create_public ? local.len_public_subnets : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.public_subnets[count.index]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  availability_zone    = length(regexall(local.az_name_regex, element(local.azs, count.index))) > 0 ? element(local.azs, count.index) : null
  availability_zone_id = length(regexall(local.az_name_regex, element(local.azs, count.index))) == 0 ? element(local.azs, count.index) : null

  tags = merge(
    {
      Name = try(
        var.public_subnet_names[count.index],
        format("${var.name}-${var.public_subnet_suffix}-%s", element(local.azs, count.index))
      )
    },
    var.tags
  )
}

################################################################################
# Private Subnets
################################################################################

resource "aws_subnet" "private" {
  count = local.create_private ? local.len_private_subnets : 0

  vpc_id     = aws_vpc.this[0].id
  cidr_block = var.private_subnets[count.index]

  availability_zone    = length(regexall(local.az_name_regex, element(local.azs, count.index))) > 0 ? element(local.azs, count.index) : null
  availability_zone_id = length(regexall(local.az_name_regex, element(local.azs, count.index))) == 0 ? element(local.azs, count.index) : null

  tags = merge(
    {
      Name = try(
        var.private_subnet_names[count.index],
        format("${var.name}-${var.private_subnet_suffix}-%s", element(local.azs, count.index))
      )
    },
    var.tags
  )
}

################################################################################
# Intra Subnets
################################################################################

resource "aws_subnet" "intra" {
  count = local.create_intra ? local.len_intra_subnets : 0

  vpc_id     = aws_vpc.this[0].id
  cidr_block = var.intra_subnets[count.index]

  availability_zone    = length(regexall(local.az_name_regex, element(local.azs, count.index))) > 0 ? element(local.azs, count.index) : null
  availability_zone_id = length(regexall(local.az_name_regex, element(local.azs, count.index))) == 0 ? element(local.azs, count.index) : null

  tags = merge(
    {
      Name = try(
        var.intra_subnet_names[count.index],
        format("${var.name}-${var.intra_subnet_suffix}-%s", element(local.azs, count.index))
      )
    },
    var.tags
  )
}

################################################################################
# Internet Gateway & Public Routing
################################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_igw_effective ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge({ Name = "${var.name}" }, var.tags)
}

resource "aws_route_table" "public" {
  count = local.create_public ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge({ Name = "${var.name}-${var.public_subnet_suffix}" }, var.tags)
}

resource "aws_route" "public_internet_gateway" {
  count = local.create_igw_effective ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = local.all_ipv4_cidr
  gateway_id             = aws_internet_gateway.this[0].id

  timeouts {
    create = "5m"
  }
}

resource "aws_route_table_association" "public" {
  count = local.create_public ? local.len_public_subnets : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

################################################################################
# NAT Gateways
################################################################################

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(
    { Name = format("${var.name}-%s", element(local.azs, count.index)) },
    var.tags
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    { Name = format("${var.name}-%s", element(local.azs, count.index)) },
    var.tags
  )

  depends_on = [aws_internet_gateway.this]
}

################################################################################
# Private Routing
################################################################################

resource "aws_route_table" "private" {
  count = local.create_private ? local.len_private_subnets : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    { Name = format("${var.name}-${var.private_subnet_suffix}-%s", element(local.azs, count.index)) },
    var.tags
  )
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count > 0 ? local.len_private_subnets : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = local.all_ipv4_cidr
  nat_gateway_id         = element(aws_nat_gateway.this[*].id, count.index)

  timeouts {
    create = "5m"
  }
}

resource "aws_route_table_association" "private" {
  count = local.create_private ? local.len_private_subnets : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

################################################################################
# Intra Routing (isolated - local VPC route only)
################################################################################

resource "aws_route_table" "intra" {
  count = local.create_intra ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge({ Name = "${var.name}-${var.intra_subnet_suffix}" }, var.tags)
}

resource "aws_route_table_association" "intra" {
  count = local.create_intra ? local.len_intra_subnets : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[0].id
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = local.vpc_id
}

output "vpc_arn" {
  description = "The ARN of the VPC."
  value       = try(aws_vpc.this[0].arn, "")
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = try(aws_vpc.this[0].cidr_block, "")
}

output "default_security_group_id" {
  description = "The ID of the locked-down default security group."
  value       = try(aws_default_security_group.this[0].id, "")
}

output "azs" {
  description = "Availability zones (names or IDs) used for subnet placement."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "List of public subnet IDs."
  value       = try(aws_subnet.public[*].id, [])
}

output "public_subnets_cidr_blocks" {
  description = "List of public subnet CIDR blocks."
  value       = try(aws_subnet.public[*].cidr_block, [])
}

output "private_subnet_ids" {
  description = "List of private subnet IDs."
  value       = try(aws_subnet.private[*].id, [])
}

output "private_subnets_cidr_blocks" {
  description = "List of private subnet CIDR blocks."
  value       = try(aws_subnet.private[*].cidr_block, [])
}

output "intra_subnet_ids" {
  description = "List of intra subnet IDs."
  value       = try(aws_subnet.intra[*].id, [])
}

output "intra_subnets_cidr_blocks" {
  description = "List of intra subnet CIDR blocks."
  value       = try(aws_subnet.intra[*].cidr_block, [])
}

output "igw_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.this[0].id, "")
}

output "public_route_table_id" {
  description = "The ID of the public route table."
  value       = try(aws_route_table.public[0].id, "")
}

output "private_route_table_ids" {
  description = "List of private route table IDs."
  value       = try(aws_route_table.private[*].id, [])
}

output "intra_route_table_id" {
  description = "The ID of the isolated intra route table."
  value       = try(aws_route_table.intra[0].id, "")
}

output "nat_gateway_ids" {
  description = "List of NAT Gateway IDs."
  value       = try(aws_nat_gateway.this[*].id, [])
}

output "nat_public_ips" {
  description = "List of public Elastic IPs allocated to NAT Gateways."
  value       = try(aws_eip.nat[*].public_ip, [])
}

output "nat_eip_allocation_ids" {
  description = "List of Elastic IP allocation IDs used by NAT Gateways."
  value       = try(aws_eip.nat[*].id, [])
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

################################################################################
# Variables
################################################################################

variable "api_type" {
  description = "Type of API Gateway to provision: \"http\" (API Gateway v2) or \"rest\" (API Gateway v1)."
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either \"http\" or \"rest\"."
  }
}

variable "api_name" {
  description = "Name of the API."
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name. Used as the prefix for stage names."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9-]{1,16}$", var.environment))
    error_message = "environment must be 1-16 lowercase alphanumeric characters or hyphens."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC that hosts the private subnets used by VPC links and load balancers."
  type        = string
  default     = "10.20.0.0/16"
}

variable "private_subnet_count" {
  description = "Number of private subnets to create across availability zones (minimum 2 for load balancers)."
  type        = number
  default     = 2

  validation {
    condition     = var.private_subnet_count >= 2 && var.private_subnet_count <= 6
    error_message = "private_subnet_count must be between 2 and 6."
  }
}

variable "enable_vpc_link" {
  description = "Create a VPC link (HTTP: API Gateway v2 VPC link; REST: NLB + VPC link) to a private backend ALB."
  type        = bool
  default     = false
}

variable "alb_port" {
  description = "TCP port on which the backend ALB listens and the NLB forwards traffic."
  type        = number
  default     = 443

  validation {
    condition     = var.alb_port > 0 && var.alb_port < 65536
    error_message = "alb_port must be a valid TCP port."
  }
}

variable "enable_custom_domain" {
  description = "Create a custom domain (TLS 1.2, regional ACM certificate) for the HTTP API."
  type        = bool
  default     = false
}

variable "hosted_zone_name" {
  description = "Name of the Route 53 hosted zone created for the custom domain."
  type        = string
  default     = "example.com"
}

variable "custom_domain_name" {
  description = "Fully-qualified custom domain name for the HTTP API."
  type        = string
  default     = "api.example.com"
}

variable "create_route53_record" {
  description = "Create a Route 53 alias A record pointing the custom domain at the API Gateway domain."
  type        = bool
  default     = false
}

variable "http_routes" {
  description = "Map of HTTP API routes. route_key is e.g. \"GET /health\"."
  type = map(object({
    route_key          = string
    integration_uri    = string
    integration_method = optional(string, "ANY")
  }))
  default = {
    health = {
      route_key          = "GET /health"
      integration_uri    = "https://httpbin.org/get"
      integration_method = "GET"
    }
    items = {
      route_key          = "ANY /items"
      integration_uri    = "https://httpbin.org/anything"
      integration_method = "ANY"
    }
  }
}

variable "rest_routes" {
  description = "Map of REST API routes. Each entry creates a resource under the root, a method and an HTTP proxy integration."
  type = map(object({
    path_part       = string
    http_method     = string
    integration_uri = string
    path_parameters = optional(list(string), [])
  }))
  default = {
    health = {
      path_part       = "health"
      http_method     = "GET"
      integration_uri = "https://httpbin.org/get"
      path_parameters = []
    }
    user = {
      path_part       = "{userId}"
      http_method     = "GET"
      integration_uri = "https://httpbin.org/anything/{userId}"
      path_parameters = ["userId"]
    }
  }
}

variable "enable_ip_restriction" {
  description = "Attach a resource policy to the REST API that restricts invocation to allowed_source_ips."
  type        = bool
  default     = false
}

variable "allowed_source_ips" {
  description = "CIDR ranges allowed to invoke the REST API when enable_ip_restriction is true."
  type        = list(string)
  default     = ["10.0.0.0/8"]
}

variable "enable_api_keys" {
  description = "Create a usage plan and API key for the REST API, stored as a SecureString in SSM Parameter Store."
  type        = bool
  default     = false
}

variable "usage_plan_quota_limit" {
  description = "Maximum number of requests per month for the usage plan."
  type        = number
  default     = 100000
}

variable "throttle_rate_limit" {
  description = "Steady-state request rate limit (requests per second)."
  type        = number
  default     = 100
}

variable "throttle_burst_limit" {
  description = "Burst request limit."
  type        = number
  default     = 200
}

variable "enable_lambda_authorizer" {
  description = "Create a custom Lambda TOKEN authorizer for the REST API."
  type        = bool
  default     = false
}

variable "authorizer_runtime" {
  description = "Runtime for the Lambda authorizer function."
  type        = string
  default     = "nodejs16.x"
}

variable "log_retention_days" {
  description = "CloudWatch Logs retention in days."
  type        = number
  default     = 90
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "benchmark-api"
    ManagedBy = "terraform"
  }
}

################################################################################
# Locals
################################################################################

locals {
  is_http = var.api_type == "http"
  is_rest = var.api_type == "rest"

  stage_name  = "${var.environment}-stage"
  name_prefix = "${var.api_name}-${var.environment}"

  common_tags = merge(var.tags, {
    Environment = var.environment
    ApiType     = var.api_type
  })

  http_vpc_link      = local.is_http && var.enable_vpc_link
  rest_vpc_link      = local.is_rest && var.enable_vpc_link
  http_custom_domain = local.is_http && var.enable_custom_domain
  http_dns_record    = local.http_custom_domain && var.create_route53_record
  rest_api_keys      = local.is_rest && var.enable_api_keys
  rest_authorizer    = local.is_rest && var.enable_lambda_authorizer
  rest_ip_policy     = local.is_rest && var.enable_ip_restriction

  authorizer_function_name = "${local.name_prefix}-authorizer"
  api_key_parameter_name   = "/${var.api_name}/${var.environment}/api-key"

  http_routes = local.is_http ? var.http_routes : {}
  rest_routes = local.is_rest ? var.rest_routes : {}

  access_log_format = jsonencode({
    requestId      = "$context.requestId"
    ip             = "$context.identity.sourceIp"
    requestTime    = "$context.requestTime"
    httpMethod     = "$context.httpMethod"
    routeKey       = "$context.routeKey"
    resourcePath   = "$context.resourcePath"
    status         = "$context.status"
    protocol       = "$context.protocol"
    responseLength = "$context.responseLength"
    integrationErr = "$context.integrationErrorMessage"
  })
}

################################################################################
# Data sources (static metadata only)
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

################################################################################
# Network
################################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = var.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default-sg-restricted"
  })
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/${local.name_prefix}/flow-logs"
  retention_in_days = var.log_retention_days

  tags = local.common_tags
}

resource "aws_iam_role" "vpc_flow_logs" {
  name = "${local.name_prefix}-vpc-flow-logs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "vpc-flow-logs.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "${local.name_prefix}-vpc-flow-logs"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogStreams"
      ]
      Resource = "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"
    }]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn

  tags = local.common_tags
}

################################################################################
# Backend ALB (target of the VPC links)
################################################################################

resource "aws_security_group" "alb" {
  count = var.enable_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-alb"
  description = "Internal backend ALB reachable only from inside the VPC"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_vpc_security_group_ingress_rule" "alb_from_vpc" {
  count = var.enable_vpc_link ? 1 : 0

  security_group_id = aws_security_group.alb[0].id
  description       = "Backend traffic from VPC link / NLB"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = var.alb_port
  to_port           = var.alb_port

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "alb_to_vpc" {
  count = var.enable_vpc_link ? 1 : 0

  security_group_id = aws_security_group.alb[0].id
  description       = "Egress to targets inside the VPC"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 1024
  to_port           = 65535

  tags = local.common_tags
}

resource "tls_private_key" "alb" {
  count = var.enable_vpc_link ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  count = var.enable_vpc_link ? 1 : 0

  private_key_pem       = tls_private_key.alb[0].private_key_pem
  validity_period_hours = 8760
  early_renewal_hours   = 720

  subject {
    common_name  = "${local.name_prefix}.internal"
    organization = var.api_name
  }

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  count = var.enable_vpc_link ? 1 : 0

  private_key      = tls_private_key.alb[0].private_key_pem
  certificate_body = tls_self_signed_cert.alb[0].cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = local.common_tags
}

resource "aws_lb" "alb" {
  count = var.enable_vpc_link ? 1 : 0

  name                       = "${local.name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb[0].id]
  subnets                    = aws_subnet.private[*].id
  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = local.common_tags
}

resource "aws_lb_listener" "alb_https" {
  count = var.enable_vpc_link ? 1 : 0

  load_balancer_arn = aws_lb.alb[0].arn
  port              = var.alb_port
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb[0].arn

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "application/json"
      message_body = "{\"status\":\"ok\"}"
      status_code  = "200"
    }
  }

  tags = local.common_tags
}

################################################################################
# HTTP API (v2)
################################################################################

resource "aws_security_group" "vpc_link" {
  count = local.http_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-http-vpc-link"
  description = "Security group for the HTTP API VPC link"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-http-vpc-link"
  })
}

resource "aws_vpc_security_group_egress_rule" "vpc_link_to_alb" {
  count = local.http_vpc_link ? 1 : 0

  security_group_id = aws_security_group.vpc_link[0].id
  description       = "VPC link to backend ALB"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = var.alb_port
  to_port           = var.alb_port

  tags = local.common_tags
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count = local.http_vpc_link ? 1 : 0

  name               = "${local.name_prefix}-http-vpc-link"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_link[0].id]

  tags = local.common_tags
}

resource "aws_apigatewayv2_api" "http" {
  count = local.is_http ? 1 : 0

  name          = var.api_name
  protocol_type = "HTTP"
  description   = "${var.api_name} HTTP API (${var.environment})"

  tags = local.common_tags
}

resource "aws_apigatewayv2_integration" "http" {
  for_each = local.http_routes

  api_id                 = aws_apigatewayv2_api.http[0].id
  integration_type       = "HTTP_PROXY"
  integration_method     = each.value.integration_method
  integration_uri        = local.http_vpc_link ? aws_lb_listener.alb_https[0].arn : each.value.integration_uri
  connection_type        = local.http_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id          = local.http_vpc_link ? aws_apigatewayv2_vpc_link.http[0].id : null
  payload_format_version = "1.0"
  timeout_milliseconds   = 29000
}

resource "aws_apigatewayv2_route" "http" {
  for_each = local.http_routes

  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = each.value.route_key
  target    = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
}

resource "aws_cloudwatch_log_group" "http_api" {
  count = local.is_http ? 1 : 0

  name              = "/aws/apigateway/${local.name_prefix}-http"
  retention_in_days = var.log_retention_days

  tags = local.common_tags
}

resource "aws_apigatewayv2_stage" "http" {
  count = local.is_http ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.http_api[0].arn
    format          = local.access_log_format
  }

  default_route_settings {
    throttling_rate_limit  = var.throttle_rate_limit
    throttling_burst_limit = var.throttle_burst_limit
  }

  tags = local.common_tags

  depends_on = [aws_apigatewayv2_route.http]
}

################################################################################
# HTTP API custom domain
################################################################################

resource "aws_route53_zone" "main" {
  count = local.http_custom_domain ? 1 : 0

  name    = var.hosted_zone_name
  comment = "Hosted zone for ${var.api_name} custom domain"

  tags = local.common_tags
}

resource "aws_acm_certificate" "api" {
  count = local.http_custom_domain ? 1 : 0

  domain_name       = var.custom_domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }

  tags = local.common_tags
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in flatten(aws_acm_certificate.api[*].domain_validation_options) : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }

  allow_overwrite = true
  zone_id         = aws_route53_zone.main[0].zone_id
  name            = each.value.name
  type            = each.value.type
  ttl             = 60
  records         = [each.value.record]
}

resource "aws_acm_certificate_validation" "api" {
  count = local.http_custom_domain ? 1 : 0

  certificate_arn         = aws_acm_certificate.api[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

resource "aws_apigatewayv2_domain_name" "http" {
  count = local.http_custom_domain ? 1 : 0

  domain_name = var.custom_domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate_validation.api[0].certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = local.http_custom_domain ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

resource "aws_route53_record" "api_alias" {
  count = local.http_dns_record ? 1 : 0

  zone_id = aws_route53_zone.main[0].zone_id
  name    = aws_apigatewayv2_domain_name.http[0].domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

################################################################################
# REST API (v1)
################################################################################

resource "aws_api_gateway_rest_api" "rest" {
  count = local.is_rest ? 1 : 0

  name        = var.api_name
  description = "${var.api_name} REST API (${var.environment})"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags
}

resource "aws_api_gateway_rest_api_policy" "rest" {
  count = local.rest_ip_policy ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowInvoke"
        Effect    = "Allow"
        Principal = "*"
        Action    = "execute-api:Invoke"
        Resource  = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*"
      },
      {
        Sid       = "DenyOutsideAllowedIps"
        Effect    = "Deny"
        Principal = "*"
        Action    = "execute-api:Invoke"
        Resource  = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*"
        Condition = {
          NotIpAddress = {
            "aws:SourceIp" = var.allowed_source_ips
          }
        }
      }
    ]
  })
}

resource "aws_api_gateway_resource" "rest" {
  for_each = local.rest_routes

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.value.path_part
}

resource "aws_api_gateway_method" "rest" {
  for_each = local.rest_routes

  rest_api_id      = aws_api_gateway_rest_api.rest[0].id
  resource_id      = aws_api_gateway_resource.rest[each.key].id
  http_method      = each.value.http_method
  authorization    = local.rest_authorizer ? "CUSTOM" : "NONE"
  authorizer_id    = local.rest_authorizer ? aws_api_gateway_authorizer.rest[0].id : null
  api_key_required = local.rest_api_keys

  request_parameters = {
    for param in each.value.path_parameters : "method.request.path.${param}" => true
  }
}

resource "aws_api_gateway_integration" "rest" {
  for_each = local.rest_routes

  rest_api_id             = aws_api_gateway_rest_api.rest[0].id
  resource_id             = aws_api_gateway_resource.rest[each.key].id
  http_method             = aws_api_gateway_method.rest[each.key].http_method
  type                    = "HTTP_PROXY"
  integration_http_method = each.value.http_method
  uri                     = local.rest_vpc_link ? "https://${aws_lb.nlb[0].dns_name}/${each.value.path_part}" : each.value.integration_uri
  connection_type         = local.rest_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id           = local.rest_vpc_link ? aws_api_gateway_vpc_link.rest[0].id : null
  timeout_milliseconds    = 29000

  request_parameters = {
    for param in each.value.path_parameters : "integration.request.path.${param}" => "method.request.path.${param}"
  }
}

resource "aws_api_gateway_deployment" "rest" {
  count = local.is_rest ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.rest,
      aws_api_gateway_method.rest,
      aws_api_gateway_integration.rest,
      aws_api_gateway_authorizer.rest,
      aws_api_gateway_rest_api_policy.rest,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.rest,
    aws_api_gateway_integration.rest,
    aws_api_gateway_rest_api_policy.rest,
  ]
}

resource "aws_iam_role" "apigateway_cloudwatch" {
  count = local.is_rest ? 1 : 0

  name = "${local.name_prefix}-apigw-cloudwatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "apigateway.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "apigateway_cloudwatch" {
  count = local.is_rest ? 1 : 0

  role       = aws_iam_role.apigateway_cloudwatch[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "rest" {
  count = local.is_rest ? 1 : 0

  cloudwatch_role_arn = aws_iam_role.apigateway_cloudwatch[0].arn

  depends_on = [aws_iam_role_policy_attachment.apigateway_cloudwatch]
}

resource "aws_cloudwatch_log_group" "rest_api" {
  count = local.is_rest ? 1 : 0

  name              = "/aws/apigateway/${local.name_prefix}-rest"
  retention_in_days = var.log_retention_days

  tags = local.common_tags
}

resource "aws_api_gateway_stage" "rest" {
  count = local.is_rest ? 1 : 0

  rest_api_id          = aws_api_gateway_rest_api.rest[0].id
  deployment_id        = aws_api_gateway_deployment.rest[0].id
  stage_name           = local.stage_name
  xray_tracing_enabled = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.rest_api[0].arn
    format          = local.access_log_format
  }

  tags = local.common_tags

  depends_on = [aws_api_gateway_account.rest]
}

resource "aws_api_gateway_method_settings" "rest" {
  count = local.is_rest ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  method_path = "*/*"

  settings {
    metrics_enabled        = true
    logging_level          = "INFO"
    data_trace_enabled     = false
    throttling_rate_limit  = var.throttle_rate_limit
    throttling_burst_limit = var.throttle_burst_limit
  }

  depends_on = [aws_api_gateway_account.rest]
}

################################################################################
# REST usage plan and API key
################################################################################

resource "aws_kms_key" "ssm" {
  count = local.rest_api_keys ? 1 : 0

  description             = "KMS key encrypting ${var.api_name} API key parameters"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_kms_alias" "ssm" {
  count = local.rest_api_keys ? 1 : 0

  name          = "alias/${local.name_prefix}-ssm"
  target_key_id = aws_kms_key.ssm[0].key_id
}

resource "aws_api_gateway_api_key" "rest" {
  count = local.rest_api_keys ? 1 : 0

  name        = "${local.name_prefix}-api-key"
  description = "API key for ${var.api_name} (${var.environment})"
  enabled     = true

  tags = local.common_tags
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = local.rest_api_keys ? 1 : 0

  name        = "${local.name_prefix}-usage-plan"
  description = "Usage plan for ${var.api_name} (${var.environment})"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  quota_settings {
    limit  = var.usage_plan_quota_limit
    period = "MONTH"
  }

  throttle_settings {
    rate_limit  = var.throttle_rate_limit
    burst_limit = var.throttle_burst_limit
  }

  tags = local.common_tags
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count = local.rest_api_keys ? 1 : 0

  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count = local.rest_api_keys ? 1 : 0

  name        = local.api_key_parameter_name
  description = "API Gateway API key for ${var.api_name} (${var.environment})"
  type        = "SecureString"
  key_id      = aws_kms_key.ssm[0].arn
  value       = aws_api_gateway_api_key.rest[0].value

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

################################################################################
# REST custom Lambda authorizer
################################################################################

data "archive_file" "authorizer" {
  count = local.rest_authorizer ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/.build/${local.authorizer_function_name}.zip"

  source {
    filename = "index.js"
    content  = <<-EOT
      'use strict';

      const TOKEN_PATTERN = /^Bearer [A-Za-z0-9\-._~+\/]+=*$/;

      exports.handler = async (event) => {
        const token = event.authorizationToken || '';
        const effect = TOKEN_PATTERN.test(token) ? 'Allow' : 'Deny';

        return {
          principalId: 'api-client',
          policyDocument: {
            Version: '2012-10-17',
            Statement: [
              {
                Action: 'execute-api:Invoke',
                Effect: effect,
                Resource: event.methodArn
              }
            ]
          }
        };
      };
    EOT
  }
}

resource "aws_cloudwatch_log_group" "authorizer" {
  count = local.rest_authorizer ? 1 : 0

  name              = "/aws/lambda/${local.authorizer_function_name}"
  retention_in_days = var.log_retention_days

  tags = local.common_tags
}

resource "aws_iam_role" "authorizer_lambda" {
  count = local.rest_authorizer ? 1 : 0

  name = "${local.authorizer_function_name}-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "authorizer_lambda" {
  count = local.rest_authorizer ? 1 : 0

  name = "${local.authorizer_function_name}-exec"
  role = aws_iam_role.authorizer_lambda[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.authorizer[0].arn}:*"
      },
      {
        Sid    = "XRayTracing"
        Effect = "Allow"
        Action = [
          "xray:PutTraceSegments",
          "xray:PutTelemetryRecords"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_lambda_function" "authorizer" {
  count = local.rest_authorizer ? 1 : 0

  function_name    = local.authorizer_function_name
  description      = "Custom TOKEN authorizer for ${var.api_name} (${var.environment})"
  role             = aws_iam_role.authorizer_lambda[0].arn
  runtime          = var.authorizer_runtime
  handler          = "index.handler"
  filename         = data.archive_file.authorizer[0].output_path
  source_code_hash = data.archive_file.authorizer[0].output_base64sha256
  memory_size      = 128
  timeout          = 5

  tracing_config {
    mode = "Active"
  }

  tags = local.common_tags

  depends_on = [
    aws_cloudwatch_log_group.authorizer,
    aws_iam_role_policy.authorizer_lambda,
  ]
}

resource "aws_iam_role" "authorizer_invocation" {
  count = local.rest_authorizer ? 1 : 0

  name = "${local.authorizer_function_name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "apigateway.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "authorizer_invocation" {
  count = local.rest_authorizer ? 1 : 0

  name = "${local.authorizer_function_name}-invoke"
  role = aws_iam_role.authorizer_invocation[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "lambda:InvokeFunction"
      Resource = aws_lambda_function.authorizer[0].arn
    }]
  })
}

resource "aws_api_gateway_authorizer" "rest" {
  count = local.rest_authorizer ? 1 : 0

  name                             = "${local.name_prefix}-authorizer"
  rest_api_id                      = aws_api_gateway_rest_api.rest[0].id
  type                             = "TOKEN"
  authorizer_uri                   = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials           = aws_iam_role.authorizer_invocation[0].arn
  identity_source                  = "method.request.header.Authorization"
  authorizer_result_ttl_in_seconds = 300

  depends_on = [aws_iam_role_policy.authorizer_invocation]
}

################################################################################
# REST VPC link (NLB -> ALB)
################################################################################

resource "aws_lb" "nlb" {
  count = local.rest_vpc_link ? 1 : 0

  name                             = "${local.name_prefix}-nlb"
  internal                         = true
  load_balancer_type               = "network"
  subnets                          = aws_subnet.private[*].id
  enable_cross_zone_load_balancing = true
  enable_deletion_protection       = false

  tags = local.common_tags
}

resource "aws_lb_target_group" "nlb_to_alb" {
  count = local.rest_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-alb-tg"
  target_type = "alb"
  protocol    = "TCP"
  port        = var.alb_port
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    protocol            = "HTTPS"
    port                = "traffic-port"
    path                = "/"
    matcher             = "200-399"
    healthy_threshold   = 3
    unhealthy_threshold = 3
    interval            = 30
  }

  tags = local.common_tags
}

resource "aws_lb_target_group_attachment" "nlb_to_alb" {
  count = local.rest_vpc_link ? 1 : 0

  target_group_arn = aws_lb_target_group.nlb_to_alb[0].arn
  target_id        = aws_lb.alb[0].id
  port             = var.alb_port

  depends_on = [aws_lb_listener.alb_https]
}

resource "aws_lb_listener" "nlb_tcp" {
  count = local.rest_vpc_link ? 1 : 0

  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.alb_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_to_alb[0].arn
  }

  tags = local.common_tags
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = local.rest_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-rest-vpc-link"
  description = "VPC link from ${var.api_name} REST API to the internal NLB"
  target_arns = [aws_lb.nlb[0].arn]

  tags = local.common_tags

  depends_on = [aws_lb_listener.nlb_tcp]
}

################################################################################
# Outputs
################################################################################

output "api_type" {
  description = "The API type provisioned."
  value       = var.api_type
}

output "api_id" {
  description = "ID of the provisioned API."
  value       = local.is_http ? one(aws_apigatewayv2_api.http[*].id) : one(aws_api_gateway_rest_api.rest[*].id)
}

output "api_endpoint" {
  description = "Base endpoint of the API."
  value       = local.is_http ? one(aws_apigatewayv2_api.http[*].api_endpoint) : try("https://${aws_api_gateway_rest_api.rest[0].id}.execute-api.${data.aws_region.current.name}.amazonaws.com", null)
}

output "stage_name" {
  description = "Name of the deployed stage."
  value       = local.stage_name
}

output "invoke_url" {
  description = "Invoke URL of the deployed stage."
  value       = local.is_http ? one(aws_apigatewayv2_stage.http[*].invoke_url) : one(aws_api_gateway_stage.rest[*].invoke_url)
}

output "execution_arn" {
  description = "Execution ARN of the API."
  value       = local.is_http ? one(aws_apigatewayv2_api.http[*].execution_arn) : one(aws_api_gateway_rest_api.rest[*].execution_arn)
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "vpc_link_id" {
  description = "ID of the VPC link (HTTP or REST), if created."
  value       = try(coalesce(one(aws_apigatewayv2_vpc_link.http[*].id), one(aws_api_gateway_vpc_link.rest[*].id)), null)
}

output "alb_arn" {
  description = "ARN of the backend ALB, if created."
  value       = one(aws_lb.alb[*].arn)
}

output "nlb_arn" {
  description = "ARN of the internal NLB used by the REST VPC link, if created."
  value       = one(aws_lb.nlb[*].arn)
}

output "nlb_dns_name" {
  description = "DNS name of the internal NLB, if created."
  value       = one(aws_lb.nlb[*].dns_name)
}

output "custom_domain_name" {
  description = "Custom domain name of the HTTP API, if created."
  value       = one(aws_apigatewayv2_domain_name.http[*].domain_name)
}

output "custom_domain_target" {
  description = "Regional target domain name for the HTTP API custom domain, if created."
  value       = try(aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name, null)
}

output "route53_zone_name_servers" {
  description = "Name servers of the hosted zone created for the custom domain (delegate the domain to these)."
  value       = try(aws_route53_zone.main[0].name_servers, null)
}

output "api_key_id" {
  description = "ID of the REST API key, if created."
  value       = one(aws_api_gateway_api_key.rest[*].id)
}

output "api_key_ssm_parameter_name" {
  description = "SSM Parameter Store name holding the REST API key value, if created."
  value       = one(aws_ssm_parameter.api_key[*].name)
}

output "usage_plan_id" {
  description = "ID of the REST usage plan, if created."
  value       = one(aws_api_gateway_usage_plan.rest[*].id)
}

output "authorizer_id" {
  description = "ID of the REST Lambda authorizer, if created."
  value       = one(aws_api_gateway_authorizer.rest[*].id)
}

output "authorizer_function_arn" {
  description = "ARN of the Lambda authorizer function, if created."
  value       = one(aws_lambda_function.authorizer[*].arn)
}

output "access_log_group_name" {
  description = "CloudWatch log group receiving API access logs."
  value       = local.is_http ? one(aws_cloudwatch_log_group.http_api[*].name) : one(aws_cloudwatch_log_group.rest_api[*].name)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Input variables
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Default tags applied to all resources via the provider default_tags block."
  type        = map(string)
  default = {
    Project   = "cloudtrail-audit"
    ManagedBy = "terraform"
  }
}

variable "name_prefix" {
  description = "Prefix used when naming supporting resources such as IAM roles, policies and SNS topics."
  type        = string
  default     = "cloudtrail-audit"
}

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "cloudtrail-audit-trail"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket for CloudTrail logs. When empty, a name is generated from the account ID, region and a random 8-character lowercase suffix."
  type        = string
  default     = ""
}

variable "s3_force_destroy" {
  description = "Whether to allow the CloudTrail log bucket to be destroyed even if it contains objects."
  type        = bool
  default     = true
}

variable "s3_versioning_enabled" {
  description = "Whether to enable versioning on the CloudTrail log bucket."
  type        = bool
  default     = false
}

variable "kms_alias_prefix" {
  description = "Prefix for the CloudTrail KMS key alias. Must begin with 'alias/'."
  type        = string
  default     = "alias/cloudtrail"

  validation {
    condition     = can(regex("^alias/", var.kms_alias_prefix)) && !can(regex("^alias/aws", var.kms_alias_prefix))
    error_message = "kms_alias_prefix must begin with 'alias/' and must not begin with the reserved 'alias/aws' prefix."
  }
}

variable "kms_decrypt_role_arn" {
  description = "Optional IAM role ARN granted permission to decrypt CloudTrail log files. Leave empty to skip."
  type        = string
  default     = ""
}

variable "cloudwatch_log_retention_days" {
  description = "Number of days to retain CloudTrail events in the CloudWatch Log Group."
  type        = number
  default     = 90

  validation {
    condition = contains(
      [0, 1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653],
      var.cloudwatch_log_retention_days
    )
    error_message = "cloudwatch_log_retention_days must be one of: 0, 1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653."
  }
}

variable "include_global_service_events" {
  description = "Whether the trail publishes events from global services such as IAM."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail captures events from all regions."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether logging is enabled for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an AWS Organizations trail. Requires running in the organization management account."
  type        = bool
  default     = false
}

variable "read_write_type" {
  description = "Type of events to log in the event selector. Valid values: All, ReadOnly, WriteOnly."
  type        = string
  default     = "All"

  validation {
    condition     = contains(["All", "ReadOnly", "WriteOnly"], var.read_write_type)
    error_message = "read_write_type must be one of: All, ReadOnly, WriteOnly."
  }
}

variable "include_management_events" {
  description = "Whether to include management events in the event selector."
  type        = bool
  default     = true
}

variable "data_resources" {
  description = "List of data resource selectors for the event selector (for example S3 objects or Lambda functions)."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_types" {
  description = "List of CloudTrail Insights types to enable. Valid values: ApiCallRateInsight, ApiErrorRateInsight."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for t in var.insight_types : contains(["ApiCallRateInsight", "ApiErrorRateInsight"], t)
    ])
    error_message = "insight_types may only contain ApiCallRateInsight and ApiErrorRateInsight."
  }
}

variable "create_sns_topic" {
  description = "Whether to create a dedicated SNS topic for CloudTrail log delivery notifications."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Optional existing SNS topic ARN for CloudTrail notifications, used only when create_sns_topic is false. Leave empty to disable notifications."
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# Random suffix for bucket naming
# -----------------------------------------------------------------------------

resource "random_string" "bucket_suffix" {
  length  = 8
  upper   = false
  special = false
  lower   = true
  numeric = true
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : "cloudtrail-${local.account_id}-${local.region}-${random_string.bucket_suffix.result}"

  trail_arn          = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"
  trail_wildcard_arn = "arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"
  account_root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"

  log_group_name = "/aws/cloudtrail/${var.trail_name}"
  log_group_arn  = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"

  cloudtrail_service_principal = "cloudtrail.amazonaws.com"
  logs_service_principal       = "logs.${local.region}.amazonaws.com"
  s3_via_service               = "s3.${local.region}.amazonaws.com"

  sns_topic_arn = var.create_sns_topic ? aws_sns_topic.cloudtrail[0].arn : (var.sns_topic_arn != "" ? var.sns_topic_arn : null)
}

# -----------------------------------------------------------------------------
# KMS key for CloudTrail, CloudWatch Logs, S3 and SNS encryption
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "EnableRootIAMUserPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_service_principal]
    }

    actions   = ["kms:GenerateDataKey*"]
    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = [local.trail_wildcard_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "AllowCloudTrailToDescribeKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_service_principal]
    }

    actions   = ["kms:DescribeKey"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailSNSNotificationEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_service_principal]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "AllowAccountPrincipalsToDecryptLogFiles"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "kms:Decrypt",
      "kms:ReEncryptFrom",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = [local.trail_wildcard_arn]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.logs_service_principal]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]
    resources = ["*"]

    condition {
      test     = "ArnEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = [local.log_group_arn]
    }
  }

  statement {
    sid    = "AllowS3BucketEncryption"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = [local.s3_via_service]
    }
  }

  dynamic "statement" {
    for_each = var.kms_decrypt_role_arn != "" ? [var.kms_decrypt_role_arn] : []

    content {
      sid    = "AllowDesignatedRoleToDecryptLogFiles"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]
      resources = ["*"]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail trail ${var.trail_name} log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "${var.kms_alias_prefix}/${var.trail_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# -----------------------------------------------------------------------------
# S3 bucket for CloudTrail logs
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = var.s3_force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = var.s3_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_ownership_controls" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_service_principal]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_service_principal]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.cloudtrail_logs.arn,
      "${aws_s3_bucket.cloudtrail_logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_logs]
}

# -----------------------------------------------------------------------------
# CloudWatch Logs integration
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = var.cloudwatch_log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid     = "AllowCloudTrailAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "${var.name_prefix}-cloudtrail-cloudwatch-role"
  description        = "Allows CloudTrail to deliver events to CloudWatch Logs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch" {
  statement {
    sid    = "AllowCloudTrailLogDelivery"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:log-stream:*"]
  }
}

resource "aws_iam_policy" "cloudtrail_cloudwatch" {
  name        = "${var.name_prefix}-cloudtrail-cloudwatch-policy"
  description = "Least-privilege policy allowing CloudTrail to write to its CloudWatch Log Group"
  policy      = data.aws_iam_policy_document.cloudtrail_cloudwatch.json
}

resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch" {
  role       = aws_iam_role.cloudtrail_cloudwatch.name
  policy_arn = aws_iam_policy.cloudtrail_cloudwatch.arn
}

# -----------------------------------------------------------------------------
# Optional SNS notifications
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  name              = "${var.name_prefix}-cloudtrail-alerts"
  kms_master_key_id = aws_kms_key.cloudtrail.id
}

data "aws_iam_policy_document" "sns_topic" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid    = "AWSCloudTrailSNSPolicy"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_service_principal]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.cloudtrail[0].arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.cloudtrail[0].arn
  policy = data.aws_iam_policy_document.sns_topic[0].json
}

# -----------------------------------------------------------------------------
# CloudTrail trail
# -----------------------------------------------------------------------------

resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  enable_log_file_validation    = true
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_arn

  event_selector {
    read_write_type           = var.read_write_type
    include_management_events = var.include_management_events

    dynamic "data_resource" {
      for_each = var.data_resources

      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_types

    content {
      insight_type = insight_selector.value
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_s3_bucket_server_side_encryption_configuration.cloudtrail_logs,
    aws_s3_bucket_ownership_controls.cloudtrail_logs,
    aws_iam_role_policy_attachment.cloudtrail_cloudwatch,
    aws_sns_topic_policy.cloudtrail,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cloudtrail_id" {
  description = "ID of the CloudTrail trail."
  value       = aws_cloudtrail.main.id
}

output "cloudtrail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.main.arn
}

output "cloudtrail_home_region" {
  description = "Region in which the CloudTrail trail was created."
  value       = aws_cloudtrail.main.home_region
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.cloudtrail_logs.id
}

output "s3_bucket_arn" {
  description = "ARN of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.cloudtrail_logs.arn
}

output "kms_key_id" {
  description = "ID of the KMS key used for CloudTrail encryption."
  value       = aws_kms_key.cloudtrail.key_id
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for CloudTrail encryption."
  value       = aws_kms_key.cloudtrail.arn
}

output "kms_alias_name" {
  description = "Alias name of the CloudTrail KMS key."
  value       = aws_kms_alias.cloudtrail.name
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.cloudtrail.name
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch Log Group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.cloudtrail.arn
}

output "cloudtrail_cloudwatch_role_arn" {
  description = "ARN of the IAM role CloudTrail uses to deliver events to CloudWatch Logs."
  value       = aws_iam_role.cloudtrail_cloudwatch.arn
}

output "cloudtrail_cloudwatch_policy_arn" {
  description = "ARN of the IAM policy attached to the CloudTrail CloudWatch Logs role."
  value       = aws_iam_policy.cloudtrail_cloudwatch.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic used for CloudTrail notifications, or null if notifications are disabled."
  value       = local.sns_topic_arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enabled" {
  description = "Global switch for the module. When false, no EBS account-level settings resources are created."
  type        = bool
  default     = true
}

variable "ebs_encryption_by_default_enabled" {
  description = "Whether to enable EBS encryption by default for all new EBS volumes and snapshot copies in the target region."
  type        = bool
  default     = true
}

variable "snapshot_block_public_access_enabled" {
  description = "Whether to manage account-level block public access settings for EBS snapshots in the target region."
  type        = bool
  default     = true
}

variable "snapshot_block_public_access_state" {
  description = "The block public access state for EBS snapshots. Valid values are \"block-all-sharing\", \"block-new-sharing\", and \"unblocked\"."
  type        = string
  default     = "block-all-sharing"

  validation {
    condition     = contains(["block-all-sharing", "block-new-sharing", "unblocked"], var.snapshot_block_public_access_state)
    error_message = "snapshot_block_public_access_state must be one of: \"block-all-sharing\", \"block-new-sharing\", \"unblocked\"."
  }
}

variable "region" {
  description = "Optional override for the target region. When null, the provider's current region is used."
  type        = string
  default     = null
  nullable    = true
}

data "aws_region" "current" {}

locals {
  region = coalesce(var.region, data.aws_region.current.name)

  create_ebs_encryption_by_default        = var.enabled && var.ebs_encryption_by_default_enabled
  create_snapshot_block_public_access     = var.enabled && var.snapshot_block_public_access_enabled
  ebs_encryption_by_default_count         = local.create_ebs_encryption_by_default ? 1 : 0
  snapshot_block_public_access_count      = local.create_snapshot_block_public_access ? 1 : 0
}

resource "aws_ebs_encryption_by_default" "this" {
  count = local.ebs_encryption_by_default_count

  enabled = true
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  count = local.snapshot_block_public_access_count

  state = var.snapshot_block_public_access_state
}

output "region" {
  description = "The effective target region for the EBS account-level settings."
  value       = local.region
}

output "ebs_encryption_by_default_enabled" {
  description = "Whether EBS encryption by default is enabled by this module in the target region."
  value       = try(aws_ebs_encryption_by_default.this[0].enabled, false)
}

output "snapshot_block_public_access_state" {
  description = "The EBS snapshot block public access state applied by this module, or null if not managed."
  value       = one(aws_ebs_snapshot_block_public_access.this[*].state)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "user_name" {
  description = "Name of the IAM deployment user."
  type        = string
  default     = "DeploymentUser"
}

variable "tags" {
  description = "Optional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of target S3 bucket ARNs for artifact management. When empty, no S3 policy is created."
  type        = list(string)
  default     = []
}

variable "s3_bucket_paths" {
  description = "Object sub-path patterns (e.g. \"artifacts/*\") appended to each bucket ARN to build object-level resource ARNs."
  type        = list(string)
  default     = ["*"]
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs whose code the deployment user may update. When empty, no Lambda policy is created."
  type        = list(string)
  default     = []
}

locals {
  create_s3_policy     = length(var.s3_bucket_arns) > 0
  create_lambda_policy = length(var.lambda_function_arns) > 0

  s3_object_arns = flatten([
    for bucket_arn in var.s3_bucket_arns : [
      for path in var.s3_bucket_paths : "${bucket_arn}/${path}"
    ]
  ])

  s3_policy_name     = "${var.user_name}-s3-deploy"
  lambda_policy_name = "${var.user_name}-lambda-deploy"
}

resource "aws_iam_user" "deployment" {
  name = var.user_name
  path = "/"
  tags = var.tags
}

data "aws_iam_policy_document" "s3_deploy" {
  count = local.create_s3_policy ? 1 : 0

  statement {
    sid    = "ObjectReadWriteAclDelete"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectAcl",
      "s3:PutObjectAcl",
    ]
    resources = local.s3_object_arns
  }

  statement {
    sid    = "BucketList"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = var.s3_bucket_arns
  }
}

resource "aws_iam_policy" "s3_deploy" {
  count = local.create_s3_policy ? 1 : 0

  name        = local.s3_policy_name
  description = "Grants ${var.user_name} read, write, ACL management, and delete access to deployment artifact paths, plus listing on the target S3 buckets."
  policy      = data.aws_iam_policy_document.s3_deploy[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "s3_deploy" {
  count = local.create_s3_policy ? 1 : 0

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.s3_deploy[0].arn
}

data "aws_iam_policy_document" "lambda_deploy" {
  count = local.create_lambda_policy ? 1 : 0

  statement {
    sid       = "UpdateFunctionCode"
    effect    = "Allow"
    actions   = ["lambda:UpdateFunctionCode"]
    resources = var.lambda_function_arns
  }
}

resource "aws_iam_policy" "lambda_deploy" {
  count = local.create_lambda_policy ? 1 : 0

  name        = local.lambda_policy_name
  description = "Grants ${var.user_name} permission to update the source code of the specified Lambda functions."
  policy      = data.aws_iam_policy_document.lambda_deploy[0].json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "lambda_deploy" {
  count = local.create_lambda_policy ? 1 : 0

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.lambda_deploy[0].arn
}

output "user_name" {
  description = "Name of the IAM deployment user."
  value       = aws_iam_user.deployment.name
}

output "user_arn" {
  description = "ARN of the IAM deployment user."
  value       = aws_iam_user.deployment.arn
}

output "s3_policy_arn" {
  description = "ARN of the S3 deployment policy, or null if it was not created."
  value       = one(aws_iam_policy.s3_deploy[*].arn)
}

output "lambda_policy_arn" {
  description = "ARN of the Lambda deployment policy, or null if it was not created."
  value       = one(aws_iam_policy.lambda_deploy[*].arn)
}

# main.tf
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# NOTE: The AWS provider block is injected by the deployment harness and must be
# configured with region = "us-east-1". CloudFront-scoped WAFv2 web ACLs and
# CloudFront ACM certificates must exist in us-east-1, so no aliased provider is used.

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "bucket_name" {
  description = "Custom S3 bucket name. If blank, falls back to domain_name, then to an auto-generated name."
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Optional apex/custom domain name for the website (e.g. example.com). Leave blank to use the CloudFront default domain."
  type        = string
  default     = ""
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for domain_name. Required when domain_name is set."
  type        = string
  default     = ""
}

variable "enable_versioning" {
  description = "Enable S3 bucket versioning."
  type        = bool
  default     = false
}

variable "include_www" {
  description = "Add a www. alias and a wildcard subject alternative name to the certificate."
  type        = bool
  default     = false
}

variable "price_class" {
  description = "CloudFront price class."
  type        = string
  default     = "PriceClass_100"

  validation {
    condition     = contains(["PriceClass_100", "PriceClass_200", "PriceClass_All"], var.price_class)
    error_message = "price_class must be one of PriceClass_100, PriceClass_200, or PriceClass_All."
  }
}

variable "enable_ipv6" {
  description = "Enable IPv6 on the CloudFront distribution."
  type        = bool
  default     = true
}

variable "default_root_object" {
  description = "Default root object served by CloudFront."
  type        = string
  default     = "index.html"
}

variable "minimum_protocol_version" {
  description = "Minimum TLS protocol version for viewer connections when a custom domain is used."
  type        = string
  default     = "TLSv1.2_2021"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "static-website"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Random suffix & locals
# -----------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

locals {
  has_domain = var.domain_name != ""

  bucket_name = (
    var.bucket_name != "" ? var.bucket_name :
    local.has_domain ? var.domain_name :
    "webapp-template-${random_id.bucket_suffix.hex}"
  )

  kms_alias_name = "alias/${replace(local.bucket_name, "/[^a-zA-Z0-9/_-]/", "-")}"

  s3_origin_id = "s3-${local.bucket_name}"
  index_path   = "/index.html"
  name_prefix  = replace(local.bucket_name, "/[^a-zA-Z0-9-]/", "-")

  aliases = local.has_domain ? (
    var.include_www ? [var.domain_name, "www.${var.domain_name}"] : [var.domain_name]
  ) : []

  subject_alternative_names = local.has_domain && var.include_www ? ["*.${var.domain_name}"] : []

  domain_precondition_message = "route53_zone_id must be a non-empty Route 53 hosted zone ID when domain_name is set."
}

# -----------------------------------------------------------------------------
# Static metadata (used only for the KMS key policy root principal)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# KMS customer-managed key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "website" {
  description             = "CMK for static website bucket ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = var.tags
}

resource "aws_kms_alias" "website" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.website.key_id
}

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowCloudFrontDecryptForDistribution"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.website.arn]
    }
  }
}

resource "aws_kms_key_policy" "website" {
  key_id = aws_kms_key.website.id
  policy = data.aws_iam_policy_document.kms_key.json
}

# -----------------------------------------------------------------------------
# S3 bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "website" {
  bucket = local.bucket_name
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "website" {
  bucket = aws_s3_bucket.website.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "website" {
  bucket = aws_s3_bucket.website.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "website" {
  bucket = aws_s3_bucket.website.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.website.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "website" {
  bucket = aws_s3_bucket.website.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# -----------------------------------------------------------------------------
# CloudFront Origin Access Control & bucket policy
# -----------------------------------------------------------------------------

resource "aws_cloudfront_origin_access_control" "website" {
  name                              = "${substr(local.name_prefix, 0, 50)}-oac"
  description                       = "OAC for ${local.bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid       = "AllowCloudFrontServicePrincipalReadOnly"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.website.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.website.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "website" {
  bucket = aws_s3_bucket.website.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.website]
}

# -----------------------------------------------------------------------------
# WAFv2 Web ACL (CloudFront scope, us-east-1)
# -----------------------------------------------------------------------------

resource "aws_wafv2_web_acl" "website" {
  name        = "${substr(local.name_prefix, 0, 100)}-waf"
  description = "WAF web ACL for ${local.bucket_name} CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "AWSManagedRulesKnownBadInputsRuleSet"
    priority = 2

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesKnownBadInputsRuleSet"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${substr(local.name_prefix, 0, 100)}-waf"
    sampled_requests_enabled   = true
  }

  tags = var.tags
}

# -----------------------------------------------------------------------------
# AWS-managed CloudFront cache policies
# -----------------------------------------------------------------------------

data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

# -----------------------------------------------------------------------------
# ACM certificate (us-east-1) with DNS validation
# -----------------------------------------------------------------------------

resource "aws_acm_certificate" "website" {
  count = local.has_domain ? 1 : 0

  domain_name               = var.domain_name
  subject_alternative_names = local.subject_alternative_names
  validation_method         = "DNS"
  tags                      = var.tags

  lifecycle {
    create_before_destroy = true

    precondition {
      condition     = var.domain_name == "" || var.route53_zone_id != ""
      error_message = local.domain_precondition_message
    }
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in flatten([for cert in aws_acm_certificate.website : cert.domain_validation_options]) :
    dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }

  allow_overwrite = true
  zone_id         = var.route53_zone_id
  name            = each.value.name
  type            = each.value.type
  ttl             = 60
  records         = [each.value.record]
}

resource "aws_acm_certificate_validation" "website" {
  count = local.has_domain ? 1 : 0

  certificate_arn         = aws_acm_certificate.website[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

# -----------------------------------------------------------------------------
# CloudFront distribution
# -----------------------------------------------------------------------------

resource "aws_cloudfront_distribution" "website" {
  enabled             = true
  comment             = "Static website for ${local.bucket_name}"
  price_class         = var.price_class
  is_ipv6_enabled     = var.enable_ipv6
  default_root_object = var.default_root_object
  http_version        = "http2and3"
  aliases             = local.aliases
  web_acl_id          = aws_wafv2_web_acl.website.arn

  origin {
    origin_id                = local.s3_origin_id
    domain_name              = aws_s3_bucket.website.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.website.id
  }

  default_cache_behavior {
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
  }

  ordered_cache_behavior {
    path_pattern           = local.index_path
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
  }

  custom_error_response {
    error_code            = 403
    response_code         = 404
    response_page_path    = local.index_path
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code            = 404
    response_code         = 404
    response_page_path    = local.index_path
    error_caching_min_ttl = 10
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = !local.has_domain
    acm_certificate_arn            = local.has_domain ? one(aws_acm_certificate_validation.website[*].certificate_arn) : null
    ssl_support_method             = local.has_domain ? "sni-only" : null
    minimum_protocol_version       = local.has_domain ? var.minimum_protocol_version : "TLSv1"
  }

  tags = var.tags

  lifecycle {
    precondition {
      condition     = var.domain_name == "" || var.route53_zone_id != ""
      error_message = local.domain_precondition_message
    }
  }
}

# -----------------------------------------------------------------------------
# Route 53 alias records
# -----------------------------------------------------------------------------

resource "aws_route53_record" "alias_a" {
  for_each = toset(local.aliases)

  zone_id = var.route53_zone_id
  name    = each.value
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.website.domain_name
    zone_id                = aws_cloudfront_distribution.website.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "alias_aaaa" {
  for_each = var.enable_ipv6 ? toset(local.aliases) : toset([])

  zone_id = var.route53_zone_id
  name    = each.value
  type    = "AAAA"

  alias {
    name                   = aws_cloudfront_distribution.website.domain_name
    zone_id                = aws_cloudfront_distribution.website.hosted_zone_id
    evaluate_target_health = false
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "s3_bucket_name" {
  description = "Name of the website S3 bucket."
  value       = aws_s3_bucket.website.id
}

output "s3_bucket_arn" {
  description = "ARN of the website S3 bucket."
  value       = aws_s3_bucket.website.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the bucket."
  value       = aws_kms_key.website.arn
}

output "cloudfront_distribution_id" {
  description = "ID of the CloudFront distribution."
  value       = aws_cloudfront_distribution.website.id
}

output "cloudfront_distribution_arn" {
  description = "ARN of the CloudFront distribution."
  value       = aws_cloudfront_distribution.website.arn
}

output "cloudfront_domain_name" {
  description = "CloudFront distribution domain name."
  value       = aws_cloudfront_distribution.website.domain_name
}

output "waf_web_acl_arn" {
  description = "ARN of the WAFv2 web ACL attached to the distribution."
  value       = aws_wafv2_web_acl.website.arn
}

output "acm_certificate_arn" {
  description = "ARN of the validated ACM certificate (null when no domain is set)."
  value       = one(aws_acm_certificate_validation.website[*].certificate_arn)
}

output "website_url" {
  description = "Public HTTPS URL of the website."
  value       = local.has_domain ? "https://${var.domain_name}" : "https://${aws_cloudfront_distribution.website.domain_name}"
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The AWS provider configuration (region = var.region) is injected by the
# deployment harness, so this file does not declare a provider block.

variable "region" {
  description = "AWS region to deploy into. Used for region selection and the S3 endpoint service name."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr_prefix" {
  description = "First two octets of the VPC CIDR block (for example 10.20 gives 10.20.0.0/16)."
  type        = string
  default     = "10.20"

  validation {
    condition     = can(regex("^\\d{1,3}\\.\\d{1,3}$", var.vpc_cidr_prefix))
    error_message = "vpc_cidr_prefix must be two dot-separated octets, such as \"10.20\"."
  }
}

variable "global_tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    "Author"     = "Fairwinds"
    "Managed By" = "Terraform"
  }
}

variable "availability_zones" {
  description = "Comma-separated list of 3 availability zone names. Leave empty to use the first 3 available AZs in the region."
  type        = string
  default     = ""
}

variable "multi_az_nat_gateway" {
  description = "Set to 1 to deploy one NAT gateway per AZ (3 in total). Takes precedence over single_nat_gateway."
  type        = number
  default     = 1

  validation {
    condition     = contains([0, 1], var.multi_az_nat_gateway)
    error_message = "multi_az_nat_gateway must be 0 or 1."
  }
}

variable "single_nat_gateway" {
  description = "Set to 1 to deploy a single NAT gateway shared by all AZs. Applies only when multi_az_nat_gateway is 0."
  type        = number
  default     = 0

  validation {
    condition     = contains([0, 1], var.single_nat_gateway)
    error_message = "single_nat_gateway must be 0 or 1."
  }
}

variable "enable_s3_vpc_endpoint" {
  description = "Whether to create an S3 gateway VPC endpoint attached to all private route tables."
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "${var.vpc_cidr_prefix}.0.0/16"

  azs = var.availability_zones != "" ? split(",", replace(var.availability_zones, " ", "")) : slice(data.aws_availability_zones.available.names, 0, 3)

  az_count = 3

  admin_subnet_suffixes           = [".0.0/21", ".8.0/21", ".16.0/21"]
  public_subnet_suffixes          = [".32.0/21", ".40.0/21", ".48.0/21"]
  private_prod_subnet_suffixes    = [".64.0/21", ".72.0/21", ".80.0/21"]
  private_working_subnet_suffixes = [".96.0/21", ".104.0/21", ".112.0/21"]

  nat_gateway_count = var.multi_az_nat_gateway == 1 ? local.az_count : var.single_nat_gateway
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.global_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "vpc" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.global_tags, {
    Name = "vpc"
  })
}

resource "aws_subnet" "admin" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.vpc_cidr_prefix}${local.admin_subnet_suffixes[count.index]}"
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.global_tags, {
    Name = "admin_az${count.index + 1}"
  })
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_prefix}${local.public_subnet_suffixes[count.index]}"
  availability_zone = local.azs[count.index]

  # Public IPs are not auto-assigned. Resources that need a public address
  # (for example internet-facing load balancers or bastions) must request one
  # explicitly, with an Elastic IP or an instance-level
  # associate_public_ip_address. The subnet stays public through the IGW route.
  map_public_ip_on_launch = false

  tags = merge(var.global_tags, {
    Name = "public_az${count.index + 1}"
  })
}

resource "aws_subnet" "private_prod" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.vpc_cidr_prefix}${local.private_prod_subnet_suffixes[count.index]}"
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.global_tags, {
    Name = "private_prod_az${count.index + 1}"
  })
}

resource "aws_subnet" "private_working" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "${var.vpc_cidr_prefix}${local.private_working_subnet_suffixes[count.index]}"
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.global_tags, {
    Name = "private_working_az${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.vpc.id
  }

  tags = merge(var.global_tags, {
    Name = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(var.global_tags, {
    Name = "nat_az${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.vpc]
}

resource "aws_nat_gateway" "nat" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.global_tags, {
    Name = "nat_az${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.vpc]
}

resource "aws_route_table" "private" {
  count = local.az_count

  vpc_id = aws_vpc.main.id

  tags = merge(var.global_tags, {
    Name = "private_az${count.index + 1}"
  })
}

resource "aws_route" "private_nat" {
  count = local.nat_gateway_count > 0 ? local.az_count : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[var.multi_az_nat_gateway == 1 ? count.index : 0].id
}

resource "aws_route_table_association" "admin" {
  count = local.az_count

  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_prod" {
  count = local.az_count

  subnet_id      = aws_subnet.private_prod[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table_association" "private_working" {
  count = local.az_count

  subnet_id      = aws_subnet.private_working[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  count = var.enable_s3_vpc_endpoint ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  # Full-access gateway endpoint policy, as requested. This is a VPC endpoint
  # resource policy, not an IAM identity policy. It can be narrowed later to
  # specific bucket ARNs (for example arn:aws:s3:::my-bucket and
  # arn:aws:s3:::my-bucket/*) to restrict which buckets are reachable via the endpoint.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "FullAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource  = "*"
      }
    ]
  })

  tags = merge(var.global_tags, {
    Name = "s3"
  })
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the subnets."
  value       = local.azs
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.vpc.id
}

output "admin_subnet_ids" {
  description = "IDs of the admin subnets."
  value       = aws_subnet.admin[*].id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_prod_subnet_ids" {
  description = "IDs of the private production subnets."
  value       = aws_subnet.private_prod[*].id
}

output "private_working_subnet_ids" {
  description = "IDs of the private working subnets."
  value       = aws_subnet.private_working[*].id
}

output "public_route_table_id" {
  description = "ID of the shared public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_ids" {
  description = "IDs of the per-AZ private route tables."
  value       = aws_route_table.private[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways."
  value       = aws_nat_gateway.nat[*].id
}

output "nat_public_ips" {
  description = "Public IPs of the NAT gateway Elastic IPs."
  value       = aws_eip.nat[*].public_ip
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint, or null if disabled."
  value       = var.enable_s3_vpc_endpoint ? aws_vpc_endpoint.s3[0].id : null
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "project_name" {
  description = "Project name used as the prefix for resource names and tags."
  type        = string
  default     = "webapp"
}

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "app_port" {
  description = "Port the application container listens on."
  type        = number
  default     = 80
}

variable "health_check_path" {
  description = "HTTP path used by the target group health check."
  type        = string
  default     = "/"
}

variable "container_image" {
  description = "Placeholder container image. CI/CD replaces it with an image from the ECR repository."
  type        = string
  default     = "public.ecr.aws/nginx/nginx:stable"
}

variable "github_org" {
  description = "GitHub organization or account whose workflows may assume the deploy role."
  type        = string
  default     = "my-github-org"
}

variable "db_username" {
  description = "Master username for the PostgreSQL database."
  type        = string
  default     = "postgres"
}

variable "db_name" {
  description = "Name of the initial PostgreSQL database."
  type        = string
  default     = "mydb"
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
  default     = "db.t3.micro"
}

variable "task_cpu" {
  description = "Fargate task CPU units."
  type        = number
  default     = 256
}

variable "task_memory" {
  description = "Fargate task memory (MiB)."
  type        = number
  default     = 512
}

locals {
  name_prefix    = "${var.project_name}-${var.environment}"
  name_suffix    = random_id.suffix.hex
  container_name = "app"
  db_port        = 5432
  https_port     = 443
  http_port      = 80

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  ecs_tasks_principal       = "ecs-tasks.amazonaws.com"
  github_oidc_host          = "token.actions.githubusercontent.com"
  github_oidc_name          = "${local.name_prefix}-github-oidc"
  github_oidc_arn           = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${local.github_oidc_host}"
  github_actions_role_label = "${local.name_prefix}-github-actions"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Per-apply unique suffix for regional / account-scoped names
# -----------------------------------------------------------------------------

resource "random_id" "suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-a", Tier = "public" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-b", Tier = "public" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 10)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a", Tier = "private" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 11)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b", Tier = "private" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# VPC endpoints (private subnets have no NAT)
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-s3-endpoint" })
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-ecr-api-endpoint" })
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-ecr-dkr-endpoint" })
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-logs-endpoint" })
}

resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.secretsmanager"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-secretsmanager-endpoint" })
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Internal ALB: HTTP/HTTPS from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = local.https_port
    to_port     = local.https_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from within the VPC (redirected to HTTPS)"
    from_port   = local.http_port
    to_port     = local.http_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb-sg" })
}

resource "aws_security_group" "app" {
  name        = "${local.name_prefix}-app-sg"
  description = "ECS tasks: reachable only from the ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "All ports from the ALB only"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description     = "HTTPS to S3 via the gateway endpoint (ECR image layers)"
    from_port       = local.https_port
    to_port         = local.https_port
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.s3.prefix_list_id]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-app-sg" })
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpce-sg"
  description = "Interface VPC endpoints: HTTPS from ECS tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTPS from ECS tasks"
    from_port       = local.https_port
    to_port         = local.https_port
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    description = "Outbound only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpce-sg" })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "RDS PostgreSQL: reachable only from ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from ECS tasks only"
    from_port       = local.db_port
    to_port         = local.db_port
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    description = "Outbound only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-sg" })
}

# -----------------------------------------------------------------------------
# Self-signed certificate imported into ACM
# -----------------------------------------------------------------------------

resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name  = "${local.name_prefix}.internal"
    organization = var.project_name
  }

  dns_names             = ["${local.name_prefix}.internal"]
  validity_period_hours = 8760
  early_renewal_hours   = 720

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  private_key      = tls_private_key.alb.private_key_pem
  certificate_body = tls_self_signed_cert.alb.cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb-cert" })
}

# -----------------------------------------------------------------------------
# Application Load Balancer
# -----------------------------------------------------------------------------

resource "aws_lb" "main" {
  name                       = "${local.name_prefix}-alb-${local.name_suffix}"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb" })
}

resource "aws_lb_target_group" "app" {
  name                 = "${local.name_prefix}-tg-${local.name_suffix}"
  port                 = var.app_port
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = var.health_check_path
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200-399"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-tg" })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = local.https_port
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-https-listener" })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = local.http_port
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = tostring(local.https_port)
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-http-listener" })
}

# -----------------------------------------------------------------------------
# Container registry
# -----------------------------------------------------------------------------

resource "aws_ecr_repository" "app" {
  name                 = "${local.name_prefix}-${local.name_suffix}"
  image_tag_mutability = "IMMUTABLE"
  force_delete         = true

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = merge(local.common_tags, { Name = local.name_prefix })
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Logging
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/${local.name_prefix}-${local.name_suffix}"
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = "/ecs/${local.name_prefix}" })
}

# -----------------------------------------------------------------------------
# Database
# -----------------------------------------------------------------------------

resource "random_password" "db" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "db" {
  name_prefix             = "${local.name_prefix}-db-credentials-"
  description             = "PostgreSQL credentials and connection string for ${local.name_prefix}"
  recovery_window_in_days = 0

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-credentials" })
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id

  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db.result
    host     = aws_db_instance.main.address
    port     = local.db_port
    dbname   = var.db_name
    url      = "postgresql://${var.db_username}:${random_password.db.result}@${aws_db_instance.main.address}:${local.db_port}/${var.db_name}"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnets-${local.name_suffix}"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnets" })
}

resource "aws_db_instance" "main" {
  identifier     = "${local.name_prefix}-db-${local.name_suffix}"
  engine         = "postgres"
  engine_version = "16"
  instance_class = var.db_instance_class

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp2"
  storage_encrypted     = true

  db_name  = var.db_name
  username = var.db_username
  password = random_password.db.result
  port     = local.db_port

  multi_az               = false
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  backup_retention_period         = 7
  backup_window                   = "03:00-04:00"
  maintenance_window              = "sun:04:30-sun:05:30"
  auto_minor_version_upgrade      = true
  copy_tags_to_snapshot           = true
  deletion_protection             = true
  skip_final_snapshot             = false
  final_snapshot_identifier       = "${local.name_prefix}-db-final-${local.name_suffix}"
  enabled_cloudwatch_logs_exports = ["postgresql"]

  timeouts {
    create = "60m"
    update = "60m"
    delete = "60m"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db" })

  # Teardown must first apply deletion_protection = false and drop this
  # prevent_destroy guard (required for stateful resources by the platform
  # rules) before running terraform destroy.
  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# ECS IAM roles
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_tasks_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ecs_tasks_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "ecs_execution" {
  name               = "${local.name_prefix}-ecs-execution-${local.name_suffix}"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-ecs-execution" })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_managed" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy" "ecs_execution_secrets" {
  name = "${local.name_prefix}-ecs-execution-secrets"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadDatabaseSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [aws_secretsmanager_secret.db.arn]
      }
    ]
  })
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.name_prefix}-ecs-task-${local.name_suffix}"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-ecs-task" })
}

# -----------------------------------------------------------------------------
# ECS cluster, task definition and service
# -----------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-cluster-${local.name_suffix}"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = ["FARGATE", "FARGATE_SPOT"]

  default_capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 1
    base              = 0
  }

  default_capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 4
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = "${local.name_prefix}-app"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = var.task_cpu
  memory                   = var.task_memory
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  runtime_platform {
    operating_system_family = "LINUX"
    cpu_architecture        = "X86_64"
  }

  container_definitions = jsonencode([
    {
      name      = local.container_name
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = var.app_port
          hostPort      = var.app_port
          protocol      = "tcp"
        }
      ]

      environment = [
        { name = "DB_HOST", value = aws_db_instance.main.address },
        { name = "DB_PORT", value = tostring(local.db_port) },
        { name = "DB_NAME", value = var.db_name },
        { name = "DB_USER", value = var.db_username },
        { name = "PORT", value = tostring(var.app_port) }
      ]

      secrets = [
        { name = "DATABASE_URL", valueFrom = "${aws_secretsmanager_secret.db.arn}:url::" },
        { name = "DB_PASSWORD", valueFrom = "${aws_secretsmanager_secret.db.arn}:password::" }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.app.name
          awslogs-region        = data.aws_region.current.name
          awslogs-stream-prefix = local.container_name
        }
      }
    }
  ])

  depends_on = [aws_secretsmanager_secret_version.db]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-app" })
}

resource "aws_ecs_service" "app" {
  name                              = "${local.name_prefix}-service-${local.name_suffix}"
  cluster                           = aws_ecs_cluster.main.id
  task_definition                   = aws_ecs_task_definition.app.arn
  desired_count                     = 2
  health_check_grace_period_seconds = 60
  propagate_tags                    = "SERVICE"
  enable_ecs_managed_tags           = true
  wait_for_steady_state             = false

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 1
    base              = 0
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 4
  }

  network_configuration {
    subnets          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
    security_groups  = [aws_security_group.app.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = local.container_name
    container_port   = var.app_port
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  deployment_minimum_healthy_percent = 100
  deployment_maximum_percent         = 200

  lifecycle {
    ignore_changes = [desired_count, task_definition]
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
    aws_ecs_cluster_capacity_providers.main,
    aws_iam_role_policy_attachment.ecs_execution_managed,
    aws_iam_role_policy.ecs_execution_secrets,
    aws_vpc_endpoint.ecr_api,
    aws_vpc_endpoint.ecr_dkr,
    aws_vpc_endpoint.logs,
    aws_vpc_endpoint.secretsmanager,
    aws_vpc_endpoint.s3,
  ]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-service" })
}

# -----------------------------------------------------------------------------
# Auto scaling
# -----------------------------------------------------------------------------

resource "aws_appautoscaling_target" "ecs" {
  service_namespace  = "ecs"
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  min_capacity       = 2
  max_capacity       = 4

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-scaling-target" })
}

resource "aws_appautoscaling_policy" "cpu" {
  name               = "${local.name_prefix}-cpu-target-tracking"
  policy_type        = "TargetTrackingScaling"
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension

  target_tracking_scaling_policy_configuration {
    target_value       = 70
    scale_in_cooldown  = 300
    scale_out_cooldown = 60

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "${local.name_prefix}-memory-target-tracking"
  policy_type        = "TargetTrackingScaling"
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension

  target_tracking_scaling_policy_configuration {
    target_value       = 75
    scale_in_cooldown  = 300
    scale_out_cooldown = 60

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
  }
}

# -----------------------------------------------------------------------------
# GitHub Actions OIDC deploy role
# -----------------------------------------------------------------------------

# Pre-create reconciliation for the account-global GitHub OIDC provider.
# No-op when the provider does not exist (greenfield). Otherwise it verifies
# the provider carries this stack's exact tags, classifies every role trusting
# it by tags (Project, Environment, ManagedBy, Name), and refuses to delete
# anything if any trusting role is not owned by this stack. Only after all
# checks pass does it delete the orphaned stack roles and then the provider.
# Requires AWS CLI v2 on the runner with Terraform's credentials and:
# iam:GetOpenIDConnectProvider, iam:ListOpenIDConnectProviderTags,
# iam:DeleteOpenIDConnectProvider, iam:ListRoles, iam:ListRoleTags,
# iam:ListRolePolicies, iam:DeleteRolePolicy, iam:ListAttachedRolePolicies,
# iam:DetachRolePolicy and iam:DeleteRole.
resource "terraform_data" "github_oidc_reconcile" {
  triggers_replace = [local.github_oidc_arn]

  provisioner "local-exec" {
    when        = create
    interpreter = ["/bin/bash", "-c"]

    environment = {
      AWS_REGION         = data.aws_region.current.name
      OIDC_ARN           = local.github_oidc_arn
      OIDC_HOST          = local.github_oidc_host
      EXPECTED_PROJECT   = var.project_name
      EXPECTED_ENV       = var.environment
      EXPECTED_MANAGED   = "terraform"
      EXPECTED_NAME      = local.github_oidc_name
      EXPECTED_ROLE_NAME = local.github_actions_role_label
    }

    command = <<-EOT
      set -euo pipefail

      # 1. Provider lookup (greenfield path is a no-op).
      if ! out=$(aws iam get-open-id-connect-provider --open-id-connect-provider-arn "$OIDC_ARN" --query Url --output text 2>&1); then
        if printf '%s' "$out" | grep -q 'NoSuchEntity'; then
          echo "No existing OIDC provider for $OIDC_HOST; nothing to reconcile."
          exit 0
        fi
        echo "Failed to query OIDC provider $OIDC_ARN: $out" >&2
        exit 1
      fi

      provider_tag() {
        aws iam list-open-id-connect-provider-tags \
          --open-id-connect-provider-arn "$OIDC_ARN" \
          --query "Tags[?Key=='$1'].Value | [0]" \
          --output text 2>/dev/null || echo "__missing__"
      }

      role_tag() {
        aws iam list-role-tags \
          --role-name "$1" \
          --query "Tags[?Key=='$2'].Value | [0]" \
          --output text 2>/dev/null || echo "__missing__"
      }

      # 2. Provider ownership check.
      if [ "$(provider_tag Project)" != "$EXPECTED_PROJECT" ] || \
         [ "$(provider_tag Environment)" != "$EXPECTED_ENV" ] || \
         [ "$(provider_tag ManagedBy)" != "$EXPECTED_MANAGED" ] || \
         [ "$(provider_tag Name)" != "$EXPECTED_NAME" ]; then
        echo "OIDC provider for $OIDC_HOST exists and is not owned by this stack - refusing to delete." >&2
        exit 1
      fi

      # 3. Classify every role that trusts the provider, by tags only.
      trusting=$(aws iam list-roles \
        --query "Roles[?contains(to_string(AssumeRolePolicyDocument), '$OIDC_ARN')].RoleName" \
        --output text)

      owned=""
      foreign=""
      if [ -n "$trusting" ] && [ "$trusting" != "None" ]; then
        for role in $trusting; do
          if [ "$(role_tag "$role" Project)" = "$EXPECTED_PROJECT" ] && \
             [ "$(role_tag "$role" Environment)" = "$EXPECTED_ENV" ] && \
             [ "$(role_tag "$role" ManagedBy)" = "$EXPECTED_MANAGED" ] && \
             [ "$(role_tag "$role" Name)" = "$EXPECTED_ROLE_NAME" ]; then
            owned="$owned $role"
          else
            foreign="$foreign $role"
          fi
        done
      fi

      if [ -n "$foreign" ]; then
        echo "OIDC provider for $OIDC_HOST is trusted by roles outside this stack ($foreign) - refusing to delete." >&2
        exit 1
      fi

      # 4. Delete orphaned stack roles so they cannot become assumable again.
      for role in $owned; do
        echo "Deleting orphaned stack role $role."

        inline=$(aws iam list-role-policies --role-name "$role" --query 'PolicyNames' --output text)
        if [ -n "$inline" ] && [ "$inline" != "None" ]; then
          for policy in $inline; do
            aws iam delete-role-policy --role-name "$role" --policy-name "$policy"
          done
        fi

        attached=$(aws iam list-attached-role-policies --role-name "$role" --query 'AttachedPolicies[].PolicyArn' --output text)
        if [ -n "$attached" ] && [ "$attached" != "None" ]; then
          for policy_arn in $attached; do
            aws iam detach-role-policy --role-name "$role" --policy-arn "$policy_arn"
          done
        fi

        aws iam delete-role --role-name "$role"
      done

      # 5. Delete the leftover provider.
      echo "Deleting leftover OIDC provider $OIDC_ARN owned by this stack."
      aws iam delete-open-id-connect-provider --open-id-connect-provider-arn "$OIDC_ARN"
    EOT
  }
}

# The reconciliation step above removes a leftover provider only if it carries this stack's tags.
resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://${local.github_oidc_host}"
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]

  tags = merge(local.common_tags, { Name = local.github_oidc_name })

  depends_on = [terraform_data.github_oidc_reconcile]
}

data "aws_iam_policy_document" "github_actions_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "${local.github_oidc_host}:sub"
      values   = ["repo:${var.github_org}/*:*"]
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name                 = "${local.name_prefix}-github-actions-${local.name_suffix}"
  assume_role_policy   = data.aws_iam_policy_document.github_actions_assume.json
  max_session_duration = 3600

  tags = merge(local.common_tags, { Name = local.github_actions_role_label })
}

resource "aws_iam_role_policy" "github_actions_deploy" {
  name = "github_actions_deploy"
  role = aws_iam_role.github_actions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EcrAuthToken"
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken"]
        Resource = "*"
      },
      {
        Sid    = "EcrPushPull"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
          "ecr:InitiateLayerUpload",
          "ecr:UploadLayerPart",
          "ecr:CompleteLayerUpload",
          "ecr:PutImage",
          "ecr:DescribeImages",
          "ecr:DescribeRepositories",
        ]
        Resource = [aws_ecr_repository.app.arn]
      },
      {
        Sid    = "EcsTaskDefinitions"
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DescribeTaskDefinition",
          "ecs:ListTaskDefinitions",
          "ecs:DeregisterTaskDefinition",
          "ecs:DeleteTaskDefinitions",
        ]
        Resource = "*"
      },
      {
        Sid    = "EcsServiceUpdate"
        Effect = "Allow"
        Action = [
          "ecs:UpdateService",
          "ecs:DescribeServices",
        ]
        Resource = [aws_ecs_service.app.id]
      },
      {
        Sid    = "PassTaskRoles"
        Effect = "Allow"
        Action = ["iam:PassRole"]
        Resource = [
          aws_iam_role.ecs_execution.arn,
          aws_iam_role.ecs_task.arn,
        ]
        Condition = {
          StringEquals = {
            "iam:PassedToService" = local.ecs_tasks_principal
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = [aws_subnet.public_a.id, aws_subnet.public_b.id]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = [aws_subnet.private_a.id, aws_subnet.private_b.id]
}

output "alb_dns_name" {
  description = "DNS name of the internal Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "alb_arn" {
  description = "ARN of the Application Load Balancer."
  value       = aws_lb.main.arn
}

output "ecr_repository_url" {
  description = "URL of the ECR repository CI/CD pushes to."
  value       = aws_ecr_repository.app.repository_url
}

output "ecs_cluster_name" {
  description = "Name of the ECS cluster."
  value       = aws_ecs_cluster.main.name
}

output "ecs_service_name" {
  description = "Name of the ECS service."
  value       = aws_ecs_service.app.name
}

output "ecs_task_definition_family" {
  description = "Family of the ECS task definition."
  value       = aws_ecs_task_definition.app.family
}

output "ecs_execution_role_arn" {
  description = "ARN of the ECS task execution role."
  value       = aws_iam_role.ecs_execution.arn
}

output "ecs_task_role_arn" {
  description = "ARN of the ECS task role."
  value       = aws_iam_role.ecs_task.arn
}

output "db_endpoint" {
  description = "Endpoint of the RDS PostgreSQL instance."
  value       = aws_db_instance.main.endpoint
}

output "db_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database credentials."
  value       = aws_secretsmanager_secret.db.arn
}

output "cloudwatch_log_group_name" {
  description = "CloudWatch log group for application containers."
  value       = aws_cloudwatch_log_group.app.name
}

output "github_actions_role_arn" {
  description = "ARN of the IAM role assumed by GitHub Actions via OIDC."
  value       = aws_iam_role.github_actions.arn
}

output "github_oidc_provider_arn" {
  description = "ARN of the GitHub Actions OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

# Provider configuration (region us-east-1) is injected by the deployment harness.
# Declaring a second provider "aws" block here would cause a duplicate-provider error,
# so this file only pins the provider version.

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_tag" {
  description = "Tag that goes into every resource name, description and tag, so several clusters can share one account."
  type        = string
  default     = "default"
}

variable "enable_key_rotation" {
  description = "Turns on annual rotation for the Vault seal KMS key."
  type        = bool
  default     = false
}

variable "machine_roles" {
  description = "Map of machine role names to sets of policy identifiers (read-tags, vault-kms, nomad-keys, consul-keys, vault-keys, client-keys)."
  type        = map(set(string))
  default     = {}
}

locals {
  name_prefix = "resinstack"
  cluster_key = "resinstack:cluster"

  common_tags = {
    (local.cluster_key) = var.cluster_tag
  }

  secret_names = toset([
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token",
  ])

  secrets_get_action = "secretsmanager:GetSecretValue"
  policy_version     = "2012-10-17"
}

# -----------------------------------------------------------------------------
# KMS key for Vault auto-unseal
# -----------------------------------------------------------------------------

resource "aws_kms_key" "vault_seal" {
  description             = "${local.name_prefix}:vault:seal:${var.cluster_tag}"
  enable_key_rotation     = var.enable_key_rotation
  rotation_period_in_days = var.enable_key_rotation ? 365 : null
  deletion_window_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Secrets Manager secrets for HashiStack tokens and keys
# (values are filled in by the cluster bootstrap process, not stored in this file)
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "secret" {
  for_each = local.secret_names

  name                    = "${local.name_prefix}-${each.key}-${var.cluster_tag}"
  description             = "ResinStack ${each.key} for cluster ${var.cluster_tag}"
  recovery_window_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM policies
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "vault_kms" {
  name        = "${local.name_prefix}-vault-kms-${var.cluster_tag}"
  description = "Lets Vault auto-unseal with the cluster KMS key"

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid    = "VaultKMSUnseal"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.vault_seal.arn
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "read_tags" {
  name        = "ResinStackReadTags-${var.cluster_tag}"
  description = "Lets instances describe EC2 instances for cloud auto-join"

  # ec2:DescribeInstances does not support resource-level permissions.
  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid      = "ResinStackReadTags"
        Effect   = "Allow"
        Action   = ["ec2:DescribeInstances"]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "client_keys" {
  name        = "${local.name_prefix}-client-keys-${var.cluster_tag}"
  description = "Lets client nodes read the secrets they need"

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid    = "ClientKeys"
        Effect = "Allow"
        Action = [local.secrets_get_action]
        Resource = [
          aws_secretsmanager_secret.secret["consul-agent-token"].arn,
          aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
          aws_secretsmanager_secret.secret["nomad-client-consul-token"].arn,
        ]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "nomad_keys" {
  name        = "${local.name_prefix}-nomad-keys-${var.cluster_tag}"
  description = "Lets Nomad servers read the secrets they need"

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid    = "NomadKeys"
        Effect = "Allow"
        Action = [local.secrets_get_action]
        Resource = [
          aws_secretsmanager_secret.secret["consul-agent-token"].arn,
          aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
          aws_secretsmanager_secret.secret["nomad-gossip-key"].arn,
          aws_secretsmanager_secret.secret["nomad-server-consul-token"].arn,
          aws_secretsmanager_secret.secret["nomad-vault-token"].arn,
        ]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "consul_keys" {
  name        = "${local.name_prefix}-consul-keys-${var.cluster_tag}"
  description = "Lets Consul servers read the secrets they need"

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid    = "ConsulKeys"
        Effect = "Allow"
        Action = [local.secrets_get_action]
        Resource = [
          aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
        ]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "vault_keys" {
  name        = "${local.name_prefix}-vault-keys-${var.cluster_tag}"
  description = "Lets Vault servers read the secrets they need"

  policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid    = "VaultKeys"
        Effect = "Allow"
        Action = [local.secrets_get_action]
        Resource = [
          aws_secretsmanager_secret.secret["consul-gossip-key"].arn,
          aws_secretsmanager_secret.secret["vault-consul-token"].arn,
        ]
      }
    ]
  })

  tags = local.common_tags
}

locals {
  policy_arns = {
    "read-tags"   = aws_iam_policy.read_tags.arn
    "vault-kms"   = aws_iam_policy.vault_kms.arn
    "nomad-keys"  = aws_iam_policy.nomad_keys.arn
    "consul-keys" = aws_iam_policy.consul_keys.arn
    "vault-keys"  = aws_iam_policy.vault_keys.arn
    "client-keys" = aws_iam_policy.client_keys.arn
  }
}

# -----------------------------------------------------------------------------
# Machine roles and instance profiles
# -----------------------------------------------------------------------------

resource "aws_iam_role" "machine" {
  for_each = var.machine_roles

  name                 = "${local.name_prefix}-${each.key}-${var.cluster_tag}"
  description          = "ResinStack ${each.key} machine role for cluster ${var.cluster_tag}"
  max_session_duration = 43200

  assume_role_policy = jsonencode({
    Version = local.policy_version
    Statement = [
      {
        Sid    = "EC2AssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_instance_profile" "machine" {
  for_each = var.machine_roles

  name = "${local.name_prefix}-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.machine[each.key].name

  tags = local.common_tags
}

locals {
  role_policy_pairs = {
    for pair in flatten([
      for role, ids in var.machine_roles : [
        for id in ids : {
          role   = role
          policy = id
        } if contains(keys(local.policy_arns), id)
      ]
    ]) : "${pair.role}:${pair.policy}" => pair
  }
}

resource "aws_iam_role_policy_attachment" "machine" {
  for_each = local.role_policy_pairs

  role       = aws_iam_role.machine[each.value.role].name
  policy_arn = local.policy_arns[each.value.policy]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vault_kms_key_id" {
  description = "ID of the KMS key Vault uses to unseal"
  value       = aws_kms_key.vault_seal.key_id
}

output "secret_names" {
  description = "Map of logical secret names to their Secrets Manager names"
  value       = { for k, s in aws_secretsmanager_secret.secret : k => s.name }
}

output "machine_role_names" {
  description = "Map of machine role keys to IAM role names"
  value       = { for k, r in aws_iam_role.machine : k => r.name }
}

output "instance_profile_names" {
  description = "Map of machine role keys to instance profile names"
  value       = { for k, p in aws_iam_instance_profile.machine : k => p.name }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_prefix" {
  description = "Prefix applied to the names and tags of all resources."
  type        = string
  default     = "elluis_codes_limited_network"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "64.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_subnet_map = {
    (data.aws_availability_zones.available.names[0]) = 11
    (data.aws_availability_zones.available.names[1]) = 22
    (data.aws_availability_zones.available.names[2]) = 33
  }

  private_subnet_offset_shift = 100
  subnet_newbits              = 8
  all_traffic_cidr            = "0.0.0.0/0"

  common_tags = {
    Environment = var.environment_prefix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  for_each = local.az_subnet_map

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, each.value)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-public-subnet-${each.key}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  for_each = local.az_subnet_map

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, each.value + local.private_subnet_offset_shift)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-private-subnet-${each.key}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.all_traffic_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  for_each = local.az_subnet_map

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-nat-eip-${each.key}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  for_each = local.az_subnet_map

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-nat-gw-${each.key}"
  })

  lifecycle {
    ignore_changes = [subnet_id]
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  for_each = local.az_subnet_map

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.all_traffic_cidr
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_prefix}-private-rt-${each.key}"
  })
}

resource "aws_route_table_association" "private" {
  for_each = local.az_subnet_map

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [route_table_id]
  }
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.main.id
}

output "public_subnet_ids" {
  description = "Map of AZ name to public subnet ID."
  value       = { for az, subnet in aws_subnet.public : az => subnet.id }
}

output "private_subnet_ids" {
  description = "Map of AZ name to private subnet ID."
  value       = { for az, subnet in aws_subnet.private : az => subnet.id }
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_ids" {
  description = "Map of AZ name to private route table ID."
  value       = { for az, rt in aws_route_table.private : az => rt.id }
}

output "nat_gateway_ids" {
  description = "Map of AZ name to NAT Gateway ID."
  value       = { for az, nat in aws_nat_gateway.main : az => nat.id }
}

output "nat_eip_public_ips" {
  description = "Map of AZ name to NAT Gateway Elastic IP address."
  value       = { for az, eip in aws_eip.nat : az => eip.public_ip }
}

# main.tf
#
# Note: no `provider "aws"` block is declared here. The deployment harness injects
# the provider configuration for us-east-1, and declaring a second one would cause a
# duplicate-provider error. Region-specific values, such as the KMS ViaService
# condition, come from data.aws_region so they always match the injected provider region.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "creation_token" {
  description = "Unique idempotency token for the EFS file system."
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "EFS performance mode."
  type        = string
  default     = "generalPurpose"

  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "performance_mode must be either \"generalPurpose\" or \"maxIO\"."
  }
}

variable "throughput_mode" {
  description = "EFS throughput mode."
  type        = string
  default     = "bursting"

  validation {
    condition     = contains(["bursting", "provisioned", "elastic"], var.throughput_mode)
    error_message = "throughput_mode must be one of \"bursting\", \"provisioned\" or \"elastic\"."
  }
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput in MiB/s. Only used when throughput_mode is \"provisioned\"."
  type        = number
  default     = 10

  validation {
    condition     = var.provisioned_throughput_in_mibps >= 1
    error_message = "provisioned_throughput_in_mibps must be at least 1."
  }
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix     = "efs-${var.creation_token}"
  vpc_cidr        = "10.0.0.0/16"
  nfs_port        = 2049
  account_id      = data.aws_caller_identity.current.account_id
  efs_service     = "elasticfilesystem.${data.aws_region.current.name}.amazonaws.com"
  account_root    = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  efs_kms_actions = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:CreateGrant", "kms:DescribeKey"]
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "efs_vpc" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "efs_private" {
  count = 2

  vpc_id                  = aws_vpc.efs_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.efs_vpc.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-private-${count.index}"
    Tier = "private"
  })
}

locals {
  subnet_ids = aws_subnet.efs_private[*].id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "efs_client_sg" {
  name        = "${local.name_prefix}-client-sg"
  description = "Attach to compute that is allowed to mount the EFS file system"
  vpc_id      = aws_vpc.efs_vpc.id

  egress {
    description = "NFS to EFS mount targets within the VPC"
    from_port   = local.nfs_port
    to_port     = local.nfs_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.efs_vpc.cidr_block]
  }

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-client-sg"
  })
}

resource "aws_security_group" "efs_sg" {
  name        = "${local.name_prefix}-mount-target-sg"
  description = "EFS mount targets - NFS from client security group only"
  vpc_id      = aws_vpc.efs_vpc.id

  ingress {
    description     = "NFS from EFS clients"
    from_port       = local.nfs_port
    to_port         = local.nfs_port
    protocol        = "tcp"
    security_groups = [aws_security_group.efs_client_sg.id]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.efs_vpc.cidr_block]
  }

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-mount-target-sg"
  })
}

locals {
  security_group_ids = [aws_security_group.efs_sg.id]
}

# -----------------------------------------------------------------------------
# KMS key for EFS encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "efs_key" {
  description             = "Customer managed KMS key that encrypts the ${var.creation_token} EFS file system at rest"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.name_prefix}-key-policy"
    Statement = [
      {
        Sid    = "EnableRootAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEFSServiceUseOfTheKey"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action   = local.efs_kms_actions
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService"    = local.efs_service
            "kms:CallerAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-kms-key"
  })
}

resource "aws_kms_alias" "efs_key_alias" {
  name          = "alias/efs-${var.creation_token}"
  target_key_id = aws_kms_key.efs_key.key_id
}

# -----------------------------------------------------------------------------
# EFS file system
# -----------------------------------------------------------------------------

resource "aws_efs_file_system" "shared" {
  creation_token                  = var.creation_token
  performance_mode                = var.performance_mode
  throughput_mode                 = var.throughput_mode
  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null
  encrypted                       = true
  kms_key_id                      = aws_kms_key.efs_key.arn

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = merge(var.tags, {
    Name = local.name_prefix
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "shared_backup" {
  file_system_id = aws_efs_file_system.shared.id

  backup_policy {
    status = "ENABLED"
  }
}

resource "aws_efs_mount_target" "shared" {
  for_each = { for idx, id in local.subnet_ids : idx => id }

  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = each.value
  security_groups = local.security_group_ids
}

resource "aws_efs_file_system_policy" "shared_policy" {
  file_system_id = aws_efs_file_system.shared.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.name_prefix}-fs-policy"
    Statement = [
      {
        Sid    = "AllowClientAccessViaMountTarget"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = aws_efs_file_system.shared.arn
        Condition = {
          Bool = {
            "elasticfilesystem:AccessedViaMountTarget" = "true"
          }
        }
      },
      {
        Sid    = "DenyInsecureTransport"
        Effect = "Deny"
        Principal = {
          AWS = "*"
        }
        Action   = "*"
        Resource = aws_efs_file_system.shared.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "efs_file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.shared.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system."
  value       = aws_efs_file_system.shared.arn
}

output "efs_dns_name" {
  description = "DNS name used to mount the EFS file system."
  value       = aws_efs_file_system.shared.dns_name
}

output "efs_mount_target_ids" {
  description = "IDs of the EFS mount targets, keyed by subnet index."
  value       = { for k, mt in aws_efs_mount_target.shared : k => mt.id }
}

output "efs_mount_target_dns_names" {
  description = "Per-AZ DNS names of the EFS mount targets, keyed by subnet index."
  value       = { for k, mt in aws_efs_mount_target.shared : k => mt.mount_target_dns_name }
}

output "kms_key_arn" {
  description = "ARN of the KMS key used to encrypt the EFS file system."
  value       = aws_kms_key.efs_key.arn
}

output "kms_key_alias" {
  description = "Alias of the KMS key used to encrypt the EFS file system."
  value       = aws_kms_alias.efs_key_alias.name
}

output "vpc_id" {
  description = "ID of the VPC hosting the EFS mount targets."
  value       = aws_vpc.efs_vpc.id
}

output "subnet_ids" {
  description = "Subnet IDs where EFS mount targets are provisioned."
  value       = local.subnet_ids
}

output "efs_security_group_id" {
  description = "Security group attached to the EFS mount targets."
  value       = aws_security_group.efs_sg.id
}

output "efs_client_security_group_id" {
  description = "Security group to attach to compute that mounts the EFS file system."
  value       = aws_security_group.efs_client_sg.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "user_name" {
  description = "Name of the IAM user cert-manager uses for Route 53 DNS-01 validation."
  type        = string
  default     = "cert-manager"
}

# NOTE: The default of "*" is broad and grants access to all hosted zones.
# Override this with a specific hosted zone ID in production.
variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID that cert-manager may change. \"*\" means all zones."
  type        = string
  default     = "*"
}

variable "tags" {
  description = "Tags applied to every resource that supports tagging."
  type        = map(string)
  default = {
    ManagedBy   = "terraform"
    Application = "cert-manager"
  }
}

data "aws_partition" "current" {}

locals {
  route53_arn_prefix     = "arn:${data.aws_partition.current.partition}:route53:::"
  hosted_zone_arn        = "${local.route53_arn_prefix}hostedzone/${var.hosted_zone_id}"
  change_arn             = "${local.route53_arn_prefix}change/*"
  access_key_param_name  = "/cert-manager/access-key"
  secret_key_param_name  = "/cert-manager/secret-key"
}

resource "aws_iam_user" "cert_manager" {
  name          = var.user_name
  path          = "/"
  force_destroy = true
  tags          = var.tags
}

# No pgp_key is set so the secret can be passed straight to Parameter Store.
# The secret is still written to Terraform state, so the state must be stored
# encrypted with tightly restricted access.
resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_ssm_parameter" "access_key" {
  name        = local.access_key_param_name
  description = "IAM access key ID for the cert-manager Route 53 DNS-01 user"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.id
  tags        = var.tags
}

resource "aws_ssm_parameter" "secret_key" {
  name        = local.secret_key_param_name
  description = "IAM secret access key for the cert-manager Route 53 DNS-01 user"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.secret
  tags        = var.tags
}

data "aws_iam_policy_document" "cert_manager" {
  statement {
    sid       = "GetChange"
    effect    = "Allow"
    actions   = ["route53:GetChange"]
    resources = [local.change_arn]
  }

  statement {
    sid       = "ChangeResourceRecordSets"
    effect    = "Allow"
    actions   = ["route53:ChangeResourceRecordSets"]
    resources = [local.hosted_zone_arn]
  }

  statement {
    sid       = "ListResourceRecordSets"
    effect    = "Allow"
    actions   = ["route53:ListResourceRecordSets"]
    resources = [local.hosted_zone_arn]
  }

  statement {
    sid       = "ListHostedZonesByName"
    effect    = "Allow"
    actions   = ["route53:ListHostedZonesByName"]
    resources = ["*"]
  }
}

output "policy_json" {
  description = "IAM policy document JSON granting cert-manager Route 53 DNS-01 permissions (not attached)."
  value       = data.aws_iam_policy_document.cert_manager.json
}

output "user_name" {
  description = "Name of the cert-manager IAM user."
  value       = aws_iam_user.cert_manager.name
}

output "user_arn" {
  description = "ARN of the cert-manager IAM user."
  value       = aws_iam_user.cert_manager.arn
}

output "access_key_parameter_name" {
  description = "SSM Parameter Store name holding the access key ID."
  value       = aws_ssm_parameter.access_key.name
}

output "access_key_parameter_arn" {
  description = "SSM Parameter Store ARN holding the access key ID."
  value       = aws_ssm_parameter.access_key.arn
}

output "secret_key_parameter_name" {
  description = "SSM Parameter Store name holding the secret access key."
  value       = aws_ssm_parameter.secret_key.name
}

output "secret_key_parameter_arn" {
  description = "SSM Parameter Store ARN holding the secret access key."
  value       = aws_ssm_parameter.secret_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "name_prefix" {
  type        = string
  description = "Prefix applied to resource names created by this configuration."
  default     = "guardduty"
}

variable "replica_region" {
  type        = string
  description = "AWS region hosting the replica KMS key and replica S3 bucket."
  default     = "us-west-2"
}

variable "enable_guardduty" {
  type        = bool
  description = "Whether the primary GuardDuty detector is enabled."
  default     = true
}

variable "finding_publishing_frequency" {
  type        = string
  description = "Frequency of notifications sent for finding occurrences."
  default     = "FIFTEEN_MINUTES"

  validation {
    condition     = contains(["FIFTEEN_MINUTES", "ONE_HOUR", "SIX_HOURS"], var.finding_publishing_frequency)
    error_message = "finding_publishing_frequency must be one of FIFTEEN_MINUTES, ONE_HOUR or SIX_HOURS."
  }
}

variable "enable_s3_protection" {
  type        = bool
  description = "Enable GuardDuty S3 data event (S3 logs) protection."
  default     = true
}

variable "enable_kubernetes_protection" {
  type        = bool
  description = "Enable GuardDuty EKS audit log monitoring."
  default     = true
}

variable "enable_malware_protection" {
  type        = bool
  description = "Enable GuardDuty EC2 (EBS) malware protection scanning."
  default     = true
}

variable "enable_snapshot_retention" {
  type        = bool
  description = "Retain EBS snapshots when malware scanning produces a finding (RETENTION_WITH_FINDING) instead of NO_RETENTION."
  default     = false
}

variable "filter_config" {
  type = map(object({
    name        = string
    description = optional(string)
    rank        = number
    action      = string
    criterion = list(object({
      field                 = string
      equals                = optional(list(string))
      not_equals            = optional(list(string))
      greater_than          = optional(string)
      greater_than_or_equal = optional(string)
      less_than             = optional(string)
      less_than_or_equal    = optional(string)
    }))
  }))
  description = "Map of GuardDuty finding filters keyed by a unique identifier."
  default     = {}

  validation {
    condition     = alltrue([for f in values(var.filter_config) : contains(["ARCHIVE", "NOOP"], f.action)])
    error_message = "Each filter action must be ARCHIVE or NOOP."
  }
}

variable "ipset_config" {
  type = map(object({
    name     = string
    format   = optional(string, "TXT")
    activate = optional(bool, true)
    content  = optional(string)
    source   = optional(string)
  }))
  description = "Map of GuardDuty trusted IP sets. Each entry provides either inline content or a local source file path."
  default     = {}
}

variable "threatintelset_config" {
  type = map(object({
    name     = string
    format   = optional(string, "TXT")
    activate = optional(bool, true)
    content  = optional(string)
    source   = optional(string)
  }))
  description = "Map of GuardDuty threat intelligence sets. Each entry provides either inline content or a local source file path."
  default     = {}
}

variable "enable_s3_publishing" {
  type        = bool
  description = "Export GuardDuty findings to the KMS-encrypted primary S3 bucket."
  default     = false
}

variable "log_retention_days" {
  type        = number
  description = "Number of days to retain S3 server access logs in the log bucket."
  default     = 365
}

variable "tags" {
  type        = map(string)
  description = "Additional tags applied to all taggable resources."
  default     = {}
}

# -----------------------------------------------------------------------------
# Static provider metadata
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  create_s3_resources = length(var.ipset_config) > 0 || length(var.threatintelset_config) > 0 || var.enable_s3_publishing

  primary_bucket_name = "${var.name_prefix}-findings-${local.account_id}-${local.region}"
  log_bucket_name     = "${var.name_prefix}-access-logs-${local.account_id}-${local.region}"
  replica_bucket_name = "${var.name_prefix}-findings-${local.account_id}-${var.replica_region}"

  kms_alias_name        = "alias/${var.name_prefix}-findings"
  replication_role_name = "${var.name_prefix}-s3-replication-${local.region}"

  guardduty_service_principal = "guardduty.amazonaws.com"
  guardduty_slr_arn           = "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/guardduty.amazonaws.com/AWSServiceRoleForAmazonGuardDuty"

  snapshot_preservation = var.enable_snapshot_retention ? "RETENTION_WITH_FINDING" : "NO_RETENTION"

  common_tags = merge(
    {
      Project   = var.name_prefix
      ManagedBy = "terraform"
      Component = "guardduty"
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# GuardDuty detector and features
# -----------------------------------------------------------------------------

resource "aws_guardduty_detector" "primary" {
  enable                       = var.enable_guardduty
  finding_publishing_frequency = var.finding_publishing_frequency

  tags = local.common_tags
}

resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "S3_DATA_EVENTS"
  status      = var.enable_s3_protection ? "ENABLED" : "DISABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "EKS_AUDIT_LOGS"
  status      = var.enable_kubernetes_protection ? "ENABLED" : "DISABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.primary.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = var.enable_malware_protection ? "ENABLED" : "DISABLED"
}

resource "terraform_data" "malware_snapshot_retention" {
  triggers_replace = [
    aws_guardduty_detector.primary.id,
    var.enable_snapshot_retention,
  ]

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.primary.id} --ebs-snapshot-preservation ${local.snapshot_preservation} --region ${local.region}"
  }

  depends_on = [aws_guardduty_detector_feature.ebs_malware_protection]
}

# -----------------------------------------------------------------------------
# GuardDuty filters
# -----------------------------------------------------------------------------

resource "aws_guardduty_filter" "this" {
  for_each = var.filter_config

  detector_id = aws_guardduty_detector.primary.id
  name        = each.value.name
  description = each.value.description
  rank        = each.value.rank
  action      = each.value.action

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.criterion
      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than             = criterion.value.less_than
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# KMS (multi-region primary + replica)
# -----------------------------------------------------------------------------

resource "aws_kms_key" "guardduty" {
  count = local.create_s3_resources ? 1 : 0

  description             = "Multi-region KMS key for GuardDuty findings, IP sets and threat intel sets"
  multi_region            = true
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = local.common_tags
}

resource "aws_kms_alias" "guardduty" {
  count = local.create_s3_resources ? 1 : 0

  name          = local.kms_alias_name
  target_key_id = aws_kms_key.guardduty[0].key_id
}

data "aws_iam_policy_document" "kms_guardduty" {
  count = local.create_s3_resources ? 1 : 0

  statement {
    sid       = "EnableRootAccountPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowGuardDutyPublishingEncryption"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey", "kms:Encrypt"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.guardduty_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.primary.arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyServiceLinkedRoleDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:DescribeKey"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.guardduty_slr_arn]
    }
  }
}

resource "aws_kms_key_policy" "guardduty" {
  count = local.create_s3_resources ? 1 : 0

  key_id = aws_kms_key.guardduty[0].id
  policy = data.aws_iam_policy_document.kms_guardduty[0].json
}

resource "aws_kms_replica_key" "guardduty_replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  description             = "Replica of the GuardDuty findings multi-region KMS key"
  primary_key_arn         = aws_kms_key.guardduty[0].arn
  deletion_window_in_days = 7

  tags = local.common_tags
}

resource "aws_kms_alias" "guardduty_replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  name          = local.kms_alias_name
  target_key_id = aws_kms_replica_key.guardduty_replica[0].key_id
}

# -----------------------------------------------------------------------------
# Access log bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  bucket = local.log_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  bucket                  = aws_s3_bucket.log_bucket[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.log_bucket[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# S3 server access logging targets support SSE-S3 only.
resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    id     = "expire-access-logs"
    status = "Enabled"

    filter {}

    expiration {
      days = var.log_retention_days
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.log_bucket]
}

data "aws_iam_policy_document" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  statement {
    sid       = "AllowS3ServerAccessLogging"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.log_bucket[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.primary[0].arn]
    }
  }

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.log_bucket[0].arn,
      "${aws_s3_bucket.log_bucket[0].arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "log_bucket" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.log_bucket[0].id
  policy = data.aws_iam_policy_document.log_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.log_bucket]
}

# -----------------------------------------------------------------------------
# Primary bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  count = local.create_s3_resources ? 1 : 0

  bucket = local.primary_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  count = local.create_s3_resources ? 1 : 0

  bucket                  = aws_s3_bucket.primary[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "primary" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "primary" {
  count = local.create_s3_resources ? 1 : 0

  bucket        = aws_s3_bucket.primary[0].id
  target_bucket = aws_s3_bucket.log_bucket[0].id
  target_prefix = "${local.primary_bucket_name}/"

  depends_on = [aws_s3_bucket_policy.log_bucket]
}

data "aws_iam_policy_document" "primary_bucket" {
  count = local.create_s3_resources ? 1 : 0

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.primary[0].arn,
      "${aws_s3_bucket.primary[0].arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "AllowGuardDutyGetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.primary[0].arn]

    principals {
      type        = "Service"
      identifiers = [local.guardduty_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.primary.arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = [local.guardduty_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.primary.arn]
    }
  }

  statement {
    sid       = "DenyIncorrectEncryptionHeader"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = [local.guardduty_service_principal]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.guardduty[0].arn]
    }
  }

  statement {
    sid       = "DenyUnencryptedObjectUploads"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = [local.guardduty_service_principal]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  count = local.create_s3_resources ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id
  policy = data.aws_iam_policy_document.primary_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.primary]
}

# -----------------------------------------------------------------------------
# Replica bucket (replica region)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  bucket = local.replica_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_replica_key.guardduty_replica[0].arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "replica_bucket" {
  count = local.create_s3_resources ? 1 : 0

  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.replica[0].arn,
      "${aws_s3_bucket.replica[0].arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  count    = local.create_s3_resources ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id
  policy = data.aws_iam_policy_document.replica_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

# -----------------------------------------------------------------------------
# Replication IAM role and policy
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_s3_resources ? 1 : 0

  statement {
    sid     = "AllowS3AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_s3_resources ? 1 : 0

  name               = local.replication_role_name
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = local.common_tags
}

data "aws_iam_policy_document" "replication" {
  count = local.create_s3_resources ? 1 : 0

  statement {
    sid       = "SourceBucketConfiguration"
    effect    = "Allow"
    actions   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
    resources = [aws_s3_bucket.primary[0].arn]
  }

  statement {
    sid    = "SourceObjectVersions"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.primary[0].arn}/*"]
  }

  statement {
    sid    = "DestinationReplication"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }

  statement {
    sid       = "DecryptSourceObjects"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.guardduty[0].arn]

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }

  statement {
    sid       = "EncryptReplicaObjects"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:GenerateDataKey"]
    resources = [aws_kms_replica_key.guardduty_replica[0].arn]

    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.${var.replica_region}.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "replication" {
  count = local.create_s3_resources ? 1 : 0

  name        = "${local.replication_role_name}-policy"
  description = "Least-privilege policy for GuardDuty findings bucket cross-region replication"
  policy      = data.aws_iam_policy_document.replication[0].json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_s3_resources ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# -----------------------------------------------------------------------------
# Cross-region replication with RTC
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "primary" {
  count = local.create_s3_resources ? 1 : 0

  role   = aws_iam_role.replication[0].arn
  bucket = aws_s3_bucket.primary[0].id

  rule {
    id       = "replicate-to-${var.replica_region}"
    status   = "Enabled"
    priority = 1

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_replica_key.guardduty_replica[0].arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

# -----------------------------------------------------------------------------
# IP sets and threat intel sets
# -----------------------------------------------------------------------------

resource "aws_s3_object" "ipset" {
  for_each = var.ipset_config

  bucket                 = aws_s3_bucket.primary[0].id
  key                    = "ipset/${each.key}"
  content                = each.value.content
  source                 = each.value.source
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.guardduty[0].arn

  tags = local.common_tags

  depends_on = [aws_s3_bucket_server_side_encryption_configuration.primary]
}

resource "aws_s3_object" "threatintelset" {
  for_each = var.threatintelset_config

  bucket                 = aws_s3_bucket.primary[0].id
  key                    = "threatintelset/${each.key}"
  content                = each.value.content
  source                 = each.value.source
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.guardduty[0].arn

  tags = local.common_tags

  depends_on = [aws_s3_bucket_server_side_encryption_configuration.primary]
}

resource "aws_guardduty_ipset" "this" {
  for_each = var.ipset_config

  detector_id = aws_guardduty_detector.primary.id
  name        = each.value.name
  format      = each.value.format
  activate    = each.value.activate
  location    = "https://s3.amazonaws.com/${aws_s3_bucket.primary[0].id}/${aws_s3_object.ipset[each.key].key}"

  tags = local.common_tags

  depends_on = [aws_kms_key_policy.guardduty]
}

resource "aws_guardduty_threatintelset" "this" {
  for_each = var.threatintelset_config

  detector_id = aws_guardduty_detector.primary.id
  name        = each.value.name
  format      = each.value.format
  activate    = each.value.activate
  location    = "https://s3.amazonaws.com/${aws_s3_bucket.primary[0].id}/${aws_s3_object.threatintelset[each.key].key}"

  tags = local.common_tags

  depends_on = [aws_kms_key_policy.guardduty]
}

# -----------------------------------------------------------------------------
# Findings publishing destination
# -----------------------------------------------------------------------------

resource "aws_guardduty_publishing_destination" "s3" {
  count = var.enable_s3_publishing ? 1 : 0

  detector_id      = aws_guardduty_detector.primary.id
  destination_type = "S3"
  destination_arn  = aws_s3_bucket.primary[0].arn
  kms_key_arn      = aws_kms_key.guardduty[0].arn

  depends_on = [
    aws_s3_bucket_policy.primary,
    aws_kms_key_policy.guardduty,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "guardduty_detector_id" {
  description = "ID of the primary GuardDuty detector."
  value       = aws_guardduty_detector.primary.id
}

output "guardduty_detector_arn" {
  description = "ARN of the primary GuardDuty detector."
  value       = aws_guardduty_detector.primary.arn
}

output "ebs_snapshot_preservation" {
  description = "EBS snapshot preservation setting applied to malware scanning."
  value       = local.snapshot_preservation
}

output "kms_key_arn" {
  description = "ARN of the primary multi-region KMS key."
  value       = one(aws_kms_key.guardduty[*].arn)
}

output "kms_replica_key_arn" {
  description = "ARN of the replica KMS key in the replica region."
  value       = one(aws_kms_replica_key.guardduty_replica[*].arn)
}

output "primary_bucket_name" {
  description = "Name of the primary GuardDuty S3 bucket."
  value       = one(aws_s3_bucket.primary[*].id)
}

output "primary_bucket_arn" {
  description = "ARN of the primary GuardDuty S3 bucket."
  value       = one(aws_s3_bucket.primary[*].arn)
}

output "log_bucket_name" {
  description = "Name of the S3 access log bucket."
  value       = one(aws_s3_bucket.log_bucket[*].id)
}

output "replica_bucket_name" {
  description = "Name of the replica S3 bucket."
  value       = one(aws_s3_bucket.replica[*].id)
}

output "replica_bucket_arn" {
  description = "ARN of the replica S3 bucket."
  value       = one(aws_s3_bucket.replica[*].arn)
}

output "replication_role_arn" {
  description = "ARN of the S3 replication IAM role."
  value       = one(aws_iam_role.replication[*].arn)
}

output "filter_ids" {
  description = "Map of GuardDuty filter IDs keyed by filter_config key."
  value       = { for k, v in aws_guardduty_filter.this : k => v.id }
}

output "ipset_ids" {
  description = "Map of GuardDuty IP set IDs keyed by ipset_config key."
  value       = { for k, v in aws_guardduty_ipset.this : k => v.id }
}

output "threatintelset_ids" {
  description = "Map of GuardDuty threat intel set IDs keyed by threatintelset_config key."
  value       = { for k, v in aws_guardduty_threatintelset.this : k => v.id }
}

output "publishing_destination_id" {
  description = "ID of the GuardDuty S3 publishing destination."
  value       = one(aws_guardduty_publishing_destination.s3[*].id)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The provider "aws" block (region = "us-east-1") is injected by the
# deployment harness and is intentionally omitted here to avoid a duplicate
# provider configuration error.

variable "name_prefix" {
  description = "Prefix applied to the name of every IAM resource created for the EMR cluster."
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "Map of tags applied to every taggable resource for consistent tagging."
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  aws_managed_policy_prefix = "arn:${local.partition}:iam::aws:policy"

  emr_service_principal         = "elasticmapreduce.amazonaws.com"
  ec2_service_principal         = "ec2.amazonaws.com"
  app_autoscaling_service_principal = "application-autoscaling.amazonaws.com"

  common_tags = merge(var.tags, {
    "for-use-with-amazon-emr-managed-policies" = "true"
  })
}

# -----------------------------------------------------------------------------
# EMR service role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_service_assume_role" {
  statement {
    sid     = "EMRServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.emr_service_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "emr_service" {
  name               = "${var.name_prefix}-emr-service-role"
  description        = "Service role assumed by Amazon EMR to provision and manage cluster resources."
  assume_role_policy = data.aws_iam_policy_document.emr_service_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "emr_service_policy" {
  role       = aws_iam_role.emr_service.name
  policy_arn = "${local.aws_managed_policy_prefix}/service-role/AmazonEMRServicePolicy_v2"
}

# -----------------------------------------------------------------------------
# EMR EC2 instance role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ec2_service_principal]
    }
  }
}

resource "aws_iam_role" "emr_ec2" {
  name               = "${var.name_prefix}-emr-ec2-role"
  description        = "Role assumed by EC2 instances in the Amazon EMR cluster (CloudWatch and SSM access)."
  assume_role_policy = data.aws_iam_policy_document.emr_ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "emr_ec2_cloudwatch" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "${local.aws_managed_policy_prefix}/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_ssm" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "${local.aws_managed_policy_prefix}/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "emr_ec2" {
  name = "${var.name_prefix}-emr-ec2-instance-profile"
  role = aws_iam_role.emr_ec2.name
  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# EMR autoscaling role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "emr_autoscaling_assume_role" {
  statement {
    sid     = "EMRAutoScalingAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        local.emr_service_principal,
        local.app_autoscaling_service_principal,
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "emr_autoscaling" {
  name               = "${var.name_prefix}-emr-autoscaling-role"
  description        = "Role assumed by Amazon EMR and Application Auto Scaling to scale EMR cluster instance groups."
  assume_role_policy = data.aws_iam_policy_document.emr_autoscaling_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling_policy" {
  role       = aws_iam_role.emr_autoscaling.name
  policy_arn = "${local.aws_managed_policy_prefix}/service-role/AmazonElasticMapReduceforAutoScalingRole"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "emr_service_role_arn" {
  description = "ARN of the EMR service role."
  value       = aws_iam_role.emr_service.arn
}

output "emr_service_role_name" {
  description = "Name of the EMR service role."
  value       = aws_iam_role.emr_service.name
}

output "emr_service_role_unique_id" {
  description = "Unique ID of the EMR service role."
  value       = aws_iam_role.emr_service.unique_id
}

output "emr_ec2_role_arn" {
  description = "ARN of the EMR EC2 instance role."
  value       = aws_iam_role.emr_ec2.arn
}

output "emr_ec2_role_name" {
  description = "Name of the EMR EC2 instance role."
  value       = aws_iam_role.emr_ec2.name
}

output "emr_ec2_role_unique_id" {
  description = "Unique ID of the EMR EC2 instance role."
  value       = aws_iam_role.emr_ec2.unique_id
}

output "emr_autoscaling_role_arn" {
  description = "ARN of the EMR autoscaling role."
  value       = aws_iam_role.emr_autoscaling.arn
}

output "emr_autoscaling_role_name" {
  description = "Name of the EMR autoscaling role."
  value       = aws_iam_role.emr_autoscaling.name
}

output "emr_autoscaling_role_unique_id" {
  description = "Unique ID of the EMR autoscaling role."
  value       = aws_iam_role.emr_autoscaling.unique_id
}

output "emr_ec2_instance_profile_id" {
  description = "ID of the EMR EC2 instance profile."
  value       = aws_iam_instance_profile.emr_ec2.id
}

output "emr_ec2_instance_profile_arn" {
  description = "ARN of the EMR EC2 instance profile."
  value       = aws_iam_instance_profile.emr_ec2.arn
}

output "emr_ec2_instance_profile_name" {
  description = "Name of the EMR EC2 instance profile."
  value       = aws_iam_instance_profile.emr_ec2.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The aws provider (region = "us-east-1") is injected by the deployment
# harness. It is intentionally not declared here to avoid a duplicate provider
# configuration error.

variable "user_name" {
  description = "Name of the dedicated IAM user used for API integration testing and monitoring."
  type        = string
  default     = "postman-user"

  validation {
    condition     = can(regex("^[A-Za-z0-9+=,.@_-]{1,64}$", var.user_name))
    error_message = "user_name must be 1-64 characters and contain only alphanumerics and +=,.@_- characters."
  }
}

variable "cognito_user_pool_arn" {
  description = "Optional Cognito user pool ARN. A non-empty value turns on the Cognito AdminInitiateAuth policy scoped to this user pool."
  type        = string
  default     = ""

  validation {
    condition     = var.cognito_user_pool_arn == "" || can(regex("^arn:aws[a-zA-Z-]*:cognito-idp:[a-z0-9-]+:[0-9]{12}:userpool/.+$", var.cognito_user_pool_arn))
    error_message = "cognito_user_pool_arn must be an empty string or a valid Cognito user pool ARN (arn:aws:cognito-idp:<region>:<account-id>:userpool/<pool-id>)."
  }
}

variable "tags" {
  description = "Tags applied to every resource that supports tagging."
  type        = map(string)
  default = {
    Purpose   = "api-integration-testing"
    ManagedBy = "terraform"
  }
}

data "aws_partition" "current" {}

locals {
  create_cognito_policy = var.cognito_user_pool_arn != ""

  iam_path    = "/"
  secret_name = "${var.user_name}-access-key"

  apigateway_policy_name = "${var.user_name}-apigateway-read"
  cloudwatch_policy_name = "${var.user_name}-cloudwatch-metrics-read"
  cognito_policy_name    = "${var.user_name}-cognito-admin-auth"
}

resource "aws_iam_user" "postman_user" {
  name          = var.user_name
  path          = local.iam_path
  force_destroy = true

  tags = var.tags
}

resource "aws_iam_access_key" "postman_user" {
  user = aws_iam_user.postman_user.name
}

resource "aws_secretsmanager_secret" "postman_user_credentials" {
  name                    = local.secret_name
  description             = "Programmatic access credentials for IAM user ${var.user_name} (API integration testing and monitoring)."
  recovery_window_in_days = 0

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "postman_user_credentials" {
  secret_id = aws_secretsmanager_secret.postman_user_credentials.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.postman_user.id
    secret_access_key = aws_iam_access_key.postman_user.secret
  })
}

data "aws_iam_policy_document" "apigateway_read" {
  statement {
    sid     = "ApiGatewayReadOnly"
    effect  = "Allow"
    actions = ["apigateway:GET"]
    resources = [
      "arn:${data.aws_partition.current.partition}:apigateway:*::/*"
    ]
  }
}

resource "aws_iam_policy" "apigateway_read" {
  name        = local.apigateway_policy_name
  path        = local.iam_path
  description = "Read-only (GET) access to API Gateway resources for ${var.user_name}."
  policy      = data.aws_iam_policy_document.apigateway_read.json

  tags = var.tags
}

data "aws_iam_policy_document" "cloudwatch_metrics_read" {
  statement {
    sid    = "CloudWatchMetricsReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics"
    ]
    # These CloudWatch actions do not support resource-level permissions.
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cloudwatch_metrics_read" {
  name        = local.cloudwatch_policy_name
  path        = local.iam_path
  description = "Read-only access to CloudWatch metrics for ${var.user_name}."
  policy      = data.aws_iam_policy_document.cloudwatch_metrics_read.json

  tags = var.tags
}

resource "aws_iam_user_policy_attachment" "apigateway_read" {
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.apigateway_read.arn
}

resource "aws_iam_user_policy_attachment" "cloudwatch_metrics_read" {
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.cloudwatch_metrics_read.arn
}

data "aws_iam_policy_document" "cognito_admin_auth" {
  count = local.create_cognito_policy ? 1 : 0

  statement {
    sid       = "CognitoAdminInitiateAuth"
    effect    = "Allow"
    actions   = ["cognito-idp:AdminInitiateAuth"]
    resources = [var.cognito_user_pool_arn]
  }
}

resource "aws_iam_policy" "cognito_admin_auth" {
  count = local.create_cognito_policy ? 1 : 0

  name        = local.cognito_policy_name
  path        = local.iam_path
  description = "Allows ${var.user_name} to call cognito-idp:AdminInitiateAuth on the configured Cognito user pool."
  policy      = data.aws_iam_policy_document.cognito_admin_auth[0].json

  tags = var.tags
}

resource "aws_iam_user_policy_attachment" "cognito_admin_auth" {
  count = local.create_cognito_policy ? 1 : 0

  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.cognito_admin_auth[0].arn
}

output "iam_user_name" {
  description = "Name of the IAM user created for API integration testing and monitoring."
  value       = aws_iam_user.postman_user.name
}

output "iam_user_arn" {
  description = "ARN of the IAM user."
  value       = aws_iam_user.postman_user.arn
}

output "access_key_id" {
  description = "Access key ID for the IAM user."
  value       = aws_iam_access_key.postman_user.id
}

output "credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the access key ID and secret access key."
  value       = aws_secretsmanager_secret.postman_user_credentials.arn
}

output "apigateway_read_policy_arn" {
  description = "ARN of the API Gateway read-only policy."
  value       = aws_iam_policy.apigateway_read.arn
}

output "cloudwatch_metrics_read_policy_arn" {
  description = "ARN of the CloudWatch metrics read-only policy."
  value       = aws_iam_policy.cloudwatch_metrics_read.arn
}

output "cognito_admin_auth_policy_arn" {
  description = "ARN of the Cognito AdminInitiateAuth policy (null when cognito_user_pool_arn is empty)."
  value       = local.create_cognito_policy ? aws_iam_policy.cognito_admin_auth[0].arn : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster used to derive IAM resource names and autoscaling tag conditions."
  type        = string
  default     = "legion"
}

data "aws_partition" "current" {}

locals {
  name_prefix            = "tf-${var.cluster_name}"
  node_name              = "${local.name_prefix}-node"
  managed_policy_prefix  = "arn:${data.aws_partition.current.partition}:iam::aws:policy"
  cluster_ownership_tag  = "kubernetes.io/cluster/${var.cluster_name}"
  autoscaler_enabled_tag = "k8s.io/cluster-autoscaler/enabled"

  common_tags = {
    Cluster = var.cluster_name
  }
}

# -----------------------------------------------------------------------------
# EKS control plane (master) role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_master_assume_role" {
  statement {
    sid     = "EKSAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_master" {
  name               = local.name_prefix
  description        = "IAM role assumed by the EKS control plane for cluster ${var.cluster_name}."
  assume_role_policy = data.aws_iam_policy_document.eks_master_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_master_cluster_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "${local.managed_policy_prefix}/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_master_service_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "${local.managed_policy_prefix}/AmazonEKSServicePolicy"
}

# -----------------------------------------------------------------------------
# EKS worker node role and instance profile
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = local.node_name
  description        = "IAM role assumed by EKS worker nodes for cluster ${var.cluster_name}."
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_prefix}/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_prefix}/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr_read_only" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_prefix}/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "eks_node" {
  name = local.node_name
  role = aws_iam_role.eks_node.name
  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Cluster Autoscaler policy for worker nodes
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_worker_autoscaling" {
  statement {
    sid    = "EksWorkerAutoscalingAll"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "EksWorkerAutoscalingOwn"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/${local.cluster_ownership_tag}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/${local.autoscaler_enabled_tag}"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "eks_worker_autoscaling" {
  name_prefix = "eks-worker-autoscaling-${var.cluster_name}"
  description = "EKS worker node Cluster Autoscaler policy for cluster ${var.cluster_name}."
  policy      = data.aws_iam_policy_document.eks_worker_autoscaling.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_worker_autoscaling.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "eks_master_role_arn" {
  description = "ARN of the IAM role for the EKS control plane."
  value       = aws_iam_role.eks_master.arn
}

output "eks_node_role_arn" {
  description = "ARN of the IAM role for EKS worker nodes."
  value       = aws_iam_role.eks_node.arn
}

output "eks_node_instance_profile_name" {
  description = "Name of the EC2 instance profile for EKS worker nodes."
  value       = aws_iam_instance_profile.eks_node.name
}

output "eks_worker_autoscaling_policy_arn" {
  description = "ARN of the Cluster Autoscaler IAM policy attached to worker nodes."
  value       = aws_iam_policy.eks_worker_autoscaling.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "172.69.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr_block, 0))
    error_message = "vpc_cidr_block must be a valid IPv4 CIDR block."
  }
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet (must fall inside the VPC CIDR)."
  type        = string
  default     = "172.69.1.0/24"

  validation {
    condition     = can(cidrhost(var.public_subnet_cidr, 0))
    error_message = "public_subnet_cidr must be a valid IPv4 CIDR block."
  }
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet (must fall inside the VPC CIDR)."
  type        = string
  default     = "172.69.2.0/24"

  validation {
    condition     = can(cidrhost(var.private_subnet_cidr, 0))
    error_message = "private_subnet_cidr must be a valid IPv4 CIDR block."
  }
}

variable "vpc_name" {
  description = "Name tag for the VPC."
  type        = string
  default     = "vpc_name"
}

variable "public_subnet_tag" {
  description = "Name tag for the public subnet."
  type        = string
  default     = "public_subnet"
}

variable "private_subnet_tag" {
  description = "Name tag for the private subnet."
  type        = string
  default     = "private_subnet"
}

variable "igw_tag" {
  description = "Name tag for the internet gateway."
  type        = string
  default     = "igw_tag"
}

variable "rtb_tag" {
  description = "Name tag for the public route table."
  type        = string
  default     = "rtb_tag"
}

variable "web_sg_tag" {
  description = "Name tag for the web server security group."
  type        = string
  default     = "web-server_security_group"
}

variable "web_ingress_rules" {
  description = "Ingress rules applied to the web server security group."
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      description = "HTTP from anywhere"
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      description = "SSH from within the VPC"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    }
  ]
}

locals {
  any_ipv4_cidr = "0.0.0.0/0"
  tcp_protocol  = "tcp"
  mysql_port    = 3306
  az            = data.aws_availability_zones.available.names[0]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Internet-routable via the public route table. Public IPs are not assigned by
# subnet default; workloads request them per instance or via an Elastic IP.
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = {
    Name = var.public_subnet_tag
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = {
    Name = var.private_subnet_tag
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_tag
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = var.rtb_tag
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_server" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Security group for web servers"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.web_ingress_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    description = "All outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = var.web_sg_tag
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Security group for database servers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from web server security group"
    from_port       = local.mysql_port
    to_port         = local.mysql_port
    protocol        = local.tcp_protocol
    security_groups = [aws_security_group.web_server.id]
  }

  egress {
    description = "All outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "database-sg_${aws_vpc.main.id}"
  }

  lifecycle {
    create_before_destroy = true
  }
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet."
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "web_server_security_group_id" {
  description = "ID of the web server security group."
  value       = aws_security_group.web_server.id
}

output "database_security_group_id" {
  description = "ID of the database security group."
  value       = aws_security_group.database.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

variable "tags" {
  description = "Map of tags applied to all IAM resources created by this module."
  type        = map(string)
  default     = {}
}

locals {
  controlplane_name = "aws_ccm_k8s_controlplane"
  worker_name       = "aws_ccm_k8s_worker"
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "aws_ccm_k8s_controlplane" {
  name               = local.controlplane_name
  description        = "Kubernetes control-plane role for the AWS Cloud Controller Manager (CCM)."
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role" "aws_ccm_k8s_worker" {
  name               = local.worker_name
  description        = "Kubernetes worker node role for the AWS Cloud Controller Manager (CCM) and ECR image pulls."
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_instance_profile" "aws_ccm_k8s_controlplane" {
  name = local.controlplane_name
  role = aws_iam_role.aws_ccm_k8s_controlplane.name
  tags = var.tags
}

resource "aws_iam_instance_profile" "aws_ccm_k8s_worker" {
  name = local.worker_name
  role = aws_iam_role.aws_ccm_k8s_worker.name
  tags = var.tags
}

data "aws_iam_policy_document" "aws_ccm_k8s_controlplane" {
  statement {
    sid    = "AutoScalingDescribe"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EC2Networking"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeImages",
      "ec2:DescribeRegions",
      "ec2:DescribeRouteTables",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVolumes",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeVpcs",
      "ec2:CreateSecurityGroup",
      "ec2:CreateTags",
      "ec2:CreateVolume",
      "ec2:ModifyInstanceAttribute",
      "ec2:ModifyVolume",
      "ec2:AttachVolume",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:CreateRoute",
      "ec2:DeleteRoute",
      "ec2:DeleteSecurityGroup",
      "ec2:DeleteVolume",
      "ec2:DetachVolume",
      "ec2:RevokeSecurityGroupIngress",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ElasticLoadBalancing"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:AddTags",
      "elasticloadbalancing:ApplySecurityGroupsToLoadBalancer",
      "elasticloadbalancing:AttachLoadBalancerToSubnets",
      "elasticloadbalancing:ConfigureHealthCheck",
      "elasticloadbalancing:CreateListener",
      "elasticloadbalancing:CreateLoadBalancer",
      "elasticloadbalancing:CreateLoadBalancerListeners",
      "elasticloadbalancing:CreateLoadBalancerPolicy",
      "elasticloadbalancing:CreateTargetGroup",
      "elasticloadbalancing:DeleteListener",
      "elasticloadbalancing:DeleteLoadBalancer",
      "elasticloadbalancing:DeleteLoadBalancerListeners",
      "elasticloadbalancing:DeleteTargetGroup",
      "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
      "elasticloadbalancing:DeregisterTargets",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeLoadBalancerAttributes",
      "elasticloadbalancing:DescribeLoadBalancerPolicies",
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeTargetHealth",
      "elasticloadbalancing:DetachLoadBalancerFromSubnets",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:ModifyLoadBalancerAttributes",
      "elasticloadbalancing:ModifyTargetGroup",
      "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:SetLoadBalancerPoliciesForBackendServer",
      "elasticloadbalancing:SetLoadBalancerPoliciesOfListener",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "KMSDescribe"
    effect    = "Allow"
    actions   = ["kms:DescribeKey"]
    resources = ["*"]
  }

  statement {
    sid       = "ServiceLinkedRole"
    effect    = "Allow"
    actions   = ["iam:CreateServiceLinkedRole"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = ["elasticloadbalancing.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "aws_ccm_k8s_controlplane" {
  name        = local.controlplane_name
  description = "Permissions for the AWS Cloud Controller Manager running on Kubernetes control-plane nodes."
  policy      = data.aws_iam_policy_document.aws_ccm_k8s_controlplane.json
  tags        = var.tags
}

data "aws_iam_policy_document" "aws_ccm_k8s_worker" {
  statement {
    sid    = "EC2Describe"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ECRReadOnly"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetRepositoryPolicy",
      "ecr:DescribeRepositories",
      "ecr:ListImages",
      "ecr:DescribeImages",
      "ecr:BatchGetImage",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "aws_ccm_k8s_worker" {
  name        = local.worker_name
  description = "Permissions for Kubernetes worker nodes to describe EC2 instances/regions and pull images from ECR."
  policy      = data.aws_iam_policy_document.aws_ccm_k8s_worker.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "aws_ccm_k8s_controlplane" {
  role       = aws_iam_role.aws_ccm_k8s_controlplane.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_controlplane.arn
}

resource "aws_iam_role_policy_attachment" "aws_ccm_k8s_worker" {
  role       = aws_iam_role.aws_ccm_k8s_worker.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_worker.arn
}

output "controlplane_role_name" {
  description = "Name of the Kubernetes control-plane IAM role."
  value       = aws_iam_role.aws_ccm_k8s_controlplane.name
}

output "controlplane_role_arn" {
  description = "ARN of the Kubernetes control-plane IAM role."
  value       = aws_iam_role.aws_ccm_k8s_controlplane.arn
}

output "controlplane_instance_profile_name" {
  description = "Name of the Kubernetes control-plane EC2 instance profile."
  value       = aws_iam_instance_profile.aws_ccm_k8s_controlplane.name
}

output "controlplane_instance_profile_arn" {
  description = "ARN of the Kubernetes control-plane EC2 instance profile."
  value       = aws_iam_instance_profile.aws_ccm_k8s_controlplane.arn
}

output "controlplane_policy_arn" {
  description = "ARN of the Kubernetes control-plane CCM IAM policy."
  value       = aws_iam_policy.aws_ccm_k8s_controlplane.arn
}

output "worker_role_name" {
  description = "Name of the Kubernetes worker IAM role."
  value       = aws_iam_role.aws_ccm_k8s_worker.name
}

output "worker_role_arn" {
  description = "ARN of the Kubernetes worker IAM role."
  value       = aws_iam_role.aws_ccm_k8s_worker.arn
}

output "worker_instance_profile_name" {
  description = "Name of the Kubernetes worker EC2 instance profile."
  value       = aws_iam_instance_profile.aws_ccm_k8s_worker.name
}

output "worker_instance_profile_arn" {
  description = "ARN of the Kubernetes worker EC2 instance profile."
  value       = aws_iam_instance_profile.aws_ccm_k8s_worker.arn
}

output "worker_policy_arn" {
  description = "ARN of the Kubernetes worker CCM/ECR IAM policy."
  value       = aws_iam_policy.aws_ccm_k8s_worker.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Contact        = var.contact
      DeployedBy     = "terraform"
      DeploymentDate = var.deployment_date
      TTL            = "infinite"
    }
  }
}

variable "name" {
  description = "Prefix applied to every IAM resource name."
  type        = string
  default     = "awscademo-"
}

variable "contact" {
  description = "Contact tag value identifying the owner of these resources."
  type        = string
  default     = "cloud-team@example.com"
}

variable "deployment_date" {
  description = "Static deployment date tag value (YYYY-MM-DD)."
  type        = string
  default     = "2026-10-03"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  partition         = data.aws_partition.current.partition
  account_id        = data.aws_caller_identity.current.account_id
  iam_arn_prefix    = "arn:${local.partition}:iam::${local.account_id}"
  account_root_arn  = "${local.iam_arn_prefix}:root"
  self_user_arn     = "${local.iam_arn_prefix}:user/$${aws:username}"
  self_mfa_arn      = "${local.iam_arn_prefix}:mfa/$${aws:username}"
  mfa_condition_key = "aws:MultiFactorAuthPresent"
}

# -----------------------------------------------------------------------------
# Demo users group with self-management policy
# -----------------------------------------------------------------------------

resource "aws_iam_group" "demo_users" {
  name = "${var.name}demo-users"
}

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowChangeOwnPassword"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "AllowManageOwnSSHPublicKeys"
    effect = "Allow"
    actions = [
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:UploadSSHPublicKey",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [local.self_mfa_arn]
  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "AllowDeactivateOwnUserMFAOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = [local.self_user_arn]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_key
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${var.name}self-management"
  description = "Allows users to manage their own password, access keys, SSH public keys and virtual MFA devices."
  policy      = data.aws_iam_policy_document.self_management.json
}

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

# -----------------------------------------------------------------------------
# Read-only users group
# -----------------------------------------------------------------------------

resource "aws_iam_group" "read_only_users" {
  name = "${var.name}read-only-users"
}

resource "aws_iam_group_policy_attachment" "read_only_users_readonly" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/ReadOnlyAccess"
}

# -----------------------------------------------------------------------------
# MFA superadmin group and administrative role
# -----------------------------------------------------------------------------

resource "aws_iam_group" "mfa_superadmins" {
  name = "${var.name}mfa-superadmins"
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    condition {
      test     = "Bool"
      variable = local.mfa_condition_key
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name_prefix          = substr("${var.name}admin-", 0, 31)
  description          = "Administrative role assumable by account principals with MFA."
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
  max_session_duration = 43200
}

data "aws_iam_policy_document" "admin" {
  statement {
    sid       = "AllowFullAdminWithMFA"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_key
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin" {
  name        = "${var.name}admin"
  description = "Full administrator permissions, conditioned on MFA presence."
  policy      = data.aws_iam_policy_document.admin.json
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin.arn
}

data "aws_iam_policy_document" "mfa_superadmins_assume_admin" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = local.mfa_condition_key
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "mfa_superadmins_assume_admin" {
  name   = "${var.name}assume-admin"
  group  = aws_iam_group.mfa_superadmins.name
  policy = data.aws_iam_policy_document.mfa_superadmins_assume_admin.json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "admin_role_arn" {
  description = "ARN of the MFA-protected administrative role."
  value       = aws_iam_role.admin.arn
}

output "demo_users_group_name" {
  description = "Name of the demo users IAM group."
  value       = aws_iam_group.demo_users.name
}

output "read_only_users_group_name" {
  description = "Name of the read-only users IAM group."
  value       = aws_iam_group.read_only_users.name
}

output "mfa_superadmins_group_name" {
  description = "Name of the MFA superadmins IAM group."
  value       = aws_iam_group.mfa_superadmins.name
}

# Region (us-east-1) is set by the provider configuration that the deployment harness
# injects, so this file has no provider block and no backend block.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Tags applied to every taggable resource in this stack."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Stack     = "iam-access-management"
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  admin_name                 = "admin"
  admin_path                 = "/admin/"
  admin_macbook_pro_name     = "admin-macbook-pro"
  admin_terraform_cloud_name = "admin-terraform-cloud"
  admin_terraform_cloud_path = "/admin_terraform_cloud/"
  github_name                = "github"
  github_path                = "/github/"
  serverless_name            = "serverless"
  serverless_path            = "/serverless/"

  secrets_path_prefix = "iam/"
  kms_alias_name      = "alias/iam-access-keys"

  lambda_service_principals = [
    "lambda.amazonaws.com",
    "edgelambda.amazonaws.com",
  ]

  serverless_role_arn_pattern = "arn:${local.partition}:iam::${local.account_id}:role${local.serverless_path}*"
  acm_certificate_arn_pattern = "arn:${local.partition}:acm:*:${local.account_id}:certificate/*"
  cloudfront_distribution_arn = "arn:${local.partition}:cloudfront::${local.account_id}:distribution/*"
  lambda_function_arn_pattern = "arn:${local.partition}:lambda:*:${local.account_id}:function:*"
  route53_hosted_zone_arn     = "arn:${local.partition}:route53:::hostedzone/*"
  route53_change_arn          = "arn:${local.partition}:route53:::change/*"
  sqs_queue_arn_pattern       = "arn:${local.partition}:sqs:*:${local.account_id}:*"
  logs_log_group_arn_pattern  = "arn:${local.partition}:logs:*:${local.account_id}:log-group:*"

  # Deployment buckets created by the Serverless Framework and by CI pipelines.
  s3_bucket_arns = [
    "arn:${local.partition}:s3:::*-serverlessdeploymentbucket-*",
    "arn:${local.partition}:s3:::serverless-*",
  ]
  s3_object_arns = [
    "arn:${local.partition}:s3:::*-serverlessdeploymentbucket-*/*",
    "arn:${local.partition}:s3:::serverless-*/*",
  ]
}

# -----------------------------------------------------------------------------
# IAM Groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "admin" {
  name = local.admin_name
  path = local.admin_path
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = local.admin_terraform_cloud_name
  path = local.admin_terraform_cloud_path
}

resource "aws_iam_group" "github" {
  name = local.github_name
  path = local.github_path
}

resource "aws_iam_group" "serverless" {
  name = local.serverless_name
  path = local.serverless_path
}

# -----------------------------------------------------------------------------
# Admin group inline policies (explicit full-admin exceptions)
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy" "admin" {
  name  = local.admin_name
  group = aws_iam_group.admin.name

  # JUSTIFIED EXCEPTION TO LEAST PRIVILEGE: the request explicitly asks for full
  # administrative rights for break-glass and human administrator access. Only
  # the named admin users belong to this group.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdministrativeAccess"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name  = local.admin_terraform_cloud_name
  group = aws_iam_group.admin_terraform_cloud.name

  # JUSTIFIED EXCEPTION TO LEAST PRIVILEGE: the Terraform Cloud workspace must
  # manage arbitrary account infrastructure, so it needs full administrative
  # rights. Only the dedicated Terraform Cloud user belongs to this group.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdministrativeAccess"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# GitHub deployment policy document
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "github" {
  # ACM
  statement {
    sid    = "AcmManageCertificates"
    effect = "Allow"
    actions = [
      "acm:AddTagsToCertificate",
      "acm:DeleteCertificate",
      "acm:DescribeCertificate",
      "acm:ListTagsForCertificate",
    ]
    resources = [local.acm_certificate_arn_pattern]
  }

  statement {
    sid    = "AcmRequestAndList"
    effect = "Allow"
    actions = [
      "acm:ListCertificates",
      "acm:RequestCertificate",
    ]
    # These ACM actions do not support resource-level permissions.
    resources = ["*"]
  }

  # CloudFront
  statement {
    sid    = "CloudFrontManageDistributions"
    effect = "Allow"
    actions = [
      "cloudfront:CreateDistribution",
      "cloudfront:CreateInvalidation",
      "cloudfront:DeleteDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:GetDistributionConfig",
      "cloudfront:GetInvalidation",
      "cloudfront:ListTagsForResource",
      "cloudfront:TagResource",
      "cloudfront:UntagResource",
      "cloudfront:UpdateDistribution",
    ]
    resources = [local.cloudfront_distribution_arn]
  }

  statement {
    sid    = "CloudFrontList"
    effect = "Allow"
    actions = [
      "cloudfront:ListDistributions",
    ]
    # ListDistributions does not support resource-level permissions.
    resources = ["*"]
  }

  # IAM (scoped to roles under /serverless/)
  statement {
    sid    = "IamManageServerlessRoles"
    effect = "Allow"
    actions = [
      "iam:AttachRolePolicy",
      "iam:CreateRole",
      "iam:DeleteRole",
      "iam:DeleteRolePolicy",
      "iam:DetachRolePolicy",
      "iam:GetRole",
      "iam:GetRolePolicy",
      "iam:ListAttachedRolePolicies",
      "iam:ListRolePolicies",
      "iam:PutRolePolicy",
      "iam:TagRole",
      "iam:UntagRole",
    ]
    resources = [local.serverless_role_arn_pattern]
  }

  statement {
    sid       = "IamPassServerlessRoleToLambda"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [local.serverless_role_arn_pattern]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = local.lambda_service_principals
    }
  }

  # Lambda
  statement {
    sid    = "LambdaManageFunctions"
    effect = "Allow"
    actions = [
      "lambda:AddPermission",
      "lambda:CreateAlias",
      "lambda:CreateFunction",
      "lambda:DeleteAlias",
      "lambda:DeleteFunction",
      "lambda:EnableReplication*",
      "lambda:GetAlias",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:GetPolicy",
      "lambda:ListTags",
      "lambda:ListVersionsByFunction",
      "lambda:PublishVersion",
      "lambda:RemovePermission",
      "lambda:TagResource",
      "lambda:UntagResource",
      "lambda:UpdateAlias",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
    ]
    resources = [local.lambda_function_arn_pattern]
  }

  statement {
    sid    = "LambdaList"
    effect = "Allow"
    actions = [
      "lambda:ListFunctions",
    ]
    # ListFunctions does not support resource-level permissions.
    resources = ["*"]
  }

  # Route53
  statement {
    sid    = "Route53ManageRecords"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:GetHostedZone",
      "route53:ListResourceRecordSets",
    ]
    resources = [local.route53_hosted_zone_arn]
  }

  statement {
    sid       = "Route53GetChange"
    effect    = "Allow"
    actions   = ["route53:GetChange"]
    resources = [local.route53_change_arn]
  }

  statement {
    sid    = "Route53List"
    effect = "Allow"
    actions = [
      "route53:ListHostedZones",
      "route53:ListHostedZonesByName",
    ]
    # These Route53 list actions do not support resource-level permissions.
    resources = ["*"]
  }

  # S3
  statement {
    sid    = "S3ManageDeploymentBuckets"
    effect = "Allow"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:DeleteBucketPolicy",
      "s3:GetBucketLocation",
      "s3:GetBucketPolicy",
      "s3:GetBucketVersioning",
      "s3:GetEncryptionConfiguration",
      "s3:ListBucket",
      "s3:PutBucketPolicy",
      "s3:PutBucketPublicAccessBlock",
      "s3:PutBucketTagging",
      "s3:PutBucketVersioning",
      "s3:PutEncryptionConfiguration",
    ]
    resources = local.s3_bucket_arns
  }

  statement {
    sid    = "S3ManageDeploymentObjects"
    effect = "Allow"
    actions = [
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = local.s3_object_arns
  }

  statement {
    sid    = "S3ListAllBuckets"
    effect = "Allow"
    actions = [
      "s3:ListAllMyBuckets",
    ]
    # ListAllMyBuckets does not support resource-level permissions.
    resources = ["*"]
  }

  # SQS
  statement {
    sid    = "SqsManageQueues"
    effect = "Allow"
    actions = [
      "sqs:CreateQueue",
      "sqs:DeleteQueue",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:ListQueueTags",
      "sqs:SetQueueAttributes",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = [local.sqs_queue_arn_pattern]
  }

  statement {
    sid    = "SqsList"
    effect = "Allow"
    actions = [
      "sqs:ListQueues",
    ]
    # ListQueues does not support resource-level permissions.
    resources = ["*"]
  }
}

resource "aws_iam_group_policy" "github" {
  name   = local.github_name
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github.json
}

# -----------------------------------------------------------------------------
# Serverless policy document (single source of truth for every serverless
# attachment). It reuses the exact ACM/CloudFront/IAM/Lambda/Route53/S3/SQS
# statements from the github document and adds CloudWatch Logs.
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "serverless" {
  source_policy_documents = [data.aws_iam_policy_document.github.json]

  statement {
    sid    = "LogsManageLogGroups"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DeleteLogGroup",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
      "logs:PutRetentionPolicy",
    ]
    resources = [local.logs_log_group_arn_pattern]
  }

  statement {
    sid    = "LogsDescribeLogGroups"
    effect = "Allow"
    actions = [
      "logs:DescribeLogGroups",
    ]
    # DescribeLogGroups does not support resource-level permissions.
    resources = ["*"]
  }
}

resource "aws_iam_group_policy" "serverless" {
  name   = local.serverless_name
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless.json
}

# -----------------------------------------------------------------------------
# IAM Users
# -----------------------------------------------------------------------------

resource "aws_iam_user" "admin" {
  name = local.admin_name
  path = local.admin_path
  tags = var.tags
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = local.admin_macbook_pro_name
  path = local.admin_path
  tags = var.tags
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = local.admin_terraform_cloud_name
  path = local.admin_terraform_cloud_path
  tags = var.tags
}

resource "aws_iam_user" "github" {
  name = local.github_name
  path = local.github_path
  tags = var.tags
}

resource "aws_iam_user" "serverless" {
  name = local.serverless_name
  path = local.serverless_path
  tags = var.tags
}

# -----------------------------------------------------------------------------
# Group memberships (one per user)
# -----------------------------------------------------------------------------

resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_macbook_pro" {
  user   = aws_iam_user.admin_macbook_pro.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_terraform_cloud" {
  user   = aws_iam_user.admin_terraform_cloud.name
  groups = [aws_iam_group.admin_terraform_cloud.name]
}

resource "aws_iam_user_group_membership" "github" {
  user   = aws_iam_user.github.name
  groups = [aws_iam_group.github.name]
}

resource "aws_iam_user_group_membership" "serverless" {
  user   = aws_iam_user.serverless.name
  groups = [aws_iam_group.serverless.name]
}

# -----------------------------------------------------------------------------
# Access keys
# -----------------------------------------------------------------------------

resource "aws_iam_access_key" "admin_macbook_pro" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

# -----------------------------------------------------------------------------
# KMS key for credential secrets
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "iam_access_keys_kms" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "iam_access_keys" {
  description             = "Encrypts Secrets Manager secrets that hold IAM user access keys."
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.iam_access_keys_kms.json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "iam_access_keys" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.iam_access_keys.key_id
}

# -----------------------------------------------------------------------------
# Secrets Manager storage for access keys
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "admin_macbook_pro_access_key" {
  name                    = "${local.secrets_path_prefix}${local.admin_macbook_pro_name}-access-key"
  description             = "Access key for IAM user ${local.admin_macbook_pro_name}."
  kms_key_id              = aws_kms_key.iam_access_keys.arn
  recovery_window_in_days = 7
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin_macbook_pro_access_key" {
  secret_id = aws_secretsmanager_secret.admin_macbook_pro_access_key.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_macbook_pro.id
    secret_access_key = aws_iam_access_key.admin_macbook_pro.secret
  })
}

resource "aws_secretsmanager_secret" "admin_terraform_cloud_access_key" {
  name                    = "${local.secrets_path_prefix}${local.admin_terraform_cloud_name}-access-key"
  description             = "Access key for IAM user ${local.admin_terraform_cloud_name}."
  kms_key_id              = aws_kms_key.iam_access_keys.arn
  recovery_window_in_days = 7
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin_terraform_cloud_access_key" {
  secret_id = aws_secretsmanager_secret.admin_terraform_cloud_access_key.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_terraform_cloud.id
    secret_access_key = aws_iam_access_key.admin_terraform_cloud.secret
  })
}

# -----------------------------------------------------------------------------
# Serverless execution role and customer managed policy
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "serverless_assume_role" {
  statement {
    sid     = "AllowLambdaAndEdgeLambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = local.lambda_service_principals
    }
  }
}

resource "aws_iam_role" "serverless" {
  name               = local.serverless_name
  path               = local.serverless_path
  assume_role_policy = data.aws_iam_policy_document.serverless_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "serverless" {
  name        = local.serverless_name
  path        = local.serverless_path
  description = "Serverless deployment permissions (identical to the serverless group inline policy)."
  policy      = data.aws_iam_policy_document.serverless.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

# -----------------------------------------------------------------------------
# Outputs (non-sensitive only; access key secrets are never output)
# -----------------------------------------------------------------------------

output "group_arns" {
  description = "ARNs of the IAM groups."
  value = {
    admin                 = aws_iam_group.admin.arn
    admin_terraform_cloud = aws_iam_group.admin_terraform_cloud.arn
    github                = aws_iam_group.github.arn
    serverless            = aws_iam_group.serverless.arn
  }
}

output "user_arns" {
  description = "ARNs of the IAM users."
  value = {
    admin                 = aws_iam_user.admin.arn
    admin_macbook_pro     = aws_iam_user.admin_macbook_pro.arn
    admin_terraform_cloud = aws_iam_user.admin_terraform_cloud.arn
    github                = aws_iam_user.github.arn
    serverless            = aws_iam_user.serverless.arn
  }
}

output "serverless_role_arn" {
  description = "ARN of the serverless IAM role."
  value       = aws_iam_role.serverless.arn
}

output "serverless_policy_arn" {
  description = "ARN of the serverless customer managed policy."
  value       = aws_iam_policy.serverless.arn
}

output "access_key_ids" {
  description = "Access key IDs (not secrets) for users with programmatic access."
  value = {
    admin_macbook_pro     = aws_iam_access_key.admin_macbook_pro.id
    admin_terraform_cloud = aws_iam_access_key.admin_terraform_cloud.id
  }
}

output "access_key_secret_arns" {
  description = "ARNs of the Secrets Manager secrets that hold the access key credentials."
  value = {
    admin_macbook_pro     = aws_secretsmanager_secret.admin_macbook_pro_access_key.arn
    admin_terraform_cloud = aws_secretsmanager_secret.admin_terraform_cloud_access_key.arn
  }
}

output "iam_access_keys_kms_key_arn" {
  description = "ARN of the KMS key that encrypts the access key secrets."
  value       = aws_kms_key.iam_access_keys.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The AWS provider configuration (region = "us-east-1") is injected by the
# deployment harness. A provider block is intentionally omitted here to avoid a
# duplicate provider configuration error.

################################################################################
# Data Sources (caller identity / static provider metadata only)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

################################################################################
# Variables
################################################################################

variable "namespace" {
  description = "Namespace, which could be your organization name or abbreviation (CloudPosse label)."
  type        = string
  default     = "eg"
}

variable "environment" {
  description = "Environment, e.g. 'prod', 'staging', 'dev' (CloudPosse label)."
  type        = string
  default     = "prod"
}

variable "name" {
  description = "Solution name, e.g. 'iam' (CloudPosse label)."
  type        = string
  default     = "iam"
}

variable "attributes" {
  description = "Additional attributes to append to the label ID (CloudPosse label)."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources (CloudPosse label)."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "mfa-enforced-iam-access"
  }
}

variable "admin_user_names" {
  description = "List of IAM user names to create and add to the admin group."
  type        = list(string)
  default     = ["example-admin-user"]
}

variable "non_admin_user_names" {
  description = "List of IAM user names to create and add to the non-admin group."
  type        = list(string)
  default     = ["example-standard-user"]
}

################################################################################
# Locals
################################################################################

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  account_root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"
  self_user_arn      = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
  self_mfa_arn       = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
  admin_access_arn   = "arn:${local.partition}:iam::aws:policy/AdministratorAccess"
  mfa_condition_test = "Bool"
  mfa_condition_key  = "aws:MultiFactorAuthPresent"
  group_path         = "/"
}

################################################################################
# CloudPosse Labels
################################################################################

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = var.attributes
  tags        = var.tags
}

module "admin_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context    = module.label.context
  attributes = ["admin"]
}

module "non_admin_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context    = module.label.context
  attributes = ["non", "admin"]
}

################################################################################
# IAM Groups
################################################################################

resource "aws_iam_group" "admin" {
  name = module.admin_label.id
  path = local.group_path
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_label.id
  path = local.group_path
}

################################################################################
# Self-Management Policy (attached to both groups)
################################################################################

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListVirtualMFADevices",
    ]
    # These account-level List/Get actions do not support resource-level permissions.
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:GetLoginProfile",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:GetAccessKeyLastUsed",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [local.self_mfa_arn]
  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = [local.self_user_arn]
  }

  statement {
    sid    = "AllowDeactivateOwnMFAOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = [
      local.self_user_arn,
      local.self_mfa_arn,
    ]

    condition {
      test     = local.mfa_condition_test
      variable = local.mfa_condition_key
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.label.id}-self-management"
  description = "Allows users to manage their own password, access keys and virtual MFA device; deactivating MFA requires an active MFA session."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.label.tags
}

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

################################################################################
# Admin Role (MFA-protected trust policy)
################################################################################

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid     = "AllowAccountPrincipalsWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    condition {
      test     = local.mfa_condition_test
      variable = local.mfa_condition_key
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = module.admin_label.id
  description          = "Administrative role assumable only by account principals authenticated with MFA."
  assume_role_policy   = data.aws_iam_policy_document.admin_role_trust.json
  max_session_duration = 3600
  tags                 = module.admin_label.tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = local.admin_access_arn
}

################################################################################
# Assume Admin Role Policy (admin group only)
################################################################################

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = local.mfa_condition_test
      variable = local.mfa_condition_key
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = "${module.admin_label.id}-assume-role"
  description = "Allows admin group members to assume the admin role when MFA is present."
  policy      = data.aws_iam_policy_document.assume_admin_role.json
  tags        = module.admin_label.tags
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

################################################################################
# IAM Users (greenfield: all listed users are created here)
################################################################################

resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_user_names)

  name = each.value
  path = local.group_path
  tags = module.admin_label.tags
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_user_names)

  name = each.value
  path = local.group_path
  tags = module.non_admin_label.tags
}

################################################################################
# Group Memberships (conditional on non-empty user lists)
################################################################################

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_user_names) > 0 ? 1 : 0

  name  = "${module.admin_label.id}-membership"
  group = aws_iam_group.admin.name
  users = [for user in aws_iam_user.admin : user.name]
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(var.non_admin_user_names) > 0 ? 1 : 0

  name  = "${module.non_admin_label.id}-membership"
  group = aws_iam_group.non_admin.name
  users = [for user in aws_iam_user.non_admin : user.name]
}

################################################################################
# Outputs
################################################################################

output "admin_group_name" {
  description = "Name of the admin IAM group."
  value       = aws_iam_group.admin.name
}

output "admin_group_arn" {
  description = "ARN of the admin IAM group."
  value       = aws_iam_group.admin.arn
}

output "non_admin_group_name" {
  description = "Name of the non-admin IAM group."
  value       = aws_iam_group.non_admin.name
}

output "non_admin_group_arn" {
  description = "ARN of the non-admin IAM group."
  value       = aws_iam_group.non_admin.arn
}

output "admin_role_name" {
  description = "Name of the MFA-protected admin role."
  value       = aws_iam_role.admin.name
}

output "admin_role_arn" {
  description = "ARN of the MFA-protected admin role."
  value       = aws_iam_role.admin.arn
}

output "self_management_policy_arn" {
  description = "ARN of the self-management IAM policy."
  value       = aws_iam_policy.self_management.arn
}

output "assume_admin_role_policy_arn" {
  description = "ARN of the policy allowing the admin group to assume the admin role."
  value       = aws_iam_policy.assume_admin_role.arn
}

output "admin_user_names" {
  description = "Names of the IAM users in the admin group."
  value       = [for user in aws_iam_user.admin : user.name]
}

output "non_admin_user_names" {
  description = "Names of the IAM users in the non-admin group."
  value       = [for user in aws_iam_user.non_admin : user.name]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The provider "aws" block (region = "us-east-1") is intentionally omitted.
# The deployment harness injects the provider configuration, and declaring a
# second default provider block would cause a duplicate-provider error.
# Tags are applied on each resource via local.common_tags.

variable "environment" {
  description = "Deployment environment name, used only for naming and tagging."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name, used only for naming and tagging."
  type        = string
  default     = "multi-tier-net"
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  name_prefix = "${var.project_name}-${var.environment}"
  any_ipv4    = "0.0.0.0/0"

  common_tags = {
    Environment = var.environment
    Project     = var.project_name
    ManagedBy   = "terraform"
  }

  az_names = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]

  # Public subnets: 10.0.0.0/24, 10.0.1.0/24
  public_subnet_cidrs = [for i in range(2) : cidrsubnet(local.vpc_cidr, 8, i)]

  # Private subnets: 10.0.10.0/24 .. 10.0.13.0/24 (two per AZ)
  private_subnet_cidrs = [for i in range(4) : cidrsubnet(local.vpc_cidr, 8, i + 10)]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# Lock down the default security group so it permits no traffic.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default-sg-restricted"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 4

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.az_names[count.index % 2]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table has no explicit routes; only the implicit local VPC route.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 4

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "public" {
  name_prefix = "${local.name_prefix}-public-"
  description = "Public tier: all traffic and SSH from VPC, HTTP from anywhere, egress to VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.any_ipv4]
  }

  egress {
    description = "All outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "private" {
  name_prefix = "${local.name_prefix}-private-"
  description = "Private tier: all traffic from VPC, egress to VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "availability_zones" {
  description = "Availability zones used by the stack."
  value       = local.az_names
}

output "public_subnet_ids" {
  description = "IDs of the public subnets (one per AZ)."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (two per AZ)."
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table."
  value       = aws_route_table.private.id
}

output "public_security_group_id" {
  description = "ID of the public security group."
  value       = aws_security_group.public.id
}

output "private_security_group_id" {
  description = "ID of the private security group."
  value       = aws_security_group.private.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The deployment harness injects the provider "aws" block, configured
# with region = "us-east-1". It is left out here so the provider is not
# declared twice. Tags are applied through local.tags rather than
# provider default_tags.

variable "name_suffix" {
  description = "Suffix appended to every resource name. Leave empty for the default names, e.g. prod-ci-role."
  type        = string
  default     = ""
}

locals {
  name_prefix = "prod-ci-"

  tags = {
    Environment = "prod"
    Stack       = "ci-cd-iam"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

# Trust policy: the principal is a wildcard, as requested. The condition
# limits it to identities in this AWS account.
data "aws_iam_policy_document" "ci_trust" {
  statement {
    sid     = "AllowAssumeRoleFromSameAccount"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

# This role has no permission policies attached. Its workload permissions
# are managed outside this configuration.
resource "aws_iam_role" "ci_role" {
  name                 = "${local.name_prefix}role${var.name_suffix}"
  description          = "Prod CI/CD deployment role assumed by the CI pipeline identity"
  assume_role_policy   = data.aws_iam_policy_document.ci_trust.json
  max_session_duration = 3600

  tags = local.tags
}

data "aws_iam_policy_document" "ci_assume_role" {
  statement {
    sid       = "AllowAssumeProdCiRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.ci_role.arn]
  }
}

resource "aws_iam_policy" "ci_assume_role" {
  name        = "${local.name_prefix}assume-role-policy${var.name_suffix}"
  description = "Allows members to assume the prod CI/CD deployment role"
  policy      = data.aws_iam_policy_document.ci_assume_role.json

  tags = local.tags
}

resource "aws_iam_group" "ci_group" {
  name = "${local.name_prefix}group${var.name_suffix}"
  path = "/"
}

resource "aws_iam_group_policy_attachment" "ci_group_assume_role" {
  group      = aws_iam_group.ci_group.name
  policy_arn = aws_iam_policy.ci_assume_role.arn
}

# This user gets all of its permissions from group membership. No access
# keys or login profile are created, so no credentials are stored in
# Terraform state. If access keys are needed later, store them in
# aws_secretsmanager_secret and aws_secretsmanager_secret_version.
resource "aws_iam_user" "ci_user" {
  name          = "${local.name_prefix}user${var.name_suffix}"
  path          = "/"
  force_destroy = false

  tags = merge(local.tags, {
    Purpose      = "ci-cd-service-identity"
    IdentityType = "service"
  })
}

resource "aws_iam_user_group_membership" "ci_user_membership" {
  user   = aws_iam_user.ci_user.name
  groups = [aws_iam_group.ci_group.name]
}

output "ci_role_arn" {
  description = "ARN of the prod CI/CD deployment role"
  value       = aws_iam_role.ci_role.arn
}

output "ci_role_name" {
  description = "Name of the prod CI/CD deployment role"
  value       = aws_iam_role.ci_role.name
}

output "ci_assume_role_policy_arn" {
  description = "ARN of the policy that allows assuming the prod CI/CD role"
  value       = aws_iam_policy.ci_assume_role.arn
}

output "ci_group_name" {
  description = "Name of the CI/CD IAM group"
  value       = aws_iam_group.ci_group.name
}

output "ci_user_name" {
  description = "Name of the CI/CD IAM user"
  value       = aws_iam_user.ci_user.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Default tags applied to all taggable resources via the provider default_tags."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
  }
}

locals {
  aggregator_name = "default"

  default_tags = merge(
    {
      ManagedBy = "Terraform"
    },
    var.tags
  )
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.default_tags
  }
}

data "aws_caller_identity" "current" {}

resource "aws_config_configuration_aggregator" "default" {
  name = local.aggregator_name

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }
}

output "config_aggregator_arn" {
  description = "ARN of the AWS Config configuration aggregator."
  value       = aws_config_configuration_aggregator.default.arn
}

output "config_aggregator_name" {
  description = "Name of the AWS Config configuration aggregator."
  value       = aws_config_configuration_aggregator.default.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = merge(var.tags, {
      ManagedBy = "terraform"
    })
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "vpc_name" {
  description = "Name of the VPC, used as a prefix for all resource Name tags."
  type        = string
  default     = "benchmark-vpc"
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

variable "ssh_inbound" {
  description = "CIDR ranges allowed to reach the public tier over SSH (TCP 22)."
  type        = list(string)
  default     = ["10.0.0.0/16"]

  validation {
    condition     = length(var.ssh_inbound) <= 50 && alltrue([for c in var.ssh_inbound : can(cidrhost(c, 0))])
    error_message = "ssh_inbound must contain at most 50 valid IPv4 CIDR blocks."
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required", "opted-in"]
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  azs      = data.aws_availability_zones.available.names
  az_count = length(local.azs)

  # Split the VPC CIDR evenly into 2 * az_count subnets (public + private).
  subnet_newbits = ceil(log(local.az_count * 2, 2))

  public_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, local.subnet_newbits, i)
  ]

  private_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, local.subnet_newbits, i + local.az_count)
  ]

  anywhere_cidr = "0.0.0.0/0"

  ephemeral_from_port = 1024
  ephemeral_to_port   = 65535

  http_port  = 80
  https_port = 443
  ssh_port   = 22

  web_ports = {
    http  = 80
    https = 443
  }

  private_sg_ingress = {
    for pair in setproduct(keys(local.web_ports), local.public_subnet_cidrs) :
    "${pair[0]}-${pair[1]}" => {
      port = local.web_ports[pair[0]]
      cidr = pair[1]
    }
  }
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = var.vpc_name
  })
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

# -----------------------------------------------------------------------------
# Internet Gateway, Elastic IP, NAT Gateway
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Route tables
# -----------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.anywhere_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.anywhere_cidr
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-rt"
  })
}

resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Default NACL and default security group (locked down, tagged)
# -----------------------------------------------------------------------------

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  # No ingress/egress blocks: all rules are removed, denying all traffic.
  # All subnets are explicitly associated with the custom NACLs below.

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-Default"
  })

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  # No ingress/egress blocks: all rules are removed.

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-Default"
  })
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Public tier: HTTP/HTTPS from the internet, restricted SSH, web egress within the VPC"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-sg"
  })
}

resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Private tier: HTTP/HTTPS from public subnets only, HTTPS egress within the VPC"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-sg"
  })
}

# Public SG ingress

resource "aws_vpc_security_group_ingress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  description       = "HTTP from anywhere"
  ip_protocol       = "tcp"
  from_port         = local.http_port
  to_port           = local.http_port
  cidr_ipv4         = local.anywhere_cidr

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-sg-in-http"
  })
}

resource "aws_vpc_security_group_ingress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  description       = "HTTPS from anywhere"
  ip_protocol       = "tcp"
  from_port         = local.https_port
  to_port           = local.https_port
  cidr_ipv4         = local.anywhere_cidr

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-sg-in-https"
  })
}

resource "aws_vpc_security_group_ingress_rule" "public_ssh" {
  for_each = toset(var.ssh_inbound)

  security_group_id = aws_security_group.public.id
  description       = "SSH from allowed CIDR ${each.value}"
  ip_protocol       = "tcp"
  from_port         = local.ssh_port
  to_port           = local.ssh_port
  cidr_ipv4         = each.value

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-sg-in-ssh"
  })
}

# Public SG egress

resource "aws_vpc_security_group_egress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  description       = "HTTP to the VPC"
  ip_protocol       = "tcp"
  from_port         = local.http_port
  to_port           = local.http_port
  cidr_ipv4         = var.vpc_cidr

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-sg-out-http"
  })
}

resource "aws_vpc_security_group_egress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  description       = "HTTPS to the VPC"
  ip_protocol       = "tcp"
  from_port         = local.https_port
  to_port           = local.https_port
  cidr_ipv4         = var.vpc_cidr

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-sg-out-https"
  })
}

# Private SG ingress

resource "aws_vpc_security_group_ingress_rule" "private_web" {
  for_each = local.private_sg_ingress

  security_group_id = aws_security_group.private.id
  description       = "TCP ${each.value.port} from public subnet ${each.value.cidr}"
  ip_protocol       = "tcp"
  from_port         = each.value.port
  to_port           = each.value.port
  cidr_ipv4         = each.value.cidr

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-sg-in-${each.key}"
  })
}

# Private SG egress

resource "aws_vpc_security_group_egress_rule" "private_https" {
  security_group_id = aws_security_group.private.id
  description       = "HTTPS to the VPC"
  ip_protocol       = "tcp"
  from_port         = local.https_port
  to_port           = local.https_port
  cidr_ipv4         = var.vpc_cidr

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-sg-out-https"
  })
}

# -----------------------------------------------------------------------------
# Network ACLs
# -----------------------------------------------------------------------------

resource "aws_network_acl" "public" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.public[*].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-public-nacl"
  })
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-private-nacl"
  })
}

# Public NACL ingress

resource "aws_network_acl_rule" "public_ingress_ssh" {
  count = length(var.ssh_inbound)

  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.ssh_inbound[count.index]
  from_port      = local.ssh_port
  to_port        = local.ssh_port
}

resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 200
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.http_port
  to_port        = local.http_port
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 210
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.https_port
  to_port        = local.https_port
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 220
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.ephemeral_from_port
  to_port        = local.ephemeral_to_port
}

# Public NACL egress

resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.http_port
  to_port        = local.http_port
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 110
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.https_port
  to_port        = local.https_port
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 120
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.ephemeral_from_port
  to_port        = local.ephemeral_to_port
}

# Private NACL ingress

resource "aws_network_acl_rule" "private_ingress_http" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.public_subnet_cidrs[count.index]
  from_port      = local.http_port
  to_port        = local.http_port
}

resource "aws_network_acl_rule" "private_ingress_https" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.public_subnet_cidrs[count.index]
  from_port      = local.https_port
  to_port        = local.https_port
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.ephemeral_from_port
  to_port        = local.ephemeral_to_port
}

# Private NACL egress

resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.anywhere_cidr
  from_port      = local.https_port
  to_port        = local.https_port
}

resource "aws_network_acl_rule" "private_egress_ephemeral_private" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.private_subnet_cidrs[count.index]
  from_port      = local.ephemeral_from_port
  to_port        = local.ephemeral_to_port
}

resource "aws_network_acl_rule" "private_egress_ephemeral_public" {
  count = local.az_count

  network_acl_id = aws_network_acl.private.id
  rule_number    = 300 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = local.public_subnet_cidrs[count.index]
  from_port      = local.ephemeral_from_port
  to_port        = local.ephemeral_to_port
}

