terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The AWS provider configuration (region = "us-east-1") is injected by the
# deployment harness. It is not declared here to avoid a duplicate provider block.

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "imagebuilder"
    ManagedBy = "terraform"
  }
}

locals {
  name_prefix              = "imagebuilder_"
  iam_path                 = "/"
  imagebuilder_policy_arn  = "arn:aws:iam::aws:policy/AWSImageBuilderFullAccess"
}

# Trust policy: only the EC2 service may assume this role.
data "aws_iam_policy_document" "imagebuilder_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "imagebuilder" {
  name_prefix        = local.name_prefix
  path               = local.iam_path
  description        = "IAM role assumed by EC2 instances for EC2 Image Builder automation."
  assume_role_policy = data.aws_iam_policy_document.imagebuilder_assume_role.json

  tags = var.tags
}

# WARNING: AWSImageBuilderFullAccess grants broad permissions. For least privilege
# on Image Builder build/test instances, AWS recommends attaching
# EC2InstanceProfileForImageBuilder together with AmazonSSMManagedInstanceCore
# instead. The full access policy is attached here because it was explicitly requested.
resource "aws_iam_role_policy_attachment" "imagebuilder_full_access" {
  role       = aws_iam_role.imagebuilder.name
  policy_arn = local.imagebuilder_policy_arn
}

resource "aws_iam_instance_profile" "imagebuilder" {
  name_prefix = local.name_prefix
  path        = local.iam_path
  role        = aws_iam_role.imagebuilder.name

  tags = var.tags
}

output "imagebuilder_role_arn" {
  description = "ARN of the IAM role for EC2 Image Builder."
  value       = aws_iam_role.imagebuilder.arn
}

output "imagebuilder_role_name" {
  description = "Name of the IAM role for EC2 Image Builder."
  value       = aws_iam_role.imagebuilder.name
}

output "imagebuilder_instance_profile_name" {
  description = "Name of the IAM instance profile for EC2 Image Builder."
  value       = aws_iam_instance_profile.imagebuilder.name
}

output "imagebuilder_instance_profile_arn" {
  description = "ARN of the IAM instance profile for EC2 Image Builder."
  value       = aws_iam_instance_profile.imagebuilder.arn
}

