  description = "Name of the IAM instance profile attached to the Tamr EC2 instance."
  type        = string
  default     = "tamr-instance-profile"
}

variable "permissions_boundary" {
  description = "Optional ARN of a managed policy to use as the permissions boundary for the Tamr IAM role. Null means no boundary is applied."
  type        = string
  default     = null
}

variable "tags" {
  description = "Map of tags applied to every taggable resource created by this configuration."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      "Application" = "tamr"
      "ManagedBy"   = "terraform"
    },
    var.tags
  )
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tamr_instance_role" {
  name                 = var.role_name
  description          = "IAM role for the Tamr data platform EC2 instance."
  assume_role_policy   = data.aws_iam_policy_document.assume_role.json
  permissions_boundary = var.permissions_boundary
  tags                 = local.common_tags
}

resource "aws_iam_instance_profile" "tamr_instance_profile" {
  name = var.instance_profile_name
  role = aws_iam_role.tamr_instance_role.name
  tags = local.common_tags
}

