}

output "role_arn" {
  description = "ARN of the Tamr IAM role."
  value       = aws_iam_role.tamr_instance_role.arn
}

output "role_id" {
  description = "Unique ID of the Tamr IAM role."
  value       = aws_iam_role.tamr_instance_role.unique_id
}

output "instance_profile_name" {
  description = "Name of the Tamr IAM instance profile."
  value       = aws_iam_instance_profile.tamr_instance_profile.name
}

output "instance_profile_arn" {
  description = "ARN of the Tamr IAM instance profile."
  value       = aws_iam_instance_profile.tamr_instance_profile.arn
}

output "instance_profile_id" {
  description = "ID of the Tamr IAM instance profile."
  value       = aws_iam_instance_profile.tamr_instance_profile.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

variable "tags" {
  description = "Tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default = {
    Purpose   = "rds-custom-sqlserver"
    ManagedBy = "terraform"
  }
}

locals {
  role_name             = "AWSRDSCustomSQLServerInstanceRole"
  instance_profile_name = "AWSRDSCustomSQLServerInstanceProfile"
  iam_path              = "/"
  managed_policy_name   = "AmazonRDSCustomInstanceProfileRolePolicy"
  managed_policy_arn    = "arn:${data.aws_partition.current.partition}:iam::aws:policy/${local.managed_policy_name}"
}

data "aws_partition" "current" {}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

resource "aws_iam_role" "rds_custom_sqlserver_instance_role" {
  name                  = local.role_name
  path                  = local.iam_path
  description           = "Instance role for Amazon RDS Custom for SQL Server EC2 instances."
  assume_role_policy    = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration  = 3600
  force_detach_policies = true

  tags = merge(var.tags, {
    Name = local.role_name
  })
}

resource "aws_iam_role_policy_attachment" "rds_custom_instance_profile_policy" {
  role       = aws_iam_role.rds_custom_sqlserver_instance_role.name
  policy_arn = local.managed_policy_arn
}

resource "aws_iam_instance_profile" "rds_custom_sqlserver_instance_profile" {
  name = local.instance_profile_name
  path = local.iam_path
  role = aws_iam_role.rds_custom_sqlserver_instance_role.name

  tags = merge(var.tags, {
    Name = local.instance_profile_name
  })

  depends_on = [aws_iam_role_policy_attachment.rds_custom_instance_profile_policy]
}

output "role_name" {
  description = "Name of the RDS Custom for SQL Server instance IAM role."
  value       = aws_iam_role.rds_custom_sqlserver_instance_role.name
}

output "role_arn" {
  description = "ARN of the RDS Custom for SQL Server instance IAM role."
  value       = aws_iam_role.rds_custom_sqlserver_instance_role.arn
}

output "instance_profile_name" {
  description = "Name of the RDS Custom for SQL Server IAM instance profile."
  value       = aws_iam_instance_profile.rds_custom_sqlserver_instance_profile.name
}

output "instance_profile_arn" {
  description = "ARN of the RDS Custom for SQL Server IAM instance profile."
  value       = aws_iam_instance_profile.rds_custom_sqlserver_instance_profile.arn
}

output "attached_policy_arn" {
  description = "ARN of the AWS managed policy attached to the instance role."
  value       = aws_iam_role_policy_attachment.rds_custom_instance_profile_policy.policy_arn
}

# Omitted on purpose: the provider "aws" block (region = "us-east-1").
# The deployment harness injects the provider configuration, and a second
# provider block would cause a duplicate-configuration error.

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name (e.g. dev, staging, prod) used as the resource name prefix."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9-]+$", var.environment))
    error_message = "The environment must contain only lowercase letters, digits and hyphens."
  }
}

variable "target_account_id" {
  description = "12-digit ID of the account that holds the software S3 bucket. Leave empty to use the current account."
  type        = string
  default     = ""

  validation {
    condition     = can(regex("^$|^[0-9]{12}$", var.target_account_id))
    error_message = "The target_account_id must be empty or exactly 12 digits."
  }
}

variable "target_role_name" {
  description = "Name of the role to assume in the target account to read software installation files."
  type        = string
  default     = "packer-software-read"

  validation {
    condition     = can(regex("^[\\w+=,.@-]{1,64}$", var.target_role_name))
    error_message = "The target_role_name must be a valid IAM role name (1-64 characters from [A-Za-z0-9_+=,.@-])."
  }
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "packer-builder"
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix = "${var.environment}-packer-builder"

  partition          = data.aws_partition.current.partition
  current_account_id = data.aws_caller_identity.current.account_id

  effective_target_account_id = var.target_account_id != "" ? var.target_account_id : local.current_account_id

  target_role_arn = "arn:${local.partition}:iam::${local.effective_target_account_id}:role/${var.target_role_name}"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
    }
  )
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "packer_builder" {
  name                 = "${local.name_prefix}-role"
  description          = "Role for the ${var.environment} EC2 Packer builder instance."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

data "aws_iam_policy_document" "assume_target_role" {
  statement {
    sid    = "AssumeCrossAccountSoftwareReadRole"
    effect = "Allow"
    actions = [
      "sts:AssumeRole",
      "sts:TagSession",
    ]
    resources = [local.target_role_arn]
  }
}

resource "aws_iam_policy" "assume_target_role" {
  name        = "${local.name_prefix}-assume-target-role"
  description = "Allows the ${var.environment} Packer builder to assume the software read role in the target account."
  policy      = data.aws_iam_policy_document.assume_target_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "assume_target_role" {
  role       = aws_iam_role.packer_builder.name
  policy_arn = aws_iam_policy.assume_target_role.arn
}

resource "aws_iam_instance_profile" "packer_builder" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.packer_builder.name

  tags = local.common_tags
}

output "packer_builder_role_name" {
  description = "Name of the IAM role used by the Packer builder instance."
  value       = aws_iam_role.packer_builder.name
}

output "packer_builder_role_arn" {
  description = "ARN of the IAM role used by the Packer builder instance."
  value       = aws_iam_role.packer_builder.arn
}

output "packer_builder_instance_profile_name" {
  description = "Name of the instance profile to set as iam_instance_profile in Packer."
  value       = aws_iam_instance_profile.packer_builder.name
}

output "packer_builder_instance_profile_arn" {
  description = "ARN of the Packer builder instance profile."
  value       = aws_iam_instance_profile.packer_builder.arn
}

output "assume_target_role_policy_arn" {
  description = "ARN of the policy that allows assuming the cross-account software read role."
  value       = aws_iam_policy.assume_target_role.arn
}

output "target_role_arn" {
  description = "ARN of the role in the target account that the Packer builder may assume."
  value       = local.target_role_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy the three-tier network into (consumed by the harness-managed provider configuration)."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC, also used as a prefix for related resource names."
  type        = string
  default     = "three-tier-vpc"
}

variable "tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    Project   = "three-tier"
    ManagedBy = "terraform"
  }
}

locals {
  vpc_cidr             = "10.16.0.0/16"
  presentation_cidr    = "10.16.0.0/24"
  application_cidr     = "10.16.1.0/24"
  data_cidr            = "10.16.2.0/24"
  internet_cidr        = "0.0.0.0/0"
  primary_az           = data.aws_availability_zones.available.names[0]
  igw_name             = "${var.vpc_name}-igw"
  presentation_rt_name = "${var.vpc_name}-presentation-rt"
  default_sg_name      = "${var.vpc_name}-default-sg"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = var.vpc_name
  })
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = local.default_sg_name
  })
}

resource "aws_subnet" "presentation" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.presentation_cidr
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "presentation-subnet"
    Tier = "presentation"
  })
}

resource "aws_subnet" "application" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.application_cidr
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "application-subnet"
    Tier = "application"
  })
}

resource "aws_subnet" "data" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.data_cidr
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "data-subnet"
    Tier = "data"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = local.igw_name
  })
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = local.presentation_rt_name
    Tier = "presentation"
  })
}

resource "aws_route" "presentation_internet" {
  route_table_id         = aws_route_table.presentation.id
  destination_cidr_block = local.internet_cidr
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

output "vpc_id" {
  description = "ID of the three-tier VPC."
  value       = aws_vpc.main.id
}

output "presentation_subnet_id" {
  description = "ID of the public presentation subnet (internet-routed via the IGW; public IPs must be requested per resource)."
  value       = aws_subnet.presentation.id
}

output "application_subnet_id" {
  description = "ID of the private application subnet."
  value       = aws_subnet.application.id
}

output "data_subnet_id" {
  description = "ID of the private data subnet."
  value       = aws_subnet.data.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "presentation_route_table_id" {
  description = "ID of the route table associated with the presentation subnet."
  value       = aws_route_table.presentation.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = "service-catalog-testing"
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

variable "environment" {
  description = "Deployment environment name used for tagging and name suffixes."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  iam_path                     = "/servicecatalog/"
  service_catalog_principal    = "servicecatalog.amazonaws.com"
  test_role_name               = "test_role"
  user_name                    = "sc-test-user-${var.environment}"
  cfn_stack_arn_prefix         = "arn:${local.partition}:cloudformation:${local.region}:${local.account_id}:stack"
  catalog_product_arn          = "arn:${local.partition}:catalog:${local.region}:${local.account_id}:product/*"
  servicecatalog_stack_arn     = "arn:${local.partition}:servicecatalog:${local.region}:${local.account_id}:stack/*"
  console_url                  = "https://${local.account_id}.signin.aws.amazon.com/console"

  common_tags = merge(
    var.tags,
    {
      Project     = "service-catalog-testing"
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  )
}

# -----------------------------------------------------------------------------
# Service Catalog launch-constraint role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "test_role_trust" {
  statement {
    sid     = "AllowServiceCatalogAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.service_catalog_principal]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name                 = local.test_role_name
  path                 = local.iam_path
  description          = "Service Catalog launch-constraint role for testing"
  assume_role_policy   = data.aws_iam_policy_document.test_role_trust.json
  max_session_duration = 3600

  tags = local.common_tags
}

data "aws_iam_policy_document" "launch_constraint" {
  statement {
    sid    = "ManageServiceCatalogCloudFormationStacks"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:UpdateStack",
      "cloudformation:DescribeStacks",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStackResource",
      "cloudformation:DescribeStackResources",
      "cloudformation:GetTemplate",
      "cloudformation:SetStackPolicy",
      "cloudformation:CreateChangeSet",
      "cloudformation:DescribeChangeSet",
      "cloudformation:ExecuteChangeSet",
      "cloudformation:DeleteChangeSet",
      "cloudformation:ListChangeSets",
      "cloudformation:TagResource",
      "cloudformation:UntagResource",
    ]
    resources = [
      "${local.cfn_stack_arn_prefix}/SC-${local.account_id}-*/*",
    ]
  }

  statement {
    sid    = "CloudFormationTemplateValidation"
    effect = "Allow"
    actions = [
      "cloudformation:ValidateTemplate",
      "cloudformation:GetTemplateSummary",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:RequestedRegion"
      values   = [local.region]
    }
  }

  statement {
    sid       = "ReadServiceCatalogProvisioningTemplates"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["arn:${local.partition}:s3:::*/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:ExistingObjectTag/servicecatalog:provisioning"
      values   = ["true"]
    }
  }

  statement {
    sid    = "ManageTestProductBuckets"
    effect = "Allow"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketTagging",
      "s3:PutBucketTagging",
      "s3:PutBucketPublicAccessBlock",
      "s3:GetBucketPublicAccessBlock",
      "s3:PutEncryptionConfiguration",
      "s3:GetEncryptionConfiguration",
      "s3:PutBucketVersioning",
      "s3:GetBucketVersioning",
    ]
    resources = ["arn:${local.partition}:s3:::sc-test-*"]
  }
}

resource "aws_iam_policy" "launch_constraint" {
  name        = "test_role-launch-constraint-policy"
  path        = local.iam_path
  description = "Least-privilege launch-constraint policy for the Service Catalog test role"
  policy      = data.aws_iam_policy_document.launch_constraint.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "test_role_launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

# -----------------------------------------------------------------------------
# Service Catalog testers group
# -----------------------------------------------------------------------------

resource "aws_iam_group" "service_catalog_testers" {
  name = "service-catalog-testers-${var.environment}"
  path = local.iam_path
}

data "aws_iam_policy_document" "group_end_user" {
  statement {
    sid    = "ServiceCatalogProductAccess"
    effect = "Allow"
    actions = [
      "servicecatalog:DescribeProduct",
      "servicecatalog:DescribeProductView",
      "servicecatalog:ListLaunchPaths",
      "servicecatalog:ProvisionProduct",
    ]
    resources = [local.catalog_product_arn]
  }

  statement {
    sid    = "ServiceCatalogProvisionedProductAccess"
    effect = "Allow"
    actions = [
      "servicecatalog:DescribeProvisionedProduct",
      "servicecatalog:TerminateProvisionedProduct",
      "servicecatalog:UpdateProvisionedProduct",
    ]
    resources = [local.servicecatalog_stack_arn]
  }

  statement {
    sid    = "ServiceCatalogNonResourceLevelActions"
    effect = "Allow"
    actions = [
      "servicecatalog:SearchProducts",
      "servicecatalog:ListRecordHistory",
      "servicecatalog:DescribeRecord",
      "servicecatalog:ScanProvisionedProducts",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:RequestedRegion"
      values   = [local.region]
    }
  }

  statement {
    sid       = "PassLaunchConstraintRoleToServiceCatalog"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.test_role.arn]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = [local.service_catalog_principal]
    }
  }
}

resource "aws_iam_policy" "group_end_user" {
  name        = "service-catalog-testers-end-user-${var.environment}"
  path        = local.iam_path
  description = "Service Catalog end-user permissions for the testers group"
  policy      = data.aws_iam_policy_document.group_end_user.json

  tags = local.common_tags
}

resource "aws_iam_group_policy_attachment" "testers_end_user" {
  group      = aws_iam_group.service_catalog_testers.name
  policy_arn = aws_iam_policy.group_end_user.arn
}

data "aws_iam_policy_document" "group_self_service" {
  statement {
    sid    = "ManageOwnPassword"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/*/$${aws:username}",
    ]
  }

  statement {
    sid       = "ViewAccountPasswordPolicy"
    effect    = "Allow"
    actions   = ["iam:GetAccountPasswordPolicy"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "group_self_service" {
  name        = "service-catalog-testers-self-service-${var.environment}"
  path        = local.iam_path
  description = "Allows console users to view the password policy and rotate their own password"
  policy      = data.aws_iam_policy_document.group_self_service.json

  tags = local.common_tags
}

resource "aws_iam_group_policy_attachment" "testers_self_service" {
  group      = aws_iam_group.service_catalog_testers.name
  policy_arn = aws_iam_policy.group_self_service.arn
}

# -----------------------------------------------------------------------------
# Console-enabled test user
# -----------------------------------------------------------------------------

resource "aws_iam_user" "test_user" {
  name          = local.user_name
  path          = local.iam_path
  force_destroy = true

  tags = local.common_tags
}

resource "aws_iam_user_login_profile" "test_user_console" {
  user                    = aws_iam_user.test_user.name
  password_length         = 24
  password_reset_required = true

  lifecycle {
    ignore_changes = [
      password_length,
      password_reset_required,
      pgp_key,
    ]
  }

  depends_on = [aws_iam_account_password_policy.strict]
}

resource "aws_secretsmanager_secret" "test_user_console_password" {
  name                    = "servicecatalog/${var.environment}/sc-test-user-console-password"
  description             = "Initial AWS-generated console password for the Service Catalog test user"
  recovery_window_in_days = 7

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "test_user_console_password" {
  secret_id = aws_secretsmanager_secret.test_user_console_password.id
  secret_string = jsonencode({
    username    = aws_iam_user.test_user.name
    password    = aws_iam_user_login_profile.test_user_console.password
    console_url = local.console_url
  })
}

resource "aws_iam_user_group_membership" "test_user_membership" {
  user   = aws_iam_user.test_user.name
  groups = [aws_iam_group.service_catalog_testers.name]
}

# -----------------------------------------------------------------------------
# Account password policy
# -----------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 24
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "test_role_arn" {
  description = "ARN of the Service Catalog launch-constraint test role."
  value       = aws_iam_role.test_role.arn
}

output "test_role_name" {
  description = "Name of the Service Catalog launch-constraint test role."
  value       = aws_iam_role.test_role.name
}

output "launch_constraint_policy_arn" {
  description = "ARN of the launch-constraint IAM policy."
  value       = aws_iam_policy.launch_constraint.arn
}

output "group_name" {
  description = "Name of the Service Catalog testers IAM group."
  value       = aws_iam_group.service_catalog_testers.name
}

output "user_name" {
  description = "Name of the console-enabled test user."
  value       = aws_iam_user.test_user.name
}

output "user_arn" {
  description = "ARN of the console-enabled test user."
  value       = aws_iam_user.test_user.arn
}

output "console_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the test user's initial console credentials."
  value       = aws_secretsmanager_secret.test_user_console_password.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      "Datadog"                 = "true"
      "DatadogAgentlessScanner" = "true"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the agentless scanner VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "name" {
  description = "Name used for the VPC and as a prefix for related resources."
  type        = string
  default     = "DatatogAgentlessScanner"
}

variable "enable_ssm_vpc_endpoint" {
  description = "Whether to create the SSM interface VPC endpoints (ec2messages, ssmmessages, ssm)."
  type        = bool
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  az_count = min(3, length(data.aws_availability_zones.available.names))
  azs      = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  public_subnet_cidrs  = [for idx in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, idx)]
  private_subnet_cidrs = [for idx in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, idx + local.az_count)]

  region                = data.aws_region.current.name
  service_prefix        = "com.amazonaws.${local.region}"
  any_ipv4_cidr         = "0.0.0.0/0"
  https_port            = 443
  interface_type        = "Interface"
  ssm_endpoint_services = ["ec2messages", "ssmmessages", "ssm"]
}

resource "aws_vpc" "vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-public-${local.azs[count.index]}"
  }
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-private-${local.azs[count.index]}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id

  tags = {
    Name = var.name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.name}-public"
  }
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.name}-nat"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "ngw" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = var.name
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block     = local.any_ipv4_cidr
    nat_gateway_id = aws_nat_gateway.ngw.id
  }

  tags = {
    Name = "${var.name}-private"
  }
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.vpc.id
  service_name      = "${local.service_prefix}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = {
    Name = "${var.name}-s3"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${var.name}-vpc-endpoints"
  description = "Security group for interface VPC endpoints"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = local.https_port
    to_port     = local.https_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.vpc.cidr_block]
  }

  egress {
    description = "HTTPS responses within the VPC"
    from_port   = local.https_port
    to_port     = local.https_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.vpc.cidr_block]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.vpc.id
  service_name        = "${local.service_prefix}.lambda"
  vpc_endpoint_type   = local.interface_type
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-lambda"
  }
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.vpc.id
  service_name        = "${local.service_prefix}.ebs"
  vpc_endpoint_type   = local.interface_type
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-ebs"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  for_each = var.enable_ssm_vpc_endpoint ? toset(local.ssm_endpoint_services) : toset([])

  vpc_id              = aws_vpc.vpc.id
  service_name        = "${local.service_prefix}.${each.value}"
  vpc_endpoint_type   = local.interface_type
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-${each.value}"
  }
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.vpc.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway."
  value       = aws_nat_gateway.ngw.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table."
  value       = aws_route_table.private.id
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint."
  value       = aws_vpc_endpoint.s3.id
}

output "lambda_vpc_endpoint_id" {
  description = "ID of the Lambda interface VPC endpoint."
  value       = aws_vpc_endpoint.lambda.id
}

output "ebs_vpc_endpoint_id" {
  description = "ID of the EBS interface VPC endpoint."
  value       = aws_vpc_endpoint.ebs.id
}

output "vpc_endpoints_security_group_id" {
  description = "ID of the security group attached to interface VPC endpoints."
  value       = aws_security_group.vpc_endpoints.id
}

# Provider configuration (region = "us-east-1") is injected by the deployment harness.
# Do not add a provider "aws" block here, because a second one would cause a
# duplicate provider configuration error.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Core toggles
# ------------------------------------------------------------------------------

variable "enable" {
  description = "Main toggle. When false, no resources or rules are created."
  type        = bool
  default     = true
}

variable "new_sg" {
  description = "True creates a new security group. False attaches rules to an existing security group."
  type        = bool
  default     = true
}

variable "existing_sg_id" {
  description = "ID of an existing security group. Used only when new_sg = false."
  type        = string
  default     = null

  validation {
    condition     = var.existing_sg_id == null || can(regex("^sg-[0-9a-f]+$", var.existing_sg_id))
    error_message = "existing_sg_id must be null or a valid security group ID (sg-...)."
  }
}

variable "vpc_id" {
  description = "VPC ID for the new security group. If null, a fallback VPC (10.0.0.0/16) is created."
  type        = string
  default     = null

  validation {
    condition     = var.vpc_id == null || can(regex("^vpc-[0-9a-f]+$", var.vpc_id))
    error_message = "vpc_id must be null or a valid VPC ID (vpc-...)."
  }
}

# ------------------------------------------------------------------------------
# Label variables
# ------------------------------------------------------------------------------

variable "name" {
  description = "Name used by the labels module."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment used by the labels module."
  type        = string
  default     = "dev"
}

variable "label_order" {
  description = "Order of label components."
  type        = list(string)
  default     = ["name", "environment"]
}

variable "managedby" {
  description = "ManagedBy tag value."
  type        = string
  default     = "terraform"
}

variable "repository" {
  description = "Source repository tag value."
  type        = string
  default     = "https://github.com/sohanyadav/terraform-aws-labels"
}

variable "tags" {
  description = "Additional tags merged into all resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Prefix list variables
# ------------------------------------------------------------------------------

variable "prefix_list_enabled" {
  description = "Create a managed prefix list when no prefix_list_ids are supplied."
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "Existing managed prefix list IDs. When non-empty, no prefix list is created."
  type        = list(string)
  default     = []
}

variable "max_entries" {
  description = "Maximum number of entries for the managed prefix list."
  type        = number
  default     = 5

  validation {
    condition     = var.max_entries >= 1
    error_message = "max_entries must be at least 1."
  }
}

variable "address_family" {
  description = "Address family of the managed prefix list."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.address_family)
    error_message = "address_family must be either \"IPv4\" or \"IPv6\"."
  }
}

variable "entry" {
  description = "Entries for the managed prefix list."
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []

  validation {
    condition     = alltrue([for e in var.entry : can(cidrhost(e.cidr, 0))])
    error_message = "Every prefix list entry must have a valid CIDR."
  }
}

# ------------------------------------------------------------------------------
# New security group rule inputs
# ------------------------------------------------------------------------------

variable "new_sg_ingress_rules_with_cidr_blocks" {
  description = "Ingress rules for the new security group based on CIDR blocks."
  type = list(object({
    rule_name        = string
    from_port        = number
    to_port          = number
    protocol         = string
    description      = string
    cidr_blocks      = optional(list(string), [])
    ipv6_cidr_blocks = optional(list(string), [])
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.new_sg_ingress_rules_with_cidr_blocks :
      !anytrue([for c in concat(r.cidr_blocks, r.ipv6_cidr_blocks) : contains(["0.0.0.0/0", "::/0"], c)]) ||
      (lower(r.protocol) == "tcp" && r.from_port == r.to_port && contains([80, 443], r.from_port))
    ])
    error_message = "Ingress from 0.0.0.0/0 or ::/0 is only allowed for single-port TCP 80 or 443."
  }

  validation {
    condition     = alltrue([for r in var.new_sg_ingress_rules_with_cidr_blocks : length(trimspace(r.description)) > 0])
    error_message = "Every rule must have a non-empty description."
  }

  validation {
    condition     = alltrue([for r in var.new_sg_ingress_rules_with_cidr_blocks : length(r.cidr_blocks) + length(r.ipv6_cidr_blocks) > 0])
    error_message = "Every CIDR rule must have at least one cidr_blocks or ipv6_cidr_blocks entry."
  }
}

