terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  log_group_prefix = "logs"
  log_group_name   = "${local.log_group_prefix}-${random_pet.log_group_suffix.id}"
}

resource "random_pet" "log_group_suffix" {
  length    = 2
  separator = "-"
}

resource "aws_cloudwatch_log_group" "logs" {
  name              = local.log_group_name
  retention_in_days = 7
  tags              = var.tags
}

data "aws_iam_policy_document" "log_group_write" {
  statement {
    sid    = "AllowLogGroupWrite"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.logs.arn,
      "${aws_cloudwatch_log_group.logs.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "log_group_write" {
  name        = "${local.log_group_name}-write"
  description = "Allows writing log streams/events to the generated log group"
  policy      = data.aws_iam_policy_document.log_group_write.json
  tags        = var.tags
}

output "log_group_name" {
  description = "Name of the CloudWatch Logs log group."
  value       = aws_cloudwatch_log_group.logs.name
}

output "log_group_arn" {
  description = "ARN of the CloudWatch Logs log group."
  value       = aws_cloudwatch_log_group.logs.arn
}

output "iam_policy_arn" {
  description = "ARN of the IAM policy granting write access to the log group."
  value       = aws_iam_policy.log_group_write.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enabled" {
  description = "Turns SSM Automation CloudWatch logging and the SSM document public-sharing block on (true) or off (false)."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags applied to every resource that supports tagging."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  log_group_name        = "/aws/ssm/automation/executeScript"
  log_retention_in_days = 14
  kms_alias_name        = "alias/ssm-automation-execute-script-logs"

  log_destination_value = "CloudWatch"
  public_sharing_value  = "Disable"

  service_setting_arn_prefix = "arn:${local.partition}:ssm:${local.region}:${local.account_id}:servicesetting"

  automation_log_destination_setting_arn = "${local.service_setting_arn_prefix}/ssm/automation/customer-script-log-destination"
  automation_log_group_name_setting_arn  = "${local.service_setting_arn_prefix}/ssm/automation/customer-script-log-group-name"
  documents_public_sharing_setting_arn   = "${local.service_setting_arn_prefix}/ssm/documents/console/public-sharing-permission"

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"
  log_group_arn    = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"
  logs_principal   = "logs.${local.region}.amazonaws.com"
}

resource "aws_kms_key" "ssm_automation_logs" {
  count = var.enabled ? 1 : 0

  description             = "CMK encrypting the SSM Automation executeScript CloudWatch log group"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:RotateKeyOnDemand",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUseOfKeyForLogGroup"
        Effect = "Allow"
        Principal = {
          Service = local.logs_principal
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = local.log_group_arn
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_kms_alias" "ssm_automation_logs" {
  count = var.enabled ? 1 : 0

  name          = local.kms_alias_name
  target_key_id = aws_kms_key.ssm_automation_logs[0].key_id
}

resource "aws_cloudwatch_log_group" "ssm_automation_execute_script" {
  count = var.enabled ? 1 : 0

  name              = local.log_group_name
  retention_in_days = local.log_retention_in_days
  kms_key_id        = aws_kms_key.ssm_automation_logs[0].arn

  tags = var.tags
}

# NOTE: aws_ssm_service_setting changes settings for the whole AWS account in one region.
# Running `terraform destroy` resets this setting to the AWS default (Automation script logs off).
resource "aws_ssm_service_setting" "automation_log_destination" {
  count = var.enabled ? 1 : 0

  setting_id    = local.automation_log_destination_setting_arn
  setting_value = local.log_destination_value

  depends_on = [aws_cloudwatch_log_group.ssm_automation_execute_script]
}

# NOTE: aws_ssm_service_setting changes settings for the whole AWS account in one region.
# Running `terraform destroy` resets this setting to the AWS default (no Automation script log group configured).
resource "aws_ssm_service_setting" "automation_log_group_name" {
  count = var.enabled ? 1 : 0

  setting_id    = local.automation_log_group_name_setting_arn
  setting_value = aws_cloudwatch_log_group.ssm_automation_execute_script[0].name
}

# NOTE: aws_ssm_service_setting changes settings for the whole AWS account in one region.
# Running `terraform destroy` resets this setting to the AWS default (public document sharing allowed again).
resource "aws_ssm_service_setting" "documents_public_sharing" {
  count = var.enabled ? 1 : 0

  setting_id    = local.documents_public_sharing_setting_arn
  setting_value = local.public_sharing_value
}

output "log_group_name" {
  description = "Name of the SSM Automation executeScript CloudWatch log group (null when disabled)."
  value       = one(aws_cloudwatch_log_group.ssm_automation_execute_script[*].name)
}

output "log_group_arn" {
  description = "ARN of the SSM Automation executeScript CloudWatch log group (null when disabled)."
  value       = one(aws_cloudwatch_log_group.ssm_automation_execute_script[*].arn)
}

output "kms_key_arn" {
  description = "ARN of the KMS key encrypting the log group (null when disabled)."
  value       = one(aws_kms_key.ssm_automation_logs[*].arn)
}

output "kms_alias_name" {
  description = "Alias of the KMS key encrypting the log group (null when disabled)."
  value       = one(aws_kms_alias.ssm_automation_logs[*].name)
}

output "automation_log_destination_setting_id" {
  description = "ARN of the SSM Automation script log destination service setting (null when disabled)."
  value       = one(aws_ssm_service_setting.automation_log_destination[*].setting_id)
}

output "automation_log_group_name_setting_id" {
  description = "ARN of the SSM Automation script log group name service setting (null when disabled)."
  value       = one(aws_ssm_service_setting.automation_log_group_name[*].setting_id)
}

output "documents_public_sharing_setting_id" {
  description = "ARN of the SSM document public-sharing permission service setting (null when disabled)."
  value       = one(aws_ssm_service_setting.documents_public_sharing[*].setting_id)
}

output "documents_public_sharing_status" {
  description = "Status of the SSM document public-sharing permission service setting (null when disabled)."
  value       = var.enabled ? aws_ssm_service_setting.documents_public_sharing[0].status : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The provider "aws" block (region = "us-east-1") is supplied by the deployment harness.

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "ddb-backup-automation"
    ManagedBy = "terraform"
  }
}

locals {
  account_id           = data.aws_caller_identity.current.account_id
  region               = data.aws_region.current.name
  dynamodb_table_arn   = "arn:aws:dynamodb:${local.region}:${local.account_id}:table/*"
  dynamodb_backup_arn  = "arn:aws:dynamodb:${local.region}:${local.account_id}:table/*/backup/*"
  lambda_log_group_arn = "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  description        = "Lambda execution role for creating DynamoDB backups"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  description        = "Lambda execution role for listing and deleting DynamoDB backups"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    sid    = "CreateDynamoDBBackups"
    effect = "Allow"
    actions = [
      "dynamodb:CreateBackup",
      "dynamodb:DescribeTable",
    ]
    resources = [local.dynamodb_table_arn]
  }
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows creating on-demand backups of DynamoDB tables in this account and region"
  policy      = data.aws_iam_policy_document.create_ddb_backup.json
  tags        = var.tags
}

data "aws_iam_policy_document" "remove_ddb_backup" {
  # dynamodb:ListBackups does not support resource-level permissions, so it
  # requires Resource "*". The action itself is explicit (not a wildcard).
  statement {
    sid       = "ListDynamoDBBackups"
    effect    = "Allow"
    actions   = ["dynamodb:ListBackups"]
    resources = ["*"]
  }

  statement {
    sid    = "DeleteDynamoDBBackups"
    effect = "Allow"
    actions = [
      "dynamodb:DescribeBackup",
      "dynamodb:DeleteBackup",
    ]
    resources = [local.dynamodb_backup_arn]
  }
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows listing and deleting DynamoDB backups in this account and region"
  policy      = data.aws_iam_policy_document.remove_ddb_backup.json
  tags        = var.tags
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid    = "LambdaCloudWatchLogsWrite"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      local.lambda_log_group_arn,
      "${local.lambda_log_group_arn}:*",
    ]
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Allows Lambda functions to write logs to CloudWatch Logs"
  policy      = data.aws_iam_policy_document.lambda_logging.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_role_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_role_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

output "create_ddb_backup_role" {
  description = "IAM role used by the Lambda that creates DynamoDB backups"
  value = {
    name = aws_iam_role.create_ddb_backup_role.name
    arn  = aws_iam_role.create_ddb_backup_role.arn
    id   = aws_iam_role.create_ddb_backup_role.id
  }
}

output "remove_ddb_backup_role" {
  description = "IAM role used by the Lambda that lists and deletes DynamoDB backups"
  value = {
    name = aws_iam_role.remove_ddb_backup_role.name
    arn  = aws_iam_role.remove_ddb_backup_role.arn
    id   = aws_iam_role.remove_ddb_backup_role.id
  }
}

output "create_ddb_backup_role_arn" {
  description = "ARN of the create_ddb_backup_role"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the remove_ddb_backup_role"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The provider configuration (region = "us-east-1") is supplied by the
# deployment harness, so this file has no provider block.

data "aws_partition" "current" {}

locals {
  managed_policy_arn_prefix = "arn:${data.aws_partition.current.partition}:iam::aws:policy"
  group_path                = "/"
}

# -----------------------------------------------------------------------------
# IAM Groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "admin" {
  name = "admin"
  path = local.group_path
}

resource "aws_iam_group" "admin_read_only" {
  name = "admin_read_only"
  path = local.group_path
}

resource "aws_iam_group" "developer_group" {
  name = "developer_group"
  path = local.group_path
}

# -----------------------------------------------------------------------------
# AWS-managed policy attachments (non-exclusive, per-group attachments only)
# -----------------------------------------------------------------------------

# This request explicitly asks for full administrator access for the admin group.
# No other group gets wildcard permissions.
resource "aws_iam_group_policy_attachment" "admin_administrator_access" {
  group      = aws_iam_group.admin.name
  policy_arn = "${local.managed_policy_arn_prefix}/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "admin_read_only_access" {
  group      = aws_iam_group.admin_read_only.name
  policy_arn = "${local.managed_policy_arn_prefix}/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_s3_full_access" {
  group      = aws_iam_group.developer_group.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonS3FullAccess"
}

# Lets developers change only their own IAM console password.
resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer_group.name
  policy_arn = "${local.managed_policy_arn_prefix}/IAMUserChangePassword"
}

# -----------------------------------------------------------------------------
# Group memberships
#
# Each aws_iam_group_membership resource has EXCLUSIVE control of its group's
# members. Add users ONLY through these `users` lists, as
# aws_iam_user.<label>.name references to aws_iam_user resources declared in
# this file. Do NOT also use aws_iam_user_group_membership for these groups,
# because the two resources would conflict and keep overwriting each other.
# -----------------------------------------------------------------------------

resource "aws_iam_group_membership" "admin_team" {
  name  = "admin_team"
  group = aws_iam_group.admin.name
  users = []
}

resource "aws_iam_group_membership" "read_only_admin_team" {
  name  = "read_only_admin_team"
  group = aws_iam_group.admin_read_only.name
  users = []
}

resource "aws_iam_group_membership" "developers" {
  name  = "developers"
  group = aws_iam_group.developer_group.name
  users = []
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "admin_group_name" {
  description = "Name of the admin IAM group."
  value       = aws_iam_group.admin.name
}

output "admin_group_arn" {
  description = "ARN of the admin IAM group."
  value       = aws_iam_group.admin.arn
}

output "admin_read_only_group_name" {
  description = "Name of the read-only admin IAM group."
  value       = aws_iam_group.admin_read_only.name
}

output "admin_read_only_group_arn" {
  description = "ARN of the read-only admin IAM group."
  value       = aws_iam_group.admin_read_only.arn
}

output "developer_group_name" {
  description = "Name of the developer IAM group."
  value       = aws_iam_group.developer_group.name
}

output "developer_group_arn" {
  description = "ARN of the developer IAM group."
  value       = aws_iam_group.developer_group.arn
}

# Terraform configuration for the GitHub Actions OIDC provider and optional GitHub-federated IAM roles.
#
# The provider "aws" block from objective 2 (region "us-east-1" with default_tags) is intentionally left out.
# The deployment harness injects the provider configuration, and declaring it here as well would create a
# duplicate provider configuration. var.tags is therefore applied to each taggable resource directly.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "github-actions-oidc"
  }
}

variable "github_roles" {
  description = "Optional map of GitHub Actions federated IAM roles to create. Each map key becomes the IAM role name. No roles are created by default."
  type = map(object({
    subjects             = list(string)
    managed_policy_arns  = optional(list(string), [])
    inline_policy_json   = optional(string)
    max_session_duration = optional(number, 3600)
    description          = optional(string, "GitHub Actions federated role")
  }))
  default = {}

  validation {
    condition = alltrue([
      for role_name, role in var.github_roles :
      length(role.subjects) > 0 && alltrue([
        for subject in role.subjects : startswith(subject, "repo:")
      ])
    ])
    error_message = "Every github_roles entry must define at least one subject, and each subject must start with \"repo:\" (e.g. \"repo:my-org/my-repo:ref:refs/heads/main\"). Wildcard-only subjects are not allowed."
  }

  validation {
    condition = alltrue([
      for role_name, role in var.github_roles :
      role.max_session_duration >= 3600 && role.max_session_duration <= 43200
    ])
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }

  validation {
    condition = alltrue([
      for role_name, role in var.github_roles :
      can(jsondecode(role.inline_policy_json)) if role.inline_policy_json != null
    ])
    error_message = "inline_policy_json must be a valid JSON IAM policy document."
  }

  validation {
    condition = alltrue(flatten([
      for role_name, role in var.github_roles : [
        for statement in try(flatten([jsondecode(role.inline_policy_json).Statement]), []) :
        !(
          contains(try(flatten([statement.Action]), []), "*") &&
          contains(try(flatten([statement.Resource]), []), "*")
        )
      ] if role.inline_policy_json != null
    ]))
    error_message = "Inline policies must follow least privilege: a statement must not combine Action \"*\" with Resource \"*\"."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  github_oidc_url  = "https://token.actions.githubusercontent.com"
  github_oidc_host = "token.actions.githubusercontent.com"
  github_audience  = "sts.amazonaws.com"

  # GitHub's published, non-secret intermediate CA thumbprints.
  github_published_thumbprints = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]

  oidc_thumbprints_all = distinct(concat(
    [for c in data.tls_certificate.github.certificates : lower(c.sha1_fingerprint) if c.is_ca],
    local.github_published_thumbprints,
  ))

  # AWS allows a maximum of 5 thumbprints per OIDC provider.
  oidc_thumbprints = slice(
    local.oidc_thumbprints_all,
    0,
    min(5, length(local.oidc_thumbprints_all)),
  )

  oidc_provider_name = "github-actions-oidc"

  role_policy_attachments = {
    for pair in flatten([
      for role_name, role in var.github_roles : [
        for policy_arn in role.managed_policy_arns : {
          role       = role_name
          policy_arn = policy_arn
        }
      ]
    ]) : "${pair.role}|${pair.policy_arn}" => pair
  }

  inline_policy_roles = {
    for role_name, role in var.github_roles : role_name => role
    if role.inline_policy_json != null
  }
}

# -----------------------------------------------------------------------------
# GitHub OIDC issuer TLS certificate (public endpoint lookup)
# -----------------------------------------------------------------------------

data "tls_certificate" "github" {
  url = local.github_oidc_url
}

# -----------------------------------------------------------------------------
# IAM OpenID Connect Provider
# -----------------------------------------------------------------------------

resource "aws_iam_openid_connect_provider" "github" {
  url             = local.github_oidc_url
  client_id_list  = [local.github_audience]
  thumbprint_list = local.oidc_thumbprints

  tags = merge(var.tags, {
    Name = local.oidc_provider_name
  })
}

# -----------------------------------------------------------------------------
# Optional GitHub-federated IAM roles
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "github_trust" {
  for_each = var.github_roles

  statement {
    sid     = "GitHubActionsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:aud"
      values   = [local.github_audience]
    }

    condition {
      test     = "StringLike"
      variable = "${local.github_oidc_host}:sub"
      values   = each.value.subjects
    }
  }
}

resource "aws_iam_role" "github" {
  for_each = var.github_roles

  name                 = each.key
  description          = each.value.description
  assume_role_policy   = data.aws_iam_policy_document.github_trust[each.key].json
  max_session_duration = each.value.max_session_duration

  tags = merge(var.tags, {
    Name = each.key
  })
}

resource "aws_iam_role_policy_attachment" "github" {
  for_each = local.role_policy_attachments

  role       = aws_iam_role.github[each.value.role].name
  policy_arn = each.value.policy_arn
}

resource "aws_iam_role_policy" "github_inline" {
  for_each = local.inline_policy_roles

  name   = "${each.key}-inline"
  role   = aws_iam_role.github[each.key].name
  policy = each.value.inline_policy_json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "oidc_provider_arn" {
  description = "ARN of the GitHub Actions IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

output "oidc_provider_url" {
  description = "Issuer URL of the GitHub Actions OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.url
}

output "oidc_audience" {
  description = "Audience (client ID) configured on the OIDC provider."
  value       = local.github_audience
}

output "oidc_thumbprints" {
  description = "Thumbprint list configured on the OIDC provider."
  value       = local.oidc_thumbprints
}

output "github_role_arns" {
  description = "Map of GitHub-federated IAM role names to role ARNs (empty unless github_roles is set)."
  value       = { for k, r in aws_iam_role.github : k => r.arn }
}

output "github_role_names" {
  description = "Map of GitHub-federated IAM role keys to role names (empty unless github_roles is set)."
  value       = { for k, r in aws_iam_role.github : k => r.name }
}

# Terraform configuration for the "projectvpc" network (main.tf)
# Two instructions conflicted here. Objective 2 asks for a provider "aws" block,
# but the output rules say the deployment harness injects the provider. A second
# default provider block would fail with a duplicate-provider error, so this
# file leaves it out. Set the region to us-east-1 in the injected provider.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name, used only for tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9-]+$", var.environment))
    error_message = "environment must contain only lowercase letters, digits and hyphens."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix = "projectvpc"

  common_tags = {
    Project     = local.name_prefix
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  flow_log_group_name = "/aws/vpc-flow-logs/${local.name_prefix}"
  account_id          = data.aws_caller_identity.current.account_id
  partition           = data.aws_partition.current.partition
  region              = data.aws_region.current.name
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.name_prefix
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet"
    Tier = "private"
  })
}

# ---------------------------------------------------------------------------
# NAT Gateway
# ---------------------------------------------------------------------------

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public.id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-gw"
  })

  depends_on = [aws_internet_gateway.main]
}

# ---------------------------------------------------------------------------
# Route tables
# ---------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Default security group: no ingress or egress rules, so it denies all traffic
# ---------------------------------------------------------------------------

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default-sg"
  })
}

# ---------------------------------------------------------------------------
# VPC flow logs: CloudWatch Logs, encrypted with a customer-managed KMS key
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "flow_logs_kms" {
  statement {
    sid       = "EnableAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsUse"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    condition {
      test     = "ArnEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.flow_log_group_name}"]
    }
  }
}

resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for ${local.name_prefix} VPC flow logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.flow_logs_kms.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs-kms"
  })
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/${local.name_prefix}-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = local.flow_log_group_name
  retention_in_days = 365
  kms_key_id        = aws_kms_key.flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs"
  })
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:ec2:${local.region}:${local.account_id}:vpc-flow-log/*"]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "${local.name_prefix}-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-logs-role"
  })
}

data "aws_iam_policy_document" "flow_logs_permissions" {
  statement {
    sid    = "WriteFlowLogsToLogGroup"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups",
    ]
    resources = [
      aws_cloudwatch_log_group.flow_logs.arn,
      "${aws_cloudwatch_log_group.flow_logs.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name   = "${local.name_prefix}-flow-logs-policy"
  role   = aws_iam_role.flow_logs.id
  policy = data.aws_iam_policy_document.flow_logs_permissions.json
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn             = aws_iam_role.flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-flow-log"
  })

  depends_on = [aws_iam_role_policy.flow_logs]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the projectvpc VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet."
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.main.id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway."
  value       = aws_nat_gateway.main.id
}

output "nat_public_ip" {
  description = "Public IP address of the NAT Gateway's Elastic IP."
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The deployment harness injects the provider configuration
# (provider "aws" { region = "us-east-1" }). It is not declared here because
# a second default "aws" provider block would fail with a duplicate provider
# configuration error.

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to every taggable resource."
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "demo"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  name = "demo-vpc"

  vpc_cidr = "10.0.0.0/16"

  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
  public_subnet_cidrs  = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]

  # 2nd, 3rd and 4th available AZs (names[1], names[2], names[3])
  azs = slice(data.aws_availability_zones.available.names, 1, 4)

  any_ipv4_cidr = "0.0.0.0/0"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })

  flow_log_group_name = "/aws/vpc/${local.name}/flow-logs"
  flow_log_group_arn  = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.flow_log_group_name}"
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.name
  })
}

# CIS: lock down the default security group so it allows no traffic.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-default-sg"
  })
}

################################################################################
# Subnets
################################################################################

# These subnets are public because their route table sends 0.0.0.0/0 to the
# internet gateway. Instances do not get a public IP automatically. Assign one
# explicitly (for example with an Elastic IP or a load balancer) when needed.
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

################################################################################
# Internet Gateway & Public Routing
################################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

################################################################################
# NAT Gateway & Private Routing
################################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.any_ipv4_cidr
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

################################################################################
# VPC Flow Logs
################################################################################

data "aws_iam_policy_document" "flow_logs_kms" {
  statement {
    sid    = "EnableAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    condition {
      test     = "ArnEquals"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = [local.flow_log_group_arn]
    }
  }
}

resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for ${local.name} VPC flow log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.flow_logs_kms.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-flow-logs-kms"
  })
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/${local.name}-flow-logs"
  target_key_id = aws_kms_key.flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = local.flow_log_group_name
  retention_in_days = 365
  kms_key_id        = aws_kms_key.flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name}-flow-logs"
  })
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "${local.name}-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-flow-logs-role"
  })
}

data "aws_iam_policy_document" "flow_logs_publish" {
  statement {
    sid    = "PublishFlowLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]

    resources = [
      aws_cloudwatch_log_group.flow_logs.arn,
      "${aws_cloudwatch_log_group.flow_logs.arn}:*",
    ]
  }

  statement {
    sid       = "DescribeLogGroups"
    effect    = "Allow"
    actions   = ["logs:DescribeLogGroups"]
    resources = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"]
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name   = "${local.name}-flow-logs-publish"
  role   = aws_iam_role.flow_logs.id
  policy = data.aws_iam_policy_document.flow_logs_publish.json
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn             = aws_iam_role.flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.common_tags, {
    Name = "${local.name}-flow-log"
  })

  depends_on = [aws_iam_role_policy.flow_logs]
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway."
  value       = aws_nat_gateway.main.id
}

output "nat_public_ip" {
  description = "Public IP address of the NAT gateway's Elastic IP."
  value       = aws_eip.nat.public_ip
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

locals {
  dev_name     = "dev"
  test_name    = "test"
  any_ipv4     = "0.0.0.0/0"
  subnet_count = 2

  # Public IPs are never assigned subnet-wide by default (Trivy AWS-0164).
  map_public_ip = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPCs
# ---------------------------------------------------------------------------

resource "aws_vpc" "dev" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = local.dev_name
  })
}

resource "aws_vpc" "test" {
  cidr_block           = "172.24.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = local.test_name
  })
}

# ---------------------------------------------------------------------------
# Default security groups (deny all)
# ---------------------------------------------------------------------------

resource "aws_default_security_group" "dev" {
  vpc_id = aws_vpc.dev.id

  tags = merge(var.tags, {
    Name = "${local.dev_name}-default-sg"
  })
}

resource "aws_default_security_group" "test" {
  vpc_id = aws_vpc.test.id

  tags = merge(var.tags, {
    Name = "${local.test_name}-default-sg"
  })
}

# ---------------------------------------------------------------------------
# Subnets - dev
# ---------------------------------------------------------------------------

# Public subnets are public because their route table has a 0.0.0.0/0 route
# to the VPC's internet gateway. Workloads that need a public IP should request
# one per instance (e.g. associate_public_ip_address on the instance or launch
# template) rather than receiving one subnet-wide by default.
resource "aws_subnet" "dev_public" {
  count = local.subnet_count

  vpc_id                  = aws_vpc.dev.id
  cidr_block              = cidrsubnet(aws_vpc.dev.cidr_block, 8, 101 + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = local.map_public_ip

  tags = merge(var.tags, {
    Name = "${local.dev_name}-public-${count.index + 1}"
  })
}

resource "aws_subnet" "dev_private" {
  count = local.subnet_count

  vpc_id                  = aws_vpc.dev.id
  cidr_block              = cidrsubnet(aws_vpc.dev.cidr_block, 8, 1 + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = local.map_public_ip

  tags = merge(var.tags, {
    Name = "${local.dev_name}-private-${count.index + 1}"
  })
}

# ---------------------------------------------------------------------------
# Subnets - test
# ---------------------------------------------------------------------------

# Public via IGW route in the public route table; no default public IP
# assignment (request per instance where required).
resource "aws_subnet" "test_public" {
  count = local.subnet_count

  vpc_id                  = aws_vpc.test.id
  cidr_block              = cidrsubnet(aws_vpc.test.cidr_block, 8, 101 + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = local.map_public_ip

  tags = merge(var.tags, {
    Name = "${local.test_name}-public-${count.index + 1}"
  })
}

resource "aws_subnet" "test_private" {
  count = local.subnet_count

  vpc_id                  = aws_vpc.test.id
  cidr_block              = cidrsubnet(aws_vpc.test.cidr_block, 8, 1 + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = local.map_public_ip

  tags = merge(var.tags, {
    Name = "${local.test_name}-private-${count.index + 1}"
  })
}

# ---------------------------------------------------------------------------
# Internet gateways
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "dev" {
  vpc_id = aws_vpc.dev.id

  tags = merge(var.tags, {
    Name = "${local.dev_name}-igw"
  })
}

resource "aws_internet_gateway" "test" {
  vpc_id = aws_vpc.test.id

  tags = merge(var.tags, {
    Name = "${local.test_name}-igw"
  })
}

# ---------------------------------------------------------------------------
# Route tables - dev
# ---------------------------------------------------------------------------

resource "aws_route_table" "dev_public" {
  vpc_id = aws_vpc.dev.id

  route {
    cidr_block = local.any_ipv4
    gateway_id = aws_internet_gateway.dev.id
  }

  tags = merge(var.tags, {
    Name = "${local.dev_name}-public-rt"
  })
}

resource "aws_route_table" "dev_private" {
  vpc_id = aws_vpc.dev.id

  tags = merge(var.tags, {
    Name = "${local.dev_name}-private-rt"
  })
}

resource "aws_route_table_association" "dev_public" {
  count = local.subnet_count

  subnet_id      = aws_subnet.dev_public[count.index].id
  route_table_id = aws_route_table.dev_public.id
}

resource "aws_route_table_association" "dev_private" {
  count = local.subnet_count

  subnet_id      = aws_subnet.dev_private[count.index].id
  route_table_id = aws_route_table.dev_private.id
}

# ---------------------------------------------------------------------------
# Route tables - test
# ---------------------------------------------------------------------------

resource "aws_route_table" "test_public" {
  vpc_id = aws_vpc.test.id

  route {
    cidr_block = local.any_ipv4
    gateway_id = aws_internet_gateway.test.id
  }

  tags = merge(var.tags, {
    Name = "${local.test_name}-public-rt"
  })
}

resource "aws_route_table" "test_private" {
  vpc_id = aws_vpc.test.id

  tags = merge(var.tags, {
    Name = "${local.test_name}-private-rt"
  })
}

resource "aws_route_table_association" "test_public" {
  count = local.subnet_count

  subnet_id      = aws_subnet.test_public[count.index].id
  route_table_id = aws_route_table.test_public.id
}

resource "aws_route_table_association" "test_private" {
  count = local.subnet_count

  subnet_id      = aws_subnet.test_private[count.index].id
  route_table_id = aws_route_table.test_private.id
}

# ---------------------------------------------------------------------------
# VPC peering
# ---------------------------------------------------------------------------

resource "aws_vpc_peering_connection" "dev_test" {
  vpc_id      = aws_vpc.dev.id
  peer_vpc_id = aws_vpc.test.id
  auto_accept = true

  tags = merge(var.tags, {
    Name = "${local.dev_name}-${local.test_name}-vpc-peer"
  })
}

resource "aws_vpc_peering_connection_options" "dev_test" {
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  accepter {
    allow_remote_vpc_dns_resolution = true
  }
}

# ---------------------------------------------------------------------------
# Peering routes
# ---------------------------------------------------------------------------

resource "aws_route" "dev_public_to_test" {
  route_table_id            = aws_route_table.dev_public.id
  destination_cidr_block    = aws_vpc.test.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "dev_private_to_test" {
  route_table_id            = aws_route_table.dev_private.id
  destination_cidr_block    = aws_vpc.test.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "test_public_to_dev" {
  route_table_id            = aws_route_table.test_public.id
  destination_cidr_block    = aws_vpc.dev.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "test_private_to_dev" {
  route_table_id            = aws_route_table.test_private.id
  destination_cidr_block    = aws_vpc.dev.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "dev_vpc_id" {
  description = "ID of the dev VPC."
  value       = aws_vpc.dev.id
}

output "test_vpc_id" {
  description = "ID of the test VPC."
  value       = aws_vpc.test.id
}

output "dev_public_subnet_ids" {
  description = "IDs of the dev public subnets."
  value       = aws_subnet.dev_public[*].id
}

output "dev_private_subnet_ids" {
  description = "IDs of the dev private subnets."
  value       = aws_subnet.dev_private[*].id
}

output "test_public_subnet_ids" {
  description = "IDs of the test public subnets."
  value       = aws_subnet.test_public[*].id
}

output "test_private_subnet_ids" {
  description = "IDs of the test private subnets."
  value       = aws_subnet.test_private[*].id
}

output "vpc_peering_connection_id" {
  description = "ID of the dev-test VPC peering connection."
  value       = aws_vpc_peering_connection.dev_test.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The deployment harness supplies the AWS provider configuration (region us-east-1),
# so this file has no provider "aws" block.

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

locals {
  common_tags = merge(var.tags, { Environment = var.environment })

  ec2_describe_policy_description = "Allows EC2 describe actions only"
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name               = "test-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role" "test_role2" {
  name               = "test-role2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = local.common_tags
}

# EC2 Describe APIs do not support resource-level permissions, so "*" is required
# for resources. Actions are limited to read-only ec2:Describe* calls.
data "aws_iam_policy_document" "ec2_describe" {
  statement {
    effect    = "Allow"
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "test_policy" {
  name        = "test-policy"
  description = local.ec2_describe_policy_description
  policy      = data.aws_iam_policy_document.ec2_describe.json
  tags        = local.common_tags
}

resource "aws_iam_policy" "test_policy2" {
  name        = "test-policy2"
  description = local.ec2_describe_policy_description
  policy      = data.aws_iam_policy_document.ec2_describe.json
  tags        = local.common_tags
}

resource "aws_iam_policy" "test_policy3" {
  name        = "test-policy3"
  description = local.ec2_describe_policy_description
  policy      = data.aws_iam_policy_document.ec2_describe.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "test_role_test_policy" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_role2_test_policy" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_role_test_policy2" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

resource "aws_iam_role_policy_attachment" "test_role2_test_policy2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

# This block stands in for the requested named attachment "test-attachment5".
# It attaches test-policy3 to both roles without taking exclusive control of
# the policy's attachments, which aws_iam_policy_attachment would do.
resource "aws_iam_role_policy_attachment" "test_attachment5" {
  for_each = {
    "test-role"  = aws_iam_role.test_role.name
    "test-role2" = aws_iam_role.test_role2.name
  }

  role       = each.value
  policy_arn = aws_iam_policy.test_policy3.arn
}

output "test_role_arn" {
  description = "ARN of the test-role IAM role."
  value       = aws_iam_role.test_role.arn
}

output "test_role2_arn" {
  description = "ARN of the test-role2 IAM role."
  value       = aws_iam_role.test_role2.arn
}

output "test_policy_arn" {
  description = "ARN of the test-policy IAM policy."
  value       = aws_iam_policy.test_policy.arn
}

output "test_policy2_arn" {
  description = "ARN of the test-policy2 IAM policy."
  value       = aws_iam_policy.test_policy2.arn
}

output "test_policy3_arn" {
  description = "ARN of the test-policy3 IAM policy."
  value       = aws_iam_policy.test_policy3.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role assumed by GitHub Actions through OIDC web identity federation."
  type        = string
  default     = "github-actions-oidc-role"
}

variable "subject_repository_patterns" {
  description = "List of GitHub OIDC subject patterns allowed to assume the role (e.g. \"my-org/my-repo:*\" or \"my-org/*:ref:refs/heads/main\"). Each entry gets the \"repo:\" prefix. When empty, no repository can assume the role."
  type        = list(string)
  default     = []
}

variable "managed_policy_arns" {
  description = "List of IAM managed policy ARNs to attach to the role. No policies are attached by default."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

locals {
  oidc_host     = "token.actions.githubusercontent.com"
  oidc_url      = "https://${local.oidc_host}"
  oidc_audience = "sts.amazonaws.com"

  github_subjects = [for p in var.subject_repository_patterns : "repo:${p}"]

  effective_subjects = length(local.github_subjects) > 0 ? local.github_subjects : ["repo:__no-repository-allowed__/__none__:*"]

  role_tags = merge(var.tags, {
    Name = var.role_name
  })
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = local.oidc_url
  client_id_list = [local.oidc_audience]
  thumbprint_list = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]

  tags = var.tags
}

data "aws_iam_policy_document" "github_oidc_trust" {
  statement {
    sid     = "GitHubActionsOidcAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_host}:iss"
      values   = [local.oidc_url]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_host}:aud"
      values   = [local.oidc_audience]
    }

    condition {
      test     = "StringLike"
      variable = "${local.oidc_host}:sub"
      values   = local.effective_subjects
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  path                  = "/"
  description           = "IAM role assumed by GitHub Actions via OIDC web identity federation."
  assume_role_policy    = data.aws_iam_policy_document.github_oidc_trust.json
  force_detach_policies = true
  max_session_duration  = 3600

  tags = local.role_tags
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.github_actions.name
  policy_arn = each.value
}

output "role_arn" {
  description = "ARN of the GitHub Actions OIDC IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "role_name" {
  description = "Name of the GitHub Actions OIDC IAM role."
  value       = aws_iam_role.github_actions.name
}

output "role_path" {
  description = "Path of the GitHub Actions OIDC IAM role."
  value       = aws_iam_role.github_actions.path
}

output "role_unique_id" {
  description = "Unique ID of the GitHub Actions OIDC IAM role."
  value       = aws_iam_role.github_actions.unique_id
}

output "oidc_provider_arn" {
  description = "ARN of the GitHub Actions OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The deployment harness injects the provider configuration (region us-east-1),
# so this file does not declare a provider "aws" block.

variable "tags" {
  description = "Tags applied to the managed force-MFA IAM policy."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "force-mfa"
  }
}

data "aws_partition" "current" {}

locals {
  policy_name        = "managed-force-mfa-policy"
  policy_path        = "/"
  policy_description = "Allows IAM users to view account info and manage their own password and virtual MFA; MFA deactivation and self-inspection require an MFA-authenticated session"

  iam_arn_prefix      = "arn:${data.aws_partition.current.partition}:iam::*"
  own_user_arn        = "${local.iam_arn_prefix}:user/$${aws:username}"
  own_mfa_device_arn  = "${local.iam_arn_prefix}:mfa/$${aws:username}"
  mfa_present_key     = "aws:MultiFactorAuthPresent"
  mfa_present_test    = "Bool"
  mfa_present_value   = "true"
}

data "aws_iam_policy_document" "force_mfa" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListAccountAliases",
      "iam:ListVirtualMFADevices",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]
    resources = [local.own_user_arn]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]
    resources = [local.own_mfa_device_arn]
  }

  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = [local.own_user_arn]
  }

  statement {
    sid    = "AllowDeactivateOwnMFAOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = [local.own_user_arn]

    condition {
      test     = local.mfa_present_test
      variable = local.mfa_present_key
      values   = [local.mfa_present_value]
    }
  }

  statement {
    sid    = "AllowSelfInspectionOnlyWhenUsingMFA"
    effect = "Allow"
    actions = [
      "iam:GetLoginProfile",
      "iam:ListAccessKeys",
      "iam:ListSigningCertificates",
      "iam:ListSSHPublicKeys",
      "iam:ListServiceSpecificCredentials",
      "iam:ListGroupsForUser",
      "iam:ListAttachedUserPolicies",
      "iam:ListUserPolicies",
    ]
    resources = [local.own_user_arn]

    condition {
      test     = local.mfa_present_test
      variable = local.mfa_present_key
      values   = [local.mfa_present_value]
    }
  }
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = local.policy_name
  path        = local.policy_path
  description = local.policy_description
  policy      = data.aws_iam_policy_document.force_mfa.json
  tags        = var.tags
}

output "managed_force_mfa_policy_arn" {
  description = "ARN of the managed force-MFA policy. Attach it with aws_iam_user_policy_attachment or aws_iam_group_policy_attachment."
  value       = aws_iam_policy.managed_force_mfa_policy.arn
}

output "managed_force_mfa_policy_name" {
  description = "Name of the managed force-MFA policy."
  value       = aws_iam_policy.managed_force_mfa_policy.name
}

output "managed_force_mfa_policy_id" {
  description = "ID of the managed force-MFA policy."
  value       = aws_iam_policy.managed_force_mfa_policy.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to every taggable IAM resource."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "team-iam-access"
  }
}

locals {
  iam_path = "/"
}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
  path = local.iam_path
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
  path = local.iam_path
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
  path = local.iam_path
}

# -----------------------------------------------------------------------------
# Users
# -----------------------------------------------------------------------------

resource "aws_iam_user" "billing" {
  name          = "Billing"
  path          = local.iam_path
  force_destroy = true
  tags          = var.tags
}

resource "aws_iam_user" "admin" {
  name          = "Admin"
  path          = local.iam_path
  force_destroy = true
  tags          = var.tags
}

resource "aws_iam_user" "suport" {
  name          = "Suport"
  path          = local.iam_path
  force_destroy = true
  tags          = var.tags
}

# -----------------------------------------------------------------------------
# Group memberships (non-exclusive)
# -----------------------------------------------------------------------------

resource "aws_iam_user_group_membership" "billing_membership" {
  user   = aws_iam_user.billing.name
  groups = [aws_iam_group.billing_group.name]
}

resource "aws_iam_user_group_membership" "admin_membership" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin_group.name]
}

resource "aws_iam_user_group_membership" "suport_membership" {
  user   = aws_iam_user.suport.name
  groups = [aws_iam_group.suport_group.name]
}

# -----------------------------------------------------------------------------
# Console login profiles (generated passwords)
# -----------------------------------------------------------------------------

resource "aws_iam_user_login_profile" "billing_login" {
  user                    = aws_iam_user.billing.name
  password_length         = 8
  password_reset_required = true

  lifecycle {
    ignore_changes = [password_length, password_reset_required, pgp_key]
  }
}

resource "aws_iam_user_login_profile" "admin_login" {
  user                    = aws_iam_user.admin.name
  password_length         = 8
  password_reset_required = true

  lifecycle {
    ignore_changes = [password_length, password_reset_required, pgp_key]
  }
}

resource "aws_iam_user_login_profile" "suport_login" {
  user                    = aws_iam_user.suport.name
  password_length         = 8
  password_reset_required = true

  lifecycle {
    ignore_changes = [password_length, password_reset_required, pgp_key]
  }
}

# -----------------------------------------------------------------------------
# Policy documents
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "billing_policy" {
  statement {
    sid    = "BillingReadOnly"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ViewAccount",
      "budgets:ViewBudget",
      "budgets:Describe*",
      "cur:DescribeReportDefinitions",
      "ce:Get*",
      "ce:Describe*",
      "ce:List*",
      "pricing:DescribeServices",
      "pricing:GetAttributeValues",
      "pricing:GetProducts",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "suport_policy" {
  statement {
    sid    = "SupportReadOnly"
    effect = "Allow"
    actions = [
      "ec2:Describe*",
      "ec2:Get*",
      "s3:Get*",
      "s3:List*",
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "rds:Describe*",
      "rds:List*",
    ]
    resources = ["*"]
  }
}

# -----------------------------------------------------------------------------
# Customer-managed policies
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  path        = local.iam_path
  description = "Read-only access to billing, usage, budgets, cost reports, and pricing."
  policy      = data.aws_iam_policy_document.billing_policy.json
  tags        = var.tags
}

resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  path        = local.iam_path
  description = "Read-only describe, get, and list access to EC2, S3, CloudWatch, and RDS."
  policy      = data.aws_iam_policy_document.suport_policy.json
  tags        = var.tags
}

# -----------------------------------------------------------------------------
# Group policy attachments
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "billing_attach" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "admin_attach" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "suport_attach" {
  group      = aws_iam_group.suport_group.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "billing_username" {
  description = "Username of the billing user."
  value       = aws_iam_user.billing.name
}

output "billing_password" {
  description = "Generated initial console password for the billing user."
  value       = aws_iam_user_login_profile.billing_login.password
  sensitive   = true
}

output "admin_username" {
  description = "Username of the admin user."
  value       = aws_iam_user.admin.name
}

output "admin_password" {
  description = "Generated initial console password for the admin user."
  value       = aws_iam_user_login_profile.admin_login.password
  sensitive   = true
}

output "suport_username" {
  description = "Username of the support user."
  value       = aws_iam_user.suport.name
}

output "suport_password" {
  description = "Generated initial console password for the support user."
  value       = aws_iam_user_login_profile.suport_login.password
  sensitive   = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Required by objective 2. If the deployment harness already injects a
# default aws provider configuration, remove this block to avoid a
# duplicate provider configuration error.
provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for naming and tagging."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    var.tags,
    {
      Name        = "shared-storage-test-efs"
      Environment = var.environment
      Purpose     = "shared-storage-testing"
      ManagedBy   = "terraform"
    }
  )
}

resource "aws_efs_file_system" "shared_storage" {
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "shared_storage" {
  file_system_id = aws_efs_file_system.shared_storage.id

  backup_policy {
    status = "ENABLED"
  }
}

output "efs_file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.shared_storage.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system."
  value       = aws_efs_file_system.shared_storage.arn
}

output "efs_dns_name" {
  description = "DNS name of the EFS file system."
  value       = aws_efs_file_system.shared_storage.dns_name
}

output "efs_creation_token" {
  description = "Terraform-generated creation token of the EFS file system."
  value       = aws_efs_file_system.shared_storage.creation_token
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "nlp-pipeline"
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  state_bucket_name = "my-terraform-state-bucket-${local.account_id}"
  lock_table_name   = "terraform-locks"

  nlp_bucket_name        = "nlp-pipeline-bucket"
  nlp_bucket_arn         = "arn:${local.partition}:s3:::${local.nlp_bucket_name}"
  nlp_bucket_objects_arn = "${local.nlp_bucket_arn}/*"

  nlp_results_table_name = "NLPResults"
  nlp_results_table_arn  = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/${local.nlp_results_table_name}"

  state_machine_name = "YourStateMachineName"
  state_machine_arn  = "arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:${local.state_machine_name}"

  lambda_functions_arn = "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
  glue_jobs_arn        = "arn:${local.partition}:glue:${local.region}:${local.account_id}:job/*"

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"
}

# ---------------------------------------------------------------------------
# KMS key for Terraform state encryption
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "terraform_state_kms" {
  statement {
    sid       = "EnableAccountRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }
}

resource "aws_kms_key" "terraform_state" {
  description             = "Customer-managed key for Terraform remote state encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.terraform_state_kms.json
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state"
  target_key_id = aws_kms_key.terraform_state.key_id
}

# ---------------------------------------------------------------------------
# S3 bucket for Terraform remote state
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "terraform_state" {
  bucket = local.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

data "aws_iam_policy_document" "terraform_state_bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.terraform_state.arn,
      "${aws_s3_bucket.terraform_state.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  policy = data.aws_iam_policy_document.terraform_state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.terraform_state]
}

# ---------------------------------------------------------------------------
# DynamoDB table for Terraform state locking
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "terraform_locks" {
  name         = local.lock_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.terraform_state.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Shared least-privilege S3 object access policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "s3_object_access" {
  statement {
    sid       = "NlpBucketObjectReadWrite"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject"]
    resources = [local.nlp_bucket_objects_arn]
  }
}

# ---------------------------------------------------------------------------
# Glue service role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "glue_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "glue_service_role" {
  name               = "glue-service-role"
  assume_role_policy = data.aws_iam_policy_document.glue_assume_role.json
}

resource "aws_iam_role_policy_attachment" "glue_service_role_managed" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_s3_access" {
  name   = "glue-nlp-bucket-object-access"
  role   = aws_iam_role.glue_service_role.id
  policy = data.aws_iam_policy_document.s3_object_access.json
}

# ---------------------------------------------------------------------------
# Comprehend service role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "comprehend_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["comprehend.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "comprehend_service_role" {
  name               = "comprehend-service-role"
  assume_role_policy = data.aws_iam_policy_document.comprehend_assume_role.json
}

resource "aws_iam_role_policy" "comprehend_s3_access" {
  name   = "comprehend-nlp-bucket-object-access"
  role   = aws_iam_role.comprehend_service_role.id
  policy = data.aws_iam_policy_document.s3_object_access.json
}

# ---------------------------------------------------------------------------
# Lambda execution role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name               = "lambda-execution-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "lambda_pipeline_access" {
  statement {
    sid       = "NlpBucketObjectReadWrite"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject"]
    resources = [local.nlp_bucket_objects_arn]
  }

  statement {
    sid    = "NlpResultsTableWrite"
    effect = "Allow"
    actions = [
      "dynamodb:PutItem",
      "dynamodb:UpdateItem",
      "dynamodb:BatchWriteItem",
    ]
    resources = [local.nlp_results_table_arn]
  }

  statement {
    sid       = "StartPipelineStateMachine"
    effect    = "Allow"
    actions   = ["states:StartExecution"]
    resources = [local.state_machine_arn]
  }
}

resource "aws_iam_role_policy" "lambda_pipeline_access" {
  name   = "lambda-nlp-pipeline-access"
  role   = aws_iam_role.lambda_execution_role.id
  policy = data.aws_iam_policy_document.lambda_pipeline_access.json
}

# ---------------------------------------------------------------------------
# Step Functions service role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "sfn_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "step_functions_service_role" {
  name               = "step-functions-service-role"
  assume_role_policy = data.aws_iam_policy_document.sfn_assume_role.json
}

data "aws_iam_policy_document" "sfn_orchestration_access" {
  statement {
    sid       = "InvokeLambdaFunctions"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = [local.lambda_functions_arn]
  }

  statement {
    sid       = "StartGlueJobRuns"
    effect    = "Allow"
    actions   = ["glue:StartJobRun"]
    resources = [local.glue_jobs_arn]
  }
}

resource "aws_iam_role_policy" "sfn_orchestration_access" {
  name   = "sfn-nlp-orchestration-access"
  role   = aws_iam_role.step_functions_service_role.id
  policy = data.aws_iam_policy_document.sfn_orchestration_access.json
}

