terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

locals {
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }

  zenml_version = "0.12.0"
  stack_name    = "demo-stack"

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  artifact_bucket_name = "demo-artifact-store-${local.account_id}"
  artifact_store_path  = "s3://${aws_s3_bucket.artifact_store.bucket}"
  ecr_registry_uri     = "${data.aws_caller_identity.current.account_id}.dkr.ecr.${data.aws_region.current.name}.amazonaws.com"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_kms_key" "artifact_store" {
  description             = "Customer-managed KMS key for the ZenML artifact store bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  key_usage               = "ENCRYPT_DECRYPT"

  tags = local.tags
}

resource "aws_kms_alias" "artifact_store" {
  name          = "alias/zenml-artifact-store"
  target_key_id = aws_kms_key.artifact_store.key_id
}

resource "aws_s3_bucket" "artifact_store" {
  bucket        = local.artifact_bucket_name
  force_destroy = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifact_store.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = "zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.artifact_store.arn
  }

  tags = local.tags
}

resource "local_file" "zenml_stack" {
  filename        = "${path.module}/${local.stack_name}.yaml"
  file_permission = "0644"

  content = yamlencode({
    zenml_version = local.zenml_version
    stack_name    = local.stack_name
    components = {
      artifact_store = {
        flavor = "s3"
        name   = "s3_artifact_store"
        path   = local.artifact_store_path
      }
      container_registry = {
        flavor  = "aws"
        name    = "ecr_registry"
        uri     = local.ecr_registry_uri
        _repo   = aws_ecr_repository.zenml_kubernetes.name
      }
      secrets_manager = {
        flavor      = "aws"
        name        = "aws_secrets_manager"
        region_name = local.region
      }
      orchestrator = {
        flavor = "local"
        name   = "default"
      }
    }
  })

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.artifact_store,
    aws_s3_bucket_public_access_block.artifact_store,
    aws_s3_bucket_ownership_controls.artifact_store,
    aws_s3_bucket_versioning.artifact_store,
    aws_ecr_repository.zenml_kubernetes,
  ]
}

output "artifact_store_bucket_name" {
  description = "Name of the ZenML S3 artifact store bucket"
  value       = aws_s3_bucket.artifact_store.bucket
}

output "artifact_store_path" {
  description = "S3 path of the ZenML artifact store"
  value       = local.artifact_store_path
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the artifact store"
  value       = aws_kms_key.artifact_store.arn
}

output "ecr_repository_url" {
  description = "URL of the zenml-kubernetes ECR repository"
  value       = aws_ecr_repository.zenml_kubernetes.repository_url
}

output "ecr_registry_uri" {
  description = "Root URI of the account's ECR registry"
  value       = local.ecr_registry_uri
}

output "zenml_stack_file" {
  description = "Path to the generated ZenML stack YAML file"
  value       = local_file.zenml_stack.filename
}

# Region us-east-1 is set by the provider configuration that the deployment harness injects.
# A provider block is left out on purpose so it doesn't clash with that injected configuration.

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Base prefix used for all resource names."
  type        = string
  default     = "nim"
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "nim"
    ManagedBy = "terraform"
  }
}

variable "registry_username" {
  description = "Container registry username stored in the repository credential secret."
  type        = string
  default     = "AWS"
}

variable "registry_password" {
  description = "Container registry password stored in the repository credential secret. Supply it outside of code (e.g. TF_VAR_registry_password)."
  type        = string
  sensitive   = true
  default     = ""
}

locals {
  ecs_task_execution_role_name_prefix = "${var.name_prefix}-ecs_task_execution-"
  repo_secret_name_prefix             = "${var.name_prefix}-reposecret-"
  ecs_task_execution_managed_policy   = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "ECSTasksAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name_prefix        = local.ecs_task_execution_role_name_prefix
  description        = "ECS task execution role for ${var.name_prefix} tasks."
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_managed" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = local.ecs_task_execution_managed_policy
}

resource "aws_secretsmanager_secret" "repo_secret" {
  name_prefix = local.repo_secret_name_prefix
  description = "Container registry credentials for ${var.name_prefix} ECS tasks."

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "repo_secret" {
  secret_id = aws_secretsmanager_secret.repo_secret.id
  secret_string = jsonencode({
    username = var.registry_username
    password = var.registry_password
  })
}

data "aws_iam_policy_document" "ecs_task_access_secrets" {
  statement {
    sid       = "ReadRepoSecretValue"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.repo_secret.arn]
  }
}

resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name   = "ECSTaskAccessSecretsPolicy"
  role   = aws_iam_role.ecs_task_execution.id
  policy = data.aws_iam_policy_document.ecs_task_access_secrets.json
}

output "ecs_task_execution_role_arn" {
  description = "ARN of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution.arn
}

output "ecs_task_execution_role_name" {
  description = "Name of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution.name
}

output "repo_secret_arn" {
  description = "ARN of the container registry credential secret."
  value       = aws_secretsmanager_secret.repo_secret.arn
}

output "repo_secret_name" {
  description = "Name of the container registry credential secret."
  value       = aws_secretsmanager_secret.repo_secret.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "aws_service_access_principals" {
  description = "List of AWS service principal names to integrate with AWS Organizations. Defaults to none."
  type        = list(string)
  default     = []
}

variable "organizational_units" {
  description = "List of slash-delimited organizational unit paths (e.g. \"Workloads/Prod/AppA\"), up to five levels deep. Defaults to empty so no OUs are created."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for p in var.organizational_units : length(split("/", p)) <= 5])
    error_message = "Each organizational unit path must be at most five levels deep."
  }

  validation {
    condition = alltrue([
      for p in var.organizational_units : alltrue([
        for s in split("/", p) : length(trimspace(s)) > 0 && trimspace(s) == s
      ])
    ])
    error_message = "Organizational unit paths must not be empty, contain empty segments, leading/trailing slashes, double slashes, or segments with leading/trailing whitespace."
  }

  validation {
    condition = alltrue([
      for p in var.organizational_units : alltrue([
        for s in split("/", p) : length(s) <= 128
      ])
    ])
    error_message = "Each organizational unit name segment must be 128 characters or fewer."
  }

  validation {
    condition     = length(distinct(var.organizational_units)) == length(var.organizational_units)
    error_message = "Organizational unit paths must be unique."
  }
}

variable "tags" {
  description = "Tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

locals {
  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]

  ou_all_paths = distinct(flatten([
    for p in var.organizational_units : [
      for i in range(1, length(split("/", p)) + 1) : join("/", slice(split("/", p), 0, i))
    ]
  ]))

  ou_level_1 = {
    for p in local.ou_all_paths : p => {
      name        = p
      parent_path = null
    } if length(split("/", p)) == 1
  }

  ou_level_2 = {
    for p in local.ou_all_paths : p => {
      name        = element(split("/", p), 1)
      parent_path = join("/", slice(split("/", p), 0, 1))
    } if length(split("/", p)) == 2
  }

  ou_level_3 = {
    for p in local.ou_all_paths : p => {
      name        = element(split("/", p), 2)
      parent_path = join("/", slice(split("/", p), 0, 2))
    } if length(split("/", p)) == 3
  }

  ou_level_4 = {
    for p in local.ou_all_paths : p => {
      name        = element(split("/", p), 3)
      parent_path = join("/", slice(split("/", p), 0, 3))
    } if length(split("/", p)) == 4
  }

  ou_level_5 = {
    for p in local.ou_all_paths : p => {
      name        = element(split("/", p), 4)
      parent_path = join("/", slice(split("/", p), 0, 4))
    } if length(split("/", p)) == 5
  }

  root_id = aws_organizations_organization.main.roots[0].id
}

resource "aws_organizations_organization" "main" {
  feature_set                   = "ALL"
  enabled_policy_types          = local.enabled_policy_types
  aws_service_access_principals = var.aws_service_access_principals

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_organizations_organizational_unit" "level_1" {
  for_each = local.ou_level_1

  name      = each.value.name
  parent_id = local.root_id
  tags      = var.tags
}

resource "aws_organizations_organizational_unit" "level_2" {
  for_each = local.ou_level_2

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_1[each.value.parent_path].id
  tags      = var.tags
}

resource "aws_organizations_organizational_unit" "level_3" {
  for_each = local.ou_level_3

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_2[each.value.parent_path].id
  tags      = var.tags
}

resource "aws_organizations_organizational_unit" "level_4" {
  for_each = local.ou_level_4

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_3[each.value.parent_path].id
  tags      = var.tags
}

resource "aws_organizations_organizational_unit" "level_5" {
  for_each = local.ou_level_5

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_4[each.value.parent_path].id
  tags      = var.tags
}

output "organization_id" {
  description = "The ID of the AWS Organization."
  value       = aws_organizations_organization.main.id
}

output "organization_arn" {
  description = "The ARN of the AWS Organization."
  value       = aws_organizations_organization.main.arn
}

output "master_account_id" {
  description = "The ID of the management (master) account."
  value       = aws_organizations_organization.main.master_account_id
}

output "root_id" {
  description = "The ID of the organization root."
  value       = local.root_id
}

output "enabled_policy_types" {
  description = "Policy types enabled on the organization root."
  value       = aws_organizations_organization.main.enabled_policy_types
}

output "organizational_unit_ids" {
  description = "Map of full slash-delimited OU path to OU ID."
  value = merge(
    { for k, v in aws_organizations_organizational_unit.level_1 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_2 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_3 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_4 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_5 : k => v.id },
  )
}

output "organizational_unit_arns" {
  description = "Map of full slash-delimited OU path to OU ARN."
  value = merge(
    { for k, v in aws_organizations_organizational_unit.level_1 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_2 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_3 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_4 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level_5 : k => v.arn },
  )
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "resource_group" {
  description = "Value for the ResourceGroup tag applied to all resources."
  type        = string
  default     = "default"
}

locals {
  vpc_name = "swe-vpc"

  any_ipv4_cidr = "0.0.0.0/0"

  common_tags = {
    ResourceGroup = var.resource_group
  }
}

resource "aws_vpc" "swe_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_default_network_acl" "swe_vpc_default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = aws_vpc.swe_vpc.cidr_block
  }

  ingress {
    rule_no    = 110
    action     = "deny"
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidr_block = local.any_ipv4_cidr
  }

  ingress {
    rule_no    = 120
    action     = "deny"
    protocol   = "tcp"
    from_port  = 3389
    to_port    = 3389
    cidr_block = local.any_ipv4_cidr
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = aws_vpc.swe_vpc.cidr_block
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-default_acl"
  })
}

resource "aws_default_security_group" "swe_vpc_default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-default_sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "swe_vpc_default_sg_icmp_echo" {
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  description       = "Allow ICMP echo (ping) from anywhere"
  ip_protocol       = "icmp"
  from_port         = 8
  to_port           = 0
  cidr_ipv4         = local.any_ipv4_cidr

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-default_sg-icmp-echo"
  })
}

resource "aws_vpc_security_group_ingress_rule" "swe_vpc_default_sg_http" {
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  description       = "Allow HTTP from anywhere"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = local.any_ipv4_cidr

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-default_sg-http"
  })
}

output "vpc_id" {
  description = "ID of the swe-vpc VPC."
  value       = aws_vpc.swe_vpc.id
}

output "default_network_acl_id" {
  description = "ID of the VPC's managed default network ACL."
  value       = aws_default_network_acl.swe_vpc_default_acl.id
}

output "default_security_group_id" {
  description = "ID of the VPC's managed default security group."
  value       = aws_default_security_group.swe_vpc_default_sg.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project_tags" {
  description = "Shared tags merged into every resource"
  type        = map(string)
  default = {
    Project   = "dev-rec-network"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_a = data.aws_availability_zones.available.names[0]
  az_b = data.aws_availability_zones.available.names[1]

  env_dev = "dev"
  env_rec = "rec"

  tier_public   = "public"
  tier_internal = "internal"
  tier_external = "external"

  ipv4_default_route = "0.0.0.0/0"
  ipv6_default_route = "::/0"
}

# ---------------------------------------------------------------------------
# VPCs
# ---------------------------------------------------------------------------

resource "aws_vpc" "vpc_dev" {
  cidr_block                       = "10.16.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(var.project_tags, {
    Name        = "vpc_dev"
    Environment = local.env_dev
  })
}

resource "aws_vpc" "vpc_rec" {
  cidr_block                       = "10.32.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(var.project_tags, {
    Name        = "vpc_rec"
    Environment = local.env_rec
  })
}

# ---------------------------------------------------------------------------
# Dev subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "subnet_dev_public_a" {
  vpc_id                  = aws_vpc.vpc_dev.id
  cidr_block              = "10.16.12.0/24"
  availability_zone       = local.az_a
  map_public_ip_on_launch = false

  tags = merge(var.project_tags, {
    Name        = "subnet_dev_public_a"
    Tier        = local.tier_public
    Environment = local.env_dev
  })
}

resource "aws_subnet" "subnet_dev_public_b" {
  vpc_id                  = aws_vpc.vpc_dev.id
  cidr_block              = "10.16.11.0/24"
  availability_zone       = local.az_b
  map_public_ip_on_launch = false

  tags = merge(var.project_tags, {
    Name        = "subnet_dev_public_b"
    Tier        = local.tier_public
    Environment = local.env_dev
  })
}

resource "aws_subnet" "subnet_dev_internal_a" {
  vpc_id                  = aws_vpc.vpc_dev.id
  cidr_block              = "10.16.1.0/24"
  availability_zone       = local.az_a
  map_public_ip_on_launch = false

  tags = merge(var.project_tags, {
    Name        = "subnet_dev_internal_a"
    Tier        = local.tier_internal
    Environment = local.env_dev
  })
}

