# Outputs
# ---------------------------------------------------------------------------

output "vpc_dev_id" {
  description = "ID of the development VPC"
  value       = aws_vpc.vpc_dev.id
}

output "vpc_rec_id" {
  description = "ID of the recette (staging) VPC"
