}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enabled" {
  description = "Master switch controlling whether any resources are created."
  type        = bool
  default     = true
}

variable "namespace" {
  description = "Cloud Posse label namespace (e.g. organization abbreviation)."
  type        = string
  default     = "eg"
}

variable "stage" {
  description = "Cloud Posse label stage (e.g. prod, staging, dev)."
  type        = string
  default     = "prod"
}

variable "name" {
  description = "Cloud Posse label name."
  type        = string
  default     = "guardduty"
}

variable "delimiter" {
  description = "Delimiter used between label components."
  type        = string
  default     = "-"
}

variable "attributes" {
  description = "Additional attributes appended to the label ID."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

variable "finding_publishing_frequency" {
  description = "Frequency of notifications for updated findings. Null leaves the AWS service default (SIX_HOURS)."
  type        = string
  default     = null
}

variable "s3_protection_enabled" {
  description = "Whether GuardDuty S3 data-event (S3 logs) protection is enabled."
  type        = bool
  default     = false
}

variable "create_sns_topic" {
  description = "Whether to create an SNS topic for GuardDuty findings notifications."
  type        = bool
  default     = false
}

variable "findings_notification_arn" {
  description = "ARN of an existing notification target (e.g. SNS topic) for GuardDuty findings. Ignored when create_sns_topic is true."
  type        = string
  default     = null
}

variable "subscribers" {
  description = "Map of SNS subscriptions to create on the findings topic."
  type = map(object({
    protocol               = string
    endpoint               = string
    endpoint_auto_confirms = bool
    raw_message_delivery   = bool
  }))
  default = {}
}

variable "cloudwatch_event_rule_pattern_detail_type" {
  description = "The detail-type matched by the EventBridge rule for GuardDuty findings."
  type        = string
  default     = "GuardDuty Finding"
}

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled    = var.enabled
  namespace  = var.namespace
  stage      = var.stage
  name       = var.name
  delimiter  = var.delimiter
  attributes = var.attributes
  tags       = var.tags
}

locals {
  enabled                   = var.enabled && module.this.enabled
  create_sns_topic          = local.enabled && var.create_sns_topic
  create_notification       = local.enabled && (var.create_sns_topic || var.findings_notification_arn != null)
  findings_resource_name    = "${module.this.id}-findings"
  findings_notification_arn = local.create_sns_topic ? aws_sns_topic.findings[0].arn : var.findings_notification_arn
}

resource "aws_guardduty_detector" "guardduty" {
  count = local.enabled ? 1 : 0

  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = var.s3_protection_enabled
    }
  }

  tags = module.this.tags
}

resource "aws_sns_topic" "findings" {
  count = local.create_sns_topic ? 1 : 0

  name              = local.findings_resource_name
  kms_master_key_id = "alias/aws/sns"

  tags = module.this.tags
}

resource "aws_sns_topic_subscription" "findings" {
  for_each = local.create_sns_topic ? var.subscribers : {}

  topic_arn              = aws_sns_topic.findings[0].arn
  protocol               = each.value.protocol
  endpoint               = each.value.endpoint
  endpoint_auto_confirms = each.value.endpoint_auto_confirms
  raw_message_delivery   = each.value.raw_message_delivery
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = local.create_sns_topic ? 1 : 0

  statement {
    sid       = "AllowEventBridgePublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "findings" {
  count = local.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.findings[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

resource "aws_cloudwatch_event_rule" "findings" {
  count = local.create_notification ? 1 : 0

  name        = local.findings_resource_name
  description = "Routes GuardDuty findings to the notification target."

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = [var.cloudwatch_event_rule_pattern_detail_type]
  })

  tags = module.this.tags
}

resource "aws_cloudwatch_event_target" "findings" {
  count = local.create_notification ? 1 : 0

  rule = aws_cloudwatch_event_rule.findings[0].name
  arn  = local.findings_notification_arn
}

output "guardduty_detector_id" {
  description = "ID of the GuardDuty detector (null when disabled)."
  value       = one(aws_guardduty_detector.guardduty[*].id)
}

output "guardduty_detector_arn" {
  description = "ARN of the GuardDuty detector (null when disabled)."
  value       = one(aws_guardduty_detector.guardduty[*].arn)
}

output "guardduty_detector_account_id" {
  description = "AWS account ID of the GuardDuty detector (null when disabled)."
  value       = one(aws_guardduty_detector.guardduty[*].account_id)
}

output "sns_topic_arn" {
  description = "ARN of the findings SNS topic (null when not created)."
  value       = one(aws_sns_topic.findings[*].arn)
}

output "sns_topic_name" {
  description = "Name of the findings SNS topic (null when not created)."
  value       = one(aws_sns_topic.findings[*].name)
}

output "sns_topic_subscriptions" {
  description = "Map of SNS topic subscription ARNs keyed by subscriber name (empty when none created)."
  value       = { for k, v in aws_sns_topic_subscription.findings : k => v.arn }
}

output "cloudwatch_event_rule_arn" {
  description = "ARN of the EventBridge rule for findings (null when not created)."
  value       = one(aws_cloudwatch_event_rule.findings[*].arn)
}

output "cloudwatch_event_rule_name" {
  description = "Name of the EventBridge rule for findings (null when not created)."
  value       = one(aws_cloudwatch_event_rule.findings[*].name)
}

output "findings_notification_arn" {
  description = "ARN of the notification target used for findings (null when notifications are disabled)."
  value       = local.create_notification ? local.findings_notification_arn : null
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "= 3.6.3"
    }
  }
}

# The provider "aws" block (region = "us-east-1") is supplied by the deployment harness.

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "sudo-backup"
    ManagedBy = "terraform"
  }
}

resource "random_string" "suffix" {
  length  = 6
  upper   = false
  lower   = true
  numeric = true
  special = false
}

locals {
  name_prefix     = "sudo-backup-${random_string.suffix.result}"
  vault_name      = "${local.name_prefix}-backup-vault"
  plan_name       = "${local.name_prefix}-backup-plan"
  rule_name       = "${local.name_prefix}-backup-rule"
  role_name       = "${local.name_prefix}-backup-role"
  selection_name  = "${local.name_prefix}-backup-selection"
  backup_schedule = "cron(0 12 * * ? *)"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_iam_role" "backup" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAWSBackupAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, {
    Name = local.role_name
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_kms_key" "backup" {
  description             = "Customer-managed KMS key for AWS Backup vault encryption (${local.name_prefix})"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAWSBackupRoleUseOfKey"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.backup.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "backup.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-backup-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.name_prefix}-backup-key"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "main" {
  name        = local.vault_name
  kms_key_arn = aws_kms_key.backup.arn

  tags = merge(var.tags, {
    Name = local.vault_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "main" {
  name = local.plan_name

  rule {
    rule_name         = local.rule_name
    target_vault_name = aws_backup_vault.main.name
    schedule          = local.backup_schedule

    recovery_point_tags = merge(var.tags, {
      Name = local.rule_name
    })
  }

  tags = merge(var.tags, {
    Name = local.plan_name
  })
}

resource "aws_backup_selection" "main" {
  name         = local.selection_name
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.main.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

output "name_prefix" {
  description = "Generated resource name prefix."
  value       = local.name_prefix
}

output "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  value       = aws_backup_vault.main.name
}

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.main.arn
}

output "backup_plan_id" {
  description = "ID of the AWS Backup plan."
  value       = aws_backup_plan.main.id
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan."
  value       = aws_backup_plan.main.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used to encrypt the backup vault."
  value       = aws_kms_key.backup.arn
}

output "backup_role_arn" {
  description = "ARN of the IAM role assumed by AWS Backup."
  value       = aws_iam_role.backup.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "app_name" {
  description = "Application name used for resource naming."
  type        = string
  default     = "coop-tweets"
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Application = "coop-tweets"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  user_pool_name        = var.app_name
  user_pool_domain      = "${var.app_name}-domain"
  identity_pool_name    = "coop tweets"
  auth_role_name        = "${var.app_name}_cognito_auth_role"
  unauth_role_name      = "${var.app_name}_cognito_unauth_role"
  auth_policy_name      = "cognito_kibana_auth_${var.app_name}"
  unauth_policy_name    = "cognito_kibana_unauth_${var.app_name}"
  cognito_identity_svc  = "cognito-identity.amazonaws.com"
  identity_pool_arn     = "arn:aws:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.coop_tweets.id}"
  sync_identity_pool_arn = "arn:aws:cognito-sync:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.coop_tweets.id}"

  cognito_policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "MobileAnalyticsPutEvents"
        Effect   = "Allow"
        Action   = ["mobileanalytics:PutEvents"]
        Resource = "*"
      },
      {
        Sid    = "CognitoSyncScopedToIdentityPool"
        Effect = "Allow"
        Action = ["cognito-sync:*"]
        Resource = [
          local.sync_identity_pool_arn,
          "${local.sync_identity_pool_arn}/*"
        ]
      },
      {
        Sid      = "CognitoIdentityScopedToIdentityPool"
        Effect   = "Allow"
        Action   = ["cognito-identity:*"]
        Resource = [local.identity_pool_arn]
      },
      {
        Sid    = "CognitoIdentityCredentialCalls"
        Effect = "Allow"
        Action = [
          "cognito-identity:GetId",
          "cognito-identity:GetCredentialsForIdentity",
          "cognito-identity:GetOpenIdToken"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cognito_user_pool" "coop_tweets" {
  name = local.user_pool_name

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
  }

  tags = var.tags
}

resource "aws_cognito_user_pool_domain" "coop_tweets" {
  domain       = local.user_pool_domain
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
}

resource "aws_cognito_identity_pool" "coop_tweets" {
  identity_pool_name               = local.identity_pool_name
  allow_unauthenticated_identities = false

  tags = var.tags
}

resource "aws_iam_role" "cognito_auth_role" {
  name = local.auth_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = local.cognito_identity_svc
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role" "cognito_unauth_role" {
  name = local.unauth_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = local.cognito_identity_svc
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "unauthenticated"
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "cognito_auth_policy" {
  name        = local.auth_policy_name
  description = "Authenticated Cognito identity permissions for ${var.app_name}"
  policy      = local.cognito_policy_document

  tags = var.tags
}

resource "aws_iam_policy" "cognito_unauth_policy" {
  name        = local.unauth_policy_name
  description = "Unauthenticated Cognito identity permissions for ${var.app_name}"
  policy      = local.cognito_policy_document

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "cognito_auth_attach" {
  role       = aws_iam_role.cognito_auth_role.name
  policy_arn = aws_iam_policy.cognito_auth_policy.arn
}

resource "aws_iam_role_policy_attachment" "cognito_unauth_attach" {
  role       = aws_iam_role.cognito_unauth_role.name
  policy_arn = aws_iam_policy.cognito_unauth_policy.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "coop_tweets" {
  identity_pool_id = aws_cognito_identity_pool.coop_tweets.id

  roles = {
    "authenticated"   = aws_iam_role.cognito_auth_role.arn
    "unauthenticated" = aws_iam_role.cognito_unauth_role.arn
  }
}

output "user_pool_id" {
  description = "ID of the Cognito user pool."
  value       = aws_cognito_user_pool.coop_tweets.id
}

output "user_pool_domain" {
  description = "Hosted Cognito user pool domain prefix."
  value       = aws_cognito_user_pool_domain.coop_tweets.domain
}

output "identity_pool_id" {
  description = "ID of the Cognito identity pool."
  value       = aws_cognito_identity_pool.coop_tweets.id
}

output "cognito_auth_role_arn" {
  description = "ARN of the authenticated identity IAM role."
  value       = aws_iam_role.cognito_auth_role.arn
}

output "cognito_unauth_role_arn" {
  description = "ARN of the unauthenticated identity IAM role."
  value       = aws_iam_role.cognito_unauth_role.arn
}

# GuardDuty detector, KMS key, EventBridge rule and optional S3 findings export
#
# Note: the AWS provider configuration (region = "us-east-1") is supplied by
# the deployment harness. It is not declared here because a second provider
# block would make the configuration invalid. All ARNs are built at runtime
# from the caller identity, partition and region data sources.

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "enable_s3_export" {
  description = "Set to true to export GuardDuty findings to a KMS-encrypted S3 bucket."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "guardduty"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  account_id   = data.aws_caller_identity.current.account_id
  partition    = data.aws_partition.current.partition
  region       = data.aws_region.current.name
  root_arn     = "arn:${local.partition}:iam::${local.account_id}:root"
  service_name = "guardduty.amazonaws.com"
  kms_alias    = "alias/guardduty"
  rule_name    = "guardduty-finding-events"
  export_count = var.enable_s3_export ? 1 : 0
  bucket_name  = "guardduty-findings-${local.account_id}-${local.region}"
}

# -----------------------------------------------------------------------------
# GuardDuty detector
# -----------------------------------------------------------------------------

resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = var.tags
}

# -----------------------------------------------------------------------------
# KMS key for encrypting findings exports
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "guardduty_kms" {
  # Documented root-admin statement: the account keeps full administration of
  # the key so it can never become unmanageable.
  statement {
    sid       = "EnableRootAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.root_arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyGenerateDataKey"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey"]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = [local.service_name]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.main.arn]
    }
  }
}

resource "aws_kms_key" "guardduty" {
  description             = "Customer-managed key for encrypting GuardDuty findings exports"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.guardduty_kms.json

  tags = var.tags
}

resource "aws_kms_alias" "guardduty" {
  name          = local.kms_alias
  target_key_id = aws_kms_key.guardduty.key_id
}

# -----------------------------------------------------------------------------
# EventBridge rule for GuardDuty findings
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  name        = local.rule_name
  description = "Matches GuardDuty Finding events published on the default event bus"
  state       = "ENABLED"

  event_pattern = jsonencode({
    source        = ["aws.guardduty"]
    "detail-type" = ["GuardDuty Finding"]
  })

  tags = var.tags

  depends_on = [aws_guardduty_detector.main]
}

# -----------------------------------------------------------------------------
# Optional S3 findings export (disabled by default)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "guardduty_findings" {
  count = local.export_count

  bucket        = local.bucket_name
  force_destroy = false

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_findings" {
  count = local.export_count

  bucket = aws_s3_bucket.guardduty_findings[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "guardduty_findings" {
  count = local.export_count

  bucket = aws_s3_bucket.guardduty_findings[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_findings" {
  count = local.export_count

  bucket = aws_s3_bucket.guardduty_findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "guardduty_findings" {
  count = local.export_count

  bucket = aws_s3_bucket.guardduty_findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "guardduty_findings_bucket" {
  count = local.export_count

  statement {
    sid       = "AllowGuardDutyGetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.guardduty_findings[0].arn]

    principals {
      type        = "Service"
      identifiers = [local.service_name]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.main.arn]
    }
  }

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.guardduty_findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = [local.service_name]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.main.arn]
    }
  }

  statement {
    sid       = "DenyIncorrectEncryptionKey"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.guardduty_findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = [local.service_name]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.guardduty.arn]
    }
  }

  statement {
    sid     = "DenyNonHttpsAccess"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.guardduty_findings[0].arn,
      "${aws_s3_bucket.guardduty_findings[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "guardduty_findings" {
  count = local.export_count

  bucket = aws_s3_bucket.guardduty_findings[0].id
  policy = data.aws_iam_policy_document.guardduty_findings_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.guardduty_findings]
}

resource "aws_guardduty_publishing_destination" "s3" {
  count = local.export_count

  detector_id      = aws_guardduty_detector.main.id
  destination_arn  = aws_s3_bucket.guardduty_findings[0].arn
  kms_key_arn      = aws_kms_key.guardduty.arn
  destination_type = "S3"

  depends_on = [
    aws_s3_bucket_policy.guardduty_findings,
    aws_s3_bucket_server_side_encryption_configuration.guardduty_findings,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "guardduty_detector_id" {
  description = "ID of the GuardDuty detector."
  value       = aws_guardduty_detector.main.id
}

output "guardduty_detector_arn" {
  description = "ARN of the GuardDuty detector."
  value       = aws_guardduty_detector.main.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used to encrypt GuardDuty findings exports."
  value       = aws_kms_key.guardduty.arn
}

output "kms_key_id" {
  description = "ID of the KMS key used to encrypt GuardDuty findings exports."
  value       = aws_kms_key.guardduty.key_id
}

output "kms_alias_name" {
  description = "Alias of the GuardDuty KMS key."
  value       = aws_kms_alias.guardduty.name
}

output "event_rule_name" {
  description = "Name of the EventBridge rule matching GuardDuty findings."
  value       = aws_cloudwatch_event_rule.guardduty_findings.name
}

output "event_rule_arn" {
  description = "ARN of the EventBridge rule matching GuardDuty findings."
  value       = aws_cloudwatch_event_rule.guardduty_findings.arn
}

output "findings_bucket_name" {
  description = "Name of the S3 findings export bucket (null when export is disabled)."
  value       = var.enable_s3_export ? aws_s3_bucket.guardduty_findings[0].id : null
}

output "findings_bucket_arn" {
  description = "ARN of the S3 findings export bucket (null when export is disabled)."
  value       = var.enable_s3_export ? aws_s3_bucket.guardduty_findings[0].arn : null
}

output "publishing_destination_id" {
  description = "ID of the GuardDuty S3 publishing destination (null when export is disabled)."
  value       = var.enable_s3_export ? aws_guardduty_publishing_destination.s3[0].id : null
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The provider "aws" block (region = "us-east-1") is not declared here.
# The deployment harness injects the provider configuration.

variable "tags" {
  description = "Tags applied to the private S3 bucket and its KMS key."
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_kms_key" "private_bucket" {
  description             = "Customer managed key for S3 server-side encryption of the private bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableOwningAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = var.tags

  # Deleting this key makes every object encrypted with it unreadable.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "private_bucket" {
  # No bucket or bucket_prefix is set, so the provider generates a unique name.
  force_destroy = true

  tags = var.tags

  # Required for stateful buckets. force_destroy only takes effect after an
  # operator deliberately removes this guard.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "private_bucket" {
  name          = "alias/private-bucket-${aws_s3_bucket.private_bucket.id}"
  target_key_id = aws_kms_key.private_bucket.key_id
}

resource "aws_s3_bucket_public_access_block" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }

  depends_on = [aws_s3_bucket_public_access_block.private_bucket]
}

# The "private canned ACL" requirement is met without aws_s3_bucket_acl.
# Every new S3 bucket gets the owner-only private ACL by default. The four
# public access block settings and the BucketOwnerPreferred ownership
# controls keep the bucket private.

resource "aws_s3_bucket_versioning" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.private_bucket,
    aws_s3_bucket_public_access_block.private_bucket,
  ]
}

# Deliberate change from the original request: SSE-KMS with a customer managed
# key (aws_kms_key.private_bucket) replaces the requested SSE-S3 (AES256) to
# satisfy Trivy AWS-0132. S3 Bucket Keys stay enabled to reduce KMS request costs.
resource "aws_s3_bucket_server_side_encryption_configuration" "private_bucket" {
  bucket = aws_s3_bucket.private_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.private_bucket.arn
    }
    bucket_key_enabled = true
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.private_bucket,
    aws_s3_bucket_public_access_block.private_bucket,
  ]
}

output "bucket_name" {
  description = "Auto-generated name of the private S3 bucket."
  value       = aws_s3_bucket.private_bucket.id
}

output "bucket_arn" {
  description = "ARN of the private S3 bucket."
  value       = aws_s3_bucket.private_bucket.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting the bucket."
  value       = aws_kms_key.private_bucket.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "billing_full_access_users" {
  description = "IAM user names to add to the billing-full-access group."
  type        = list(string)
  default     = []
}

variable "billing_view_access_users" {
  description = "IAM user names to add to the billing-view-access group."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to every taggable IAM role and IAM policy."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "billing-access-delegation"
  }
}

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  billing_full_access_name = "billing-full-access"
  billing_view_access_name = "billing-view-access"
  iam_path                 = "/"
}

data "aws_iam_policy_document" "billing_assume_role" {
  statement {
    sid     = "AllowAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "billing_full_access" {
  name                 = local.billing_full_access_name
  path                 = local.iam_path
  description          = "Role granting full access to the AWS billing console. Requires MFA to assume."
  assume_role_policy   = data.aws_iam_policy_document.billing_assume_role.json
  max_session_duration = 3600
  tags                 = var.tags
}

resource "aws_iam_role" "billing_view_access" {
  name                 = local.billing_view_access_name
  path                 = local.iam_path
  description          = "Role granting view-only access to the AWS billing console. Requires MFA to assume."
  assume_role_policy   = data.aws_iam_policy_document.billing_assume_role.json
  max_session_duration = 3600
  tags                 = var.tags
}

data "aws_iam_policy_document" "billing_full_access" {
  statement {
    sid    = "FullBillingManagement"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ModifyBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ViewAccount",
      "aws-portal:ModifyAccount",
      "aws-portal:ViewPaymentMethods",
      "aws-portal:ModifyPaymentMethods",
      "billing:*",
      "payments:*",
      "budgets:*",
      "ce:*",
      "cur:*",
      "invoicing:*",
      "tax:*",
      "purchase-orders:*",
      "consolidatedbilling:*",
      "freetier:*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = local.billing_full_access_name
  path        = local.iam_path
  description = "Allows full management of billing, usage, payment methods, and budgets."
  policy      = data.aws_iam_policy_document.billing_full_access.json
  tags        = var.tags
}

data "aws_iam_policy_document" "billing_view_access" {
  statement {
    sid    = "ViewBillingOnly"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ViewAccount",
      "aws-portal:ViewPaymentMethods",
      "billing:Get*",
      "billing:List*",
      "payments:Get*",
      "payments:List*",
      "budgets:ViewBudget",
      "budgets:Describe*",
      "ce:Get*",
      "ce:Describe*",
      "ce:List*",
      "cur:Describe*",
      "cur:Get*",
      "invoicing:Get*",
      "invoicing:List*",
      "consolidatedbilling:Get*",
      "consolidatedbilling:List*",
      "freetier:Get*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = local.billing_view_access_name
  path        = local.iam_path
  description = "Allows viewing billing, usage, account, payment methods, and budgets only."
  policy      = data.aws_iam_policy_document.billing_view_access.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

resource "aws_iam_group" "billing_full_access" {
  name = local.billing_full_access_name
  path = local.iam_path
}

resource "aws_iam_group" "billing_view_access" {
  name = local.billing_view_access_name
  path = local.iam_path
}

data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    sid       = "AllowAssumeBillingFullAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
  }
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    sid       = "AllowAssumeBillingViewAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
  }
}

resource "aws_iam_group_policy" "billing_full_access_assume_role" {
  name   = "${local.billing_full_access_name}-assume-role"
  group  = aws_iam_group.billing_full_access.name
  policy = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

resource "aws_iam_group_policy" "billing_view_access_assume_role" {
  name   = "${local.billing_view_access_name}-assume-role"
  group  = aws_iam_group.billing_view_access.name
  policy = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

resource "aws_iam_group_membership" "billing_full_access" {
  count = length(var.billing_full_access_users) > 0 ? 1 : 0

  name  = "${local.billing_full_access_name}-membership"
  group = aws_iam_group.billing_full_access.name
  users = var.billing_full_access_users
}

resource "aws_iam_group_membership" "billing_view_access" {
  count = length(var.billing_view_access_users) > 0 ? 1 : 0

  name  = "${local.billing_view_access_name}-membership"
  group = aws_iam_group.billing_view_access.name
  users = var.billing_view_access_users
}

output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access IAM role."
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access IAM role."
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access IAM group."
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access IAM group."
  value       = aws_iam_group.billing_view_access.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "= 3.6.3"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = merge(
      {
        Project   = var.name
        ManagedBy = "terraform"
      },
      var.tags
    )
  }
}

variable "name" {
  description = "Base name used for all resources."
  type        = string
  default     = "cognito"
}

variable "tags" {
  description = "Additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

resource "random_string" "sms_external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = false
  special = false
}

locals {
  name                      = "${var.name}-${random_pet.suffix.id}"
  user_pool_name            = replace(local.name, "-", "_")
  partition                 = data.aws_partition.current.partition
  region                    = data.aws_region.current.name
  account_id                = data.aws_caller_identity.current.account_id
  cognito_identity_service  = "cognito-identity.amazonaws.com"
  cognito_idp_service       = "cognito-idp.amazonaws.com"
  identity_pool_arn         = "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
  sync_identity_pool_arn    = "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
  string_attribute_max_size = 2048
}

################################################################################
# SMS role for Cognito User Pool
################################################################################

data "aws_iam_policy_document" "cognito_sms_trust" {
  statement {
    sid     = "AllowCognitoIdpAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.cognito_idp_service]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.sms_external_id.result]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "cognito_sms" {
  name               = "${local.name}-sms"
  assume_role_policy = data.aws_iam_policy_document.cognito_sms_trust.json
}

data "aws_iam_policy_document" "cognito_sms_publish" {
  statement {
    sid       = "AllowSnsPublishForSms"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "cognito_sms_publish" {
  name   = "${local.name}-sms-publish"
  role   = aws_iam_role.cognito_sms.id
  policy = data.aws_iam_policy_document.cognito_sms_publish.json
}

################################################################################
# Cognito User Pool
################################################################################

resource "aws_cognito_user_pool" "main" {
  name                     = local.user_pool_name
  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]

  sms_configuration {
    external_id    = random_string.sms_external_id.result
    sns_caller_arn = aws_iam_role.cognito_sms.arn
    sns_region     = local.region
  }

  schema {
    name                     = "email"
    attribute_data_type      = "String"
    required                 = true
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "phone_number"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "profile_user_id"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "profile_email"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "profile_first_name"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "profile_last_name"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "profile_gender"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "profile_age"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  schema {
    name                     = "profile_persona"
    attribute_data_type      = "String"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = 0
      max_length = local.string_attribute_max_size
    }
  }

  depends_on = [aws_iam_role_policy.cognito_sms_publish]

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [schema]
  }
}

resource "aws_cognito_user_pool_client" "main" {
  name         = "${local.name}-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret               = false
  prevent_user_existence_errors = "ENABLED"
  enable_token_revocation       = true

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

################################################################################
# Cognito Identity Pool
################################################################################

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.user_pool_name
  allow_unauthenticated_identities = true
  allow_classic_flow               = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.main.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }
}

data "aws_iam_policy_document" "signed_users_trust" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [local.cognito_identity_service]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.cognito_identity_service}:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "${local.cognito_identity_service}:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "signed_users" {
  name               = "${local.name}-signed-users"
  assume_role_policy = data.aws_iam_policy_document.signed_users_trust.json
}

data "aws_iam_policy_document" "anonymous_users_trust" {
  statement {
    sid     = "AllowCognitoUnauthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [local.cognito_identity_service]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.cognito_identity_service}:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "${local.cognito_identity_service}:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "anonymous_users" {
  name               = "${local.name}-anonymous-users"
  assume_role_policy = data.aws_iam_policy_document.anonymous_users_trust.json
}

data "aws_iam_policy_document" "signed_users" {
  statement {
    sid       = "AllowCognitoIdentityOnPool"
    effect    = "Allow"
    actions   = ["cognito-identity:*"]
    resources = [local.identity_pool_arn]
  }

  statement {
    sid     = "AllowCognitoSyncOnPool"
    effect  = "Allow"
    actions = ["cognito-sync:*"]
    resources = [
      local.sync_identity_pool_arn,
      "${local.sync_identity_pool_arn}/*",
    ]
  }
}

resource "aws_iam_role_policy" "signed_users" {
  name   = "${local.name}-signed-users"
  role   = aws_iam_role.signed_users.id
  policy = data.aws_iam_policy_document.signed_users.json
}

data "aws_iam_policy_document" "anonymous_users" {
  statement {
    sid       = "AllowCognitoIdentityOnPool"
    effect    = "Allow"
    actions   = ["cognito-identity:*"]
    resources = [local.identity_pool_arn]
  }
}

resource "aws_iam_role_policy" "anonymous_users" {
  name   = "${local.name}-anonymous-users"
  role   = aws_iam_role.anonymous_users.id
  policy = data.aws_iam_policy_document.anonymous_users.json
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated   = aws_iam_role.signed_users.arn
    unauthenticated = aws_iam_role.anonymous_users.arn
  }
}

################################################################################
# Outputs
################################################################################

output "name" {
  description = "Generated base name for all resources."
  value       = local.name
}

output "user_pool_id" {
  description = "ID of the Cognito user pool."
  value       = aws_cognito_user_pool.main.id
}

output "user_pool_arn" {
  description = "ARN of the Cognito user pool."
  value       = aws_cognito_user_pool.main.arn
}

output "user_pool_endpoint" {
  description = "Endpoint of the Cognito user pool."
  value       = aws_cognito_user_pool.main.endpoint
}

output "user_pool_client_id" {
  description = "ID of the Cognito user pool app client."
  value       = aws_cognito_user_pool_client.main.id
}

output "identity_pool_id" {
  description = "ID of the Cognito identity pool."
  value       = aws_cognito_identity_pool.main.id
}

output "identity_pool_arn" {
  description = "ARN of the Cognito identity pool."
  value       = aws_cognito_identity_pool.main.arn
}

output "signed_users_role_arn" {
  description = "ARN of the IAM role for authenticated identities."
  value       = aws_iam_role.signed_users.arn
}

output "anonymous_users_role_arn" {
  description = "ARN of the IAM role for unauthenticated identities."
  value       = aws_iam_role.anonymous_users.arn
}

output "sms_role_arn" {
  description = "ARN of the IAM role Cognito assumes to send SMS."
  value       = aws_iam_role.cognito_sms.arn
}

output "partition" {
  description = "Current AWS partition."
  value       = local.partition
}

output "region" {
  description = "Current AWS region."
  value       = local.region
}

output "account_id" {
  description = "Current AWS account ID."
  value       = local.account_id
}

# Terraform configuration for the provider block is injected by the deployment harness.
# Objective 2 asks for provider "aws" { region = "us-east-1" }. It is left out on purpose,
# because a second provider configuration would conflict with the injected one.
# Deploy to us-east-1. Tags are set on each resource instead of through default_tags.

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  name_prefix = "${terraform.workspace}-batch"
  vpc_cidr    = "192.168.0.0/16"

  common_tags = {
    Name        = local.name_prefix
    Environment = terraform.workspace
    Project     = "batch"
  }

  results_bucket_name = "benchmark-batch-results-${data.aws_caller_identity.current.account_id}"

  interface_endpoint_services = toset([
    "ecs",
    "ecs-agent",
    "ecs-telemetry",
    "ecr.api",
    "ecr.dkr",
    "logs",
  ])
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "batch_compute" {
  name        = "${local.name_prefix}-sg"
  description = "Batch compute instances - HTTPS egress to VPC endpoints only"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "HTTPS to VPC CIDR (VPC interface endpoints)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpce-sg"
  description = "VPC interface endpoints - HTTPS from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-sg"
  })
}

# -----------------------------------------------------------------------------
# VPC endpoints. With these, instances limited to HTTPS egress inside the VPC
# can still reach ECS, ECR, CloudWatch Logs and S3.
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${replace(each.value, ".", "-")}-vpce"
  })
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-gateway-vpce"
  })
}

# The S3 interface endpoint uses private DNS for all in-VPC resolvers. S3 names then
# resolve to addresses inside the VPC CIDR, so the HTTPS-to-VPC-CIDR egress rule covers
# S3 traffic, including ECR image layer downloads.
resource "aws_vpc_endpoint" "s3_interface" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  dns_options {
    dns_record_ip_type                             = "ipv4"
    private_dns_only_for_inbound_resolver_endpoint = false
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-interface-vpce"
  })

  depends_on = [aws_vpc_endpoint.s3_gateway]
}

# -----------------------------------------------------------------------------
# KMS + S3 results bucket
# -----------------------------------------------------------------------------

resource "aws_kms_key" "s3" {
  description             = "KMS key for ${local.name_prefix} S3 results bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-kms"
  })
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${local.name_prefix}-s3"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket" "results" {
  bucket = local.results_bucket_name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-results"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM - ECS instance role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ecs_instance_role" {
  name = "${local.name_prefix}-ecs-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ecs-instance-role"
  })
}

resource "aws_iam_role_policy_attachment" "ecs_instance_role" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_policy" "ecs_s3_policy" {
  name        = "${local.name_prefix}-ecs_s3_policy"
  description = "S3 read/list access plus read/write/delete on the ${local.name_prefix} results bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ReadList"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:ListAllMyBuckets"
        ]
        Resource = "*"
      },
      {
        Sid    = "ResultsBucketReadWriteDelete"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.results.arn,
          "${aws_s3_bucket.results.arn}/*"
        ]
      },
      {
        Sid    = "ResultsBucketKms"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.s3.arn
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ecs_s3_policy"
  })
}

resource "aws_iam_role_policy_attachment" "ecs_s3_policy" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = aws_iam_policy.ecs_s3_policy.arn
}

resource "aws_iam_instance_profile" "ecs_instance_profile" {
  name = "${local.name_prefix}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance_role.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ecs-instance-profile"
  })
}

# -----------------------------------------------------------------------------
# IAM - Batch service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "batch_service_role" {
  name = "${local.name_prefix}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-service-role"
  })
}

resource "aws_iam_role_policy_attachment" "batch_service_role" {
  role       = aws_iam_role.batch_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBatchServiceRole"
}

# -----------------------------------------------------------------------------
# AWS Batch
# -----------------------------------------------------------------------------

resource "aws_batch_compute_environment" "main" {
  compute_environment_name = local.name_prefix
  type                     = "MANAGED"
  state                    = "ENABLED"
  service_role             = aws_iam_role.batch_service_role.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    instance_type       = ["optimal"]
    min_vcpus           = 0
    max_vcpus           = 4
    instance_role       = aws_iam_instance_profile.ecs_instance_profile.arn
    subnets             = [aws_subnet.private.id]
    security_group_ids  = [aws_security_group.batch_compute.id]

    ec2_configuration {
      image_type = "ECS_AL2023"
    }

    tags = merge(local.common_tags, {
      Name = "${local.name_prefix}-compute"
    })
  }

  tags = merge(local.common_tags, {
    Name = local.name_prefix
  })

  depends_on = [
    aws_iam_role_policy_attachment.batch_service_role,
    aws_iam_role_policy_attachment.ecs_instance_role,
    aws_iam_role_policy_attachment.ecs_s3_policy,
    aws_route_table_association.private,
    aws_nat_gateway.main,
    aws_vpc_endpoint.interface,
    aws_vpc_endpoint.s3_gateway,
    aws_vpc_endpoint.s3_interface,
  ]
}

resource "aws_batch_job_queue" "main" {
  name     = "${local.name_prefix}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environment_order {
    order               = 1
    compute_environment = aws_batch_compute_environment.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-queue"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the Batch VPC"
  value       = aws_vpc.main.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "batch_compute_environment_arn" {
  description = "ARN of the Batch compute environment"
  value       = aws_batch_compute_environment.main.arn
}

output "batch_job_queue_arn" {
  description = "ARN of the Batch job queue"
  value       = aws_batch_job_queue.main.arn
}

output "results_bucket_name" {
  description = "Name of the S3 results bucket"
  value       = aws_s3_bucket.results.bucket
}

output "kms_key_arn" {
  description = "ARN of the KMS key encrypting the results bucket"
  value       = aws_kms_key.s3.arn
}

# main.tf
#
# Provider configuration (region = "us-east-1") is injected by the deployment
# harness, so no provider "aws" block is declared here.
#
# ENCRYPTION DEVIATION NOTICE (Trivy AWS-0132):
# The original request asked for default server-side encryption using
# S3-managed keys (SSE-S3 / AES256). This configuration uses SSE-KMS with a
# dedicated customer-managed KMS key (CMK) instead. The key rotates
# automatically, and S3 Bucket Keys are enabled. This change was needed to pass
# the HIGH-severity Trivy check AWS-0132 ("S3 encryption should use Customer
# Managed Keys") without any scanner suppression. To go back to SSE-S3
# (AES256), the pipeline owner must first approve a scanner exception.
# The IAM user's KMS decrypt and data-key access is scoped to this CMK, and
# only through S3.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "endpoint-backup"
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_name     = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
  iam_user_name   = "endpoint-backup"
  iam_policy_name = "endpoint-backup-bucket-read-write-access"
  kms_alias_name  = "alias/endpoint-backup"
  account_root    = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer-managed KMS key that encrypts the ${local.bucket_name} endpoint-backup S3 bucket."
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket              = local.bucket_name
  object_lock_enabled = false
  force_destroy       = false
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default encryption uses SSE-KMS with the dedicated CMK to meet AWS-0132.
# See the deviation notice at the top of this file.
resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

data "aws_iam_policy_document" "endpoint_backup_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyOutdatedTLS"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceLockOver90Days"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.endpoint_backup]
}

resource "aws_iam_user" "endpoint_backup" {
  name = local.iam_user_name
  path = "/"
  tags = var.tags
}

data "aws_iam_policy_document" "endpoint_backup_rw" {
  statement {
    sid    = "BucketList"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListBucketMultipartUploads",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetBucketObjectLockConfiguration",
    ]

    resources = [aws_s3_bucket.endpoint_backup.arn]
  }

  statement {
    sid    = "ObjectReadWriteDeleteVersionRetentionRestore"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectAttributes",
      "s3:GetObjectVersionAttributes",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:RestoreObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "BucketCmkAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.endpoint_backup.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "endpoint_backup_rw" {
  name        = local.iam_policy_name
  path        = "/"
  description = "Least-privilege read, write, delete, version, retention, and restore access to the ${local.bucket_name} bucket, plus decrypt/data-key use of the bucket's customer-managed KMS key via S3."
  policy      = data.aws_iam_policy_document.endpoint_backup_rw.json
  tags        = var.tags
}

resource "aws_iam_user_policy_attachment" "endpoint_backup_rw" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_rw.arn
}

output "bucket_name" {
  description = "Name of the endpoint backup S3 bucket."
  value       = aws_s3_bucket.endpoint_backup.id
}

output "bucket_arn" {
  description = "ARN of the endpoint backup S3 bucket."
  value       = aws_s3_bucket.endpoint_backup.arn
}

output "iam_user_name" {
  description = "Name of the endpoint backup IAM user."
  value       = aws_iam_user.endpoint_backup.name
}

output "iam_user_arn" {
  description = "ARN of the endpoint backup IAM user."
  value       = aws_iam_user.endpoint_backup.arn
}

output "iam_policy_arn" {
  description = "ARN of the endpoint backup bucket read/write IAM policy."
  value       = aws_iam_policy.endpoint_backup_rw.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the endpoint backup bucket."
  value       = aws_kms_key.endpoint_backup.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Tags applied to every resource that supports tagging."
  type        = map(string)
  default = {
    project   = "unity"
    component = "shared-services"
  }
}

variable "uds_distribution_callback_urls" {
  description = "Callback URLs for the unity-uds-distribution-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/test/data/login"]
}

variable "uds_distribution_logout_urls" {
  description = "Logout URLs for the unity-uds-distribution-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/test/data/logout"]
}

variable "localhost_jupyterhub_callback_urls" {
  description = "Callback URLs for the localhost-jupyterhub-user-pool-client app client."
  type        = list(string)
  default     = ["http://localhost:8000/hub/oauth_callback"]
}

variable "localhost_jupyterhub_logout_urls" {
  description = "Logout URLs for the localhost-jupyterhub-user-pool-client app client."
  type        = list(string)
  default     = ["http://localhost:8000/hub/logout"]
}

variable "app_to_app_callback_urls" {
  description = "Callback URLs for the unity-app-to-app-client-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/test/app-to-app/callback"]
}

variable "app_to_app_logout_urls" {
  description = "Logout URLs for the unity-app-to-app-client-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/test/app-to-app/logout"]
}

variable "jupyter_development_callback_urls" {
  description = "Callback URLs for the uads-jupyter-development-client-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/dev/jupyter/hub/oauth_callback"]
}

variable "jupyter_development_logout_urls" {
  description = "Logout URLs for the uads-jupyter-development-client-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/dev/jupyter/hub/logout"]
}

variable "hysds_ui_callback_urls" {
  description = "Callback URLs for the hysds-ui-client-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/test/hysds-ui/"]
}

variable "hysds_ui_logout_urls" {
  description = "Logout URLs for the hysds-ui-client-user-pool-client app client."
  type        = list(string)
  default     = ["https://api.example.com/test/hysds-ui/logout"]
}

variable "localhost_hysds_ui_callback_urls" {
  description = "Callback URLs for the localhost-hysds-ui-client-user-pool-client app client."
  type        = list(string)
  default     = ["http://localhost:3000/"]
}

variable "localhost_hysds_ui_logout_urls" {
  description = "Logout URLs for the localhost-hysds-ui-client-user-pool-client app client."
  type        = list(string)
  default     = ["http://localhost:3000/logout"]
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  user_pool_name          = "unity-shared-services-user-pool"
  user_pool_id_param_name = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-id"
  hosted_ui_domain_prefix = "unity-shared-services-test"

  oauth_flows          = ["code"]
  oauth_scopes         = ["email", "openid"]
  identity_providers   = ["COGNITO"]
  prevent_existence    = "ENABLED"
  auth_flows_with_pass = ["ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]
  auth_flows_no_pass   = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_SRP_AUTH"]
}

# -----------------------------------------------------------------------------
# Cognito User Pool
# -----------------------------------------------------------------------------

resource "aws_cognito_user_pool" "shared_services" {
  name                     = local.user_pool_name
  deletion_protection      = "ACTIVE"
  auto_verified_attributes = ["email"]

  admin_create_user_config {
    allow_admin_create_user_only = true

    invite_message_template {
      email_subject = "Your Unity Shared Services account"
      email_message = "Welcome to Unity Shared Services. Your username is {username} and your temporary password is {####}. You will be asked to change your password the first time you sign in."
      sms_message   = "Unity Shared Services: your username is {username} and your temporary password is {####}"
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  password_policy {
    minimum_length                   = 12
    require_uppercase                = true
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  email_configuration {
    email_sending_account = "COGNITO_DEFAULT"
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# SSM Parameter publishing the User Pool ID
# -----------------------------------------------------------------------------

resource "aws_ssm_parameter" "user_pool_id" {
  name        = local.user_pool_id_param_name
  description = "ID of the Unity shared-services Cognito user pool."
  type        = "String"
  value       = aws_cognito_user_pool.shared_services.id
  tags        = var.tags
}

# -----------------------------------------------------------------------------
# Hosted UI Domain
# -----------------------------------------------------------------------------

resource "aws_cognito_user_pool_domain" "shared_services" {
  domain       = local.hosted_ui_domain_prefix
  user_pool_id = aws_cognito_user_pool.shared_services.id
}

# -----------------------------------------------------------------------------
# App Clients
# -----------------------------------------------------------------------------

resource "aws_cognito_user_pool_client" "uds_distribution" {
  name                                 = "unity-uds-distribution-user-pool-client"
  user_pool_id                         = aws_cognito_user_pool.shared_services.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = local.oauth_flows
  allowed_oauth_scopes                 = local.oauth_scopes
  supported_identity_providers         = local.identity_providers
  callback_urls                        = var.uds_distribution_callback_urls
  logout_urls                          = var.uds_distribution_logout_urls
  explicit_auth_flows                  = local.auth_flows_with_pass
  prevent_user_existence_errors        = local.prevent_existence
}

resource "aws_cognito_user_pool_client" "localhost_jupyterhub" {
  name                                 = "localhost-jupyterhub-user-pool-client"
  user_pool_id                         = aws_cognito_user_pool.shared_services.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = local.oauth_flows
  allowed_oauth_scopes                 = local.oauth_scopes
  supported_identity_providers         = local.identity_providers
  callback_urls                        = var.localhost_jupyterhub_callback_urls
  logout_urls                          = var.localhost_jupyterhub_logout_urls
  explicit_auth_flows                  = local.auth_flows_with_pass
  prevent_user_existence_errors        = local.prevent_existence
}

resource "aws_cognito_user_pool_client" "app_to_app" {
  name                                 = "unity-app-to-app-client-user-pool-client"
  user_pool_id                         = aws_cognito_user_pool.shared_services.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = local.oauth_flows
  allowed_oauth_scopes                 = local.oauth_scopes
  supported_identity_providers         = local.identity_providers
  callback_urls                        = var.app_to_app_callback_urls
  logout_urls                          = var.app_to_app_logout_urls
  explicit_auth_flows                  = local.auth_flows_no_pass
  prevent_user_existence_errors        = local.prevent_existence
}

resource "aws_cognito_user_pool_client" "jupyter_development" {
  name                                 = "uads-jupyter-development-client-user-pool-client"
  user_pool_id                         = aws_cognito_user_pool.shared_services.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = local.oauth_flows
  allowed_oauth_scopes                 = local.oauth_scopes
  supported_identity_providers         = local.identity_providers
  callback_urls                        = var.jupyter_development_callback_urls
  logout_urls                          = var.jupyter_development_logout_urls
  explicit_auth_flows                  = local.auth_flows_no_pass
  prevent_user_existence_errors        = local.prevent_existence
}

resource "aws_cognito_user_pool_client" "hysds_ui" {
  name                                 = "hysds-ui-client-user-pool-client"
  user_pool_id                         = aws_cognito_user_pool.shared_services.id
  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = local.oauth_flows
  allowed_oauth_scopes                 = local.oauth_scopes
  supported_identity_providers         = local.identity_providers
  callback_urls                        = var.hysds_ui_callback_urls
  logout_urls                          = var.hysds_ui_logout_urls
  explicit_auth_flows                  = local.auth_flows_with_pass
  prevent_user_existence_errors        = local.prevent_existence
}

resource "aws_cognito_user_pool_client" "localhost_hysds_ui" {
  name                                 = "localhost-hysds-ui-client-user-pool-client"
  user_pool_id                         = aws_cognito_user_pool.shared_services.id
  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = local.oauth_flows
  allowed_oauth_scopes                 = local.oauth_scopes
  supported_identity_providers         = local.identity_providers
  callback_urls                        = var.localhost_hysds_ui_callback_urls
  logout_urls                          = var.localhost_hysds_ui_logout_urls
  explicit_auth_flows                  = local.auth_flows_with_pass
  prevent_user_existence_errors        = local.prevent_existence
}

# -----------------------------------------------------------------------------
# User Groups
# -----------------------------------------------------------------------------

resource "aws_cognito_user_group" "unity_admin" {
  name         = "Unity_Admin"
  user_pool_id = aws_cognito_user_pool.shared_services.id
  description  = "Administrators of the Unity shared-services platform with full management access."
}

resource "aws_cognito_user_group" "unity_viewer" {
  name         = "Unity_Viewer"
  user_pool_id = aws_cognito_user_pool.shared_services.id
  description  = "Users of the Unity shared-services platform with read-only access."
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "user_pool_id" {
  description = "ID of the Unity shared-services Cognito user pool."
  value       = aws_cognito_user_pool.shared_services.id
}

output "user_pool_arn" {
  description = "ARN of the Unity shared-services Cognito user pool."
  value       = aws_cognito_user_pool.shared_services.arn
}

output "hosted_ui_domain" {
  description = "Cognito hosted UI domain prefix for the user pool."
  value       = aws_cognito_user_pool_domain.shared_services.domain
}

output "uds_distribution_client_id" {
  description = "App client ID for unity-uds-distribution-user-pool-client."
  value       = aws_cognito_user_pool_client.uds_distribution.id
}

output "localhost_jupyterhub_client_id" {
  description = "App client ID for localhost-jupyterhub-user-pool-client."
  value       = aws_cognito_user_pool_client.localhost_jupyterhub.id
}

output "app_to_app_client_id" {
  description = "App client ID for unity-app-to-app-client-user-pool-client."
  value       = aws_cognito_user_pool_client.app_to_app.id
}

output "jupyter_development_client_id" {
  description = "App client ID for uads-jupyter-development-client-user-pool-client."
  value       = aws_cognito_user_pool_client.jupyter_development.id
}

output "hysds_ui_client_id" {
  description = "App client ID for hysds-ui-client-user-pool-client."
  value       = aws_cognito_user_pool_client.hysds_ui.id
}

output "localhost_hysds_ui_client_id" {
  description = "App client ID for localhost-hysds-ui-client-user-pool-client."
  value       = aws_cognito_user_pool_client.localhost_hysds_ui.id
}

locals {
  name_suffix = "${var.app_name}-${var.environment}"
  az_count    = 3

  common_tags = {
    App         = var.app_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "app_name" {
  description = "Application name used for resource naming and tagging."
  type        = string
  default     = "terraform"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "testing"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "enable_ipv6" {
  description = "Assign an Amazon-provided IPv6 CIDR block to the VPC and subnets."
  type        = bool
  default     = false
}

variable "enable_transit_gateway_attachment" {
  description = "Create a transit gateway and attach the VPC private subnets to it."
  type        = bool
  default     = false
}

variable "enable_ipv6_egress" {
  description = "Create an egress-only internet gateway for private subnet IPv6 egress (requires enable_ipv6)."
  type        = bool
  default     = false
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets, one per availability zone."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]

  validation {
    condition     = length(var.public_subnet_cidrs) == 3
    error_message = "public_subnet_cidrs must contain exactly 3 CIDR blocks."
  }
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets, one per availability zone."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]

  validation {
    condition     = length(var.private_subnet_cidrs) == 3
    error_message = "private_subnet_cidrs must contain exactly 3 CIDR blocks."
  }
}

variable "flow_log_retention_days" {
  description = "Retention period in days for VPC flow logs."
  type        = number
  default     = 365
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = false
  assign_generated_ipv6_cidr_block = var.enable_ipv6
  instance_tenancy                 = "default"

  tags = merge(local.common_tags, {
    Name = "vpc-${local.name_suffix}"
  })
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.public_subnet_cidrs[count.index]
  availability_zone               = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch         = false
  ipv6_cidr_block                 = var.enable_ipv6 ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index) : null
  assign_ipv6_address_on_creation = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "subnet-public-${local.name_suffix}-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.private_subnet_cidrs[count.index]
  availability_zone               = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch         = false
  ipv6_cidr_block                 = var.enable_ipv6 ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 10) : null
  assign_ipv6_address_on_creation = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "subnet-private-${local.name_suffix}-${count.index + 1}"
    Tier = "private"
  })
}

# -----------------------------------------------------------------------------
# Internet gateway and public routing
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "igw-${local.name_suffix}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "rt-public-${local.name_suffix}"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_internet_ipv6" {
  count = var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# NAT gateway and private routing
# -----------------------------------------------------------------------------

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "eip-nat-${local.name_suffix}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public[0].id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = "nat-${local.name_suffix}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "rt-private-${local.name_suffix}"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Optional IPv6 egress for private subnets
# -----------------------------------------------------------------------------

resource "aws_egress_only_internet_gateway" "main" {
  count = var.enable_ipv6 && var.enable_ipv6_egress ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "eigw-${local.name_suffix}"
  })
}

resource "aws_route" "private_ipv6_egress" {
  count = var.enable_ipv6 && var.enable_ipv6_egress ? 1 : 0

  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

# -----------------------------------------------------------------------------
# Optional transit gateway attachment
# -----------------------------------------------------------------------------

resource "aws_ec2_transit_gateway" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  description                     = "Transit gateway for ${local.name_suffix}"
  auto_accept_shared_attachments  = "disable"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
  dns_support                     = "enable"
  vpn_ecmp_support                = "enable"

  tags = merge(local.common_tags, {
    Name = "tgw-${local.name_suffix}"
  })
}

resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  transit_gateway_id = aws_ec2_transit_gateway.main[0].id
  vpc_id             = aws_vpc.main.id
  subnet_ids         = aws_subnet.private[*].id
  dns_support        = "enable"
  ipv6_support       = var.enable_ipv6 ? "enable" : "disable"

  tags = merge(local.common_tags, {
    Name = "tgw-attach-${local.name_suffix}"
  })
}

# -----------------------------------------------------------------------------
# Default security group lockdown (CIS 5.4)
# -----------------------------------------------------------------------------

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "default-sg-${local.name_suffix}"
  })
}

# -----------------------------------------------------------------------------
# DB subnet group
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = lower("db-subnet-${local.name_suffix}")
  description = "Database subnet group spanning private subnets for ${local.name_suffix}"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "db-subnet-${local.name_suffix}"
  })
}

# -----------------------------------------------------------------------------
# VPC flow logs
# -----------------------------------------------------------------------------

resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for VPC flow logs of ${local.name_suffix}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/vpc/flow-logs/${local.name_suffix}"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "kms-flow-logs-${local.name_suffix}"
  })
}

resource "aws_kms_alias" "flow_logs" {
  name          = "alias/flow-logs-${local.name_suffix}"
  target_key_id = aws_kms_key.flow_logs.key_id
}

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc/flow-logs/${local.name_suffix}"
  retention_in_days = var.flow_log_retention_days
  kms_key_id        = aws_kms_key.flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "flow-logs-${local.name_suffix}"
  })
}

resource "aws_iam_role" "flow_logs" {
  name = "role-flow-logs-${local.name_suffix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "role-flow-logs-${local.name_suffix}"
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "policy-flow-logs-${local.name_suffix}"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs.arn,
          "${aws_cloudwatch_log_group.flow_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id                   = aws_vpc.main.id
  traffic_type             = "ALL"
  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn             = aws_iam_role.flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.common_tags, {
    Name = "flow-log-${local.name_suffix}"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_arn" {
  description = "ARN of the VPC."
  value       = aws_vpc.main.arn
}

output "vpc_cidr_block" {
  description = "IPv4 CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block of the VPC (empty when IPv6 is disabled)."
  value       = aws_vpc.main.ipv6_cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidr_blocks" {
  description = "CIDR blocks of the public subnets."
  value       = aws_subnet.public[*].cidr_block
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidr_blocks" {
  description = "CIDR blocks of the private subnets."
  value       = aws_subnet.private[*].cidr_block
}

output "subnet_availability_zones" {
  description = "Availability zones used by the subnets."
  value       = aws_subnet.public[*].availability_zone
}

output "default_security_group_id" {
  description = "ID of the locked-down default security group."
  value       = aws_default_security_group.default.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway."
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT gateway."
  value       = aws_eip.nat.public_ip
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the shared private route table."
  value       = aws_route_table.private.id
}

output "db_subnet_group_name" {
  description = "Name of the DB subnet group."
  value       = aws_db_subnet_group.main.name
}

output "transit_gateway_id" {
  description = "ID of the transit gateway (null when disabled)."
  value       = var.enable_transit_gateway_attachment ? aws_ec2_transit_gateway.main[0].id : null
}

output "transit_gateway_attachment_id" {
  description = "ID of the transit gateway VPC attachment (null when disabled)."
  value       = var.enable_transit_gateway_attachment ? aws_ec2_transit_gateway_vpc_attachment.main[0].id : null
}

output "egress_only_internet_gateway_id" {
  description = "ID of the egress-only internet gateway (null when disabled)."
  value       = var.enable_ipv6 && var.enable_ipv6_egress ? aws_egress_only_internet_gateway.main[0].id : null
}

output "flow_log_id" {
  description = "ID of the VPC flow log."
  value       = aws_flow_log.main.id
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "gitops-bridge"
    ManagedBy = "terraform"
  }
}

locals {
  gitops_user_name    = "gitops-bridge-gitops"
  gitops_repositories = toset(["gitops-apps", "gitops-platform", "gitops-addons"])
  ssh_private_key     = pathexpand("~/.ssh/gitops_ssh.pem")
  ssh_config_snippet  = pathexpand("~/.ssh/config.d/gitops-codecommit.conf")
}

# ---------------------------------------------------------------------------
# CodeCommit repositories
# ---------------------------------------------------------------------------

resource "aws_codecommit_repository" "gitops" {
  for_each = local.gitops_repositories

  repository_name = each.value
  description     = "${each.value} repository, part of the Argo CD GitOps bridge."

  tags = merge(var.tags, {
    Name = each.value
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM user (SSH-only access to CodeCommit; no access keys or login profile)
# ---------------------------------------------------------------------------

resource "aws_iam_user" "gitops_bridge" {
  name = local.gitops_user_name
  path = "/"

  tags = merge(var.tags, {
    Name = local.gitops_user_name
  })
}

resource "tls_private_key" "gitops_ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_iam_user_ssh_key" "gitops_bridge" {
  username   = aws_iam_user.gitops_bridge.name
  encoding   = "SSH"
  public_key = tls_private_key.gitops_ssh.public_key_openssh
  status     = "Active"
}

# ---------------------------------------------------------------------------
# Least-privilege policy: Git pull/push on the three repositories only
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "gitops_bridge" {
  statement {
    sid    = "GitOpsRepositoryGitAccess"
    effect = "Allow"

    actions = [
      "codecommit:GitPull",
      "codecommit:GitPush",
    ]

    resources = [for repo in aws_codecommit_repository.gitops : repo.arn]
  }
}

resource "aws_iam_policy" "gitops_bridge" {
  name        = local.gitops_user_name
  path        = "/"
  description = "Git pull and push access to the Argo CD GitOps bridge CodeCommit repositories."
  policy      = data.aws_iam_policy_document.gitops_bridge.json

  tags = merge(var.tags, {
    Name = local.gitops_user_name
  })
}

resource "aws_iam_user_policy_attachment" "gitops_bridge" {
  user       = aws_iam_user.gitops_bridge.name
  policy_arn = aws_iam_policy.gitops_bridge.arn
}

# ---------------------------------------------------------------------------
# Secrets Manager: store the generated SSH private key
# ---------------------------------------------------------------------------

resource "random_string" "secret_suffix" {
  length  = 5
  special = false
  upper   = false
}

resource "aws_secretsmanager_secret" "codecommit_key" {
  name        = "codecommit-key-${random_string.secret_suffix.result}"
  description = "SSH private key for the ${local.gitops_user_name} IAM user used to access the Argo CD GitOps bridge CodeCommit repositories."

  tags = merge(var.tags, {
    Name = "codecommit-key-${random_string.secret_suffix.result}"
  })
}

resource "aws_secretsmanager_secret_version" "codecommit_key" {
  secret_id     = aws_secretsmanager_secret.codecommit_key.id
  secret_string = tls_private_key.gitops_ssh.private_key_pem
}

# ---------------------------------------------------------------------------
# Local SSH material
# ---------------------------------------------------------------------------

resource "local_sensitive_file" "gitops_ssh_pem" {
  filename             = local.ssh_private_key
  content              = tls_private_key.gitops_ssh.private_key_pem
  file_permission      = "0600"
  directory_permission = "0700"
}

# Written as a standalone snippet so the user's existing ~/.ssh/config is never
# overwritten. Enable it by adding this line at the top of ~/.ssh/config:
#   Include config.d/*
resource "local_file" "gitops_ssh_config" {
  filename             = local.ssh_config_snippet
  file_permission      = "0600"
  directory_permission = "0700"

  content = <<-EOT
    # Managed by Terraform - Argo CD GitOps bridge (CodeCommit over SSH)
    Host git-codecommit.*.amazonaws.com
      User ${aws_iam_user_ssh_key.gitops_bridge.ssh_public_key_id}
      IdentityFile ${local_sensitive_file.gitops_ssh_pem.filename}
      IdentitiesOnly yes
  EOT

  depends_on = [aws_iam_user_ssh_key.gitops_bridge]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "repository_clone_urls_ssh" {
  description = "SSH clone URLs for the GitOps CodeCommit repositories."
  value       = { for name, repo in aws_codecommit_repository.gitops : name => repo.clone_url_ssh }
}

output "repository_arns" {
  description = "ARNs of the GitOps CodeCommit repositories."
  value       = { for name, repo in aws_codecommit_repository.gitops : name => repo.arn }
}

output "iam_user_name" {
  description = "Name of the IAM user used for CodeCommit SSH access."
  value       = aws_iam_user.gitops_bridge.name
}

output "ssh_public_key_id" {
  description = "SSH key ID to use as the SSH user name for CodeCommit."
  value       = aws_iam_user_ssh_key.gitops_bridge.ssh_public_key_id
}

output "iam_policy_arn" {
  description = "ARN of the customer-managed IAM policy granting Git access."
  value       = aws_iam_policy.gitops_bridge.arn
}

output "secret_name" {
  description = "Name of the Secrets Manager secret holding the SSH private key."
  value       = aws_secretsmanager_secret.codecommit_key.name
}

output "secret_arn" {
  description = "ARN of the Secrets Manager secret holding the SSH private key."
  value       = aws_secretsmanager_secret.codecommit_key.arn
}

output "private_key_path" {
  description = "Local path of the generated SSH private key."
  value       = local_sensitive_file.gitops_ssh_pem.filename
}

output "ssh_config_path" {
  description = "Local path of the SSH config snippet (include it from ~/.ssh/config)."
  value       = local_file.gitops_ssh_config.filename
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Input variables (module-style, all defaulted for unattended apply)
# -----------------------------------------------------------------------------

variable "instance_name" {
  description = "Name of the EC2 instance and prefix for related resources."
  type        = string
  default     = "benchmark-instance"
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t2.micro"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC created by this module."
  type        = string
  default     = "10.70.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet created by this module."
  type        = string
  default     = "10.70.0.0/24"
}

variable "key_name" {
  description = "Name of the EC2 key pair created by this module."
  type        = string
  default     = "benchmark-d8bc612be4e0-key"
}

variable "public_key" {
  description = "SSH public key material for the key pair. Public keys are not secret."
  type        = string
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIOkMx0rTfuQl+jm4D1rcZNJNp1IGwHcoOpAE5LqdXPx7 benchmark"
}

variable "root_volume_size" {
  description = "Size of the root EBS volume in GiB."
  type        = number
  default     = 10
}

variable "root_volume_type" {
  description = "Type of the root EBS volume."
  type        = string
  default     = "gp2"
}

variable "monitoring" {
  description = "Enable detailed CloudWatch monitoring for the instance."
  type        = bool
  default     = true
}

variable "ebs_volumes" {
  description = "Optional additional EBS volumes to create and attach, keyed by logical name. Volumes are always encrypted with the module's KMS key."
  type = map(object({
    device_name = string
    size        = number
    type        = optional(string, "gp3")
  }))
  default = {}
}

variable "additional_network_interfaces" {
  description = "Optional additional network interfaces to create and attach, keyed by logical name."
  type = map(object({
    device_index  = number
    associate_eip = optional(bool, false)
  }))
  default = {}
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "benchmark"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static / well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = var.instance_name

  account_id       = data.aws_caller_identity.current.account_id
  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"
  ec2_via_service  = "ec2.${data.aws_region.current.name}.amazonaws.com"

  reboot_action_arn = "arn:${data.aws_partition.current.partition}:automate:${data.aws_region.current.name}:ec2:reboot"

  extra_eni_eips = {
    for k, v in var.additional_network_interfaces : k => v if v.associate_eip
  }
}

# -----------------------------------------------------------------------------
# KMS key for EBS encryption (root and optional volumes)
# -----------------------------------------------------------------------------

resource "aws_kms_key" "ebs" {
  description             = "Customer-managed KMS key for EBS volumes of ${local.name_prefix}"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountRootKeyAdministration"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowEBSUseViaEC2"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService"    = local.ec2_via_service
            "kms:CallerAccount" = local.account_id
          }
        }
      },
      {
        Sid       = "AllowEBSGrantsViaEC2"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = ["kms:CreateGrant"]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService"    = local.ec2_via_service
            "kms:CallerAccount" = local.account_id
          }
          Bool = {
            "kms:GrantIsForAWSResource" = "true"
          }
        }
      }
    ]
  })

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-ebs-kms"
  })
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/${local.name_prefix}-ebs"
  target_key_id = aws_kms_key.ebs.key_id
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-rt"
  })
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

# -----------------------------------------------------------------------------
# Security group (egress to VPC CIDR only, no ingress)
# -----------------------------------------------------------------------------

resource "aws_security_group" "instance" {
  name        = "${local.name_prefix}-sg"
  description = "Dedicated security group for ${local.name_prefix}; egress to VPC CIDR only, no ingress"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all egress to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-sg"
  })
}

# -----------------------------------------------------------------------------
# Key pair
# -----------------------------------------------------------------------------

resource "aws_key_pair" "main" {
  key_name   = var.key_name
  public_key = var.public_key

  tags = merge(var.tags, {
    Name = var.key_name
  })
}

# -----------------------------------------------------------------------------
# IAM role and instance profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "instance" {
  name               = "${local.name_prefix}-role"
  description        = "EC2 instance role for ${local.name_prefix}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-role"
  })
}

resource "aws_iam_instance_profile" "instance" {
  name = "${local.name_prefix}-profile"
  role = aws_iam_role.instance.name

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-profile"
  })
}

# -----------------------------------------------------------------------------
# EC2 instance
# -----------------------------------------------------------------------------

resource "aws_instance" "main" {
  ami                         = data.aws_ami.ubuntu.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.main.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  key_name                    = aws_key_pair.main.key_name
  iam_instance_profile        = aws_iam_instance_profile.instance.name
  monitoring                  = var.monitoring
  associate_public_ip_address = true

  root_block_device {
    volume_type           = var.root_volume_type
    volume_size           = var.root_volume_size
    encrypted             = true
    kms_key_id            = aws_kms_key.ebs.arn
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  tags = merge(var.tags, {
    Name = var.instance_name
  })

  volume_tags = merge(var.tags, {
    Name = "${local.name_prefix}-root"
  })

  depends_on = [aws_route_table_association.main]
}

resource "aws_eip" "main" {
  domain   = "vpc"
  instance = aws_instance.main.id

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# CloudWatch alarm: auto-reboot on instance status check failure
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "instance_status_check" {
  alarm_name          = "${local.name_prefix}-status-check-failed-instance"
  alarm_description   = "Reboots ${local.name_prefix} when the instance status check fails for 5 consecutive minutes"
  namespace           = "AWS/EC2"
  metric_name         = "StatusCheckFailed_Instance"
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 5
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "missing"

  dimensions = {
    InstanceId = aws_instance.main.id
  }

  alarm_actions = [local.reboot_action_arn]

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-status-check-failed-instance"
  })
}

# -----------------------------------------------------------------------------
# Optional extra EBS volumes (none by default)
# -----------------------------------------------------------------------------

resource "aws_ebs_volume" "extra" {
  for_each = var.ebs_volumes

  availability_zone = aws_instance.main.availability_zone
  size              = each.value.size
  type              = each.value.type
  encrypted         = true
  kms_key_id        = aws_kms_key.ebs.arn

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "extra" {
  for_each = var.ebs_volumes

  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.extra[each.key].id
  instance_id = aws_instance.main.id
}

# -----------------------------------------------------------------------------
# Optional additional network interfaces with EIPs (none by default)
# -----------------------------------------------------------------------------

resource "aws_network_interface" "extra" {
  for_each = var.additional_network_interfaces

  subnet_id       = aws_subnet.main.id
  security_groups = [aws_security_group.instance.id]

  attachment {
    instance     = aws_instance.main.id
    device_index = each.value.device_index
  }

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-eni-${each.key}"
  })
}

resource "aws_eip" "extra" {
  for_each = local.extra_eni_eips

  domain            = "vpc"
  network_interface = aws_network_interface.extra[each.key].id

  tags = merge(var.tags, {
    Name = "${local.name_prefix}-eip-${each.key}"
  })

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "instance_id" {
  description = "ID of the EC2 instance."
  value       = aws_instance.main.id
}

output "public_ip" {
  description = "Elastic IP address attached to the instance."
  value       = aws_eip.main.public_ip
}

output "private_ip" {
  description = "Private IP address of the instance."
  value       = aws_instance.main.private_ip
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "subnet_id" {
  description = "ID of the subnet."
  value       = aws_subnet.main.id
}

output "security_group_id" {
  description = "ID of the instance security group."
  value       = aws_security_group.instance.id
}

output "iam_role_arn" {
  description = "ARN of the instance IAM role."
  value       = aws_iam_role.instance.arn
}

output "status_check_alarm_arn" {
  description = "ARN of the StatusCheckFailed_Instance CloudWatch alarm."
  value       = aws_cloudwatch_metric_alarm.instance_status_check.arn
}

output "ebs_kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for EBS encryption."
  value       = aws_kms_key.ebs.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "source1"
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "us-east-2"
}

provider "aws" {
  alias  = "replica2"
  region = "us-west-1"
}

variable "env" {
  description = "Environment tag applied to all resources."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {
  provider = aws.source1
}

data "aws_partition" "current" {
  provider = aws.source1
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  region_source1  = "us-east-1"
  region_source2  = "us-west-2"
  region_replica1 = "us-east-2"
  region_replica2 = "us-west-1"

  source_group1 = ["log1a.veerum", "log1b.veerum"]
  source_group2 = ["log2a.veerum", "log2b.veerum"]

  source_bucket_groups = merge(
    { for b in local.source_group1 : b => 1 },
    { for b in local.source_group2 : b => 2 }
  )

  all_source_bases = keys(local.source_bucket_groups)

  source_bucket_names   = { for b in local.all_source_bases : b => "${b}-${local.account_id}" }
  replica1_bucket_names = { for b in local.all_source_bases : b => "${b}-replica1-${local.account_id}" }
  replica2_bucket_names = { for b in local.all_source_bases : b => "${b}-replica2-${local.account_id}" }

  versioning_status  = "Enabled"
  object_ownership   = "BucketOwnerEnforced"
  storage_class      = "STANDARD"
  replication_status = "Enabled"

  common_tags = {
    Env = var.env
  }

  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountRootAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# KMS keys
# -----------------------------------------------------------------------------

resource "aws_kms_key" "source1" {
  provider                = aws.source1
  description             = "SSE-KMS key for source buckets in ${local.region_source1}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = local.kms_key_policy
  tags                    = local.common_tags
}

resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "SSE-KMS key for source buckets in ${local.region_source2}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = local.kms_key_policy
  tags                    = local.common_tags
}

resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "SSE-KMS key for replica buckets in ${local.region_replica1}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = local.kms_key_policy
  tags                    = local.common_tags
}

resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "SSE-KMS key for replica buckets in ${local.region_replica2}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = local.kms_key_policy
  tags                    = local.common_tags
}

resource "aws_kms_alias" "source1" {
  provider      = aws.source1
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_alias" "source2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

# -----------------------------------------------------------------------------
# Source buckets - group 1 (us-east-1)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "source1" {
  provider = aws.source1
  for_each = toset(local.source_group1)
  bucket   = local.source_bucket_names[each.key]
  tags     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "source1" {
  provider                = aws.source1
  for_each                = toset(local.source_group1)
  bucket                  = aws_s3_bucket.source1[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "source1" {
  provider = aws.source1
  for_each = toset(local.source_group1)
  bucket   = aws_s3_bucket.source1[each.key].id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_versioning" "source1" {
  provider = aws.source1
  for_each = toset(local.source_group1)
  bucket   = aws_s3_bucket.source1[each.key].id

  versioning_configuration {
    status = local.versioning_status
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source1" {
  provider = aws.source1
  for_each = toset(local.source_group1)
  bucket   = aws_s3_bucket.source1[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source1.arn
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Source buckets - group 2 (us-west-2)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "source2" {
  provider = aws.source2
  for_each = toset(local.source_group2)
  bucket   = local.source_bucket_names[each.key]
  tags     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "source2" {
  provider                = aws.source2
  for_each                = toset(local.source_group2)
  bucket                  = aws_s3_bucket.source2[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "source2" {
  provider = aws.source2
  for_each = toset(local.source_group2)
  bucket   = aws_s3_bucket.source2[each.key].id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_versioning" "source2" {
  provider = aws.source2
  for_each = toset(local.source_group2)
  bucket   = aws_s3_bucket.source2[each.key].id

  versioning_configuration {
    status = local.versioning_status
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source2" {
  provider = aws.source2
  for_each = toset(local.source_group2)
  bucket   = aws_s3_bucket.source2[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source2.arn
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Replica buckets - replica region 1 (us-east-2)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_source_bases)
  bucket   = local.replica1_bucket_names[each.key]
  tags     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica1" {
  provider                = aws.replica1
  for_each                = toset(local.all_source_bases)
  bucket                  = aws_s3_bucket.replica1[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_source_bases)
  bucket   = aws_s3_bucket.replica1[each.key].id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_versioning" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_source_bases)
  bucket   = aws_s3_bucket.replica1[each.key].id

  versioning_configuration {
    status = local.versioning_status
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_source_bases)
  bucket   = aws_s3_bucket.replica1[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica1.arn
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Replica buckets - replica region 2 (us-west-1)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_source_bases)
  bucket   = local.replica2_bucket_names[each.key]
  tags     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica2" {
  provider                = aws.replica2
  for_each                = toset(local.all_source_bases)
  bucket                  = aws_s3_bucket.replica2[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_source_bases)
  bucket   = aws_s3_bucket.replica2[each.key].id

  rule {
    object_ownership = local.object_ownership
  }
}

resource "aws_s3_bucket_versioning" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_source_bases)
  bucket   = aws_s3_bucket.replica2[each.key].id

  versioning_configuration {
    status = local.versioning_status
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_source_bases)
  bucket   = aws_s3_bucket.replica2[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica2.arn
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# IAM role and policy for replication
# -----------------------------------------------------------------------------

resource "aws_iam_role" "s3_replication" {
  provider = aws.source1
  name     = "s3-replication-${var.env}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3AssumeRole"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "s3_replication" {
  provider    = aws.source1
  name        = "s3-replication-${var.env}"
  description = "Least-privilege policy for cross-region S3 replication of log buckets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadSourceBucketConfiguration"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = concat(
          [for k in local.source_group1 : aws_s3_bucket.source1[k].arn],
          [for k in local.source_group2 : aws_s3_bucket.source2[k].arn]
        )
      },
      {
        Sid    = "ReadSourceObjectVersions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = concat(
          [for k in local.source_group1 : "${aws_s3_bucket.source1[k].arn}/*"],
          [for k in local.source_group2 : "${aws_s3_bucket.source2[k].arn}/*"]
        )
      },
      {
        Sid    = "ReplicateIntoReplicaBuckets"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = concat(
          [for k in local.all_source_bases : "${aws_s3_bucket.replica1[k].arn}/*"],
          [for k in local.all_source_bases : "${aws_s3_bucket.replica2[k].arn}/*"]
        )
      },
      {
        Sid    = "DecryptWithSourceKeys"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [
          aws_kms_key.source1.arn,
          aws_kms_key.source2.arn
        ]
        Condition = {
          StringLike = {
            "kms:ViaService" = [
              "s3.${local.region_source1}.amazonaws.com",
              "s3.${local.region_source2}.amazonaws.com"
            ]
          }
        }
      },
      {
        Sid    = "EncryptWithReplicaKeys"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.replica1.arn,
          aws_kms_key.replica2.arn
        ]
        Condition = {
          StringLike = {
            "kms:ViaService" = [
              "s3.${local.region_replica1}.amazonaws.com",
              "s3.${local.region_replica2}.amazonaws.com"
            ]
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  provider   = aws.source1
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

# -----------------------------------------------------------------------------
# Replication configurations
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "source1" {
  provider = aws.source1
  for_each = toset(local.source_group1)
  role     = aws_iam_role.s3_replication.arn
  bucket   = aws_s3_bucket.source1[each.key].id

  rule {
    id       = "replicate-to-replica1"
    priority = 1
    status   = local.replication_status

    filter {}

    delete_marker_replication {
      status = local.replication_status
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = local.replication_status
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = local.storage_class

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    priority = 2
    status   = local.replication_status

    filter {}

    delete_marker_replication {
      status = local.replication_status
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = local.replication_status
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = local.storage_class

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
    aws_iam_role_policy_attachment.s3_replication
  ]
}

resource "aws_s3_bucket_replication_configuration" "source2" {
  provider = aws.source2
  for_each = toset(local.source_group2)
  role     = aws_iam_role.s3_replication.arn
  bucket   = aws_s3_bucket.source2[each.key].id

  rule {
    id       = "replicate-to-replica1"
    priority = 1
    status   = local.replication_status

    filter {}

    delete_marker_replication {
      status = local.replication_status
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = local.replication_status
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = local.storage_class

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    priority = 2
    status   = local.replication_status

    filter {}

    delete_marker_replication {
      status = local.replication_status
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = local.replication_status
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = local.storage_class

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
    aws_iam_role_policy_attachment.s3_replication
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "source_bucket_names" {
  description = "Names of the four source buckets."
  value = merge(
    { for k in local.source_group1 : k => aws_s3_bucket.source1[k].id },
    { for k in local.source_group2 : k => aws_s3_bucket.source2[k].id }
  )
}

output "replica1_bucket_names" {
  description = "Names of the four replica buckets in replica region 1."
  value       = { for k in local.all_source_bases : k => aws_s3_bucket.replica1[k].id }
}

output "replica2_bucket_names" {
  description = "Names of the four replica buckets in replica region 2."
  value       = { for k in local.all_source_bases : k => aws_s3_bucket.replica2[k].id }
}

output "kms_key_arns" {
  description = "ARNs of the four customer-managed KMS keys."
  value = {
    sourcekey1  = aws_kms_key.source1.arn
    sourcekey2  = aws_kms_key.source2.arn
    replicakey1 = aws_kms_key.replica1.arn
    replicakey2 = aws_kms_key.replica2.arn
  }
}

output "replication_role_arn" {
  description = "ARN of the IAM role used by S3 replication."
  value       = aws_iam_role.s3_replication.arn
}

terraform {
  required_version = ">= 1.4"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = "~> 5.0"
      configuration_aliases = [aws.replica]
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

################################################################################
# Variables
################################################################################

variable "name_prefix" {
  description = "Prefix used for naming resources created by this module."
  type        = string
  default     = "guardduty"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,20}[a-z0-9]$", var.name_prefix))
    error_message = "name_prefix must be 3-22 lowercase alphanumeric characters or hyphens."
  }
}

variable "repository_url" {
  description = "Repository URL of this module, applied as a tag to every taggable resource."
  type        = string
  default     = "https://github.com/example-org/terraform-aws-guardduty"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

variable "replica_region" {
  description = "Region for the cross-region replica of the findings export bucket."
  type        = string
  default     = "us-west-2"

  validation {
    condition     = var.replica_region != "us-east-1"
    error_message = "replica_region must differ from the primary region (us-east-1)."
  }
}

variable "filters" {
  description = "Map of GuardDuty findings filters to create, keyed by filter name."
  type = map(object({
    action      = string
    rank        = number
    description = optional(string)
    criterion = list(object({
      field                 = string
      equals                = optional(list(string))
      not_equals            = optional(list(string))
      greater_than          = optional(string)
      greater_than_or_equal = optional(string)
      less_than             = optional(string)
      less_than_or_equal    = optional(string)
    }))
  }))
  default = {}

  validation {
    condition     = alltrue([for f in values(var.filters) : contains(["ARCHIVE", "NOOP"], f.action)])
    error_message = "Each filter action must be ARCHIVE or NOOP."
  }
}

variable "ipsets" {
  description = "Map of trusted IP sets to create, keyed by IP set name."
  type = map(object({
    format   = string
    location = string
    activate = optional(bool, true)
  }))
  default = {}
}

variable "threatintelsets" {
  description = "Map of threat intelligence sets to create, keyed by set name."
  type = map(object({
    format   = string
    location = string
    activate = optional(bool, true)
  }))
  default = {}
}

variable "malware_protection_plans" {
  description = "Map of S3 malware protection plans to create, keyed by a short plan name."
  type = map(object({
    bucket_name     = string
    object_prefixes = optional(list(string), [])
    tagging_enabled = optional(bool, true)
    kms_key_arn     = optional(string)
  }))
  default = {}
}

variable "enable_findings_export" {
  description = "Whether to export GuardDuty findings to an encrypted, replicated S3 bucket."
  type        = bool
  default     = false
}

variable "findings_transition_days" {
  description = "Days after which exported findings transition to the GLACIER storage class."
  type        = number
  default     = 90
}

variable "findings_noncurrent_expiration_days" {
  description = "Days after which noncurrent versions of exported findings are expired."
  type        = number
  default     = 365
}

variable "access_log_expiration_days" {
  description = "Days after which server access logs are expired. Set to 0 to disable the expiration rule."
  type        = number
  default     = 365
}

################################################################################
# Data sources (self-referential lookups only)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

################################################################################
# Locals
################################################################################

locals {
  tags = merge(var.tags, { Repository = var.repository_url })

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  guardduty_service         = "guardduty.amazonaws.com"
  s3_service                = "s3.amazonaws.com"
  s3_logging_service        = "logging.s3.amazonaws.com"
  malware_protection_service = "malware-protection-plan.guardduty.amazonaws.com"

  detector_features = toset([
    "S3_DATA_EVENTS",
    "RDS_LOGIN_EVENTS",
    "LAMBDA_NETWORK_LOGS",
    "EKS_AUDIT_LOGS",
    "EBS_MALWARE_PROTECTION",
  ])

  runtime_additional_configurations = [
    "EKS_ADDON_MANAGEMENT",
    "ECS_FARGATE_AGENT_MANAGEMENT",
    "EC2_AGENT_MANAGEMENT",
  ]

  export_count = var.enable_findings_export ? 1 : 0

  root_principal_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  findings_bucket_name    = "${var.name_prefix}-findings-${local.account_id}-${local.region}"
  access_logs_bucket_name = "${var.name_prefix}-access-logs-${local.account_id}-${local.region}"
  replica_bucket_name     = "${var.name_prefix}-findings-replica-${local.account_id}-${var.replica_region}"
}

################################################################################
# GuardDuty detector and features
################################################################################

resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = local.tags
}

resource "aws_guardduty_detector_feature" "this" {
  for_each = local.detector_features

  detector_id = aws_guardduty_detector.main.id
  name        = each.value
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.main.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  dynamic "additional_configuration" {
    for_each = local.runtime_additional_configurations
    content {
      name   = additional_configuration.value
      status = "DISABLED"
    }
  }

  depends_on = [aws_guardduty_detector_feature.this]
}

resource "terraform_data" "malware_scan_settings" {
  triggers_replace = [aws_guardduty_detector.main.id]

  input = {
    detector_id = aws_guardduty_detector.main.id
    region      = local.region
  }

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${self.input.detector_id} --ebs-snapshot-preservation NO_RETENTION --region ${self.input.region}"
  }

  depends_on = [
    aws_guardduty_detector_feature.this,
    aws_guardduty_detector_feature.runtime_monitoring,
  ]
}

################################################################################
# Optional findings filters, IP sets and threat intel sets
################################################################################

resource "aws_guardduty_filter" "this" {
  for_each = var.filters

  name        = each.key
  detector_id = aws_guardduty_detector.main.id
  action      = each.value.action
  rank        = each.value.rank
  description = each.value.description

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.criterion
      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than             = criterion.value.less_than
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }

  tags = local.tags
}

resource "aws_guardduty_ipset" "this" {
  for_each = var.ipsets

  name        = each.key
  detector_id = aws_guardduty_detector.main.id
  format      = each.value.format
  location    = each.value.location
  activate    = each.value.activate

  tags = local.tags
}

resource "aws_guardduty_threatintelset" "this" {
  for_each = var.threatintelsets

  name        = each.key
  detector_id = aws_guardduty_detector.main.id
  format      = each.value.format
  location    = each.value.location
  activate    = each.value.activate

  tags = local.tags
}

################################################################################
# Optional S3 malware protection plans
################################################################################

resource "aws_iam_role" "malware_protection" {
  for_each = var.malware_protection_plans

  name = "${var.name_prefix}-malware-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGuardDutyMalwareProtection"
        Effect    = "Allow"
        Principal = { Service = local.malware_protection_service }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "malware_protection" {
  for_each = var.malware_protection_plans

  name = "${var.name_prefix}-malware-${each.key}"
  role = aws_iam_role.malware_protection[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "AllowManagedRuleToSendS3EventsToGuardDuty"
          Effect = "Allow"
          Action = [
            "events:PutRule",
            "events:DeleteRule",
            "events:PutTargets",
            "events:RemoveTargets",
          ]
          Resource = "arn:${local.partition}:events:${local.region}:${local.account_id}:rule/DO-NOT-DELETE-AmazonGuardDutyMalwareProtectionS3*"
          Condition = {
            StringLike = {
              "events:ManagedBy" = local.malware_protection_service
            }
          }
        },
        {
          Sid    = "AllowGuardDutyToMonitorEventBridgeManagedRule"
          Effect = "Allow"
          Action = [
            "events:DescribeRule",
            "events:ListTargetsByRule",
          ]
          Resource = "arn:${local.partition}:events:${local.region}:${local.account_id}:rule/DO-NOT-DELETE-AmazonGuardDutyMalwareProtectionS3*"
        },
        {
          Sid    = "AllowPostScanTag"
          Effect = "Allow"
          Action = [
            "s3:PutObjectTagging",
            "s3:GetObjectTagging",
            "s3:PutObjectVersionTagging",
            "s3:GetObjectVersionTagging",
          ]
          Resource = "arn:${local.partition}:s3:::${each.value.bucket_name}/*"
        },
        {
          Sid    = "AllowEnableS3EventBridgeEvents"
          Effect = "Allow"
          Action = [
            "s3:PutBucketNotification",
            "s3:GetBucketNotification",
          ]
          Resource = "arn:${local.partition}:s3:::${each.value.bucket_name}"
        },
        {
          Sid      = "AllowPutValidationObject"
          Effect   = "Allow"
          Action   = "s3:PutObject"
          Resource = "arn:${local.partition}:s3:::${each.value.bucket_name}/malware-protection-resource-validation-object"
        },
        {
          Sid      = "AllowCheckBucketOwnership"
          Effect   = "Allow"
          Action   = "s3:ListBucket"
          Resource = "arn:${local.partition}:s3:::${each.value.bucket_name}"
        },
        {
          Sid    = "AllowMalwareScan"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:GetObjectVersion",
          ]
          Resource = "arn:${local.partition}:s3:::${each.value.bucket_name}/*"
        },
      ],
      [
        for key_arn in [each.value.kms_key_arn] : {
          Sid    = "AllowDecryptForMalwareScan"
          Effect = "Allow"
          Action = [
            "kms:GenerateDataKey",
            "kms:Decrypt",
          ]
          Resource = key_arn
          Condition = {
            StringLike = {
              "kms:ViaService" = "s3.*.amazonaws.com"
            }
          }
        } if key_arn != null
      ]
    )
  })
}

resource "aws_guardduty_malware_protection_plan" "this" {
  for_each = var.malware_protection_plans

  role = aws_iam_role.malware_protection[each.key].arn

  protected_resource {
    s3_bucket {
      bucket_name     = each.value.bucket_name
      object_prefixes = each.value.object_prefixes
    }
  }

  actions {
    tagging {
      status = each.value.tagging_enabled ? "ENABLED" : "DISABLED"
    }
  }

  tags = local.tags

  depends_on = [aws_iam_role_policy.malware_protection]
}

################################################################################
# Optional findings export - KMS key
################################################################################

resource "aws_kms_key" "findings" {
  count = local.export_count

  description             = "Encrypts GuardDuty findings exported to S3"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountAdministration"
        Effect    = "Allow"
        Principal = { AWS = local.root_principal_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowGuardDutyToEncryptFindings"
        Effect    = "Allow"
        Principal = { Service = local.guardduty_service }
        Action    = "kms:GenerateDataKey"
        Resource  = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
            "aws:SourceArn"     = aws_guardduty_detector.main.arn
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "findings" {
  count = local.export_count

  name          = "alias/${var.name_prefix}-findings"
  target_key_id = aws_kms_key.findings[0].key_id
}

################################################################################
# Optional findings export - access log bucket
################################################################################

resource "aws_s3_bucket" "access_logs" {
  count = local.export_count

  bucket = local.access_logs_bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  count = local.export_count

  bucket                  = aws_s3_bucket.access_logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  count = local.export_count

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  count = local.export_count

  bucket = aws_s3_bucket.access_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  count = local.export_count

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs" {
  count = var.enable_findings_export && var.access_log_expiration_days > 0 ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    id     = "expire-access-logs"
    status = "Enabled"

    filter {}

    expiration {
      days = var.access_log_expiration_days
    }

    noncurrent_version_expiration {
      noncurrent_days = var.access_log_expiration_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.access_logs]
}

resource "aws_s3_bucket_policy" "access_logs" {
  count = local.export_count

  bucket = aws_s3_bucket.access_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ServerAccessLogging"
        Effect    = "Allow"
        Principal = { Service = local.s3_logging_service }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.access_logs[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.findings[0].arn
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.access_logs[0].arn,
          "${aws_s3_bucket.access_logs[0].arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.access_logs]
}

################################################################################
# Optional findings export - findings bucket
################################################################################

resource "aws_s3_bucket" "findings" {
  count = local.export_count

  bucket = local.findings_bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings" {
  count = local.export_count

  bucket                  = aws_s3_bucket.findings[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "findings" {
  count = local.export_count

  bucket = aws_s3_bucket.findings[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "findings" {
  count = local.export_count

  bucket = aws_s3_bucket.findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings" {
  count = local.export_count

  bucket = aws_s3_bucket.findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.findings[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "findings" {
  count = local.export_count

  bucket        = aws_s3_bucket.findings[0].id
  target_bucket = aws_s3_bucket.access_logs[0].id
  target_prefix = "findings/"

  depends_on = [aws_s3_bucket_policy.access_logs]
}

resource "aws_s3_bucket_lifecycle_configuration" "findings" {
  count = local.export_count

  bucket = aws_s3_bucket.findings[0].id

  rule {
    id     = "findings-retention"
    status = "Enabled"

    filter {}

    transition {
      days          = var.findings_transition_days
      storage_class = "GLACIER"
    }

    noncurrent_version_expiration {
      noncurrent_days = var.findings_noncurrent_expiration_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.findings]
}

resource "aws_s3_bucket_policy" "findings" {
  count = local.export_count

  bucket = aws_s3_bucket.findings[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGuardDutyGetBucketLocation"
        Effect    = "Allow"
        Principal = { Service = local.guardduty_service }
        Action    = "s3:GetBucketLocation"
        Resource  = aws_s3_bucket.findings[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
            "aws:SourceArn"     = aws_guardduty_detector.main.arn
          }
        }
      },
      {
        Sid       = "AllowGuardDutyPutObject"
        Effect    = "Allow"
        Principal = { Service = local.guardduty_service }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
            "aws:SourceArn"     = aws_guardduty_detector.main.arn
          }
        }
      },
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = { Service = local.guardduty_service }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings[0].arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
      {
        Sid       = "DenyIncorrectEncryptionKey"
        Effect    = "Deny"
        Principal = { Service = local.guardduty_service }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings[0].arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.findings[0].arn
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.findings[0].arn,
          "${aws_s3_bucket.findings[0].arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.findings]
}

################################################################################
# Optional findings export - cross-region replica
################################################################################

resource "aws_kms_key" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  description             = "Encrypts replicated GuardDuty findings"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountAdministration"
        Effect    = "Allow"
        Principal = { AWS = local.root_principal_arn }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  name          = "alias/${var.name_prefix}-findings-replica"
  target_key_id = aws_kms_key.findings_replica[0].key_id
}

resource "aws_s3_bucket" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  bucket = local.replica_bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  bucket                  = aws_s3_bucket.findings_replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.findings_replica[0].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "findings_replica" {
  count    = local.export_count
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.findings_replica[0].arn,
          "${aws_s3_bucket.findings_replica[0].arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.findings_replica]
}

################################################################################
# Optional findings export - replication role
################################################################################

resource "aws_iam_role" "replication" {
  count = local.export_count

  name = "${var.name_prefix}-findings-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3Replication"
        Effect    = "Allow"
        Principal = { Service = local.s3_service }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "replication" {
  count = local.export_count

  name = "${var.name_prefix}-findings-replication"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadSourceBucketConfiguration"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = aws_s3_bucket.findings[0].arn
      },
      {
        Sid    = "ReadSourceObjectVersions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
        ]
        Resource = "${aws_s3_bucket.findings[0].arn}/*"
      },
      {
        Sid    = "WriteReplicaObjects"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
        ]
        Resource = "${aws_s3_bucket.findings_replica[0].arn}/*"
      },
      {
        Sid      = "DecryptSourceObjects"
        Effect   = "Allow"
        Action   = "kms:Decrypt"
        Resource = aws_kms_key.findings[0].arn
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${local.region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "EncryptReplicaObjects"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
        ]
        Resource = aws_kms_key.findings_replica[0].arn
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${var.replica_region}.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "findings" {
  count = local.export_count

  role   = aws_iam_role.replication[0].arn
  bucket = aws_s3_bucket.findings[0].id

  rule {
    id     = "replicate-findings"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.findings_replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.findings_replica[0].arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.findings,
    aws_s3_bucket_versioning.findings_replica,
    aws_iam_role_policy.replication,
  ]
}

################################################################################
# Optional findings export - publishing destination
################################################################################

resource "aws_guardduty_publishing_destination" "s3" {
  count = local.export_count

  detector_id      = aws_guardduty_detector.main.id
  destination_arn  = aws_s3_bucket.findings[0].arn
  kms_key_arn      = aws_kms_key.findings[0].arn
  destination_type = "S3"

  depends_on = [
    aws_s3_bucket_policy.findings,
    aws_kms_key.findings,
  ]
}

################################################################################
# Outputs
################################################################################

output "detector_id" {
  description = "ID of the GuardDuty detector."
  value       = aws_guardduty_detector.main.id
}

output "detector_arn" {
  description = "ARN of the GuardDuty detector."
  value       = aws_guardduty_detector.main.arn
}

output "detector_feature_statuses" {
  description = "Status of each enabled GuardDuty detector feature."
  value = merge(
    { for name, feature in aws_guardduty_detector_feature.this : name => feature.status },
    { (aws_guardduty_detector_feature.runtime_monitoring.name) = aws_guardduty_detector_feature.runtime_monitoring.status }
  )
}

output "filter_ids" {
  description = "IDs of the GuardDuty findings filters, keyed by filter name."
  value       = { for name, filter in aws_guardduty_filter.this : name => filter.id }
}

output "ipset_ids" {
  description = "IDs of the GuardDuty trusted IP sets, keyed by name."
  value       = { for name, ipset in aws_guardduty_ipset.this : name => ipset.id }
}

output "threatintelset_ids" {
  description = "IDs of the GuardDuty threat intel sets, keyed by name."
  value       = { for name, set in aws_guardduty_threatintelset.this : name => set.id }
}

output "malware_protection_plan_ids" {
  description = "IDs of the S3 malware protection plans, keyed by plan name."
  value       = { for name, plan in aws_guardduty_malware_protection_plan.this : name => plan.id }
}

output "findings_bucket_arn" {
  description = "ARN of the findings export bucket, or null when export is disabled."
  value       = one(aws_s3_bucket.findings[*].arn)
}

output "findings_kms_key_arn" {
  description = "ARN of the KMS key encrypting exported findings, or null when export is disabled."
  value       = one(aws_kms_key.findings[*].arn)
}

output "access_logs_bucket_arn" {
  description = "ARN of the server access log bucket, or null when export is disabled."
  value       = one(aws_s3_bucket.access_logs[*].arn)
}

output "findings_replica_bucket_arn" {
  description = "ARN of the cross-region replica bucket, or null when export is disabled."
  value       = one(aws_s3_bucket.findings_replica[*].arn)
}

output "replication_role_arn" {
  description = "ARN of the S3 replication IAM role, or null when export is disabled."
  value       = one(aws_iam_role.replication[*].arn)
}

output "publishing_destination_id" {
  description = "ID of the GuardDuty publishing destination, or null when export is disabled."
  value       = one(aws_guardduty_publishing_destination.s3[*].id)
}
